// Fragt beim Server die fertigen Zahlen ab und schreibt sie in die Seite.

// Die Wortmarke misst ihre Buchstaben aus. Erst messen, wenn die Logo-Schrift geladen ist.
let schriftWarten = document.fonts.load('400 100px "DM Serif Display"').catch(() => {});
const euro = new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' });
const zahl = new Intl.NumberFormat('de-DE', { maximumFractionDigits: 4 });
const prozent = new Intl.NumberFormat('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2, signDisplay: 'always' });
const plusEuro = new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR', signDisplay: 'always' });

const el = (id) => document.getElementById(id);

// Auf dem NUC: Ist die Sitzung abgelaufen, antwortet der Server mit 401. Dann zur Anmeldeseite.
{
  const original = window.fetch.bind(window);
  window.fetch = async (...args) => {
    const r = await original(...args);
    if (r.status === 401 && !String(args[0]).includes('/api/konto/')) location.href = '/anmelden';
    return r;
  };
}

// Jede Adresse wird pro Seitenaufruf nur einmal beim Server abgefragt.
const antworten = {};
function api(pfad) {
  antworten[pfad] ??= fetch(pfad)
    .then((r) => { if (!r.ok) throw new Error(r.status); return r.json(); })
    .catch((f) => { delete antworten[pfad]; throw f; });
  return antworten[pfad];
}


// ---- Preisalarme überall: Fenster zum Setzen, Liste auf der Watchlist, Hinweis beim Erreichen ----
// Gespeichert werden sie wie die Alerts der Chartanalyse (chart_alerts.yaml), es ist dieselbe Liste.
// Der Kurs ist in der Handelswährung (wie im Chart), nicht in Euro.
let alAlle = [];
const alSenden = (pfad, methode, daten) => fetch(pfad, { method: methode, headers: { 'content-type': 'application/json', 'x-vinter': 'chart' }, body: daten ? JSON.stringify(daten) : undefined })
  .then((r) => r.json()).catch(() => ({ fehler: 'Server nicht erreichbar.' }));
const alPreis = (v) => (v === null || v === undefined ? '–' : new Intl.NumberFormat('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: v < 10 ? 4 : 2 }).format(v));
const alBedingung = (a) => `${a.richtung === 'ueber' ? 'steigt über' : 'fällt unter'} ${alPreis(a.preis)}`;
const AL_GLOCKE = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 8a6 6 0 1 1 12 0c0 7 3 9 3 9H3s3-2 3-9"/><path d="M10 21a2 2 0 0 0 4 0"/></svg>';

// Nach jeder Änderung alles nachziehen, was Alarme zeigt
async function alNeu() {
  await ladeChartAlerts();
  caAlerts = alAlle;
  if (typeof caZeichneAlerts === 'function' && el('ca-alerts-karte')) caZeichneAlerts();
  if (tv.chart) { tvPreisLinien(); tv.version = (tv.version || 0) + 1; tvSignaturZuruecksetzen(); }
  if (el('al-dialog').open && alDialogWert) alDialogZeichnen();
}

// Fenster: Alarm für einen Wert setzen, bestehende sehen und löschen
let alDialogWert = null;
async function alarmDialog(ticker, name) {
  alDialogWert = { ticker, name: name || ticker, kurs: null };
  el('al-titel').textContent = `Preisalarm · ${alDialogWert.name}`;
  el('al-meldung').textContent = '';
  el('al-preis').value = '';
  el('al-text').value = '';
  if (!el('al-dialog').open) el('al-dialog').showModal();
  alDialogZeichnen();
  const k = await fetch(`/api/chart/kurs?ticker=${encodeURIComponent(ticker)}`).then((r) => r.json()).catch(() => ({}));
  if (alDialogWert?.ticker !== ticker) return;
  alDialogWert.kurs = k.preis ?? null;
  if (k.preis) el('al-preis').placeholder = alPreis(k.preis);
  alDialogZeichnen();
  el('al-preis').focus();
}
function alDialogZeichnen() {
  const w = alDialogWert;
  el('al-unter').textContent = `${w.ticker} · Kurs ${w.kurs === null ? 'wird geladen …' : alPreis(w.kurs)} (Handelswährung)`;
  const eigene = alAlle.filter((a) => a.ticker === w.ticker);
  el('al-liste').innerHTML = eigene.length ? `<h3>Alarme für ${esc(w.ticker)}</h3>${eigene.map((a) => `<div class="al-zeile${a.erreicht ? ' erreicht' : ''}">
      <span>${esc(alBedingung(a))}${a.text ? ` <small>${esc(a.text)}</small>` : ''}</span>
      <span class="klein">${a.erreicht ? `erreicht${a.erreicht_am ? ` am ${esc(a.erreicht_am.slice(8, 10))}.${esc(a.erreicht_am.slice(5, 7))}.` : ''}` : a.abstand === null ? '' : `noch ${ggVz(a.abstand, gz1)} %`}</span>
      <button type="button" class="knopf al-weg" data-al-weg="${esc(a.id)}" aria-label="Alarm löschen">Löschen</button></div>`).join('')}` : '';
  const p = zaZahl(el('al-preis').value);
  el('al-richtung').textContent = p && w.kurs ? (p >= w.kurs ? `Meldet sich, wenn der Kurs über ${alPreis(p)} steigt (${ggVz((p / w.kurs - 1) * 100, gz1)} %).` : `Meldet sich, wenn der Kurs unter ${alPreis(p)} fällt (${ggVz((p / w.kurs - 1) * 100, gz1)} %).`) : 'Preis eingeben: liegt er über dem Kurs, meldet sich der Alarm beim Steigen, darunter beim Fallen.';
}
el('al-preis').addEventListener('input', alDialogZeichnen);
el('al-form').addEventListener('submit', async (e) => {
  e.preventDefault();
  const w = alDialogWert;
  const p = zaZahl(el('al-preis').value);
  if (!p || Number.isNaN(p) || p <= 0) { el('al-meldung').textContent = 'Bitte einen Preis eingeben.'; return; }
  const richtung = w.kurs ? (p >= w.kurs ? 'ueber' : 'unter') : 'ueber';
  const r = await alSenden('/api/chart/alerts', 'POST', { ticker: w.ticker, preis: p, richtung, text: el('al-text').value.trim() || '' });
  if (r.fehler) { el('al-meldung').textContent = r.fehler; return; }
  el('al-preis').value = ''; el('al-text').value = '';
  el('al-meldung').textContent = 'Gespeichert.';
  await alNeu();
});
el('al-dialog').addEventListener('click', (e) => {
  const r = el('al-dialog').getBoundingClientRect();
  if (e.target === el('al-dialog') && (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom)) el('al-dialog').close();
});
el('al-schliessen').addEventListener('click', () => el('al-dialog').close());
el('mf-alarm').addEventListener('click', () => { el('mf-dialog').close(); alarmDialog(mf.ticker, mf.name); });

// Löschen und Öffnen per Klick, überall auf der Seite
document.addEventListener('click', async (e) => {
  const weg = e.target.closest('[data-al-weg]');
  if (weg) {
    e.preventDefault(); e.stopPropagation();
    weg.disabled = true;
    const r = await alSenden(`/api/chart/alerts/${encodeURIComponent(weg.dataset.alWeg)}`, 'DELETE');
    if (r.fehler) alert(r.fehler);
    await alNeu();
    return;
  }
  const neu = e.target.closest('[data-al-neu]');
  if (neu) { e.preventDefault(); e.stopPropagation(); alarmDialog(neu.dataset.alNeu, neu.dataset.alName); }
}, true);

// Liste aller Alarme auf der Watchlist-Seite
function alListeZeichnen() {
  const box = el('w-alarme');
  if (!box) return;
  if (!alAlle.length) {
    box.innerHTML = `<div class="th-kopf"><h2>Preisalarme</h2><p class="sekundaer">Noch keine. Über die Glocke bei einem Wert, im Chart-Fenster („Preisalarm“) oder in der Chartanalyse (Alert-Linie) setzen.</p></div>`;
    return;
  }
  const sortiert = [...alAlle].sort((a, b) => Number(b.erreicht) - Number(a.erreicht) || Math.abs(a.abstand ?? 999) - Math.abs(b.abstand ?? 999));
  box.innerHTML = `<div class="th-kopf"><h2>Preisalarme</h2><p class="sekundaer">${alAlle.length} Alarme, ${alAlle.filter((a) => a.erreicht).length} erreicht. Kurse in der Handelswährung.</p></div>
    ${ggTabelle(['Wert', 'Bedingung', 'Kurs', 'Abstand', 'Status', ''], sortiert.map((a) => `<tr class="${a.erreicht ? 'gg-aktiv' : ''}">
      <td><button type="button" class="gg-zeilenknopf" data-mf="${esc(a.ticker)}" data-mf-name="${esc(a.name ?? a.ticker)}">${esc(a.name ?? a.ticker)}</button> <small>${esc(a.ticker)}${a.text ? ` · ${esc(a.text)}` : ''}</small></td>
      <td>${esc(alBedingung(a))}</td><td>${alPreis(a.kurs)}</td><td>${a.abstand === null ? '–' : `${ggVz(a.abstand, gz1)} %`}</td>
      <td>${a.erreicht ? `<b class="gold">erreicht${a.erreicht_am ? ` ${esc(a.erreicht_am.slice(8, 10))}.${esc(a.erreicht_am.slice(5, 7))}.` : ''}</b>` : a.kurs === null ? 'kein Kurs' : 'wartet'}</td>
      <td><button type="button" class="knopf ca-mini" data-al-weg="${esc(a.id)}" aria-label="Alarm löschen">×</button></td></tr>`), 'al-tabelle')}`;
}

// Erreicht: Hinweis oben rechts, einmal. Weggeklickt = quittiert (auf dem Server), dann nie wieder.
const alGezeigt = new Set();
function alHinweise() {
  const offen = alAlle.filter((a) => a.erreicht && !a.quittiert && !alGezeigt.has(a.id));
  for (const a of offen) {
    alGezeigt.add(a.id);
    const karte = document.createElement('div');
    karte.className = 'al-toast';
    karte.setAttribute('role', 'status');
    karte.innerHTML = `<span class="al-toast-glocke">${AL_GLOCKE}</span>
      <div><b>Preisalarm ${esc(a.name ?? a.ticker)}</b><span>${esc(alBedingung(a))} erreicht · Kurs ${alPreis(a.kurs_bei_erreichen ?? a.kurs)}</span></div>
      <button type="button" class="knopf" data-al-chart>Chart</button><button type="button" class="al-toast-zu" aria-label="Hinweis schließen">×</button>`;
    el('al-toasts').append(karte);
    const zu = () => { karte.classList.add('weg'); setTimeout(() => karte.remove(), 250); alSenden(`/api/chart/alerts/${encodeURIComponent(a.id)}/quittieren`, 'POST'); };
    karte.querySelector('.al-toast-zu').addEventListener('click', zu);
    karte.querySelector('[data-al-chart]').addEventListener('click', () => { zu(); mfOeffnen(a.ticker, a.name ?? a.ticker); });
    // Ohne Klick verschwindet er nach 20 Sekunden, kommt aber beim nächsten Öffnen von Vinter noch einmal (bis weggeklickt)
    setTimeout(() => { if (karte.isConnected) { karte.classList.add('weg'); setTimeout(() => karte.remove(), 250); } }, 20000);
  }
}

// ---- Mehr vom Markt (Definitionen früh, weil manche Seiten schon beim Start laden; Leiste am Dateiende) ----
const MW_SEKTOREN = ['XLK', 'XLF', 'XLV', 'XLE', 'XLI', 'XLY', 'XLP', 'XLU', 'XLB', 'XLRE', 'XLC'];
const MW_INDIZES = ['SPY', 'QQQ', 'IWM'];
const MW_INDIZES_EURO = ['QQQ', 'EXS1.DE', 'IWM'];  // für den Benchmark: S&P 500 und MSCI World sind schon dabei
const MW_SEITEN = {
  risiko: { gruppen: ['watchlist', 'sektoren', 'indizes'], nurMarkt: false, neu: () => ladeRisiko(), text: 'Weitere Werte erscheinen in „Wie ähnlich bewegen sich deine Werte?“ und im Vergleich zweier Werte, zählen aber nicht in Schwankung, VaR und Risikobeitrag deines Depots.' },
  benchmark: { gruppen: ['indizes'], nurMarkt: false, neu: () => ladeBenchmark(), hoechstens: 4, text: 'Weitere Vergleichswerte (höchstens 4), z. B. QQQ, EXS1.DE (DAX) oder ein Branchen-ETF. Alle in Euro gerechnet.' },
  volumen: { gruppen: ['watchlist', 'indizes'], nurMarkt: true, neu: () => ladeVolumen() },
  relativ: { gruppen: ['watchlist', 'sektoren'], nurMarkt: true, neu: () => ladeRelativ() },
  faktoren: { gruppen: ['watchlist', 'sektoren', 'indizes'], nurMarkt: false, neu: () => ladeFaktoren() },
  makro: { gruppen: ['watchlist', 'sektoren', 'indizes'], nurMarkt: false, neu: () => ladeMakroSens() },
  dcf: { gruppen: ['watchlist'], nurMarkt: true, neu: () => ladeDcf() },
  'earnings-moves': { gruppen: ['watchlist'], nurMarkt: true, neu: () => ladeEarningsMoves() },
  'earnings-sheet': { gruppen: ['watchlist'], nurMarkt: true, neu: () => ladeEarningsSheet() },
  fonds: { gruppen: ['watchlist'], nurMarkt: true, neu: () => { delete ggDaten.fonds; ggLaden('fonds', GG_SEITEN.fonds); } },
  signale: { gruppen: ['watchlist'], nurMarkt: false, neu: () => { delete ggDaten.signale; ggLaden('signale', GG_SEITEN.signale); } },
  nacht: { gruppen: ['watchlist', 'sektoren'], nurMarkt: true, neu: () => { delete ggDaten.nacht; ggLaden('nacht', GG_SEITEN.nacht); } },
};
const MW_GRUPPEN = { watchlist: 'Watchlist', sektoren: 'S&P-Sektoren', indizes: 'Indizes' };
const mwWahl = {};
for (const s in MW_SEITEN) {
  try { mwWahl[s] = JSON.parse(localStorage.getItem(`mw:${s}`) || 'null'); } catch { mwWahl[s] = null; }
  mwWahl[s] ??= { extra: [], depot: true };
}
let mwWatchlist = null;

// API-Pfad mit den zusätzlichen Werten
function mwPfad(seite, pfad) {
  const w = mwWahl[seite];
  if (!w || (!w.extra.length && w.depot)) return pfad;
  const teile = [];
  if (w.extra.length) teile.push(`extra=${encodeURIComponent(w.extra.join(','))}`);
  if (!w.depot && w.extra.length) teile.push('depot=false');
  return pfad + (pfad.includes('?') ? '&' : '?') + teile.join('&');
}

// Vorbörse: US-Aktien zählen vor der US-Eröffnung mit ihrem Kurs in Deutschland ("an")
// oder nur mit dem Handel in New York ("aus"). Gilt für Gewinn und Verlust und die Depot-Charts.
// Drei Ansichten für den Tageschart: "an" = mit Vorbörse (europäische Börsen ab 9 Uhr),
// "tr" = Trade Republic (jüngster Kurs aller freien Handelsplätze 8 bis 23 Uhr, ohne Krypto),
// "ny" = New York Open (nur die Bewegung seit der Eröffnung in New York).
let vorboerse = 'an';
try { const w = localStorage.getItem('vorboerse'); if (w === 'tr' || w === 'ny') vorboerse = w; } catch {}
const mitVorboerse = (pfad) => (vorboerse === 'tr' ? `${pfad}?tr=true` : vorboerse === 'ny' && pfad === '/api/tagesverlauf' ? `${pfad}?ny=true` : pfad);
const VORBOERSE_PFADE = ['/api/perioden', '/api/verlauf', '/api/verlauf/stunden', '/api/tagesverlauf'];

const klasse = (w) => (w > 0 ? 'plus' : w < 0 ? 'minus' : '');
const esc = (t) => String(t ?? '').replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
const artNamen = { STOCK: 'Aktie', FUND: 'ETF', CRYPTO: 'Krypto', DERIVATIVE: 'Derivat' };

// Hell/Dunkel merken. Der Speicher kann gesperrt sein, die Seite läuft dann trotzdem.
function setzeThema(thema) {
  document.documentElement.dataset.theme = thema;
}
el('thema')?.addEventListener('click', () => {
  setzeThema(document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark');
});
// Vinter gibt es nur noch dunkel (Wunsch vom 16.11.2026).

function meldungen(texte) {
  el('meldungen').innerHTML = texte.map((t) => `<p class="meldung">${esc(t)}</p>`).join('');
}

function setzeWert(id, text, wert) {
  el(id).textContent = text;
  el(id).className = `kennzahl ${klasse(wert)}`;
}

const AKTUALITAET = { echtzeit: 'Echtzeit', verzoegert: 'Verzögert', schluss: 'Schlusskurs' };

// Zeit des letzten Abrufs: heute nur die Uhrzeit, sonst mit Datum.
const tagMonat = new Intl.DateTimeFormat('de-DE', { day: '2-digit', month: '2-digit' });
const zeitText = (iso) => {
  const d = new Date(iso);
  return isoLokal(d) === isoLokal(new Date()) ? uhrzeit.format(d) : `${tagMonat.format(d)} ${uhrzeit.format(d)}`;
};
const neuesteZeit = (liste) => liste.map((x) => x.aktualisiert).filter(Boolean).sort().at(-1);

// Stammt der Kurs von einem früheren Handelstag, zählt dessen Datum, nicht der Abruf.
function kursZeit(p) {
  if (!p.kurs_aktualisiert) return '';
  return p.kurs_stand && p.kurs_stand < isoLokal(new Date()) ? tagMonat.format(lokal(p.kurs_stand)) : zeitText(p.kurs_aktualisiert);
}
// Bei US-Werten vor der US-Eröffnung steht dazu, dass der Kurs von einer deutschen Börse kommt.
const mitZeit = (text, p) => [p.kurs_handelsplatz || text, kursZeit(p)].filter(Boolean).join(' · ');
const aktualitaetHtml = (p) => {
  const a = p.kurs_aktualitaet;
  return AKTUALITAET[a] ? `<span class="klein">${a === 'echtzeit' ? '<span class="plus led">Echtzeit</span>' : (p.kurs_handelsplatz ? esc(p.kurs_handelsplatz) : AKTUALITAET[a])}${kursZeit(p) ? ` · ${kursZeit(p)}` : ''}</span>` : '';
};

// Führt zur Chart-Seite des Werts bei Yahoo. Ohne Ticker bleibt die Zeile ein normaler Eintrag.
const yahooLink = (ticker) => `https://finance.yahoo.com/quote/${encodeURIComponent(ticker)}/chart/`;
function wertZeile(klassen, ticker, inhalt, titel = '', fenster = null) {
  if (!ticker) return `<div class="${klassen}">${inhalt}</div>`;
  // Klick öffnet das Chart-Fenster (Markt-Fenster), Strg+Klick wie bisher Yahoo Finance
  const mfAttr = ` data-mf="${esc(ticker)}" data-mf-name="${esc(fenster ?? ticker)}"`;
  return `<a class="${klassen} wert-link" href="${esc(yahooLink(ticker))}" target="_blank" rel="noopener"${mfAttr}${titel ? ` title="${esc(titel)}"` : ''}>${inhalt}</a>`;
}

// KGV-Bewertung: kommt getrennt vom Server, damit die Kurse nicht auf Yahoo-Stammdaten warten.
let bewertung = null; // null = noch nicht geladen
let positionenListe = [];
const URTEIL = { billig: ['Billig', 'plus'], normal: ['Normal', ''], teuer: ['Teuer', 'minus'] };

function kgvTexte(p) {
  if (p.art !== 'STOCK') return null;
  if (!bewertung) return { wert: '…', unter: '' };
  const b = bewertung[p.ticker];
  if (b?.urteil === 'verlust') return { wert: 'k. A.', unter: 'Verlust', titel: 'Das Unternehmen macht Verlust, ein KGV ergibt hier keinen Sinn.' };
  if (!b?.kgv) return { wert: 'k. A.', unter: '<span class="alt">kein KGV</span>' };
  const titel = `${b.sektor ? `Sektor ${b.sektor}` : 'Sektor unbekannt'}${b.sektor_kgv ? `, KGV ${eps.format(b.sektor_kgv)}` : ''}${b.kgv_erwartet ? `. Erwartetes KGV ${eps.format(b.kgv_erwartet)}` : ''}`;
  const [text, farbe] = URTEIL[b.urteil] ?? [];
  const unter = text ? `<span class="${farbe}">${text}</span> · Ø ${eps.format(b.sektor_kgv)}` : 'Sektor fehlt';
  return { wert: eps.format(b.kgv), unter, titel };
}

function zeichnePositionen() {
  el('positionen').innerHTML = positionenListe.map(zeile).join('');
  posSpuren();
}

function zeile(p) {
  const hatKurs = p.kurs_eur !== null;
  const k = kgvTexte(p);
  const titel = k?.titel ? ` title="${esc(k.titel)}"` : '';
  const gv = hatKurs
    ? `<span class="${klasse(p.gv_eur)}">${plusEuro.format(p.gv_eur)}<span class="klein ${klasse(p.gv_eur)}">${prozent.format(p.gv_prozent)} %</span></span>`
    : '<span class="klein">–</span>';
  const kurs = hatKurs
    ? `${euro.format(p.kurs_eur)}${p.kurs_status === 'veraltet' ? `<span class="klein alt">${esc(mitZeit('veraltet', p))}</span>` : aktualitaetHtml(p)}`
    : '<span class="klein alt">kein Kurs</span>';
  const art = artNamen[p.art] ?? p.art;
  return wertZeile('zeile', p.ticker, `
    <span>
      <span class="name" style="display:block">${esc(p.name)}</span>${p.ticker ? `<span class="pos-spur" data-spur="${esc(p.ticker)}" aria-hidden="true"></span>` : ''}
      <span class="klein spalte-breit">${esc(art)}${p.ticker ? ` · ${esc(p.ticker)}` : ''}</span>
      <span class="klein nur-mobil">${zahl.format(p.stueck)} Stück · ${euro.format(p.einstand_stueck)}</span>
      ${hatKurs ? `<span class="klein nur-mobil">${esc(mitZeit(AKTUALITAET[p.kurs_aktualitaet], p))}</span>` : ''}
      ${k ? `<span class="klein nur-mobil">KGV ${k.wert}${k.unter ? ` · ${k.unter}` : ''}</span>` : ''}
    </span>
    <span class="spalte-breit">${zahl.format(p.stueck)}</span>
    <span class="spalte-breit">${euro.format(p.einstand_stueck)}</span>
    <span class="spalte-breit">${kurs}</span>
    <span class="spalte-breit">${hatKurs ? euro.format(p.wert_eur) : '–'}</span>
    <span class="spalte-breit"${titel}>${k ? `${k.wert}<span class="klein">${k.unter}</span>` : '–'}</span>
    <span>
      <span class="nur-mobil">${hatKurs ? euro.format(p.wert_eur) : 'kein Kurs'}</span>
      ${gv}
    </span>`, 'Chart öffnen (Strg+Klick: Yahoo Finance)');
}

const positionenStatus = (d) => `${d.positionen.length} Positionen · Kurse aktualisiert ${d.kurse_aktualisiert ? zeitText(d.kurse_aktualisiert) : d.abgerufen} Uhr`;

async function lade() {
  let d;
  try {
    d = await api('/api/portfolio');
  } catch {
    el('status').textContent = el('g-status').textContent = 'Die Daten konnten nicht geladen werden. Läuft der Server noch?';
    return;
  }
  if (d.fehler) {
    el('status').textContent = '';
    el('g-status').textContent = d.fehler;
    meldungen([d.fehler]);
    return;
  }

  const s = d.summen;
  el('status').textContent = positionenStatus(d);
  const hinweise = [...d.warnungen];
  if (s.ohne_kurs) hinweise.push(`Für ${s.ohne_kurs} Position(en) gibt es gerade keinen Kurs. Sie fehlen im Depotwert.`);
  meldungen(hinweise);

  setzeWert('wert', euro.format(s.wert), 0);
  el('einstand').textContent = `Einstand ${euro.format(s.einstand)}`;
  setzeWert('gv', plusEuro.format(s.gesamt), s.gesamt);
  el('gv-prozent').textContent = ergebnisDetail(s);

  const jahr = d.realisiert.find((r) => r.jahr === new Date().getFullYear());
  setzeWert('real', plusEuro.format(jahr ? jahr.gewinn : 0), jahr ? jahr.gewinn : 0);
  el('real-details').textContent = d.realisiert.length
    ? d.realisiert.map((r) => `${r.jahr}: ${plusEuro.format(r.gewinn)}`).join(' · ')
    : 'Noch keine Verkäufe';

  positionenListe = d.positionen;
  zeichnePositionen();
  el('karten').hidden = el('tabelle').hidden = el('hinweis').hidden = false;
  fuelleGesamt(d, jahr);
}

async function ladeBewertung() {
  let d = {};
  try { d = await api('/api/bewertung'); } catch {}
  // Bei einem Ausfall bleibt ein alter Stand stehen, sonst zeigen die Zeilen "kein KGV".
  if (d.werte) bewertung = d.werte;
  else bewertung ??= {};
  zeichnePositionen();
}

// ---- Kalender ----
const tagNamen = ['Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa', 'So'];
const eps = new Intl.NumberFormat('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const deutschKurz = new Intl.DateTimeFormat('de-DE', { day: 'numeric', month: 'short' });
const lokal = (iso) => { const [j, m, t] = iso.split('-').map(Number); return new Date(j, m - 1, t); };
const isoLokal = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
const plusTage = (d, n) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);
const montag = (d) => plusTage(d, -((d.getDay() + 6) % 7));

function kalenderwoche(mo) {
  const donnerstag = plusTage(mo, 3);
  const jahresstart = new Date(donnerstag.getFullYear(), 0, 1);
  return Math.floor((donnerstag - jahresstart) / 604800000) + 1;
}

function umsatz(w) {
  if (w >= 1e9) return `${eps.format(w / 1e9)} Mrd.`;
  return `${eps.format(w / 1e6)} Mio.`;
}

function makroTermin(t) {
  const werte = [t.erwartung !== null ? `Erw. ${t.erwartung}` : '', t.tatsaechlich !== null ? `Ist ${t.tatsaechlich}${t.automatisch ? ` (${t.automatisch})` : ''}` : ''].filter(Boolean).join(' · ');
  const zeit = [t.uhrzeit ? `${t.uhrzeit} Uhr` : '', t.wichtigkeit === 'hoch' ? 'wichtig' : ''].filter(Boolean).join(' · ');
  return `<button type="button" class="termin makro klickbar" ${terminAttribut(t)}><b>${esc(t.name)}</b>
    ${zeit ? `<small>${esc(zeit)}</small>` : ''}${werte ? `<small>${esc(werte)}</small>` : ''}
  </button>`;
}

// Jeder Termin merkt sich seine Daten, die Detailansicht findet sie über das Attribut wieder.
const terminRegister = new Map();
function terminAttribut(t) {
  const schluessel = `${t.datum}|${t.makro ? 'makro' : 'earnings'}|${t.ticker ?? t.name}`;
  terminRegister.set(schluessel, t);
  return `data-termin="${esc(schluessel)}"`;
}

function termin(t) {
  if (t.makro) return makroTermin(t);
  const e = t.ergebnis;
  const zeit = t.ipo ? 'Eigener IPO-Termin' : e ? ['Gemeldet', t.sitzung].filter(Boolean).join(' · ')
    : t.zeit_de ? `${t.zeit_de} Uhr · ${t.sitzung}` : t.zeitraum ? 'Termin geschätzt' : t.sitzung ? t.sitzung : 'Uhrzeit offen';
  const zahlen = e
    ? `EPS ${eps.format(e.ist)}${e.ueberraschung === null ? '' : ` <span class="${klasse(e.ueberraschung)}">${prozent.format(e.ueberraschung)} %</span>`}`
    : esc([
      t.eps !== null && t.eps !== undefined ? `EPS ${eps.format(t.eps)}` : '',
      t.umsatz ? `Umsatz ${umsatz(t.umsatz)}` : '',
    ].filter(Boolean).join(' · '));
  const abw = t.abweichung && !e ? `<small class="alt">FMP nennt ${deutschKurz.format(lokal(t.abweichung))}</small>` : '';
  const bezug = t.bezug.length ? `<small>wegen ${esc(t.bezug.join(', '))}</small>` : t.markt && t.boersenwert ? `<small>${gz0.format(t.boersenwert / 1e9)} Mrd. $ Börsenwert</small>` : '';
  const neu = t.meldungen?.length ? '<small class="termin-neu">Meldungen da</small>' : '';
  return `<button type="button" class="termin klickbar ${t.eigen ? 'eigen' : ''}${t.markt ? ' markt' : ''}" ${terminAttribut(t)}>
    <b>${esc(t.name)}</b><small>${esc(zeit)}</small>
    ${neu}${zahlen ? `<small>${zahlen}</small>` : ''}${bezug}${abw}
  </button>`;
}

// ---- Detailansicht eines Termins ----
const langesDatum = new Intl.DateTimeFormat('de-DE', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });

function detailZeile(name, wert, unter = '', farbe = '') {
  return `<div class="reihe"><span>${esc(name)}</span><span class="${farbe}">${wert}${unter ? `<span class="klein">${unter}</span>` : ''}</span></div>`;
}

const spanneText = (s, format) => (s?.[0] != null && s?.[1] != null ? `Spanne ${format(s[0])} bis ${format(s[1])}` : '');

function gemeldetHtml(e) {
  const zeile = (name, ist, erwartet, abw, format) => (ist == null ? '' : detailZeile(
    name,
    `${format(ist)}${abw == null ? '' : ` · ${prozent.format(abw)} %`}`,
    erwartet == null ? '' : `erwartet ${format(erwartet)}`,
    klasse(abw ?? 0),
  ));
  return `<h3>Gemeldete Zahlen</h3>
    ${zeile('Gewinn je Aktie (EPS)', e.ist, e.erwartet, e.ueberraschung, (w) => eps.format(w))}
    ${zeile('Umsatz', e.umsatz, e.umsatz_erwartet, e.umsatz_ueberraschung, umsatz)}`;
}

function erwartetHtml(t) {
  const jetzt = new Date();
  const heute = isoLokal(jetzt);
  const uhr = `${String(jetzt.getHours()).padStart(2, '0')}:${String(jetzt.getMinutes()).padStart(2, '0')}`;
  const ueberfaellig = t.datum < heute || (t.datum === heute && t.zeit_de && uhr > t.zeit_de);
  const zeilen = [
    t.eps == null ? '' : detailZeile('Gewinn je Aktie (EPS)', eps.format(t.eps), spanneText(t.eps_spanne, (w) => eps.format(w))),
    t.umsatz ? detailZeile('Umsatz', umsatz(t.umsatz), spanneText(t.umsatz_spanne, umsatz)) : '',
  ].join('');
  const meldungen = t.meldungen ?? [];
  return `${meldungen.length ? `<h3>Erste Meldungen</h3>${meldungen.map(meldungHtml).join('')}
      <p class="hinweis">Schlagzeilen aus Google News, bis die genauen Zahlen in den Daten sind.</p>` : ''}
    <h3>Erwartet</h3>
    ${zeilen || '<p class="sekundaer">Für diesen Termin gibt es keine Schätzungen.</p>'}
    ${ueberfaellig && !meldungen.length ? '<p class="hinweis">Der Termin ist vorbei, die Zahlen sind aber noch nicht in den Daten. Sie erscheinen hier, sobald die Quelle sie liefert.</p>' : ''}`;
}

const sichererLink = (l) => (/^https?:\/\//i.test(l ?? '') ? l : '');
const uhrzeit = new Intl.DateTimeFormat('de-DE', { hour: '2-digit', minute: '2-digit' });

function meldungHtml(m) {
  const titel = sichererLink(m.link)
    ? `<a class="reihe-name" href="${esc(m.link)}" target="_blank" rel="noopener">${esc(m.titel)}</a>`
    : `<span class="reihe-name">${esc(m.titel)}</span>`;
  return `<div class="reihe k-meldung"><span>${titel}<span class="klein">${esc(m.quelle)} · ${uhrzeit.format(new Date(m.zeit))} Uhr</span></span></div>`;
}

function zeigeTermin(t) {
  const datum = langesDatum.format(lokal(t.datum));
  el('k-titel').textContent = t.name;
  const link = el('k-link');
  link.hidden = Boolean(t.makro);
  if (t.makro) {
    el('k-unter').textContent = [datum, t.uhrzeit ? `${t.uhrzeit} Uhr` : '', t.wichtigkeit === 'hoch' ? 'wichtig' : ''].filter(Boolean).join(' · ');
    const zeilen = [
      t.erwartung !== null ? detailZeile('Erwartung', esc(t.erwartung)) : '',
      t.tatsaechlich !== null ? detailZeile('Tatsächlich', `${esc(t.tatsaechlich)}${t.automatisch ? ` <small class="sekundaer">automatisch aus ${esc(t.automatisch)} (Makro-Daten); ein eigener Eintrag in makro_termine.yaml hat Vorrang</small>` : ''}`) : '',
    ].join('');
    el('k-inhalt').innerHTML = zeilen || '<p class="sekundaer">Noch keine Werte eingetragen. Du pflegst sie in daten/markt/makro_termine.yaml.</p>';
  } else {
    const zeit = t.zeit_de ? `${t.zeit_de} Uhr` : '';
    el('k-unter').textContent = [t.ticker, datum, zeit, t.sitzung, t.bezug.length ? `wegen ${t.bezug.join(', ')}` : ''].filter(Boolean).join(' · ');
    el('k-inhalt').innerHTML = t.ergebnis ? gemeldetHtml(t.ergebnis) : erwartetHtml(t);
    link.href = `https://finance.yahoo.com/quote/${encodeURIComponent(t.ticker)}/analysis/`;
  }
  el('k-dialog').showModal();
}

document.addEventListener('click', (e) => {
  const knopf = e.target.closest('[data-termin]');
  const t = knopf && terminRegister.get(knopf.dataset.termin);
  if (t) zeigeTermin(t);
});
el('k-schliessen').addEventListener('click', () => el('k-dialog').close());
el('k-dialog').addEventListener('click', (e) => {
  // Ein Klick neben das Fenster trifft den Hintergrund, der zum Dialog selbst zählt.
  const r = el('k-dialog').getBoundingClientRect();
  if (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom) el('k-dialog').close();
});

function woche(mo, termine, heute) {
  const tage = [];
  for (let i = 0; i < 7; i++) {
    const iso = isoLokal(plusTage(mo, i));
    const liste = termine.filter((t) => t.datum === iso);
    if (i < 5 || liste.length) tage.push({ i, iso, liste });
  }
  const ende = plusTage(mo, 6);
  const spalten = tage.map((t) => `<div class="tag ${t.iso === heute ? 'heute' : ''} ${t.liste.length ? '' : 'tag-leer'}">
      <div class="tag-kopf">${tagNamen[t.i]} ${lokal(t.iso).getDate()}.</div>${t.liste.map(termin).join('')}
    </div>`).join('');
  return `<section class="woche">
    <h2>KW ${kalenderwoche(mo)}<span>${deutschKurz.format(mo)} bis ${deutschKurz.format(ende)}</span></h2>
    <div class="tage" style="grid-template-columns:repeat(${tage.length},minmax(0,1fr))">${spalten}</div>
  </section>`;
}

// Holt Earnings und Makro getrennt: Fällt eine Quelle aus, bleibt die andere sichtbar.
async function alleTermine() {
  const [e, m] = await Promise.allSettled([api('/api/earnings'), api('/api/makro')]);
  const termine = [];
  const hinweise = [];
  if (e.status === 'fulfilled' && !e.value.fehler) {
    termine.push(...e.value.termine);
    hinweise.push(...e.value.meldungen);
  } else {
    hinweise.push(e.value?.fehler ?? 'Die Earnings-Termine konnten nicht geladen werden. Läuft der Server noch?');
  }
  if (m.status === 'fulfilled' && !m.value.fehler) {
    termine.push(...m.value.termine.map((t) => ({ ...t, makro: true })));
    hinweise.push(...m.value.meldungen);
  } else {
    hinweise.push(m.value?.fehler ?? 'Die Makro-Termine konnten nicht geladen werden. Läuft der Server noch?');
  }
  termine.sort((a, b) => a.datum.localeCompare(b.datum) || Number(Boolean(b.makro)) - Number(Boolean(a.makro)));
  return { termine, hinweise };
}

let kalenderGeladen = false;
async function ladeKalender() {
  if (kalenderGeladen) return;
  kalenderGeladen = true;
  const { termine, hinweise } = await alleTermine();

  kalTermine = termine;
  el('kal-meldungen').innerHTML = hinweise.map((t) => `<p class="meldung">${esc(t)}</p>`).join('');
  zeichneKalender();
  el('kal-hinweis').hidden = false;
}

// Zeichnet die Wochen neu. Der Filter braucht dafür keine neue Serverabfrage.
let kalTermine = null;
let kalFilter = 'alle';
try { kalFilter = localStorage.getItem('kalFilter') || 'alle'; } catch {}

function zeigeFilterStatus() {
  document.querySelectorAll('#kal-filter button').forEach((b) => {
    b.setAttribute('aria-pressed', String(b.dataset.filter === kalFilter));
  });
}
el('kal-filter').addEventListener('click', (e) => {
  const knopf = e.target.closest('button');
  if (!knopf) return;
  kalFilter = knopf.dataset.filter;
  try { localStorage.setItem('kalFilter', kalFilter); } catch {}
  zeigeFilterStatus();
  if (kalTermine) zeichneKalender();
});
zeigeFilterStatus();

// "Ganzer Markt": Earnings aller großen Firmen (nasdaq.com), erst beim ersten Umschalten geladen
let kalMarkt = null;
async function kalMarktLaden() {
  kalMarkt = 'lädt';
  el('kal-status').textContent = 'Termine des ganzen Marktes werden geladen …';
  let d;
  try { d = await api('/api/earnings/markt'); } catch { d = { fehler: 'Der Server antwortet gerade nicht.' }; }
  kalMarkt = d.fehler ? { termine: [], fehler: d.fehler } : d;
  zeichneKalender();
}

function zeichneKalender() {
  const jetzt = new Date();
  const heute = isoLokal(jetzt);
  const bis = plusTage(jetzt, 28);
  const erste = montag(jetzt);
  if (kalFilter === 'markt' && kalMarkt === null) kalMarktLaden();
  let quelle = kalTermine;
  if (kalFilter === 'markt') {
    const eigene = new Set(kalTermine.filter((t) => !t.makro).map((t) => t.ticker));
    quelle = [...kalTermine.filter((t) => !t.makro), ...((kalMarkt?.termine) ?? []).filter((t) => !eigene.has(t.ticker))]
      .sort((a, b) => a.datum.localeCompare(b.datum) || Number(b.eigen) - Number(a.eigen) || (b.boersenwert ?? 0) - (a.boersenwert ?? 0));
  }
  const sichtbar = quelle.filter((t) => t.datum >= isoLokal(erste) && t.datum <= isoLokal(bis)
    && (kalFilter === 'alle' || kalFilter === 'markt' || (kalFilter === 'makro') === Boolean(t.makro)));
  const eigene = sichtbar.filter((t) => t.eigen).length;
  const makro = sichtbar.filter((t) => t.makro).length;
  el('kal-status').textContent = kalFilter === 'makro'
    ? `${makro} Makro-Termine`
    : kalFilter === 'markt'
      ? (kalMarkt === 'lädt' ? 'Termine des ganzen Marktes werden geladen …' : kalMarkt?.fehler ? kalMarkt.fehler
        : `${sichtbar.length} Earnings-Termine: deine ${eigene} Werte und alle Firmen ab ${gz0.format((kalMarkt?.mindest ?? 2e10) / 1e9)} Mrd. $ Börsenwert (nasdaq.com)`)
      : `${sichtbar.length} Termine, davon ${eigene} eigene Werte${kalFilter === 'alle' ? ` und ${makro} Makro-Termine` : ''}`;

  let html = '';
  for (let mo = erste; mo <= montag(bis); mo = plusTage(mo, 7)) {
    const start = isoLokal(mo);
    const ende = isoLokal(plusTage(mo, 6));
    html += woche(mo, sichtbar.filter((t) => t.datum >= start && t.datum <= ende), heute);
  }
  el('kal-wochen').innerHTML = html;
}

// ---- Märkte ----
const komma2 = new Intl.NumberFormat('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const komma4 = new Intl.NumberFormat('de-DE', { minimumFractionDigits: 4, maximumFractionDigits: 4 });
const bpFormat = new Intl.NumberFormat('de-DE', { maximumFractionDigits: 0, signDisplay: 'always' });

function marktWert(k) {
  if (k.art === 'rendite') return `${komma2.format(k.wert)} %`;
  if (k.art === 'fx') return komma4.format(k.wert);
  if (k.art === 'roh') return `${komma2.format(k.wert)} $`;
  return komma2.format(k.wert);
}
function marktAenderung(k, w) {
  if (w === null || w === undefined) return '–';
  return k.art === 'rendite' ? `${bpFormat.format(w)} Bp` : `${prozent.format(w)} %`;
}
const marktFarbe = (k, w) => (['index', 'roh'].includes(k.art) && w ? klasse(w) : '');

// Der VIX-Wert übernimmt die Farbe seiner Stufe auf der Skala.
const vixFarbe = (k) => (k.ticker === '^VIX' && k.skala ? `t${k.skala.stufe}` : '');

function skalaHtml(k) {
  const s = k.skala;
  if (!s) return '';
  return `<div class="skala" role="img" aria-label="${esc(k.name)}: ${esc(s.label)}">
    <div class="skala-label t${s.stufe}">${esc(s.label)}</div>
    <div class="skala-balken">${s.zonen.map((z) => `<span class="z${z.stufe}" style="flex:${z.breite}" title="${esc(z.name)}"></span>`).join('')}<i style="left:${s.position}%"></i></div>
    <div class="skala-ende"><span>${esc(s.links)}</span><span>${esc(s.rechts)}</span></div>
  </div>`;
}

// ---- Leiste oben: wechselt ruhig zwischen Märkten, größten Positionen und frischen Zahlen ----
const kopf = { maerkte: '', watchlist: '', exits: '', alerts: '', schlagzeile: '', zahlen: '', mover: '', heute: '', positionen: '', handel: '' };
const KOPF_ZIEL = { handel: '#handel', alerts: '#chartanalyse', maerkte: '#maerkte', zahlen: '#kalender', mover: '#maerkte', heute: '#kalender', positionen: '#uebersicht', exits: '#exits' };
let kopfSchlagzeile = null; // nur diese Folie führt auf eine fremde Seite
const kopfGesehen = new Set();
let kopfIndex = 0;
let kopfPause = false;
// LIVE-Hinweise (Reden gerade live, Prognosen mit großem Sprung) wechseln sich mit den normalen Folien ab.
let kopfLive = [];
let kopfLiveIndex = 0;
let kopfLiveDran = false;

function zeichneKopf() {
  if (kopfLiveDran && kopfLive.length) {
    const l = kopfLive[kopfLiveIndex % kopfLive.length];
    el('kopf-markt').innerHTML = `<a class="kopf-link" href="${esc(l.ziel)}" title="${esc(l.titel)}"><span class="kopf-item kopf-titel kopf-live"><em class="led">Live</em><b>${esc(l.text)}</b></span></a>`;
    return;
  }
  const folien = Object.keys(kopf).filter((k) => kopf[k]);
  if (!folien.length) return;
  const folie = folien[kopfIndex % folien.length];
  const leiste = el('kopf-markt');
  // Top und Flop sowie die Watchlist haben je Wert einen eigenen Link, jede andere Folie ist ein einziger Link.
  if (folie === 'mover' || folie === 'watchlist') {
    leiste.innerHTML = kopf[folie];
    return;
  }
  const extern = folie === 'schlagzeile' && sichererLink(kopfSchlagzeile?.link);
  const titel = folie === 'schlagzeile' ? ` title="${esc(`${kopfSchlagzeile.titel} (${kopfSchlagzeile.quelle})`)}"` : '';
  leiste.innerHTML = `<a class="kopf-link" href="${esc(extern || KOPF_ZIEL[folie])}"${extern ? ' target="_blank" rel="noopener"' : ''}${titel}>${kopf[folie]}</a>`;
}

async function ladeKopf() {
  let d;
  try {
    d = await api('/api/kopf');
  } catch {
    return; // Die Leiste kommt auch ohne diese Folien aus.
  }
  const name = (m, wort) => `<a class="kopf-item" href="${esc(yahooLink(m.ticker))}" target="_blank" rel="noopener" title="Chart von ${esc(m.name)} bei Yahoo Finance öffnen"><em>${wort} ${esc(kurzName(m.name))}</em><b class="${klasse(m.prozent)}">${prozent.format(m.prozent)} %</b></a>`;
  kopf.mover = d.mover.map((m) => name(m, m.prozent > 0 ? 'Top' : 'Flop')).join('');
  kopfSchlagzeile = d.schlagzeile;
  kopf.handel = (d.handel ?? []).length ? `<span class="kopf-item"><em>Neue Handelsdaten</em><b>${d.handel.slice(0, 2).map((x) => `${esc(x.quelle_name.split(',')[0].split(' (')[0])} ${esc(x.zeitraum_text)}`).join(' · ')}</b></span>` : '';

  // Eine wirklich neue Top-Meldung wird sofort gezeigt und bis zum nächsten Abruf als neu markiert.
  // Springt Google zu einer schon bekannten Meldung zurück, zählt das nicht.
  const titel = d.schlagzeile?.titel;
  const neu = titel && kopfGesehen.size > 0 && !kopfGesehen.has(titel);
  if (titel) kopfGesehen.add(titel);
  kopf.schlagzeile = titel ? `<span class="kopf-item kopf-titel">${neu ? '<em>Neu</em>' : ''}<b>${esc(titel)}</b></span>` : '';
  if (neu && !kopfPause) kopfIndex = Object.keys(kopf).filter((k) => kopf[k]).indexOf('schlagzeile');
  zeichneKopf();
}

// LIVE in der Laufleiste: wichtige Sprecher, die gerade reden, und verfolgte Prognosen mit großem Sprung.
const LIVE_GRUPPEN = new Set(['Fed', 'EZB', 'Notenbanken', 'Trump & US-Regierung']);
const PROGNOSE_SPRUNG = 5; // Prozentpunkte seit gestern
async function ladeKopfLive() {
  const hole = async (pfad) => { delete antworten[pfad]; try { const d = await api(pfad); return d?.fehler ? null : d; } catch { return null; } };
  const [zitate, prog] = await Promise.all([hole('/api/zitate'), hole('/api/prognosen/kurz')]);
  const neu = [];
  for (const a of zitate?.auftritte ?? []) {
    if (!a.live || !LIVE_GRUPPEN.has(a.kategorie)) continue;
    const letztes = a.zitate.at(-1).text;
    neu.push({ text: `${a.wer} spricht: „${letztes}“`, titel: `${a.wer}, ${a.zitate.length} Aussagen bisher`, ziel: '#news' });
  }
  for (const s of prog?.fed?.sitzungen ?? []) {
    const v = s.veraenderung_erhoehung?.tag;
    if (v != null && Math.abs(v) >= PROGNOSE_SPRUNG) neu.push({ text: `Fed ${datumDe(s.datum)}: Erhöhung jetzt ${Math.round(s.erhoehung * 100)} % (${pkt.format(v)} Pkt. seit gestern)`, titel: 'Fed-Wahrscheinlichkeit', ziel: '#prognosen' });
  }
  for (const m of prog?.eigene ?? []) {
    const v = m.veraenderung?.tag;
    const p = m.art === 'ja_nein' ? m.p : m.antworten?.[0]?.p;
    if (v != null && Math.abs(v) >= PROGNOSE_SPRUNG) neu.push({ text: `${m.frage}: ${Math.round((p ?? 0) * 100)} % (${pkt.format(v)} Pkt. seit gestern)`, titel: 'Verfolgte Prognose', ziel: '#prognosen' });
  }
  kopfLive = neu;
}

// Was heute noch ansteht. Bereits gemeldete Earnings zeigt die Folie mit den Zahlen.
function kopfHeute(termine) {
  const jetzt = new Date();
  const heute = isoLokal(jetzt);
  const uhr = uhrzeit.format(jetzt);
  kopf.heute = termine
    .filter((t) => t.datum === heute && !t.ergebnis && (t.makro ? t.uhrzeit : t.zeit_de) >= uhr)
    .sort((a, b) => (a.makro ? a.uhrzeit : a.zeit_de).localeCompare(b.makro ? b.uhrzeit : b.zeit_de))
    .slice(0, 3)
    .map((t) => `<span class="kopf-item"><em>Heute ${t.makro ? t.uhrzeit : t.zeit_de}</em><b>${esc(kurzName(t.name))}</b></span>`)
    .join('');
  zeichneKopf();
}

setInterval(() => {
  const anzahl = Object.values(kopf).filter(Boolean).length;
  if (kopfPause || document.hidden || (anzahl < 2 && !kopfLive.length)) return;
  // Gibt es etwas Live, kommt es nach jeder normalen Folie einmal dran.
  if (kopfLive.length && !kopfLiveDran) { kopfLiveDran = true; kopfLiveIndex += 1; }
  else { kopfLiveDran = false; kopfIndex = (kopfIndex + 1) % Math.max(anzahl, 1); }
  el('kopf-markt').classList.add('wechsel');
  setTimeout(() => { zeichneKopf(); el('kopf-markt').classList.remove('wechsel'); }, 180);
}, 8000);

// Beim Lesen oder Anklicken bleibt die Leiste stehen.
for (const [ereignis, pause] of [['mouseenter', true], ['mouseleave', false], ['focusin', true], ['focusout', false]]) {
  el('kopf-markt').addEventListener(ereignis, () => { kopfPause = pause; });
}

function kopfPositionen(d) {
  const keineEinzelwerte = ['Breiter ETF', 'Rohstoffe', 'Krypto'];
  const werte = new Map();
  Object.entries(d.sektor_positionen).filter(([n]) => !keineEinzelwerte.includes(n))
    .forEach(([, liste]) => liste.forEach((p) => werte.set(p.ticker, p)));
  kopf.positionen = [...werte.values()].sort((a, b) => b.anteil - a.anteil).slice(0, 3).map((p) => (
    `<span class="kopf-item"><em>${esc(kurzName(p.name))}</em><b class="${p.tag ? klasse(p.tag) : ''}">${p.tag === undefined || p.tag === null ? '–' : `${prozent.format(p.tag)} %`}</b></span>`
  )).join('');
  zeichneKopf();
}

async function ladeZahlen() {
  let d;
  try {
    d = await api('/api/zahlen');
  } catch {
    return; // Die Leiste kommt auch ohne Zahlen aus.
  }
  if (d.fehler) return;
  kopf.zahlen = d.zahlen.slice(0, 2).map((z) => {
    const erwartet = z.erwartet === null ? '' : ` <em>erw. ${eps.format(z.erwartet)}</em>`;
    const ueberraschung = z.ueberraschung === null ? '' : ` <b class="${klasse(z.ueberraschung)}">${prozent.format(z.ueberraschung)} %</b>`;
    return `<span class="kopf-item"><em>${esc(kurzName(z.name))}</em><b>EPS ${eps.format(z.ist)}</b>${erwartet}${ueberraschung}</span>`;
  }).join('');
  zeichneKopf();
}

function kopfLeiste(alle) {
  const finde = (t) => alle.find((k) => k.ticker === t && k.wert !== null);
  const teile = [];
  const vix = finde('^VIX');
  if (vix) teile.push(`<span class="kopf-item kopf-mf" data-mf="^VIX" data-mf-name="VIX" role="button" tabindex="0" title="Chart öffnen"><em>VIX</em><b class="${vixFarbe(vix)}">${komma2.format(vix.wert)}</b> <b class="t${vix.skala.stufe}">${esc(vix.skala.label)}</b></span>`);
  for (const [ticker, name] of [['^GSPC', 'S&amp;P'], ['^GDAXI', 'DAX'], ['^IXIC', 'Nasdaq']]) {
    const k = finde(ticker);
    if (k) teile.push(`<span class="kopf-item kopf-mf" data-mf="${ticker}" data-mf-name="${esc(k.name)}" role="button" tabindex="0" title="Chart öffnen"><em>${name}</em><b class="${marktFarbe(k, k.tag)}">${marktAenderung(k, k.tag)}</b></span>`);
  }
  kopf.maerkte = teile.join('');
  zeichneKopf();
}

function marktKachel(k) {
  if (k.wert === null) {
    return wertZeile('karte m-karte', k.ticker, `<h2>${esc(k.name)}</h2><p class="sekundaer alt">Gerade keine Daten</p>`, 'Chart öffnen (Strg+Klick: Yahoo Finance)', k.name);
  }
  const warnung = k.eingefroren ? 'Wert seit Tagen unverändert, evtl. veraltet' : k.veraltet ? 'Yahoo antwortet nicht, letzter bekannter Stand' : '';
  return wertZeile('karte m-karte', k.ticker, `<h2>${esc(k.name)}</h2>
    <p class="kennzahl ${vixFarbe(k)}">${marktWert(k)}</p>
    <p class="klein">Verzögert${k.aktualisiert ? ` · ${zeitText(k.aktualisiert)}` : ''}</p>
    <div class="m-zeile"><span>Tag</span><span class="${marktFarbe(k, k.tag)}">${marktAenderung(k, k.tag)}</span></div>
    <div class="m-zeile"><span>Woche</span><span class="${marktFarbe(k, k.woche)}">${marktAenderung(k, k.woche)}</span></div>
    ${skalaHtml(k)}
    ${warnung ? `<p class="klein alt">${esc(warnung)}</p>` : ''}
  `, 'Chart öffnen (Strg+Klick: Yahoo Finance)', k.name);
}

async function ladeMaerkte() {
  let d;
  try {
    d = await api('/api/maerkte');
    if (d.fehler) throw new Error(d.fehler);
  } catch (f) {
    const text = d?.fehler ?? 'Die Marktdaten konnten nicht geladen werden. Läuft der Server noch?';
    el('m-status').textContent = text;
    el('g-maerkte').innerHTML = `<p class="sekundaer">${esc(text)}</p>`;
    return;
  }
  const alle = d.gruppen.flatMap((g) => g.kacheln);
  const stand = alle.map((k) => k.stand).filter(Boolean).sort().at(-1);
  const marktZeit = neuesteZeit(alle);
  el('m-status').textContent = stand ? `Letzter Stand ${lokal(stand).toLocaleDateString('de-DE')}${marktZeit ? ` · aktualisiert ${zeitText(marktZeit)} Uhr` : ''}` : 'Gerade keine Daten';
  el('m-gruppen').innerHTML = d.gruppen.map((g) => `<section class="m-gruppe"><h2>${esc(g.titel)}</h2>
    <div class="m-kacheln">${g.kacheln.map(marktKachel).join('')}</div></section>`).join('');

  kopfLeiste(alle);
  const fuerStart = ['^GSPC', '^GDAXI', '^VIX', '^TNX', 'EURUSD=X'];
  el('g-maerkte').innerHTML = fuerStart.map((t) => alle.find((k) => k.ticker === t)).filter((k) => k && k.wert !== null).map((k) => wertZeile('reihe', k.ticker, `
      <span class="reihe-name">${esc(k.name)}</span>
      <span><span class="${vixFarbe(k)}">${marktWert(k)}</span><span class="klein ${marktFarbe(k, k.tag)}">${marktAenderung(k, k.tag)}</span></span>
    `, 'Chart öffnen (Strg+Klick: Yahoo Finance)', k.name)).join('');
}

// ---- Trade-Republic-Export hochladen ----
function zeigeUpload(text) {
  el('u-status').textContent = text;
  el('u-status').hidden = false;
}
try {
  const gemerkt = sessionStorage.getItem('uploadMeldung');
  if (gemerkt) { zeigeUpload(gemerkt); sessionStorage.removeItem('uploadMeldung'); }
} catch {}

el('u-datei').addEventListener('change', async (e) => {
  const datei = e.target.files[0];
  e.target.value = ''; // damit dieselbe Datei erneut gewählt werden kann
  if (!datei) return;
  zeigeUpload('Datei wird geprüft …');
  let d;
  try {
    const antwort = await fetch('/api/upload', { method: 'POST', headers: { 'X-Vinter': 'upload' }, body: datei });
    d = await antwort.json();
  } catch {
    d = { fehler: 'Das Hochladen hat nicht geklappt. Läuft der Server noch?' };
  }
  if (d.fehler) { zeigeUpload(d.fehler); return; }
  if (d.neu === 0 && !d.nachgetragen) { zeigeUpload('Keine neuen Buchungen, dein Stand ist schon aktuell.'); return; }
  const meldung = [d.neu && `${d.neu} neue Buchungen übernommen.`, d.nachgetragen && `${d.nachgetragen} vorläufige Buchungen mit dem echten Betrag aktualisiert.`];
  try { sessionStorage.setItem('uploadMeldung', meldung.filter(Boolean).join(' ')); } catch {}
  location.reload(); // alle Seiten rechnen mit den neuen Daten neu
});

// ---- Thesen ----
let thesenListe = [];
let bearbeiteteThese = null; // null = neue These
const THESEN_LISTEN = ['katalysatoren', 'bestaetigung', 'bruch', 'news_themen'];
const EXIT_FELDER = [
  ['teilverkauf_kurs', 'Teilverkauf bei'],
  ['teilverkauf_anteil', 'Anteil in %'],
  ['komplett_kurs', 'Komplett raus bei'],
  ['nachkauf_unter', 'Nachkauf unter'],
  ['stop', 'Stop'],
];

function theseListe(titel, werte) {
  if (!werte.length) return '';
  return `<div><h3>${esc(titel)}</h3><ul>${werte.map((w) => `<li>${esc(w)}</li>`).join('')}</ul></div>`;
}

function exitText(e) {
  const teile = [];
  if (e.teilverkauf_kurs !== null) teile.push(`Teilverkauf bei ${euro.format(e.teilverkauf_kurs)}${e.teilverkauf_anteil !== null ? ` (${zahl.format(e.teilverkauf_anteil)} %)` : ''}`);
  if (e.komplett_kurs !== null) teile.push(`komplett raus bei ${euro.format(e.komplett_kurs)}`);
  if (e.nachkauf_unter !== null) teile.push(`Nachkauf unter ${euro.format(e.nachkauf_unter)}`);
  if (e.stop !== null) teile.push(`Stop ${euro.format(e.stop)}`);
  return teile.join(' · ');
}

// ---- News zu den Thesen ----
let newsDaten = null;
let newsSchwelle = 45;
try {
  const gemerkt = Number(localStorage.getItem('newsSchwelle'));
  if (gemerkt >= 20 && gemerkt <= 80) newsSchwelle = gemerkt;
} catch {}

function zeigeNewsSchwelle() {
  el('t-schwelle').value = newsSchwelle;
  el('t-schwelle-wert').textContent = `${newsSchwelle} %`;
}
zeigeNewsSchwelle();

function tendenzHtml(w) {
  // Bewusst ohne Prozentzahl und ohne Extremwerte: Das Modell misst nur Ähnlichkeit.
  const text = w >= 15 ? 'eher dafür' : w <= -15 ? 'eher dagegen' : 'neutral';
  const stil = w >= 15 ? 'dafuer' : w <= -15 ? 'dagegen' : '';
  return `<span class="tendenz" title="Grobe Einschätzung anhand deiner Signale, keine Bewertung der Nachricht">
    <span class="tendenz-text ${stil}">${text}</span>
    <span class="tendenz-spur"><i style="left:${50 + w * 0.3}%"></i></span>
  </span>`;
}

function newsZeile(n) {
  const datum = new Date(n.zeit).toLocaleDateString('de-DE', { day: 'numeric', month: 'short' });
  const weitere = n.weitere ? ` · +${n.weitere} ähnliche` : '';
  const titel = /^https?:\/\//.test(n.link)
    ? `<a href="${esc(n.link)}" target="_blank" rel="noopener noreferrer">${esc(n.titel)}</a>`
    : esc(n.titel);
  return `<div class="news-zeile">
    ${tendenzHtml(n.tendenz)}
    <span>${titel}<span class="klein">${esc(n.quelle)} · ${datum} · Relevanz ${Math.round(n.relevanz * 100)} %${weitere}</span><span class="klein">passt zu: ${esc(n.passt_zu)}</span></span>
  </div>`;
}

let newsSortierung = 'wichtig';
let thesenAnsicht = 'thesen';
try { thesenAnsicht = localStorage.getItem('thesenAnsicht') === 'news' ? 'news' : 'thesen'; } catch {}

function zeichneNews() {
  if (!newsDaten) return;
  const ordnung = {
    wichtig: (a, b) => b.relevanz - a.relevanz,
    neueste: (a, b) => new Date(b.zeit) - new Date(a.zeit),
    dafuer: (a, b) => b.tendenz - a.tendenz || b.relevanz - a.relevanz,
    dagegen: (a, b) => a.tendenz - b.tendenz || b.relevanz - a.relevanz,
  }[newsSortierung];

  // Jede These bleibt für sich. Warnungen stehen in ihrer These und gelten unabhängig vom Regler.
  el('t-news').innerHTML = newsDaten.thesen.map((eintrag) => {
    const warnungen = eintrag.news.filter((n) => n.warnung).sort(newsSortierung === 'neueste' ? ordnung : (a, b) => b.relevanz - a.relevanz);
    const passend = eintrag.news.filter((n) => !n.warnung && n.relevanz * 100 >= newsSchwelle).sort(ordnung);
    const gesamt = eintrag.news.length;
    const warnBlock = warnungen.length
      ? `<div class="warn-block"><h3>Warnungen: ähneln deinen Bruch-Signalen</h3>${warnungen.map(newsZeile).join('')}</div>`
      : '';
    const mehr = passend.slice(8);
    const liste = passend.length
      ? `${passend.slice(0, 8).map(newsZeile).join('')}${mehr.length ? `<details><summary>${mehr.length} weitere</summary>${mehr.map(newsZeile).join('')}</details>` : ''}`
      : '<p class="sekundaer">Keine weiteren News über dem Filter.</p>';
    return `<article class="karte these-karte"><h2 class="these-name">${esc(eintrag.name)}</h2>
      <p class="sekundaer">${warnungen.length + passend.length} von ${gesamt} Meldungen der letzten 7 Tage</p>
      ${warnBlock}
      <div class="these-news">${liste}</div>
    </article>`;
  }).join('') || '<p class="sekundaer">Noch keine These angelegt.</p>';
}

function zeigeThesenAnsicht() {
  el('t-bereich-thesen').hidden = thesenAnsicht !== 'thesen';
  el('t-bereich-news').hidden = thesenAnsicht !== 'news';
  el('t-neu').hidden = thesenAnsicht !== 'thesen';
  document.querySelectorAll('#t-ansicht button').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.ansicht === thesenAnsicht)));
  document.querySelectorAll('#t-sortierung button').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.sortierung === newsSortierung)));
}
el('t-ansicht').addEventListener('click', (e) => {
  const knopf = e.target.closest('button');
  if (!knopf) return;
  thesenAnsicht = knopf.dataset.ansicht;
  try { localStorage.setItem('thesenAnsicht', thesenAnsicht); } catch {}
  zeigeThesenAnsicht();
  ladeThesenNews();
});
el('t-sortierung').addEventListener('click', (e) => {
  const knopf = e.target.closest('button');
  if (!knopf) return;
  newsSortierung = knopf.dataset.sortierung;
  zeigeThesenAnsicht();
  zeichneNews();
});
zeigeThesenAnsicht();

async function ladeThesenNews() {
  // Nur in der News-Ansicht: das Sprachmodell braucht viel Arbeitsspeicher.
  if (el('seite-thesen').hidden || thesenAnsicht !== 'news' || !thesenListe.length) return;
  if (!newsDaten) el('t-news').innerHTML = '<p class="sekundaer">News werden geladen. Beim ersten Mal kann das bis zu einer Minute dauern …</p>';
  let d;
  try {
    d = await api('/api/news');
  } catch {
    d = { fehler: 'Die News konnten nicht geladen werden. Läuft der Server noch?' };
  }
  if (d.fehler) {
    el('t-meldungen').innerHTML = `<p class="meldung">${esc(d.fehler)}</p>`;
    el('t-news').innerHTML = '';
    return;
  }
  newsDaten = d;
  if (d.meldungen.length) el('t-meldungen').innerHTML = d.meldungen.map((t) => `<p class="meldung">${esc(t)}</p>`).join('');
  zeichneNews();
}

el('t-schwelle').addEventListener('input', (e) => {
  newsSchwelle = Number(e.target.value);
  el('t-schwelle-wert').textContent = `${newsSchwelle} %`;
  try { localStorage.setItem('newsSchwelle', String(newsSchwelle)); } catch {}
  zeichneNews();
});

function theseKarte(t, positionen) {
  const kurse = t.ticker.map((tk) => {
    const p = positionen.find((x) => x.ticker === tk);
    return p && p.kurs_eur !== null ? `${esc(tk)} ${euro.format(p.kurs_eur)}` : esc(tk);
  }).join(' · ');
  const exits = t.ticker.map((tk) => {
    const text = exitText(t.exits[tk]);
    return text ? `<p class="these-exit"><b>${esc(tk)}:</b> ${esc(text)}</p>` : '';
  }).join('');
  return `<article class="karte these-karte" data-these-karte="${esc(t.id)}">
    <div class="these-oben">
      <div>
        <h2 class="these-name">${esc(t.name)}${t.ticker.length > 1 ? '<span class="these-chip">Ordner</span>' : ''}</h2>
        <p class="sekundaer">${kurse}</p>
      </div>
      <button class="knopf" type="button" data-these="${esc(t.id)}">Bearbeiten</button>
    </div>
    ${t.kernthese ? `<p class="these-kern">${esc(t.kernthese)}</p>` : ''}
    <details><summary>Signale und Exit-Plan</summary>
      <div class="these-spalten">
        ${theseListe('Katalysatoren', t.katalysatoren)}${theseListe('Bestätigung', t.bestaetigung)}
        ${theseListe('Bruch-Signale', t.bruch)}${theseListe('News-Themen', t.news_themen)}
      </div>
      ${exits}
    </details>
  </article>`;
}

async function ladeThesen() {
  let d;
  delete antworten['/api/thesen'];
  delete antworten['/api/news']; // geänderte These: News neu bewerten
  try {
    d = await api('/api/thesen');
  } catch {
    el('t-status').textContent = 'Die Thesen konnten nicht geladen werden. Läuft der Server noch?';
    return;
  }
  let positionen = [];
  try { positionen = (await api('/api/portfolio')).positionen ?? []; } catch {}
  thesenListe = d.thesen;
  el('t-status').textContent = thesenListe.length === 1 ? '1 These' : `${thesenListe.length} Thesen`;
  el('t-meldungen').innerHTML = d.meldungen.map((t) => `<p class="meldung">${esc(t)}</p>`).join('');
  el('t-liste').innerHTML = thesenListe.length
    ? thesenListe.map((t) => theseKarte(t, positionen)).join('')
    : '<p class="sekundaer">Noch keine These. Lege mit „Neue These“ die erste an.</p>';
  if (newsDaten) zeichneNews();
  ladeThesenNews();
  ladeThesenHandel();
}

const tickerAusFeld = () => [...new Set(el('t-ticker').value.split(',').map((t) => t.trim().toUpperCase()).filter(Boolean))];

function exitWerteAusFormular() {
  const werte = {};
  document.querySelectorAll('#t-exits input').forEach((i) => {
    (werte[i.dataset.ticker] ??= {})[i.dataset.feld] = i.value === '' ? null : i.value;
  });
  return werte;
}

function zeichneExitFelder(werte) {
  el('t-exits').innerHTML = tickerAusFeld().map((tk) => `<div class="exit-block"><b>${esc(tk)}</b><div class="exit-felder">
    ${EXIT_FELDER.map(([feld, titel]) => `<label class="feld"><span>${titel}</span>
      <input type="number" step="any" min="0" inputmode="decimal" data-ticker="${esc(tk)}" data-feld="${feld}" value="${esc(werte[tk]?.[feld] ?? '')}"></label>`).join('')}
  </div></div>`).join('');
}

function oeffneThese(t) {
  bearbeiteteThese = t;
  el('t-titel').textContent = t ? 'These bearbeiten' : 'Neue These';
  el('t-name').value = t?.name ?? '';
  el('t-ticker').value = t ? t.ticker.join(', ') : '';
  el('t-kernthese').value = t?.kernthese ?? '';
  THESEN_LISTEN.forEach((f) => { el(`t-${f}`).value = t ? t[f].join('\n') : ''; });
  el('t-loeschen').hidden = !t;
  el('t-fehler').hidden = true;
  zeichneExitFelder(t?.exits ?? {});
  el('t-dialog').showModal();
}

async function theseSenden(methode, pfad, daten) {
  const antwort = await fetch(pfad, {
    method: methode,
    headers: { 'X-Vinter': 'thesen', 'Content-Type': 'application/json' },
    body: daten ? JSON.stringify(daten) : undefined,
  });
  return antwort.json();
}

function zeigeThesenFehler(text) {
  el('t-fehler').textContent = text;
  el('t-fehler').hidden = false;
}

el('t-neu').addEventListener('click', () => oeffneThese(null));

// Wochenbericht: Der Server baut die Markdown-Datei, die Seite lädt sie herunter.
// Die News nehmen dieselbe Relevanz-Schwelle wie der Regler auf dieser Seite.
el('t-bericht').addEventListener('click', async () => {
  const knopf = el('t-bericht');
  const status = el('t-bericht-status');
  knopf.disabled = true;
  status.hidden = false;
  status.textContent = 'Wochenbericht wird erstellt. Beim ersten Mal kann das wegen der News bis zu einer Minute dauern …';
  try {
    const antwort = await fetch(`/api/wochenbericht?schwelle=${newsSchwelle}`);
    if (!antwort.ok) throw new Error(antwort.status);
    const name = /filename="([^"]+)"/.exec(antwort.headers.get('Content-Disposition') ?? '')?.[1] ?? 'vinter-wochenbericht.md';
    const adresse = URL.createObjectURL(await antwort.blob());
    const link = Object.assign(document.createElement('a'), { href: adresse, download: name });
    document.body.append(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(adresse), 10000);
    status.textContent = `Fertig: ${name} liegt in deinen Downloads. Gib die Datei am Sonntag Claude zum Thesen-Check.`;
  } catch {
    status.textContent = 'Der Wochenbericht konnte nicht erstellt werden. Läuft der Server noch?';
  } finally {
    knopf.disabled = false;
  }
});
el('t-abbrechen').addEventListener('click', () => el('t-dialog').close());
el('t-ticker').addEventListener('input', () => zeichneExitFelder(exitWerteAusFormular()));
el('t-liste').addEventListener('click', (e) => {
  const knopf = e.target.closest('button[data-these]');
  if (knopf) oeffneThese(thesenListe.find((t) => t.id === knopf.dataset.these));
});

el('t-form').addEventListener('submit', async (e) => {
  e.preventDefault();
  const daten = {
    name: el('t-name').value,
    ticker: tickerAusFeld(),
    kernthese: el('t-kernthese').value,
    exits: exitWerteAusFormular(),
  };
  THESEN_LISTEN.forEach((f) => { daten[f] = el(`t-${f}`).value.split('\n').map((x) => x.trim()).filter(Boolean); });
  let d;
  try {
    d = bearbeiteteThese
      ? await theseSenden('PUT', `/api/thesen/${encodeURIComponent(bearbeiteteThese.id)}`, daten)
      : await theseSenden('POST', '/api/thesen', daten);
  } catch {
    d = { fehler: 'Das Speichern hat nicht geklappt. Läuft der Server noch?' };
  }
  if (d.fehler) { zeigeThesenFehler(d.fehler); return; }
  el('t-dialog').close();
  ladeThesen();
});

el('t-loeschen').addEventListener('click', async () => {
  if (!bearbeiteteThese || !confirm(`These „${bearbeiteteThese.name}“ wirklich löschen? Sie landet im Papierkorb-Ordner.`)) return;
  let d;
  try {
    d = await theseSenden('DELETE', `/api/thesen/${encodeURIComponent(bearbeiteteThese.id)}`);
  } catch {
    d = { fehler: 'Das Löschen hat nicht geklappt. Läuft der Server noch?' };
  }
  if (d.fehler) { zeigeThesenFehler(d.fehler); return; }
  el('t-dialog').close();
  ladeThesen();
});

// ---- Freibetrag ----
async function ladeFreibetrag() {
  let d;
  try {
    d = await api('/api/freibetrag');
  } catch {
    d = { fehler: 'Der Freibetrag konnte nicht geladen werden. Läuft der Server noch?' };
  }
  if (d.fehler) {
    el('f-status').textContent = d.fehler;
    return;
  }
  el('f-status').textContent = `Jahr ${d.jahr} · letzte Buchung im Export: ${lokal(d.letzte_buchung).toLocaleDateString('de-DE')}`;
  // Karte auf der Seite "Positionen"
  el('frei-anteil').textContent = `${Math.round(d.anteil)} %`;
  el('frei-details').textContent = d.ueber > 0 ? `um ${euro.format(d.ueber)} überschritten` : `${euro.format(d.verbraucht)} von ${euro.format(d.pauschbetrag)} verbraucht`;
  el('frei-karte').hidden = false;

  const hinweise = [];
  if (d.ueber > 0) hinweise.push(`Der Freibetrag ist voraussichtlich um ${euro.format(d.ueber)} überschritten. Auf diesen Teil fällt Steuer an.`);
  else if (d.anteil >= 80) hinweise.push('Der Freibetrag ist fast aufgebraucht.');
  if (d.aktien_vortrag > 0) hinweise.push(`Aktienverluste von ${euro.format(d.aktien_vortrag)} sind nicht verrechenbar und werden voraussichtlich vorgetragen.`);
  if (d.krypto_verkaeufe > 0) hinweise.push(`${d.krypto_verkaeufe} Krypto-Verkäufe sind hier nicht enthalten, sie werden steuerlich separat behandelt.`);
  el('f-meldungen').innerHTML = hinweise.map((t) => `<p class="meldung">${esc(t)}</p>`).join('');

  el('f-verbraucht').textContent = euro.format(d.verbraucht);
  el('f-von').textContent = `von ${euro.format(d.pauschbetrag)} (${komma2.format(d.anteil)} %)`;
  el('f-balken').style.width = `${d.anteil}%`;
  el('f-balken').style.background = d.anteil >= 100 ? 'var(--verlust)' : d.anteil >= 80 ? 'var(--warnung)' : 'var(--akzent)';
  el('f-frei').textContent = euro.format(d.frei);
  el('f-ueber').textContent = `Geschätzte Kapitalerträge ${euro.format(d.basis)}`;

  const zeilen = d.posten.filter((p) => Math.abs(p.wert) >= 0.005).map((p) => `<div class="reihe">
      <span><span class="reihe-name">${esc(p.name)}</span><span class="klein">${esc(p.detail)}</span></span>
      <span class="${klasse(p.wert)}">${plusEuro.format(p.wert)}</span>
    </div>`).join('');
  const quelle = d.quellensteuer > 0 ? `<div class="reihe">
      <span><span class="reihe-name">Quellensteuer auf Dividenden</span><span class="klein">laut Export einbehalten, nur zur Information</span></span>
      <span>${euro.format(d.quellensteuer)}</span>
    </div>` : '';
  el('f-posten').innerHTML = zeilen + quelle;
  el('f-karten').hidden = el('f-posten').hidden = false;
}

// ---- Portfolio-Verteilung ----
let verteilungDaten = null;
let schwelle = 25;
try {
  const gemerkt = Number(localStorage.getItem('schwelle'));
  if (gemerkt >= 1 && gemerkt <= 100) schwelle = gemerkt;
} catch {}
el('v-schwelle').value = schwelle;

function zeichneVerteilung() {
  const d = verteilungDaten;
  const anteil = new Intl.NumberFormat('de-DE', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
  const istZuViel = (titel, t) => titel === 'Thema' && t.anteil > schwelle && !d.ohne_warnung.includes(t.name) && t.name !== 'Ohne Thema';
  const thema = d.dimensionen.find((x) => x.titel === 'Thema');
  const zeile = (t, zuViel) => `<div class="v-zeile ${zuViel ? 'zu-viel' : ''}">
      <div class="v-text"><span>${esc(t.name)}</span><span>${anteil.format(t.anteil)} % · ${euro.format(t.wert)}</span></div>
      <div class="v-spur"><div class="v-balken" style="width:${t.anteil}%"></div></div>
    </div>`;

  // Verwandte Themen bleiben getrennt, stehen aber zusammen unter ihrer Gruppensumme.
  const bloecke = [];
  const vergeben = new Set();
  for (const [name, themen] of Object.entries(d.themen_gruppen)) {
    const kinder = (thema?.teile ?? []).filter((t) => themen.includes(t.name));
    if (!kinder.length) continue;
    kinder.forEach((t) => vergeben.add(t.name));
    bloecke.push({
      name, kinder,
      wert: kinder.reduce((s, t) => s + t.wert, 0),
      anteil: kinder.reduce((s, t) => s + t.anteil, 0),
    });
  }
  (thema?.teile ?? []).filter((t) => !vergeben.has(t.name)).forEach((t) => bloecke.push({ ...t, kinder: null }));
  bloecke.sort((a, b) => b.anteil - a.anteil);

  const warnungen = [];
  for (const b of bloecke) {
    if (b.kinder) {
      if (b.anteil > schwelle) warnungen.push(`Klumpenrisiko: Die Gruppe ${b.name} macht zusammen ${anteil.format(b.anteil)} % deines Depots aus.`);
      b.kinder.filter((t) => istZuViel('Thema', t)).forEach((t) => warnungen.push(`Klumpenrisiko: ${t.name} macht ${anteil.format(t.anteil)} % deines Depots aus.`));
    } else if (istZuViel('Thema', b)) {
      warnungen.push(`Klumpenrisiko: ${b.name} macht ${anteil.format(b.anteil)} % deines Depots aus.`);
    }
  }
  el('v-meldungen').innerHTML = [...warnungen, ...d.meldungen].map((t) => `<p class="meldung">${esc(t)}</p>`).join('');

  const themaHtml = bloecke.map((b) => (b.kinder
    ? `<div class="v-gruppe">${zeile(b, b.anteil > schwelle)}<div class="v-unter">${b.kinder.map((t) => zeile(t, istZuViel('Thema', t))).join('')}</div></div>`
    : zeile(b, istZuViel('Thema', b)))).join('');

  el('v-karten').innerHTML = d.dimensionen.map((x) => `<article class="karte"><h2>${esc(x.titel)}</h2>
    ${x.titel === 'Thema' ? themaHtml : x.teile.map((t) => zeile(t, false)).join('')}
  </article>`).join('');
}

el('v-schwelle').addEventListener('input', (e) => {
  const wert = Number(e.target.value);
  if (!(wert >= 1 && wert <= 100)) return;
  schwelle = wert;
  try { localStorage.setItem('schwelle', String(wert)); } catch {}
  if (verteilungDaten) zeichneVerteilung();
});

async function ladeVerteilung() {
  let d;
  try {
    d = await api('/api/verteilung');
  } catch {
    d = { fehler: 'Die Verteilung konnte nicht geladen werden. Läuft der Server noch?' };
  }
  el('verteilung').hidden = false;
  if (d.fehler) {
    el('v-meldungen').innerHTML = `<p class="meldung">${esc(d.fehler)}</p>`;
    return;
  }
  verteilungDaten = d;
  kopfPositionen(d);
  zeichneVerteilung();
  if (sektorDaten) zeichneSektoren(); // ergänzt deine Positionen in der Heatmap
}

// ---- Sektoren-Heatmap ----
// Ab dieser Veränderung (in %) ist die Farbe am kräftigsten, je Zeitraum fest.
const volleFarbe = { tag: 3, woche: 6, monat: 10, ytd: 30 };
let sektorDaten = null;
let branchenDaten = [];
let offenerSektor = null;
let sektorZeit = 'tag';
try { sektorZeit = localStorage.getItem('sektorZeit') || 'tag'; } catch {}

function zeigeSektorFilter() {
  document.querySelectorAll('#s-filter button').forEach((b) => {
    b.setAttribute('aria-pressed', String(b.dataset.zeit === sektorZeit));
  });
}

const eigeneIn = (name) => verteilungDaten?.sektor_positionen?.[name] ?? [];
const kurzName = (n) => n.replace(/\s+(Technology|Semiconductors|Health|Energy|Martin)$/i, '');

function kachelnHtml(liste) {
  const wert = (s) => s[sektorZeit] ?? null;
  const sortiert = [...liste].sort((a, b) => (wert(b) ?? -Infinity) - (wert(a) ?? -Infinity));
  const kacheln = sortiert.map((s) => {
    const w = wert(s);
    const offen = s.ticker === offenerSektor;
    const attribute = `type="button" class="sektor" data-ticker="${esc(s.ticker)}" aria-expanded="${offen}"`;
    if (w === null) return `<button ${attribute}><b>${esc(s.name)}</b><small>Gerade keine Daten</small></button>`;
    const staerke = Math.round(12 + Math.min(1, Math.abs(w) / volleFarbe[sektorZeit]) * 43);
    const farbe = w >= 0 ? 'var(--gewinn)' : 'var(--verlust)';
    const eigene = eigeneIn(s.name);
    const namen = eigene.slice(0, 3).map((p) => kurzName(p.name)).join(', ') + (eigene.length > 3 ? ` +${eigene.length - 3}` : '');
    return `<button ${attribute} style="background:color-mix(in srgb, ${farbe} ${staerke}%, var(--karte))">
      <b>${esc(s.name)}</b><span>${prozent.format(w)} %</span><small>${esc(s.ticker)}${s.veraltet ? ' · veraltet' : ''} · ${offen ? '▴' : '▾'} Top-Werte</small>
      ${eigene.length ? `<small class="sektor-eigene">Du: ${esc(namen)}</small>` : ''}
    </button>`;
  });

  // Das Klappfeld kommt hinter die letzte Kachel der Reihe, damit keine Lücken entstehen.
  const index = sortiert.findIndex((s) => s.ticker === offenerSektor);
  if (index >= 0) {
    const spalten = Math.max(1, getComputedStyle(el('s-karte')).gridTemplateColumns.split(' ').length);
    const reihenEnde = Math.min(kacheln.length, (Math.floor(index / spalten) + 1) * spalten);
    kacheln.splice(reihenEnde, 0, '<div class="sektor-panel" id="s-panel"></div>');
  }
  return kacheln.join('');
}

function zeichneSektoren() {
  el('s-karte').innerHTML = kachelnHtml(sektorDaten);
  el('s-branchen').innerHTML = kachelnHtml(branchenDaten);
  if (offenerSektor) fuelleSektorDetails(offenerSektor);
}

async function fuelleSektorDetails(ticker) {
  el('s-panel').innerHTML = '<p class="sekundaer">Top-Werte werden geladen …</p>';
  let d;
  try {
    d = await api(`/api/sektoren/${encodeURIComponent(ticker)}`);
  } catch {
    d = { fehler: 'Die Top-Werte konnten nicht geladen werden. Läuft der Server noch?' };
  }
  const panel = el('s-panel');
  if (offenerSektor !== ticker || !panel) return; // inzwischen zugeklappt oder gewechselt
  if (d.fehler) {
    panel.innerHTML = `<p class="sekundaer">${esc(d.fehler)}</p>`;
    return;
  }
  const name = [...sektorDaten, ...branchenDaten].find((s) => s.ticker === ticker)?.name ?? ticker;
  const gehalten = new Set(Object.values(verteilungDaten?.sektor_positionen ?? {}).flat().map((p) => p.ticker));
  const eigene = eigeneIn(name);
  const eigeneZeilen = eigene.map((p) => {
    const w = p[sektorZeit] ?? null;
    return wertZeile('reihe eigen', p.ticker, `
      <span><span class="reihe-name">${esc(p.name)}</span><span class="klein">${esc(p.ticker)} · ${komma2.format(p.anteil)} % vom Depot</span></span>
      <span class="${w === null ? '' : klasse(w)}">${w === null ? '–' : `${prozent.format(w)} %`}</span>
    `, 'Chart öffnen (Strg+Klick: Yahoo Finance)');
  }).join('');
  const zeitNamen = { tag: 'Tag', woche: 'Woche', monat: 'Monat', ytd: 'seit Jahresbeginn' };
  const zeilen = d.werte.map((t) => {
    const w = t[sektorZeit] ?? null;
    return wertZeile(`reihe ${gehalten.has(t.ticker) ? 'eigen' : ''}`, t.ticker, `
      <span><span class="reihe-name">${esc(t.name)}</span><span class="klein">${esc(t.ticker)} · ${komma2.format(t.gewicht)} % vom ETF</span></span>
      <span class="${w === null ? '' : klasse(w)}">${w === null ? '–' : `${prozent.format(w)} %`}${t.veraltet ? '<span class="klein alt">veraltet</span>' : ''}</span>
    `, 'Chart öffnen (Strg+Klick: Yahoo Finance)');
  }).join('');
  const meinTeil = eigene.length ? `<h4>Deine Positionen</h4><div class="sektor-liste">${eigeneZeilen}</div><h4>Die 10 größten Werte</h4>` : '';
  panel.innerHTML = `<h3>${esc(name)} · ${zeitNamen[sektorZeit]} <a class="mehr etf-link" href="${esc(yahooLink(ticker))}" target="_blank" rel="noopener">${esc(ticker)}-Chart ↗</a></h3>${meinTeil}<div class="sektor-liste">${zeilen}</div>`;
}

for (const feld of ['s-karte', 's-branchen']) {
  el(feld).addEventListener('click', (e) => {
    const knopf = e.target.closest('button.sektor');
    if (!knopf) return;
    const ticker = knopf.dataset.ticker;
    offenerSektor = offenerSektor === ticker ? null : ticker;
    zeichneSektoren();
    document.querySelector(`button.sektor[data-ticker="${ticker}"]`)?.focus();
  });
}
window.addEventListener('resize', () => { if (sektorDaten && offenerSektor) zeichneSektoren(); });

el('s-filter').addEventListener('click', (e) => {
  const knopf = e.target.closest('button');
  if (!knopf) return;
  sektorZeit = knopf.dataset.zeit;
  try { localStorage.setItem('sektorZeit', sektorZeit); } catch {}
  zeigeSektorFilter();
  if (sektorDaten) zeichneSektoren();
});
zeigeSektorFilter();

async function ladeSektoren() {
  let d;
  try {
    d = await api('/api/sektoren');
    if (d.fehler) throw new Error(d.fehler);
  } catch {
    el('s-status').textContent = d?.fehler ?? 'Die Sektoren konnten nicht geladen werden. Läuft der Server noch?';
    return;
  }
  sektorDaten = d.sektoren;
  branchenDaten = d.branchen;
  const stand = sektorDaten.map((s) => s.stand).filter(Boolean).sort().at(-1);
  const sektorZeitpunkt = neuesteZeit([...sektorDaten, ...branchenDaten]);
  el('s-status').textContent = stand ? `Stand ${lokal(stand).toLocaleDateString('de-DE')}${sektorZeitpunkt ? `, aktualisiert ${zeitText(sektorZeitpunkt)} Uhr` : ''}, verzögert, sortiert nach Veränderung` : 'Gerade keine Daten';
  zeichneSektoren();
}

// ---- Startseite: Lava-Lampe aus den eigenen Positionen ----
// Jede Position ist eine Blase: Größe nach Anteil am Depot, Farbe nach dem heutigen Ergebnis
// (mint = Plus, rot = Minus, je kräftiger, desto größer die Bewegung). Die Blasen steigen und sinken
// langsam und verschmelzen, wenn sie sich nahekommen. Gerechnet wird in einem kleinen Bild, das der
// Browser groß und weich zieht: Das ist sparsam genug fürs iPhone.
const lava = { blasen: [], breite: 0, hoehe: 0, bild: null, zuletzt: 0 };
const LAVA_FARBEN = {
  dark: { plus: [126, 227, 173], minus: [240, 150, 138], neutral: [110, 128, 118], deckung: 0.6 },
  light: { plus: [28, 168, 98], minus: [226, 78, 66], neutral: [128, 146, 136], deckung: 0.8 },
};

function lavaGroesse() {
  const c = el('lava');
  lava.breite = 160;
  lava.hoehe = Math.max(60, Math.round(160 * innerHeight / Math.max(innerWidth, 1)));
  c.width = lava.breite;
  c.height = lava.hoehe;
  lava.bild = c.getContext('2d').createImageData(lava.breite, lava.hoehe);
}

function setzeLavaBlasen(positionen) {
  lava.blasen = blasenAus(positionen);
  zeichneLava(performance.now());
}

// Kugeln aus einer Liste {wert, prozent}: Größe nach Anteil am Ganzen, nebeneinander von groß nach klein
function blasenAus(positionen, mindest = 0.022) {
  const summe = positionen.reduce((s, p) => s + p.wert, 0) || 1;
  // Zufall mit festem Startwert: Jede Blase behält bei jedem Neuladen ihren Platz und ihr Tempo.
  let saat = 7;
  const zufall = () => ((saat = (saat * 16807) % 2147483647) / 2147483647);
  return [...positionen].sort((a, b) => b.wert - a.wert).map((p, i, alle) => ({
    radius: mindest + 0.085 * Math.sqrt(p.wert / summe),
    prozent: p.prozent,
    x: 0.1 + 0.8 * ((i + 0.5) / alle.length) + (zufall() - 0.5) * 0.08,
    y: 0.35 + zufall() * 0.45,
    hub: 0.12 + zufall() * 0.16,             // wie weit sie steigt und sinkt
    seite: 0.02 + zufall() * 0.04,           // wie weit sie seitlich pendelt
    tempo: (2 * Math.PI) / (38 + zufall() * 44), // eine Runde dauert 38 bis 82 Sekunden
    phase: zufall() * 2 * Math.PI,
  }));
}

function lavaFarbe(prozent, f) {
  const staerke = Math.min(1, Math.abs(prozent) / 3) ** 0.6; // ab ±3 % volle Farbe
  const ziel = prozent >= 0 ? f.plus : f.minus;
  return f.neutral.map((n, k) => n + (ziel[k] - n) * staerke);
}

function zeichneLava(jetzt) {
  // Stil "Vinter": dieselben Blasen, aber als Punktraster wie eine LED-Tafel (siehe zeichnePunkte).
  if (document.documentElement.dataset.stil === 'vinter') { zeichnePunkte(jetzt); return; }
  if (!lava.bild || !lava.blasen.length) return;
  const f = LAVA_FARBEN[document.documentElement.dataset.theme === 'light' ? 'light' : 'dark'];
  const { breite: B, hoehe: H, bild } = lava;
  const t = jetzt / 1000;
  const masse = Math.min(B, H * 1.6);
  const blasen = lava.blasen.map((b) => ({
    x: (b.x + b.seite * Math.sin(t * b.tempo * 0.7 + b.phase * 2)) * B,
    y: (b.y + b.hub * Math.sin(t * b.tempo + b.phase)) * H,
    r2: (b.radius * masse) ** 2,
    farbe: lavaFarbe(b.prozent, f),
  }));
  const px = bild.data;
  let i = 0;
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < B; x++) {
      // Feld wie bei Metaballs: Jede Blase strahlt nach außen schwächer ab. Wo die Summe über 1
      // liegt, ist "Lava", darunter läuft sie weich aus. Die Farbe mischt sich nach Nähe.
      // Jede Blase wirkt nur bis zum doppelten Radius, sonst liefe alles zu einem Fleck zusammen.
      let feld = 0, r = 0, g = 0, bl = 0;
      for (const b of blasen) {
        const dx = x - b.x, dy = y - b.y;
        const q = (dx * dx + dy * dy) / (4 * b.r2);
        if (q >= 1) continue;
        const w = (1 - q) ** 3;
        feld += w; r += b.farbe[0] * w; g += b.farbe[1] * w; bl += b.farbe[2] * w;
      }
      if (feld === 0) { px[i + 3] = 0; i += 4; continue; }
      const kern = Math.min(1, Math.max(0, (feld - 0.22) / 0.3));
      const deckung = kern * kern * (3 - 2 * kern) * 0.85 + Math.min(feld, 1) * 0.15;
      px[i] = r / feld; px[i + 1] = g / feld; px[i + 2] = bl / feld;
      px[i + 3] = deckung * f.deckung * 255;
      i += 4;
    }
  }
  el('lava').getContext('2d').putImageData(bild, 0, 0);
}

function lavaSchleife(jetzt) {
  requestAnimationFrame(lavaSchleife);
  // 30 Bilder pro Sekunde reichen für die langsame Bewegung; im Hintergrund-Tab wird nichts gerechnet.
  if (document.hidden || jetzt - lava.zuletzt < 33) return;
  lava.zuletzt = jetzt;
  zeichneLava(jetzt);
}

async function ladeLava() {
  hgLaden();
  let d, depot;
  try {
    [d, depot] = await Promise.all([api(mitVorboerse('/api/perioden')), api('/api/portfolio')]);
  } catch {
    return; // Die Lampe ist nur Dekoration, die Seite funktioniert auch ohne sie.
  }
  const heute = d?.zeitraeume?.tag;
  if (!heute || depot.fehler) return;
  const wert = Object.fromEntries(depot.positionen.map((p) => [p.isin, p.wert_eur]));
  hg.positionen = heute.positionen
    .filter((p) => !p.verkauft && wert[p.isin] > 0 && p.gv_prozent !== null)
    .map((p) => ({ wert: wert[p.isin], prozent: p.gv_prozent }));
  hg.stand++;
  setzeLavaBlasen([...hg.positionen]);
  if (heute.gv_prozent !== null) {
    document.body.style.setProperty('--tag-staerke', Math.min(1, Math.abs(heute.gv_prozent) / 3).toFixed(2));
  }
}


// ---- Punktraster (Stil "Vinter") ----
// Ein Raster aus kleinen Punkten wie eine LED-Anzeigetafel. Größe und Helligkeit jedes Punkts
// kommen aus einem Feld zwischen 0 und 1:
//  - Startseite: deine Positionen als Leuchtpunkte (Größe nach Anteil, Farbe nach heute), wie die Lava-Lampe
//  - alle anderen Seiten: ruhige Lichtbänder, leicht getönt nach dem heutigen Depot-Ergebnis
// Gerechnet wird höchstens zehnmal pro Sekunde, auf den anderen Seiten nur, wenn sich etwas ändert.
const punkte = { abstand: 7, letzteArt: '', letzteZeit: 0, groesse: '' };

function punkteFarben() {
  const hell = document.documentElement.dataset.theme === 'light';
  return hell
    ? { plus: [31, 140, 86], minus: [196, 72, 62], neutral: [120, 132, 125], grund: 0.55 }
    : { plus: [126, 227, 173], minus: [239, 143, 134], neutral: [150, 162, 155], grund: 0.85 };
}

function zeichnePunkte(jetzt) {
  const c = el('lava');
  const home = document.body.classList.contains('auf-home');
  const thema = document.documentElement.dataset.theme;
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  const B = innerWidth, H = innerHeight;
  const groesse = `${B}x${H}x${dpr}`;
  // lavaGroesse() setzt die Fläche für die alte Lampe klein: dann hier wieder auf volle Auflösung.
  if (punkte.groesse !== groesse || c.width !== Math.round(B * dpr)) {
    c.width = Math.round(B * dpr); c.height = Math.round(H * dpr);
    punkte.groesse = groesse; punkte.letzteArt = ''; punkte.muster = null;
  }
  if (!home || hg.wahl === 'himmel') { zeichneHimmel(jetzt, c, B, H, dpr); return; }
  const art = (home ? 'home' : 'baender') + thema + (depotTag ?? '') + hg.wahl + hg.stand;
  // Die Bänder wandern langsam (siebenmal pro Sekunde reicht), die Blasen zehnmal pro Sekunde.
  // Wer weniger Bewegung eingestellt hat, bekommt ein Standbild.
  const ruhig = matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (ruhig && punkte.letzteArt === art) return;
  if (jetzt - punkte.letzteZeit < (home ? 100 : 140) && punkte.letzteArt === art) return;
  punkte.letzteZeit = jetzt;
  punkte.letzteArt = art;

  // Schnell statt Punkt für Punkt: Jeder Punkt ist ein Pixel in einem kleinen Bild. Das Bild wird
  // ohne Glätten groß gezogen und dann durch eine Maske aus runden Punkten gestanzt.
  const s = punkte.abstand;
  const spalten = Math.ceil(B / s), zeilen = Math.ceil(H / s);
  if (!punkte.klein || punkte.klein.width !== spalten || punkte.klein.height !== zeilen) {
    punkte.klein = Object.assign(document.createElement('canvas'), { width: spalten, height: zeilen });
  }
  const kg = punkte.klein.getContext('2d');
  const bild = kg.createImageData(spalten, zeilen);
  const px = bild.data;
  const f = punkteFarben();
  const t = jetzt / 1000;
  // Ruhezonen: hinter Wortmarke, Datum, Satz und LED-Tafel werden die Punkte weich ausgeblendet,
  // damit sich die Punkte der Schrift nicht mit dem Hintergrund beißen.
  const zonen = home ? [...document.querySelectorAll('#seite-home .wortmarke, #seite-home .hero-datum, #seite-home .hero-satz, #led-tafel')]
    .map((e) => e.getBoundingClientRect()).filter((r) => r.width && r.bottom > 0 && r.top < H) : [];
  const ruhe = (x, y) => {
    let m = 1;
    for (const r of zonen) {
      const dx = Math.max(r.left - x, 0, x - r.right), dy = Math.max(r.top - y, 0, y - r.bottom);
      const d = Math.hypot(dx, dy);
      m = Math.min(m, d >= 140 ? 1 : 0.5 + 0.5 * (d / 140) ** 2);
    }
    return m;
  };

  const quelle = { sektoren: hg.sektorBlasen, themen: hg.themenBlasen, kugeln: lava.blasen }[hg.wahl] ?? [];
  const welt = home ? hgBildPx(spalten, zeilen, thema) : null;
  if (welt) {
    // Weltkarte: fertiges Bild übernehmen, eine langsame Welle lässt die Punkte leicht atmen
    const ruhigBild = matchMedia('(prefers-reduced-motion: reduce)').matches;
    for (let zy = 0, i = 0; zy < zeilen; zy++) {
      const y = zy * s + s / 2;
      for (let zx = 0; zx < spalten; zx++, i += 4) {
        if (!welt[i + 3]) continue;
        const x = zx * s + s / 2;
        const welle = ruhigBild ? 1 : 0.82 + 0.18 * Math.sin(t * 0.9 - zx * 0.06 + zy * 0.03);
        px[i] = welt[i]; px[i + 1] = welt[i + 1]; px[i + 2] = welt[i + 2];
        px[i + 3] = welt[i + 3] * f.grund * welle * (zonen.length ? ruhe(x, y) : 1);
      }
    }
  } else if (home && quelle.length) {
    const masse = Math.min(B, H * 1.6);
    const farben = LAVA_FARBEN[thema === 'light' ? 'light' : 'dark'];
    const blasen = quelle.map((b) => ({
      x: (b.x + b.seite * Math.sin(t * b.tempo * 0.7 + b.phase * 2)) * B,
      y: (b.y + b.hub * Math.sin(t * b.tempo + b.phase)) * H,
      r2: (b.radius * masse) ** 2,
      farbe: lavaFarbe(b.prozent, farben),
    }));
    let i = 0;
    for (let zy = 0; zy < zeilen; zy++) {
      const y = zy * s + s / 2;
      for (let zx = 0; zx < spalten; zx++, i += 4) {
        const x = zx * s + s / 2;
        let feld = 0, r = 0, gr = 0, bl = 0;
        for (const b of blasen) {
          const dx = x - b.x, dy = y - b.y;
          const q = (dx * dx + dy * dy) / (4 * b.r2);
          if (q >= 1) continue;
          const w = (1 - q) ** 3;
          feld += w; r += b.farbe[0] * w; gr += b.farbe[1] * w; bl += b.farbe[2] * w;
        }
        if (feld < 0.03) continue;
        const v = Math.min(1, feld);
        px[i] = r / feld; px[i + 1] = gr / feld; px[i + 2] = bl / feld;
        px[i + 3] = Math.min(1, 0.2 + v * 0.95) * f.grund * 255 * (zonen.length ? ruhe(x, y) : 1);
      }
    }
  }
  kg.putImageData(bild, 0, 0);

  const g = c.getContext('2d');
  g.setTransform(dpr, 0, 0, dpr, 0, 0);
  g.globalCompositeOperation = 'source-over';
  g.clearRect(0, 0, B, H);
  g.imageSmoothingEnabled = false;
  g.drawImage(punkte.klein, 0, 0, spalten * s, zeilen * s);
  // Maske: ein runder Punkt pro Zelle, alles dazwischen wird durchsichtig.
  if (!punkte.muster) {
    const kachel = Object.assign(document.createElement('canvas'), { width: s * dpr, height: s * dpr });
    const tg = kachel.getContext('2d');
    tg.scale(dpr, dpr);
    tg.fillStyle = '#000';
    tg.beginPath(); tg.arc(s / 2, s / 2, s * 0.32, 0, 6.283); tg.fill();
    punkte.muster = g.createPattern(kachel, 'repeat');
    punkte.muster.setTransform(new DOMMatrix().scale(1 / dpr));
  }
  g.globalCompositeOperation = 'destination-in';
  g.fillStyle = punkte.muster;
  g.fillRect(0, 0, B, H);
  g.globalCompositeOperation = 'destination-over'; // Sterne hinter die Leuchtpunkte
  zeichneSterne(g, B, H, jetzt, false);
  g.globalCompositeOperation = 'source-over';
  zeichneSchnuppen(g, B, H, jetzt);
}


// ---- Startseite: wählbarer Hintergrund ----
// Alles als Punktraster aus vorhandenen Daten. Die Auswahl klappt unter "Gesamtansicht" auf und wird im Browser gemerkt.
const HG_ARTEN = [
  ['kugeln', 'Positionen'], ['kacheln', 'Depot-Kacheln'], ['chart', 'Chart'], ['welt', 'Weltkarte'],
  ['sektoren', 'Sektoren'], ['themen', 'Themen'], ['himmel', 'Polarlicht'], ['sterne', 'Sterne'],
];
const hg = { wahl: 'kugeln', chart: 'depot', stand: 0, geladen: {}, sektoren: null, sektorBlasen: [], themen: null, themenBlasen: [],
  maerkte: null, laender: null, verlauf: null, positionen: [], px: null, pxSchluessel: '' };
try {
  const w = localStorage.getItem('hintergrund'); if (HG_ARTEN.some(([k]) => k === w)) hg.wahl = w;
  hg.chart = localStorage.getItem('hintergrundChart') || 'depot';
} catch {}
// Ungefähres Gewicht der Sektoren im S&P 500 (nur für die Größe der Kugeln)
const HG_GEWICHT = { XLK: 33, XLF: 13, XLY: 10, XLC: 10, XLV: 9, XLI: 8, XLP: 5, XLE: 3, XLU: 2.5, XLRE: 2, XLB: 2 };

function hgWaehlen(art, chart = hg.chart) {
  hg.wahl = art; hg.chart = chart;
  try { localStorage.setItem('hintergrund', art); localStorage.setItem('hintergrundChart', chart); } catch {}
  hgAuswahlBauen(false);
  hgLaden();
}

async function hgLaden() {
  const jetzt = Date.now();
  const faellig = (k) => { if (hg.geladen[k] && jetzt - hg.geladen[k] < 5 * 60 * 1000) return false; hg.geladen[k] = jetzt; return true; };
  const hol = (u) => fetch(u).then((x) => x.json());
  try {
    if (hg.wahl === 'sektoren' && faellig('sektoren')) {
      const d = await hol('/api/sektoren');
      if (!d.fehler) {
        hg.sektoren = d.sektoren.filter((s) => Number.isFinite(s.tag));
        hg.sektorBlasen = blasenAus(hg.sektoren.map((s) => ({ wert: HG_GEWICHT[s.ticker] ?? 3, prozent: s.tag })), 0.04);
      }
    }
    if (hg.wahl === 'themen' && faellig('themen')) {
      const d = await hol('/api/themen');
      if (!d.fehler) {
        hg.themen = d.themen.filter((t) => Number.isFinite(t.schnitt?.tag)).map((t) => ({ name: t.name, tag: t.schnitt.tag }));
        hg.themenBlasen = blasenAus(hg.themen.map((t) => ({ wert: 1, prozent: t.tag })), 0.035);
      }
    }
    const brauchtMaerkte = hg.wahl === 'welt' || (hg.wahl === 'chart' && hg.chart !== 'depot');
    if (brauchtMaerkte && faellig('maerkte')) {
      const [d, t] = await Promise.all([hol('/api/karte/maerkte'), hg.laender || hg.wahl !== 'welt' ? null : hol('lib/karte/countries-110m.json')]);
      if (t && window.topojson) hg.laender = topojson.feature(t, t.objects.countries).features.filter((f) => f.id !== '010');
      if (!d.fehler) hg.maerkte = d.laender;
    }
    if (hg.wahl === 'welt' && !hg.laender && window.topojson) {
      const t = await hol('lib/karte/countries-110m.json');
      hg.laender = topojson.feature(t, t.objects.countries).features.filter((f) => f.id !== '010');
    }
    if (hg.wahl === 'chart' && hg.chart === 'depot' && faellig('verlauf')) {
      const d = await hol('/api/verlauf');
      if (!d.fehler) hg.verlauf = d.punkte;
    }
  } catch { /* Der Hintergrund ist nur Schmuck, die Seite funktioniert auch ohne. */ }
  hg.stand++;
  hgAuswahlBauen(false);
  punkte.letzteArt = '';
  zeichneLava(performance.now());
}

const hgPz = (v) => `${v >= 0 ? '+' : '−'}${Math.abs(v).toLocaleString('de-DE', { minimumFractionDigits: 1, maximumFractionDigits: 1 })} %`;
// Die Reihe für den Chart-Hintergrund: Depot (seit Beginn) oder ein Leitindex (etwa drei Monate)
function hgChartReihe() {
  if (hg.chart === 'depot') return hg.verlauf?.length > 1 ? { name: 'Depot', werte: hg.verlauf.map((p) => p.wert), seit: hg.verlauf[0].datum } : null;
  const l = hg.maerkte?.find((m) => m.ticker === hg.chart);
  return l?.verlauf?.length > 1 ? { name: l.index, werte: l.verlauf, seit: null } : null;
}

// Eine Zeile unter der Auswahl: was die Farben bedeuten und wer heute vorne und hinten liegt
function hgText() {
  const spanne = (liste, name) => {
    if (!liste?.length) return 'Wird geladen …';
    const s = [...liste].sort((a, b) => b.tag - a.tag);
    return `Vorne ${esc(name(s[0]))} ${hgPz(s[0].tag)}, hinten ${esc(name(s.at(-1)))} ${hgPz(s.at(-1).tag)}`;
  };
  const r = hgChartReihe();
  return {
    kugeln: 'Deine Positionen als Kugeln: Größe nach Anteil, Farbe nach heute',
    kacheln: 'Deine Positionen als Kacheln: Fläche nach Anteil, Farbe nach heute',
    chart: r ? `${esc(r.name)} ${r.seit ? `seit ${new Date(r.seit).toLocaleDateString('de-DE', { month: 'short', year: 'numeric' })}` : 'letzte drei Monate'}: ${hgPz((r.werte.at(-1) / r.werte[0] - 1) * 100)}` : 'Wird geladen …',
    welt: `Leitindex je Land heute, grün Plus, rot Minus · ${spanne(hg.maerkte?.filter((l) => Number.isFinite(l.tag)), (l) => l.name)}`,
    sektoren: `S&P-Sektoren heute, Größe nach Gewicht · ${spanne(hg.sektoren, (s) => s.name)}`,
    themen: `Deine Themen heute (Schnitt der Werte) · ${spanne(hg.themen, (t) => t.name)}`,
    himmel: 'Polarlicht in der Tagesfarbe deines Depots',
    sterne: 'Nur Sterne, nichts lenkt ab',
  }[hg.wahl];
}

// Bild-Hintergründe (Weltkarte, Kacheln, Chart): einmal je Größe und Datenstand in ein kleines Bild gemalt,
// ein Pixel = ein Punkt. Danach übernimmt zeichnePunkte() das Bild mit einer leichten Welle.
function hgBildPx(spalten, zeilen, thema) {
  if (!['welt', 'kacheln', 'chart'].includes(hg.wahl) || !window.d3) return null;
  const schluessel = `${hg.wahl}${hg.chart}${spalten}x${zeilen}${thema}${hg.stand}`;
  if (hg.pxSchluessel === schluessel) return hg.px;
  const c = Object.assign(document.createElement('canvas'), { width: spalten, height: zeilen });
  const g = c.getContext('2d');
  const farben = LAVA_FARBEN[thema === 'light' ? 'light' : 'dark'];
  const rgba = (rgb, a) => `rgba(${rgb.map(Math.round).join(',')},${a})`;
  if (hg.wahl === 'welt') {
    if (!hg.laender) return null;
    const sammlung = { type: 'FeatureCollection', features: hg.laender };
    const pfad = d3.geoPath(d3.geoEquirectangular().fitExtent([[1, zeilen * 0.06], [spalten - 1, zeilen * 0.97]], sammlung), g);
    const tag = new Map((hg.maerkte ?? []).filter((l) => Number.isFinite(l.tag)).map((l) => [l.land, l.tag]));
    for (const f of hg.laender) {
      const v = tag.get(f.id);
      g.fillStyle = v === undefined ? rgba(farben.neutral, 0.4) : rgba(lavaFarbe(v, farben), 1);
      g.beginPath(); pfad(f); g.fill();
    }
  } else if (hg.wahl === 'kacheln') {
    if (!hg.positionen.length) return null;
    // Treemap über den ganzen Bildschirm, eine Zelle Abstand zwischen den Kacheln
    const wurzel = d3.hierarchy({ kinder: hg.positionen }, (d) => d.kinder).sum((d) => d.wert ?? 0).sort((a, b) => b.value - a.value);
    d3.treemap().size([spalten - 2, zeilen - 2]).paddingInner(1).round(true)(wurzel);
    for (const b of wurzel.leaves()) {
      g.fillStyle = rgba(lavaFarbe(b.data.prozent, farben), 0.9);
      g.fillRect(b.x0 + 1, b.y0 + 1, Math.max(1, b.x1 - b.x0), Math.max(1, b.y1 - b.y0));
    }
  } else {
    const r = hgChartReihe(); if (!r) return null;
    // Fläche unter der Linie, nach unten auslaufend; die Linie selbst voll
    const w = r.werte, lo = Math.min(...w), hi = Math.max(...w);
    const oben = zeilen * 0.3, unten = zeilen * 0.94, links = spalten * 0.03, rechts = spalten * 0.97;
    const x = (i) => links + i / (w.length - 1) * (rechts - links);
    const y = (v) => unten - (v - lo) / (hi - lo || 1) * (unten - oben);
    const farbe = lavaFarbe((w.at(-1) / w[0] - 1) * 100, farben);
    const verlauf = g.createLinearGradient(0, oben, 0, zeilen);
    verlauf.addColorStop(0, rgba(farbe, 0.45)); verlauf.addColorStop(1, rgba(farbe, 0.04));
    g.beginPath(); g.moveTo(x(0), zeilen); w.forEach((v, i) => g.lineTo(x(i), y(v))); g.lineTo(x(w.length - 1), zeilen); g.closePath();
    g.fillStyle = verlauf; g.fill();
    g.beginPath(); w.forEach((v, i) => (i ? g.lineTo(x(i), y(v)) : g.moveTo(x(i), y(v))));
    g.strokeStyle = rgba(farbe, 1); g.lineWidth = 1.4; g.lineJoin = 'round'; g.stroke();
  }
  hg.px = g.getImageData(0, 0, spalten, zeilen).data;
  hg.pxSchluessel = schluessel;
  return hg.px;
}

document.addEventListener('click', (e) => { const k = e.target.closest('[data-hg]'); if (k) hgWaehlen(k.dataset.hg, k.dataset.hg === 'chart' ? hg.chart : undefined); });
document.addEventListener('change', (e) => { if (e.target.id === 'hg-chart') hgWaehlen('chart', e.target.value); });
// Ausklappbar: zu sieht man nur "Hintergrund: Weltkarte", offen alle Knöpfe und die Erklärzeile
function hgAuswahlBauen(laden = true) {
  const feld = el('hg-wahl'); if (!feld) return;
  const offen = feld.querySelector('details')?.open ?? false;
  const name = HG_ARTEN.find(([k]) => k === hg.wahl)?.[1] ?? '';
  const indizes = (hg.maerkte ?? []).filter((l) => l.verlauf?.length > 1);
  const chartWahl = hg.wahl === 'chart' ? `<label class="hg-chart">Reihe <select id="hg-chart"><option value="depot">Dein Depot</option>${indizes.map((l) => `<option value="${esc(l.ticker)}" ${l.ticker === hg.chart ? 'selected' : ''}>${esc(l.index)} (${esc(l.name)})</option>`).join('')}${hg.chart !== 'depot' && !indizes.length ? `<option value="${esc(hg.chart)}" selected>Index</option>` : ''}</select></label>` : '';
  feld.innerHTML = `<details ${offen ? 'open' : ''}><summary><span class="hg-titel">Hintergrund</span> <b>${esc(name)}</b><span class="hg-pfeil" aria-hidden="true">▾</span></summary>
    <div class="hg-innen"><span class="hg-knoepfe">${HG_ARTEN.map(([k, n]) => `<button type="button" data-hg="${k}" aria-pressed="${k === hg.wahl}">${n}</button>`).join('')}</span>
    ${chartWahl}<small class="hg-text">${hgText()}</small></div></details>`;
  if (hg.wahl === 'chart' && !hg.maerkte && !hg.geladen.maerkte) { hg.geladen.maerkte = Date.now(); fetch('/api/karte/maerkte').then((x) => x.json()).then((d) => { if (!d.fehler) { hg.maerkte = d.laender; hgAuswahlBauen(false); } }).catch(() => {}); }
  if (hg.chart === 'depot' && feld.querySelector('#hg-chart')) feld.querySelector('#hg-chart').value = 'depot';
  if (laden) hgLaden();
}

// ---- Nachthimmel (Stil "Vinter", alle Seiten außer der Startseite) ----
// Polarlicht-Stränge ziehen in weichen Schwüngen quer übers Bild, dazu feste und funkelnde Sterne
// und ab und zu eine Sternschnuppe. Alles grün an Plus-Tagen, rot an Minus-Tagen.
// Das Polarlicht wird in einem kleinen Bild gerechnet und weich hochgezogen: Das sieht nach Licht
// aus und spart Rechenzeit. Höchstens 15 Bilder pro Sekunde, bei "weniger Bewegung" ein Standbild.
const himmel = { sterne: null, groesse: '', zuletzt: 0, schnuppen: [], naechste: 0, klein: null };

// Solange die Tagesfarbe noch nicht feststeht, leuchten die Lichter weiß. Sobald der Live-Wert da ist,
// gleiten sie in 1,6 Sekunden zu grün oder rot (lichtFarbe.ab = Startzeit des Übergangs).
const lichtFarbe = { da: false, ab: 0 };
const LICHT_WEISS = { kern: [236, 242, 248], rand: [176, 188, 200], saum: [200, 208, 220], stern: [236, 240, 246] };
function lichtMix() {
  if (!lichtFarbe.da) return 0;
  const x = Math.min(1, (performance.now() - lichtFarbe.ab) / 1600);
  return x * x * (3 - 2 * x); // sanft an- und auslaufend
}
function himmelFarben() {
  const plus = depotTag === null || depotTag >= 0;
  const ziel = plus
    ? { kern: [170, 255, 200], rand: [40, 200, 130], saum: [70, 210, 190], stern: [214, 255, 228] }
    : { kern: [255, 170, 165], rand: [215, 60, 75], saum: [235, 95, 140], stern: [255, 222, 220] };
  const m = lichtMix();
  if (m >= 1) return ziel;
  const aus = {};
  for (const k in ziel) aus[k] = ziel[k].map((v, i) => Math.round(LICHT_WEISS[k][i] + (v - LICHT_WEISS[k][i]) * m));
  return aus;
}

function himmelSterne(B, H) {
  let saat = 11;
  const zufall = () => ((saat = (saat * 16807) % 2147483647) / 2147483647);
  const anzahl = Math.round(B * H / 6500);
  return Array.from({ length: anzahl }, (_, i) => ({
    x: zufall() * B, y: zufall() * H * 0.92,
    r: 0.5 + zufall() ** 3 * 1.3,
    a: 0.25 + zufall() * 0.55,
    funkelt: i % 4 === 0,
    tempo: 0.6 + zufall() * 1.8, phase: zufall() * 6.283,
  }));
}

function zeichneSterne(g, B, H, jetzt, tönen = true) {
  const groesse = `${B}x${H}`;
  if (!himmel.sterne || himmel.groesse !== groesse) { himmel.sterne = himmelSterne(B, H); himmel.groesse = groesse; }
  const ruhig = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const [r, gr, b] = himmelFarben().stern;
  const t = jetzt / 1000;
  for (const st of himmel.sterne) {
    const a = st.funkelt && !ruhig ? st.a * (0.35 + 0.65 * (0.5 + 0.5 * Math.sin(t * st.tempo + st.phase)) ** 2) : st.a;
    g.fillStyle = `rgba(${r},${gr},${b},${a})`;
    g.beginPath(); g.arc(st.x, st.y, st.r, 0, 6.283); g.fill();
  }
}

function zeichneSchnuppen(g, B, H, jetzt) {
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  if (!himmel.naechste) himmel.naechste = jetzt + 4000;
  if (jetzt >= himmel.naechste) {
    const rechts = Math.random() < 0.5;
    const winkel = (18 + Math.random() * 18) * Math.PI / 180;
    himmel.schnuppen.push({ x: B * (0.15 + Math.random() * 0.7), y: H * Math.random() * 0.35, dx: Math.cos(winkel) * (rechts ? 1 : -1), dy: Math.sin(winkel), start: jetzt, weg: 260 + Math.random() * 220 });
    himmel.naechste = jetzt + 6000 + Math.random() * 9000;
  }
  const [r, gr, b] = himmelFarben().kern;
  himmel.schnuppen = himmel.schnuppen.filter((sn) => {
    const zeit = (jetzt - sn.start) / 1000;
    const strecke = zeit * 700;
    if (strecke > sn.weg) return false;
    const hx = sn.x + sn.dx * strecke, hy = sn.y + sn.dy * strecke;
    const laenge = Math.min(140, strecke);
    const blende = 1 - strecke / sn.weg; // verglüht zum Ende hin
    const verlauf = g.createLinearGradient(hx, hy, hx - sn.dx * laenge, hy - sn.dy * laenge);
    verlauf.addColorStop(0, `rgba(${r},${gr},${b},${0.95 * blende})`);
    verlauf.addColorStop(1, `rgba(${r},${gr},${b},0)`);
    g.strokeStyle = verlauf;
    g.lineWidth = 1.6;
    g.lineCap = 'round';
    g.beginPath(); g.moveTo(hx, hy); g.lineTo(hx - sn.dx * laenge, hy - sn.dy * laenge); g.stroke();
    return true;
  });
}

function zeichneHimmel(jetzt, c, B, H, dpr) {
  const ruhig = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const art = `himmel${depotTag ?? ''}:${Math.round(lichtMix() * 40)}`;
  if (jetzt - himmel.zuletzt < 66 && punkte.letzteArt === art) return;
  if (ruhig && punkte.letzteArt === art) return;
  himmel.zuletzt = jetzt;
  punkte.letzteArt = art;

  // Polarlicht im kleinen Bild (eine Zelle = 8 Pixel)
  const z = 8;
  const spalten = Math.ceil(B / z), zeilen = Math.ceil(H / z);
  if (!himmel.klein || himmel.klein.width !== spalten || himmel.klein.height !== zeilen) {
    himmel.klein = Object.assign(document.createElement('canvas'), { width: spalten, height: zeilen });
  }
  const kg = himmel.klein.getContext('2d');
  const bild = kg.createImageData(spalten, zeilen);
  const px = bild.data;
  const f = himmelFarben();
  const t = ruhig ? 0 : jetzt / 1000;
  // Drei Stränge, schräg quer übers Bild, jeder mit eigenem Schwung und Tempo
  // Die Stränge liegen in der Mitte und im unteren Teil des Bildschirms. Jeder wandert zusätzlich
  // langsam auf und ab (zwei Sinuswellen mit krummem Tempo, das wirkt zufällig, wiederholt sich aber kaum).
  const straenge = [
    { y0: 0.76, neig: -0.16, a1: 0.12, k1: 2.7, p1: 0.3, w1: 0.11, a2: 0.05, k2: 6.3, p2: 1.1, w2: 0.17, dick: 0.07, hell: 1, h: 0.37 },
    { y0: 0.97, neig: -0.1, a1: 0.09, k1: 2.1, p1: 2.2, w1: 0.08, a2: 0.04, k2: 5.1, p2: 0.4, w2: 0.13, dick: 0.06, hell: 0.8, h: 0.23 },
    { y0: 0.58, neig: -0.22, a1: 0.08, k1: 3.4, p1: 4.0, w1: 0.14, a2: 0.03, k2: 8.7, p2: 2.6, w2: 0.2, dick: 0.045, hell: 0.55, h: 0.29 },
  ].map((st) => ({ ...st, y0: st.y0 + 0.06 * Math.sin(t * st.h * 0.31 + st.p1) + 0.035 * Math.sin(t * st.h * 0.73 + st.p2) }));
  let i = 0;
  for (let zy = 0; zy < zeilen; zy++) {
    const w = (zy + 0.5) / zeilen;
    for (let zx = 0; zx < spalten; zx++, i += 4) {
      const u = (zx + 0.5) / spalten;
      let licht = 0, saum = 0;
      for (const st of straenge) {
        const mitte = st.y0 + st.neig * (u - 0.5) + st.a1 * Math.sin(u * st.k1 + st.p1 + t * st.w1) + st.a2 * Math.sin(u * st.k2 + st.p2 - t * st.w2);
        const d = w - mitte; // > 0: unterhalb der Mitte
        // Unten eine klarere Kante, nach oben ein langer Vorhang wie auf dem Foto
        const profil = d > 0 ? Math.exp(-((d / (st.dick * 0.7)) ** 2)) : Math.exp(d / (st.dick * 4.6));
        // feine Striche quer zum Strang und Helligkeit, die am Strang entlang wandert
        const striche = 0.72 + 0.28 * Math.sin(u * 95 + 3 * Math.sin(u * 8 + t * st.w1 * 3 + st.p2));
        const puls = 0.65 + 0.35 * Math.sin(u * 2.7 + st.p1 - t * st.w2 * 2);
        const anteil = profil * striche * puls * st.hell;
        licht += anteil;
        saum += anteil * Math.min(1, Math.max(0, -d / (st.dick * 4.6)));
      }
      if (licht < 0.02) continue;
      const v = Math.min(1, licht);
      const m = Math.min(1, saum / licht * 1.3); // 0 im Kern, 1 oben im Vorhang
      const kernAnteil = Math.min(1, v * 1.2) * (1 - m);
      for (let k = 0; k < 3; k++) {
        const basis = f.rand[k] + (f.kern[k] - f.rand[k]) * kernAnteil;
        px[i + k] = basis + (f.saum[k] - basis) * m * 0.6;
      }
      px[i + 3] = Math.min(1, v ** 1.15 * 0.5) * 255;
    }
  }
  kg.putImageData(bild, 0, 0);

  const g = c.getContext('2d');
  g.setTransform(dpr, 0, 0, dpr, 0, 0);
  g.globalCompositeOperation = 'source-over';
  g.clearRect(0, 0, B, H);
  zeichneSterne(g, B, H, jetzt);
  // Punktoptik: das Polarlicht einmal weich groß ziehen und dann durch ein feines Punktraster stanzen.
  const pb = Math.round(B * dpr), ph = Math.round(H * dpr);
  if (!himmel.gross || himmel.gross.width !== pb || himmel.gross.height !== ph) {
    himmel.gross = Object.assign(document.createElement('canvas'), { width: pb, height: ph });
    himmel.muster = null;
  }
  const hg = himmel.gross.getContext('2d');
  hg.setTransform(dpr, 0, 0, dpr, 0, 0);
  hg.globalCompositeOperation = 'source-over';
  hg.clearRect(0, 0, B, H);
  hg.imageSmoothingEnabled = true;
  hg.imageSmoothingQuality = 'high';
  hg.drawImage(himmel.klein, 0, 0, spalten * z, zeilen * z);
  // Das Polarlicht leuchtet über den Sternen, wie am echten Himmel: erst ein schwacher weicher Schein ...
  g.setTransform(1, 0, 0, 1, 0, 0);
  g.globalCompositeOperation = 'screen';
  g.globalAlpha = 0.3;
  g.drawImage(himmel.gross, 0, 0);
  // ... dann dasselbe Licht als Punkte, die das Bild tragen.
  if (!himmel.muster) {
    const a = 5; // Punktabstand, feiner als auf der Startseite
    const kachel = Object.assign(document.createElement('canvas'), { width: a * dpr, height: a * dpr });
    const tg = kachel.getContext('2d');
    tg.scale(dpr, dpr);
    tg.fillStyle = '#000';
    tg.beginPath(); tg.arc(a / 2, a / 2, a * 0.36, 0, 6.283); tg.fill();
    himmel.muster = hg.createPattern(kachel, 'repeat');
    himmel.muster.setTransform(new DOMMatrix().scale(1 / dpr));
  }
  hg.globalCompositeOperation = 'destination-in';
  hg.fillStyle = himmel.muster;
  hg.fillRect(0, 0, B, H);
  g.globalAlpha = 1;
  g.drawImage(himmel.gross, 0, 0);
  g.setTransform(dpr, 0, 0, dpr, 0, 0);
  g.globalCompositeOperation = 'source-over';
  zeichneSchnuppen(g, B, H, jetzt);
}

// ---- LED-Tafel auf der Startseite: der heutige Depotverlauf aus Punkten ----
function zeichneLedTafel() {
  if (document.documentElement.dataset.stil !== 'vinter') return;
  document.querySelectorAll('.led-tafel').forEach(zeichneEineLedTafel);
}
function zeichneEineLedTafel(c) {
  const minuten = tagesDaten?.minuten;
  const B = c.clientWidth, H = c.clientHeight;
  if (!B || !H) return;
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  c.width = Math.round(B * dpr); c.height = Math.round(H * dpr);
  const g = c.getContext('2d');
  g.setTransform(dpr, 0, 0, dpr, 0, 0);
  g.clearRect(0, 0, B, H);
  const f = punkteFarben();
  const s = 6;
  const spalten = Math.floor(B / s), zeilen = Math.floor(H / s);
  if (!minuten?.length) {
    // Noch keine Kurse heute: die leere Tafel, damit nichts springt
    g.fillStyle = `rgba(${f.neutral.join(',')},.18)`;
    for (let i = 0; i < spalten; i++) for (let j = 0; j < zeilen; j++) { g.beginPath(); g.arc(i * s + s / 2, j * s + s / 2, 0.6, 0, 6.283); g.fill(); }
    return;
  }
  const werte = minuten.map((m) => m.w);
  const hoch = Math.max(0.2, ...werte.map(Math.abs));
  const nullZeile = Math.round((zeilen - 1) / 2);
  const zeileVon = (w) => Math.max(0, Math.min(zeilen - 1, Math.round(nullZeile - (w / hoch) * (zeilen / 2 - 1))));
  const farbe = werte.at(-1) >= 0 ? f.plus : f.minus;
  for (let i = 0; i < spalten; i++) {
    const w = werte[Math.min(werte.length - 1, Math.floor(i / spalten * werte.length))];
    const ziel = zeileVon(w);
    for (let j = 0; j < zeilen; j++) {
      const zwischen = (j >= Math.min(ziel, nullZeile) && j <= Math.max(ziel, nullZeile));
      const linie = j === ziel;
      const alpha = linie ? 1 : zwischen ? 0.5 : j === nullZeile ? 0.3 : 0.1;
      const r = linie ? 2.3 : zwischen ? 1.8 : 0.8;
      g.fillStyle = linie || zwischen ? `rgba(${farbe.join(',')},${alpha})` : `rgba(${f.neutral.join(',')},${alpha})`;
      g.beginPath(); g.arc(i * s + s / 2, j * s + s / 2, r, 0, 6.283); g.fill();
    }
  }
}
addEventListener('resize', zeichneLedTafel);

lavaGroesse();
addEventListener('resize', () => { lavaGroesse(); zeichneLava(performance.now()); });
// Wer weniger Bewegung eingestellt hat, bekommt ein ruhiges Standbild.
if (!matchMedia('(prefers-reduced-motion: reduce)').matches) requestAnimationFrame(lavaSchleife);

// Depot-Stimmung als Akzentfarbe: Plus grün, Minus rot, kleine Bewegungen neutral (Schwelle einstellbar).
let depotTag = null;
let depotTagLive = false; // true, sobald der Live-Tageswert aus /api/perioden da ist
let stimmungSchwelle = 0.3;
try {
  const gemerkt = localStorage.getItem('stimmungSchwelle');
  if (gemerkt !== null && Number(gemerkt) >= 0 && Number(gemerkt) <= 5) stimmungSchwelle = Number(gemerkt);
} catch {}
el('s-schwelle').value = String(stimmungSchwelle);
// Start-Animation der Lichter: erst zünden, wenn die Tagesfarbe (grün/rot) feststeht, damit das Licht
// nicht grün aufleuchtet und dann auf rot springt. Spätestens nach 2,5 Sekunden geht es trotzdem los.
let lichtGezuendet = false;
function zuendeLicht() {
  if (lichtGezuendet) return;
  lichtGezuendet = true;
  const c = el('lava');
  c.classList.remove('intro-warten');
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  c.classList.add('intro');
  c.addEventListener('animationend', () => c.classList.remove('intro'), { once: true });
}
// Kurz auf die Daten warten; kommen sie nicht schnell, startet das Licht weiß und färbt sich später.
el('lava').classList.add('intro-warten');
setTimeout(zuendeLicht, 700);
// Kommt der Live-Wert gar nicht, färbt der Schlusskurs-Wert das Licht nach 8 Sekunden.
setTimeout(() => { if (depotTag !== null) faerbeLicht(); }, 8000);
function faerbeLicht() {
  if (lichtFarbe.da) return;
  lichtFarbe.da = true;
  // Noch nicht gezündet oder weniger Bewegung gewünscht: gleich in der richtigen Farbe, ohne Übergang.
  lichtFarbe.ab = !lichtGezuendet || matchMedia('(prefers-reduced-motion: reduce)').matches ? -1e9 : performance.now();
}
function setzeStimmung() {
  if (depotTag === null) return;
  const neutral = Math.abs(depotTag) < stimmungSchwelle;
  document.body.classList.toggle('tag-neutral', neutral);
  document.body.classList.toggle('tag-plus', !neutral && depotTag > 0);
  document.body.classList.toggle('tag-minus', !neutral && depotTag < 0);
}
el('s-schwelle').addEventListener('change', (e) => {
  const wert = Number(String(e.target.value).replace(',', '.'));
  if (!(wert >= 0 && wert <= 5)) { e.target.value = String(stimmungSchwelle); return; }
  stimmungSchwelle = wert;
  try { localStorage.setItem('stimmungSchwelle', String(wert)); } catch {}
  setzeStimmung();
});

async function ladeVerlauf() {
  let d;
  try {
    d = await api(mitVorboerse('/api/verlauf'));
  } catch {
    d = { fehler: 'Der Depot-Verlauf konnte nicht geladen werden. Läuft der Server noch?' };
  }
  // Derselbe Verlauf liefert die Kerzen für Monat, Jahr und Gesamt auf "Gewinn & Verlust".
  if (!d.fehler || !verlaufDaten) verlaufDaten = d;
  if (chartZeitraum !== 'tag') zeigeChart();
  if (d.fehler || d.tag === null) return;
  // Nur als Startwert, bis der Live-Tageswert da ist.
  if (!depotTagLive) { depotTag = d.tag; setzeStimmung(); }
  const titel = `Depot am ${lokal(d.stand).toLocaleDateString('de-DE')}: ${prozent.format(d.tag)} %`;
  document.querySelectorAll('.wortmarke, .leiste-titel').forEach((m) => { m.title = titel; });
}

// ---- Menü mit den drei Strichen: Hover am PC, Tippen am Handy ----
const menue = el('menue');
// Laufende Nummer jeder Zeile: Je weiter unten, desto später fährt sie ins Bild.
document.querySelectorAll('.tabs .tab-titel, .tabs .tab').forEach((zeile, i) => zeile.style.setProperty('--i', i));
function menueOffen(offen) {
  menue.classList.toggle('offen', offen);
  el('menue-knopf').setAttribute('aria-expanded', String(offen));
}
el('menue-knopf').addEventListener('click', () => menueOffen(!menue.classList.contains('offen')));
document.addEventListener('click', (e) => { if (!menue.contains(e.target)) menueOffen(false); });
document.addEventListener('keydown', (e) => { if (e.key === 'Escape') menueOffen(false); });
el('menue-liste').addEventListener('click', (e) => {
  if (!e.target.closest('a')) return;
  menueOffen(false);
  menue.classList.add('gesperrt'); // schließt das Menü sofort, auch wenn die Maus noch darauf liegt
});
menue.addEventListener('mouseleave', () => menue.classList.remove('gesperrt'));
// Die Seitenleiste scrollt, wenn sie (mit aufgeklappten Untermenüs) länger als der Bildschirm ist.
// Das Glas dahinter muss dann so hoch sein wie der ganze Inhalt, sonst endet es beim Scrollen mitten im Menü.
{
  const liste = el('menue-liste');
  const hoehe = () => liste.style.setProperty('--tabs-hoehe', `${liste.scrollHeight}px`);
  const beobachter = new ResizeObserver(hoehe);
  liste.querySelectorAll('.tab-gruppe').forEach((g) => beobachter.observe(g));
  menue.addEventListener('mouseenter', hoehe);
  el('menue-knopf').addEventListener('click', hoehe);
}

// ---- Startseite: Gesamtansicht ----
function ergebnisDetail(s) {
  const unrealisiert = `Unrealisiert ${plusEuro.format(s.gv)}${s.gv_prozent === null ? '' : ` (${prozent.format(s.gv_prozent)} %)`}`;
  return `${unrealisiert} · Realisiert ${plusEuro.format(s.realisiert)} · Dividenden ${plusEuro.format(s.dividenden)}`;
}

function fuelleGesamt(d, jahr) {
  const s = d.summen;
  el('g-status').textContent = positionenStatus(d);
  setzeWert('g-wert', euro.format(s.wert), 0);
  el('g-einstand').textContent = `Einstand ${euro.format(s.einstand)}`;
  setzeWert('g-gv', plusEuro.format(s.gesamt), s.gesamt);
  el('g-gv-prozent').textContent = ergebnisDetail(s);
  setzeWert('g-real', plusEuro.format(jahr ? jahr.gewinn : 0), jahr ? jahr.gewinn : 0);
  el('g-real-details').textContent = jahr ? `${jahr.verkaeufe} Verkäufe` : 'Noch keine Verkäufe';
  el('g-positionen').innerHTML = d.positionen.slice(0, 5).map((p) => wertZeile('reihe', p.ticker, `
      <span class="reihe-name">${esc(p.name)}</span>
      <span>${p.wert_eur === null ? '–' : euro.format(p.wert_eur)}
        ${p.gv_prozent === null ? '' : `<span class="klein ${klasse(p.gv_eur)}">${prozent.format(p.gv_prozent)} %</span>`}</span>
    `, 'Chart öffnen (Strg+Klick: Yahoo Finance)', p.name)).join('');
}

async function ladeGesamtTermine() {
  const { termine, hinweise } = await alleTermine();
  kopfHeute(termine);
  const heute = isoLokal(new Date());
  const naechste = termine.filter((t) => t.datum >= heute).slice(0, 6);
  if (!naechste.length) {
    el('g-termine').innerHTML = `<p class="sekundaer">${esc(hinweise[0] ?? 'Keine Termine in nächster Zeit.')}</p>`;
    return;
  }
  el('g-termine').innerHTML = naechste.map((t) => {
    const tag = lokal(t.datum);
    const zeit = t.makro ? t.uhrzeit : t.zeit_de;
    return `<button type="button" class="reihe klickbar ${t.makro ? 'makro' : t.eigen ? 'eigen' : ''}" ${terminAttribut(t)}>
      <span><span class="reihe-name">${esc(t.name)}</span></span>
      <span>${tagNamen[(tag.getDay() + 6) % 7]} ${deutschKurz.format(tag)}${zeit ? `<span class="klein">${esc(zeit)} Uhr</span>` : ''}</span>
    </button>`;
  }).join('');
}

el('runter').addEventListener('click', () => {
  const ruhig = matchMedia('(prefers-reduced-motion: reduce)').matches;
  el('gesamt').scrollIntoView({ behavior: ruhig ? 'auto' : 'smooth' });
});

// ---- Gewinn und Verlust nach Zeitraum ----
const PERIODEN_TEXT = { tag: 'seit dem letzten Schlusskurs', woche: 'in den letzten 7 Tagen', monat: 'seit Monatsbeginn', ytd: 'seit Jahresbeginn', jahr: 'in den letzten 12 Monaten', ny: 'seit New York Open' };
let periodenDaten = null;
let periodenIsin = ''; // leer = alle Positionen
let periodenEinheit = 'eur'; // "eur" oder "prozent"
try { if (localStorage.getItem('periodenEinheit') === 'prozent') periodenEinheit = 'prozent'; } catch {}
const plusProzent = (w) => (w === null || w === undefined ? '–' : `${prozent.format(w)} %`);
let periodenZeit = 'tag';
try { if (PERIODEN_TEXT[localStorage.getItem('periodenZeit')]) periodenZeit = localStorage.getItem('periodenZeit'); } catch {}

function periodenZeile(p) {
  const art = artNamen[p.art] ?? p.art;
  const unter = [art, p.ticker, p.verkauft ? 'verkauft' : ''].filter(Boolean).join(' · ');
  // Groß steht, was oben gewählt ist (€ oder %), klein darunter das andere.
  const [gross, klein] = periodenEinheit === 'prozent'
    ? [plusProzent(p.gv_prozent), plusEuro.format(p.gv_eur)]
    : [plusEuro.format(p.gv_eur), p.gv_prozent === null ? '' : plusProzent(p.gv_prozent)];
  const wert = p.gv_eur === null
    ? '<span class="klein alt">keine Kurse</span>'
    : `<span class="${klasse(p.gv_eur)}">${gross}${klein ? `<span class="klein ${klasse(p.gv_eur)}">${klein}</span>` : ''}</span>`;
  return wertZeile('reihe', p.ticker, `
    <span><span class="reihe-name">${esc(p.name)}</span><span class="klein">${esc(unter)}</span></span>
    ${wert}
  `, 'Chart öffnen (Strg+Klick: Yahoo Finance)');
}

// Die Auswahl wird nur bei geänderten Positionen neu gebaut, sonst klappt sie beim Aktualisieren zu.
function fuellePositionsAuswahl() {
  const namen = new Map();
  for (const z of Object.values(periodenDaten.zeitraeume)) for (const p of z.positionen) namen.set(p.isin, p.name);
  const sortiert = [...namen].sort((a, b) => a[1].localeCompare(b[1], 'de'));
  const auswahl = el('p-position');
  const kennung = sortiert.map(([isin]) => isin).join();
  if (auswahl.dataset.kennung !== kennung) {
    auswahl.dataset.kennung = kennung;
    auswahl.innerHTML = `<option value="">Alle Positionen</option>${sortiert.map(([isin, name]) => `<option value="${esc(isin)}">${esc(name)}</option>`).join('')}`;
  }
  if (!namen.has(periodenIsin)) periodenIsin = '';
  auswahl.value = periodenIsin;
}

function zeichnePerioden() {
  document.querySelectorAll('#p-filter button').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.zeit === periodenZeit)));
  // "NY Open" gehört zum Tag: Der Knopf fährt nur aus, wenn Tag oder NY Open gewählt ist.
  el('p-filter').classList.toggle('ny-offen', periodenZeit === 'tag' || periodenZeit === 'ny');
  const inProzent = periodenEinheit === 'prozent';
  el('p-position').classList.toggle('gewaehlt', Boolean(periodenIsin));
  if (!periodenDaten) return;
  const z = periodenDaten.zeitraeume[periodenZeit];
  if (!z) return;
  // Vor 15:30 (bzw. 14:30) oder an US-Feiertagen gibt es "seit NY-Öffnung" noch nicht.
  if (z.hinweis) {
    setzeWert('p-summe', '–', 0);
    el('p-details').textContent = z.hinweis;
    el('p-liste').innerHTML = '';
    return;
  }
  const seit = periodenZeit === 'ny' ? `seit New York Open um ${z.oeffnung} Uhr`
    : periodenZeit === 'tag' && periodenDaten.tr ? 'seit dem letzten Kurs gestern, wie bei Trade Republic (ohne Krypto)'
      : `${PERIODEN_TEXT[periodenZeit]}${periodenDaten.tr ? ', ohne Krypto' : ''}`;
  const stand = periodenDaten.aktualisiert ? `Stand ${zeitText(periodenDaten.aktualisiert)} Uhr` : '';

  if (periodenIsin) {
    const p = z.positionen.find((x) => x.isin === periodenIsin);
    const bekannt = p && p.gv_eur !== null;
    setzeWert('p-summe', !bekannt ? '–' : inProzent ? plusProzent(p.gv_prozent) : plusEuro.format(p.gv_eur), bekannt ? p.gv_eur : 0);
    el('p-details').textContent = !p ? `In diesem Zeitraum nicht im Depot`
      : !bekannt ? 'Für diese Position gibt es keine Kurse'
      : [inProzent ? plusEuro.format(p.gv_eur) : p.gv_prozent === null ? '' : plusProzent(p.gv_prozent), seit, p.verkauft ? 'verkauft' : '', stand].filter(Boolean).join(' · ');
    el('p-liste').innerHTML = '';
    return;
  }

  setzeWert('p-summe', inProzent ? plusProzent(z.gv_prozent) : plusEuro.format(z.gv_eur), z.gv_eur);
  el('p-details').textContent = [
    inProzent ? plusEuro.format(z.gv_eur) : z.gv_prozent === null ? '' : plusProzent(z.gv_prozent),
    seit,
    stand,
    z.ohne_daten ?`${z.ohne_daten} Position(en) ohne Kurse fehlen in der Summe` : '',
  ].filter(Boolean).join(' · ');
  // In Prozent nach Prozent sortiert, sonst nach Euro (so kommt es vom Server).
  const liste = inProzent ? [...z.positionen].sort((a, b) => (b.gv_prozent ?? -Infinity) - (a.gv_prozent ?? -Infinity)) : z.positionen;
  el('p-liste').innerHTML = liste.map(periodenZeile).join('');
}
function setzeEinheit(einheit) {
  periodenEinheit = einheit;
  try { localStorage.setItem('periodenEinheit', periodenEinheit); } catch {}
  zeichnePerioden();
  zeigeChart(); // Chart und Liste zeigen immer dieselbe Einheit
}
// Ein Klick auf die große Zahl (im Chart oder unten) wechselt zwischen € und %.
for (const id of ['c-wert', 'p-summe']) {
  const zahl = el(id);
  zahl.classList.add('einheit-wechsel');
  zahl.tabIndex = 0;
  zahl.setAttribute('role', 'button');
  zahl.title = 'Klicken: zwischen Euro und Prozent wechseln';
  const wechsel = () => setzeEinheit(periodenEinheit === 'prozent' ? 'eur' : 'prozent');
  zahl.addEventListener('click', wechsel);
  zahl.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); wechsel(); } });
}

// Der Chart rechnet in Prozent. Für Euro wird mit dem Betrag des passenden Zeitraums umgerechnet:
// Euro je Prozentpunkt = Gewinn/Verlust in € geteilt durch Gewinn/Verlust in %. "Gesamt" hat dafür
// eine eigene Euro-Reihe (Summe der täglichen Kursgewinne), die Kerzen sind dort direkt in Euro.
function chartEuroFaktor() {
  if (periodenEinheit !== 'prozent' && chartAnsicht?.euro) return 1; // Kerzen sind schon in Euro
  if (periodenEinheit !== 'prozent' && periodenDaten) {
    const schluessel = chartZeitraum === 'tag' ? (vorboerse === 'ny' ? 'ny' : 'tag') : chartZeitraum;
    const z = periodenDaten.zeitraeume?.[schluessel];
    if (z && z.gv_eur != null && z.gv_prozent != null && Math.abs(z.gv_prozent) >= 0.02) return z.gv_eur / z.gv_prozent;
  }
  return null;
}
const chartZahl = (w, faktor = chartEuroFaktor()) => (faktor === null ? `${prozent.format(w)} %` : plusEuro.format(w * faktor));

el('p-filter').addEventListener('click', (e) => {
  const knopf = e.target.closest('button');
  if (!knopf) return;
  periodenZeit = knopf.dataset.zeit;
  try { localStorage.setItem('periodenZeit', periodenZeit); } catch {}
  zeichnePerioden();
});
el('p-position').addEventListener('change', (e) => {
  periodenIsin = e.target.value;
  zeichnePerioden();
});
zeichnePerioden();

async function ladePerioden() {
  let d;
  try {
    d = await api(mitVorboerse('/api/perioden'));
  } catch {
    d = { fehler: 'Die Daten konnten nicht geladen werden. Läuft der Server noch?' };
  }
  if (d.fehler) {
    if (!periodenDaten) el('p-details').textContent = d.fehler; // sonst bleibt der letzte Stand stehen
    return;
  }
  periodenDaten = d;
  // Die Stimmung (grün/rot) folgt dem Live-Tageswert, nicht dem Schlusskurs-Verlauf (der hinkt bis zu einer Stunde
  // und nimmt den heutigen Tag erst, wenn die meisten Börsen Kurse haben).
  const heute = d.zeitraeume?.tag?.gv_prozent;
  if (heute !== null && heute !== undefined && Number.isFinite(heute)) { depotTag = heute; depotTagLive = true; setzeStimmung(); faerbeLicht(); requestAnimationFrame(() => requestAnimationFrame(zuendeLicht)); }
  fuellePositionsAuswahl();
  zeichnePerioden();
  if (chartAnsicht) zeigeChart(); // der Chart braucht die Euro-Beträge für die Umrechnung
}

// ---- Zoomen und Verschieben entlang der Zeitachse (für alle Zeit-Charts) ----
// Strg + Mausrad (oder Zwei-Finger-Zoom am Trackpad) zoomt an der Zeigerstelle, Ziehen oder
// waagrechtes Scrollen verschiebt, Doppelklick zeigt wieder alles. Auf dem Handy: zwei Finger zoomen,
// ein Finger wischt waagrecht. Gerechnet wird in Einheiten der Achse (Kerzen-Plätze oder Tage):
// ganz() nennt den ganzen Bereich, lage() die Zeichenfläche in Pixeln, zeichnen() malt neu.
const SCHOENE_SCHRITTE = [1, 2, 3, 4, 5, 6, 8, 10, 12, 15, 20, 25, 30, 40, 50, 60, 80, 100, 150, 200, 250, 300, 400, 500, 1000];
const schrittFuer = (anzahl, hoechstens) => SCHOENE_SCHRITTE.find((s) => anzahl / s <= hoechstens) ?? Math.ceil(anzahl / hoechstens);
const grobZeiger = matchMedia('(pointer: coarse)').matches;

function zeitZoom(ziel, { ganz, lage, minBreite, zeichnen, leiste = null }) {
  const z = { von: null, bis: null, zieht: false };
  // Hält den Ausschnitt im erlaubten Bereich. null heißt: alles zu sehen.
  const begrenzen = (von, bis) => {
    const g = ganz();
    const voll = g.bis - g.von;
    const breite = Math.min(voll, Math.max(Math.min(voll, minBreite()), bis - von));
    if (breite >= voll - 1e-9) return null;
    const anfang = Math.min(g.bis - breite, Math.max(g.von, von));
    return { von: anfang, bis: anfang + breite };
  };
  z.ausschnitt = () => {
    const g = ganz();
    const b = z.von === null ? null : begrenzen(z.von, z.bis);
    return b ?? { von: g.von, bis: g.bis };
  };
  z.gezoomt = () => z.von !== null && begrenzen(z.von, z.bis) !== null;

  // Mehrere Ereignisse pro Bildschirmbild werden zu einem Neuzeichnen zusammengefasst.
  let geplant = false;
  const malen = () => {
    if (geplant) return;
    geplant = true;
    requestAnimationFrame(() => { geplant = false; zeichnen(); leisteAktualisieren(); });
  };
  z.setze = (von, bis) => {
    const b = begrenzen(von, bis);
    z.von = b?.von ?? null; z.bis = b?.bis ?? null;
    malen();
  };
  z.zuruecksetzen = () => { z.von = z.bis = null; malen(); };
  z.loesen = () => { z.von = z.bis = null; leisteAktualisieren(); }; // ohne Neuzeichnen, für Daten- oder Zeitraumwechsel

  const anteil = (clientX) => {
    const { links, breite } = lage();
    return Math.min(1, Math.max(0, (clientX - ziel.getBoundingClientRect().left - links) / breite));
  };
  // Zoomt so, dass der Wert an der Stelle f (0 = links, 1 = rechts) dort stehen bleibt.
  z.zoom = (faktor, f = 0.5, basis = z.ausschnitt()) => {
    const mitte = basis.von + (basis.bis - basis.von) * f;
    const neu = (basis.bis - basis.von) * faktor;
    z.setze(mitte - neu * f, mitte - neu * f + neu);
  };
  const schieben = (px, basis = z.ausschnitt()) => {
    const proPixel = (basis.bis - basis.von) / lage().breite;
    z.setze(basis.von + px * proPixel, basis.bis + px * proPixel);
  };

  ziel.addEventListener('wheel', (e) => {
    const zeile = e.deltaMode === 1 ? 16 : 1; // manche Mäuse melden Zeilen statt Pixel
    if (e.ctrlKey || e.metaKey) {
      e.preventDefault(); // sonst zoomt der Browser die ganze Seite
      z.zoom(Math.exp(e.deltaY * zeile * 0.0025), anteil(e.clientX));
    } else if (z.gezoomt() && (e.shiftKey || Math.abs(e.deltaX) > Math.abs(e.deltaY))) {
      e.preventDefault();
      schieben((e.deltaX || e.deltaY) * zeile);
    }
  }, { passive: false });

  // Ziehen mit Maus oder Finger; zwei Finger zoomen.
  const finger = new Map();
  let start = null;
  ziel.addEventListener('pointerdown', (e) => {
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    finger.set(e.pointerId, e.clientX);
    const basis = z.ausschnitt();
    if (finger.size === 2) {
      const [a, b] = [...finger.values()];
      start = { art: 'zwei', abstand: Math.max(20, Math.abs(a - b)), f: anteil((a + b) / 2), basis };
    } else if (finger.size === 1) {
      start = { art: 'zug', x: e.clientX, y: e.clientY, basis };
    }
  });
  ziel.addEventListener('pointermove', (e) => {
    if (!start || !finger.has(e.pointerId)) return;
    finger.set(e.pointerId, e.clientX);
    if (start.art === 'zwei') {
      const [a, b] = [...finger.values()];
      if (!z.zieht) { z.zieht = true; ziel.classList.add('zieht'); }
      z.zoom(start.abstand / Math.max(20, Math.abs(a - b)), start.f, start.basis);
      return;
    }
    const dx = e.clientX - start.x;
    if (!z.zieht) {
      // Erst ab ein paar Pixeln und eher waagrecht gilt es als Ziehen, sonst bleibt es ein Tippen
      // (Tooltip) oder senkrechtes Scrollen der Seite.
      if (Math.abs(dx) < 5 || Math.abs(dx) < Math.abs(e.clientY - start.y)) return;
      if (!z.gezoomt()) { start = null; return; }
      z.zieht = true;
      ziel.classList.add('zieht');
      try { ziel.setPointerCapture(e.pointerId); } catch {}
    }
    schieben(-dx, start.basis); // 1:1 mit dem Zeiger
  });
  const loslassen = (e) => {
    finger.delete(e.pointerId);
    if (finger.size) return;
    start = null;
    if (z.zieht) { z.zieht = false; ziel.classList.remove('zieht'); }
  };
  ziel.addEventListener('pointerup', loslassen);
  ziel.addEventListener('pointercancel', loslassen);
  ziel.addEventListener('dblclick', () => z.zuruecksetzen());
  ziel.addEventListener('keydown', (e) => {
    const faktor = { '+': 0.7, '=': 0.7, '-': 1 / 0.7 }[e.key];
    if (faktor) { e.preventDefault(); z.zoom(faktor); } else if (e.key === '0') { e.preventDefault(); z.zuruecksetzen(); }
  });

  // Hinweiszeile unter dem Chart, mit Knopf zurück zur Gesamtansicht.
  function leisteAktualisieren() {
    if (!leiste) return;
    if (!leiste.firstChild) {
      leiste.innerHTML = `<span>${grobZeiger ? 'Zwei Finger: zoomen · wischen: verschieben' : 'Strg + Mausrad: zoomen · ziehen: verschieben · Doppelklick: alles'}</span><button type="button" class="knopf zoom-zurueck" hidden>Alles zeigen</button>`;
      leiste.querySelector('button').addEventListener('click', () => z.zuruecksetzen());
    }
    leiste.querySelector('button').hidden = !z.gezoomt();
    ziel.classList.toggle('gezoomt', z.gezoomt());
  }
  leisteAktualisieren();
  return z;
}

// Beschriftungen nur dort, wo sie nicht über den Rand hinausragen.
const imBild = (x, links, rechts, halb = 16) => x >= links + halb && x <= rechts - halb;

// ---- Depot-Chart als Kerzen: SVG von Hand, damit keine fremde Bibliothek nötig ist ----
// Zeitraum "Tag" kommt aus Minutenkursen (/api/tagesverlauf), alle längeren Zeiträume aus dem
// täglichen Depot-Verlauf (/api/verlauf). Die Kerzen baut die Seite selbst in der gewählten Länge.
let tagesDaten = null;   // Minutenwerte des jüngsten Handelstags
let verlaufDaten = null; // Tageswerte seit dem ersten Kauf, als Index (Start = 100)
let stundenDaten = null; // Stundenwerte der letzten zwei Monate, ebenfalls als Index
let chartAnsicht = null; // die gerade gezeichneten Kerzen samt Achse
let chartLage = null;    // merkt sich die Maße für den Tooltip

// Kerzenlängen je Zeitraum so, dass es etwa 20 bis 130 Kerzen gibt.
const CHART_ZEITRAUM = {
  tag: { name: 'Tag', laengen: [5, 10, 15, 30, 60], standard: 10 },
  woche: { name: 'Woche', laengen: [60, 240, 'tag'], standard: 60 },
  monat: { name: 'Monat', laengen: [60, 240, 'tag'], standard: 240 },
  ytd: { name: 'Seit Jahresbeginn', laengen: ['tag', 'woche', 'monat'], standard: 'woche' },
  jahr: { name: '1 Jahr', laengen: ['tag', 'woche', 'monat'], standard: 'woche' },
  gesamt: { name: 'Gesamt', laengen: ['tag', 'woche', 'monat'], standard: 'woche' },
};
const LAENGE_NAME = { 1: '1 Min', 2: '2 Min', 5: '5 Min', 10: '10 Min', 15: '15 Min', 30: '30 Min', 60: '1 Std', 240: '4 Std', tag: '1 Tag', woche: '1 Woche', monat: '1 Monat' };
let chartZeitraum = 'tag';
const chartLaenge = { tag: 10, woche: 60, monat: 240, ytd: 'woche', jahr: 'woche', gesamt: 'woche' };
// Bei New York Open ist der Chart nur wenige Stunden lang: dann gibt es auch 1- und 2-Minuten-Kerzen.
const NY_LAENGEN = [1, 2, 5, 10, 15, 30];
const laengenFuer = (z) => (z === 'tag' && vorboerse === 'ny' ? NY_LAENGEN : CHART_ZEITRAUM[z].laengen);
try {
  const gemerkt = JSON.parse(localStorage.getItem('chartWahl') ?? 'null');
  if (gemerkt && CHART_ZEITRAUM[gemerkt.zeitraum]) {
    chartZeitraum = gemerkt.zeitraum;
    Object.entries(gemerkt.laenge ?? {}).forEach(([z, l]) => { if (CHART_ZEITRAUM[z] && laengenFuer(z).includes(l)) chartLaenge[z] = l; });
  }
} catch {}

const achsenProzent = (schritt) => new Intl.NumberFormat('de-DE', { minimumFractionDigits: schritt < 0.1 ? 2 : schritt < 1 ? 1 : 0, maximumFractionDigits: 2, signDisplay: 'exceptZero' });
const minutenVon = (hhmm) => { const [h, m] = hhmm.split(':').map(Number); return h * 60 + m; };
const uhrAus = (min) => `${String(Math.floor(min / 60)).padStart(2, '0')}:${String(min % 60).padStart(2, '0')}`;
const datumKurz = (iso) => lokal(iso).toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit' });
const datumLang = (iso) => lokal(iso).toLocaleDateString('de-DE', { weekday: 'short', day: '2-digit', month: '2-digit', year: 'numeric' });

// Runde Achsenwerte: höchstens etwa fünf Linien, die Null ist immer dabei.
// Achse ohne Nullpunkt mit "runden" Schritten (1, 2, 2,5, 5 mal Zehnerpotenz), z. B. für Kurse um 6.000
function achsenFrei(tief, hoch) {
  const spanne = hoch - tief || Math.abs(hoch) * 0.1 || 1;
  const roh = spanne / 4;
  const p = 10 ** Math.floor(Math.log10(roh));
  const schritt = [1, 2, 2.5, 5, 10].map((m) => m * p).find((x) => x >= roh);
  const werte = [];
  for (let n = Math.floor(tief / schritt); n <= Math.ceil(hoch / schritt); n++) werte.push(n * schritt);
  return { werte, schritt };
}
const achsenZahl = (schritt) => new Intl.NumberFormat('de-DE', { minimumFractionDigits: schritt < 0.1 ? 2 : schritt < 1 ? 1 : 0, maximumFractionDigits: 2 });

function achsenWerte(tief, hoch) {
  const unten = Math.min(tief, 0);
  const oben = Math.max(hoch, 0);
  const roh = Math.max((oben - unten || 0.2) / 4, 0.05);
  const p = 10 ** Math.floor(Math.log10(roh));
  const schritt = [1, 2, 2.5, 5, 10].map((m) => m * p).find((s) => s >= roh - 1e-12);
  const werte = [];
  for (let n = Math.floor(unten / schritt); n <= Math.ceil(oben / schritt); n++) werte.push(n * schritt);
  return { werte, schritt };
}

// Tag: Minutenwerte zu Kerzen von 5 bis 60 Minuten bündeln. Die Achse zeigt den ganzen Börsentag.
function ansichtTag(laenge) {
  if (!tagesDaten?.minuten?.length) return null;
  const gruppen = new Map();
  for (const { zeit, w } of tagesDaten.minuten) {
    const beginn = Math.floor(minutenVon(zeit) / laenge) * laenge;
    const k = gruppen.get(beginn);
    if (k) { k.h = Math.max(k.h, w); k.l = Math.min(k.l, w); k.c = w; } else gruppen.set(beginn, { beginn, o: w, h: w, l: w, c: w });
  }
  const liste = [...gruppen.values()];
  // Jede Kerze beginnt beim Schluss der vorigen (die erste bei 0 %, dem Vergleichswert). Sonst wäre eine
  // 1-Minuten-Kerze nur ein Punkt, weil es in einer Minute nur einen Kurs gibt.
  let vorher = 0;
  for (const k of liste) {
    k.o = vorher;
    k.h = Math.max(k.h, k.o);
    k.l = Math.min(k.l, k.o);
    vorher = k.c;
  }
  // Die Achse zeigt die Handelszeit der gewählten Ansicht (Trade Republic 8 bis 23 Uhr, New York ab Eröffnung).
  const achse = tagesDaten.achse;
  const start = achse ? Math.min(minutenVon(achse.von), liste[0].beginn) : Math.min(9 * 60, liste[0].beginn);
  const ende = Math.max(achse ? minutenVon(achse.bis) : 22 * 60, liste.at(-1).beginn + laenge);
  // Uhrzeiten für den sichtbaren Ausschnitt: je enger gezoomt, desto feiner (bis 5 Minuten).
  const achseFuer = (von, bis) => {
    const minuten = (bis - von) * laenge;
    const abstand = [5, 10, 15, 30, 60, 120, 180, 240].filter((m) => m >= laenge && m % laenge === 0).find((m) => minuten / m <= 6) ?? 360;
    const liste = [];
    for (let m = Math.ceil((start + von * laenge) / abstand) * abstand; m <= start + bis * laenge; m += abstand) liste.push({ slot: (m - start) / laenge, text: uhrAus(m) });
    return liste;
  };
  return {
    slots: (ende - start) / laenge,
    achseFuer,
    kerzen: liste.map((k) => ({ ...k, slot: (k.beginn - start) / laenge, titel: `${uhrAus(k.beginn)} bis ${uhrAus(k.beginn + laenge)} Uhr` })),
  };
}

// Längere Zeiträume: aus den Tagesschlusswerten. Eine Kerze beginnt beim Schluss der vorigen,
// Hoch und Tief sind die höchsten und tiefsten Schlusswerte darin (Tageshochs gibt es hier nicht).
function ansichtLang(zeitraum, laenge) {
  const punkte = verlaufDaten?.punkte;
  if (!punkte?.length) return null;
  const ab = chartAb(zeitraum);
  const erster = punkte.findIndex((p) => p.datum >= ab);
  if (erster < 0) return null;
  // In Euro: direkt die aufsummierten Kursgewinne seit dem Schluss vor dem Zeitraum. Eine Umrechnung
  // der Prozente wäre bei Käufen im Zeitraum falsch (zeitgewichtete Prozente, geldgewichtete Euro).
  const euro = periodenEinheit !== 'prozent' && punkte.every((p) => p.eur !== undefined);
  // Bezug ist der Schluss vor dem Zeitraum, damit die erste Kerze schon die erste Bewegung zeigt.
  const basis = punkte[Math.max(0, erster - 1)].wert;
  const basisEur = erster > 0 ? punkte[erster - 1].eur : 0;
  const prozentVon = (wert) => (wert / basis - 1) * 100;
  const wertVon = (p) => (euro ? p.eur - basisEur : prozentVon(p.wert));
  const schluessel = (iso) => {
    if (laenge === 'monat') return iso.slice(0, 7);
    if (laenge === 'woche') {
      const d = lokal(iso);
      d.setDate(d.getDate() - ((d.getDay() + 6) % 7)); // Montag dieser Woche
      return isoLokal(d);
    }
    return iso;
  };
  const kerzen = [];
  let vorher = erster > 0 || euro ? 0 : prozentVon(punkte[0].wert);
  for (const p of punkte.slice(erster)) {
    const w = wertVon(p);
    const k = kerzen.at(-1);
    if (k && k.schluessel === schluessel(p.datum)) {
      k.h = Math.max(k.h, w); k.l = Math.min(k.l, w); k.c = w; k.bis = p.datum;
    } else {
      kerzen.push({ schluessel: schluessel(p.datum), von: p.datum, bis: p.datum, o: vorher, h: Math.max(vorher, w), l: Math.min(vorher, w), c: w });
    }
    vorher = w;
  }
  kerzen.forEach((k, i) => {
    k.slot = i;
    k.titel = laenge === 'tag' ? datumLang(k.von)
      : laenge === 'woche' ? `Woche ${datumKurz(k.von)} bis ${datumKurz(k.bis)}`
      : lokal(k.von).toLocaleDateString('de-DE', { month: 'long', year: 'numeric' });
  });
  // Etwa fünf gleichmäßig verteilte Beschriftungen im sichtbaren Ausschnitt.
  const text = (k) => (laenge === 'monat' ? lokal(k.von).toLocaleDateString('de-DE', { month: 'short', year: '2-digit' }) : datumKurz(k.von));
  const achseFuer = (von, bis) => {
    const alle = schrittFuer(bis - von, 5);
    const liste = [];
    for (let i = Math.max(0, Math.ceil(von / alle) * alle); i < Math.min(bis, kerzen.length); i += alle) liste.push({ slot: i + 0.5, text: text(kerzen[i]) });
    return liste;
  };
  return { slots: Math.max(kerzen.length, 8), achseFuer, kerzen, euro, prozent: prozentVon(punkte.at(-1).wert) };
}

// Erster Tag eines Zeitraums (ISO). Woche und 1 Jahr zählen rollierend bis heute.
function chartAb(zeitraum) {
  const heute = new Date();
  const iso = isoLokal(heute);
  if (zeitraum === 'woche') { const d = new Date(heute); d.setDate(d.getDate() - 6); return isoLokal(d); }
  if (zeitraum === 'jahr') { const d = new Date(heute); d.setFullYear(d.getFullYear() - 1); d.setDate(d.getDate() + 1); return isoLokal(d); }
  return { monat: `${iso.slice(0, 8)}01`, ytd: `${iso.slice(0, 5)}01-01`, gesamt: '' }[zeitraum] ?? '';
}

// Monat in Stunden-Kerzen: aus dem Stundenverlauf. Nachts und am Wochenende gibt es keine Lücken,
// die Kerzen stehen einfach nebeneinander.
function ansichtStunden(laenge, zeitraum = 'monat') {
  const punkte = stundenDaten?.punkte;
  if (!punkte?.length) return null;
  const ab = chartAb(zeitraum);
  const erster = punkte.findIndex((p) => p.zeit >= ab);
  if (erster < 0) return null;
  const basis = punkte[Math.max(0, erster - 1)].wert;
  const kerzen = [];
  let vorher = erster > 0 ? 0 : (punkte[0].wert / basis - 1) * 100;
  for (const p of punkte.slice(erster)) {
    const w = (p.wert / basis - 1) * 100;
    const tag = p.zeit.slice(0, 10);
    const beginn = Math.floor(minutenVon(p.zeit.slice(11)) / laenge) * laenge;
    const k = kerzen.at(-1);
    if (k && k.tag === tag && k.beginn === beginn) { k.h = Math.max(k.h, w); k.l = Math.min(k.l, w); k.c = w; }
    else kerzen.push({ tag, beginn, o: vorher, h: Math.max(vorher, w), l: Math.min(vorher, w), c: w });
    vorher = w;
  }
  kerzen.forEach((k, i) => { k.slot = i; k.titel = `${datumLang(k.tag)}, ${uhrAus(k.beginn)} bis ${uhrAus(Math.min(k.beginn + laenge, 1440))} Uhr`; });
  // Beschriftung am ersten Balken eines Tages, höchstens etwa sechs. Ist so weit gezoomt,
  // dass kaum Tageswechsel zu sehen sind, stehen Uhrzeiten dazwischen.
  const tagesStart = (i) => i === 0 || kerzen[i - 1].tag !== kerzen[i].tag;
  const achseFuer = (von, bis) => {
    const sichtbar = kerzen.filter((k) => k.slot + 1 > von && k.slot < bis);
    const starts = sichtbar.filter((k) => tagesStart(k.slot));
    if (starts.length >= 2) {
      const alle = schrittFuer(starts.length, 6);
      return starts.filter((_, i) => i % alle === 0).map((k) => ({ slot: k.slot + 0.5, text: datumKurz(k.tag) }));
    }
    const alle = schrittFuer(bis - von, 5);
    return sichtbar.filter((k) => k.slot % alle === 0 || tagesStart(k.slot))
      .map((k) => ({ slot: k.slot + 0.5, text: tagesStart(k.slot) ? datumKurz(k.tag) : uhrAus(k.beginn) }));
  };
  return { slots: Math.max(kerzen.length, 12), achseFuer, kerzen };
}

function baueAnsicht() {
  const laenge = chartLaenge[chartZeitraum];
  if (chartZeitraum === 'tag') return ansichtTag(laenge);
  if (typeof laenge === 'number') return ansichtStunden(laenge, chartZeitraum);
  return ansichtLang(chartZeitraum, laenge);
}

async function ladeStunden() {
  let d;
  try {
    d = await api(mitVorboerse('/api/verlauf/stunden'));
  } catch {
    d = { fehler: 'Der Stundenverlauf konnte nicht geladen werden. Läuft der Server noch?' };
  }
  if (!d.fehler || !stundenDaten) stundenDaten = d;
  if (chartZeitraum === 'monat' || chartZeitraum === 'woche') zeigeChart();
}

// Umschalter für Zeitraum und Kerzenlänge; die Längen passen sich dem Zeitraum an.
function zeichneChartWahl() {
  el('c-zeitraum').innerHTML = Object.entries(CHART_ZEITRAUM).map(([z, info]) =>
    `<button type="button" data-zeitraum="${z}" aria-pressed="${z === chartZeitraum}">${info.name}</button>`).join('');
  el('c-laenge').innerHTML = laengenFuer(chartZeitraum).map((l) =>
    `<button type="button" data-laenge="${l}" aria-pressed="${l === chartLaenge[chartZeitraum]}">${LAENGE_NAME[l]}</button>`).join('');
}
function merkeChartWahl() {
  try { localStorage.setItem('chartWahl', JSON.stringify({ zeitraum: chartZeitraum, laenge: chartLaenge })); } catch {}
}
el('c-zeitraum').addEventListener('click', (e) => {
  const knopf = e.target.closest('button[data-zeitraum]');
  if (!knopf || knopf.dataset.zeitraum === chartZeitraum) return;
  chartZeitraum = knopf.dataset.zeitraum;
  el('c-zeitraum').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b === knopf)));
  // Die Längen-Knöpfe wechseln: ohne Gleiten, die alte Pille würde sonst über neue Knöpfe wandern.
  el('c-laenge').innerHTML = laengenFuer(chartZeitraum).map((l) =>
    `<button type="button" data-laenge="${l}" aria-pressed="${l === chartLaenge[chartZeitraum]}">${LAENGE_NAME[l]}</button>`).join('');
  setzePille(el('c-laenge'), true);
  merkeChartWahl();
  chartZoom.loesen();
  zeigeChart();
});
el('c-vorboerse').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.vorboerse === vorboerse)));
el('c-vorboerse').addEventListener('click', (e) => {
  const knopf = e.target.closest('button[data-vorboerse]');
  if (!knopf || knopf.dataset.vorboerse === vorboerse) return;
  vorboerse = knopf.dataset.vorboerse;
  try { localStorage.setItem('vorboerse', vorboerse); } catch {}
  el('c-vorboerse').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b === knopf)));
  chartZoom.loesen();
  // Passende Kerzenlänge: 1 und 2 Minuten gibt es nur bei New York Open.
  if (!laengenFuer('tag').includes(chartLaenge.tag)) chartLaenge.tag = vorboerse === 'ny' ? 5 : 10;
  if (chartZeitraum === 'tag') {
    el('c-laenge').innerHTML = laengenFuer('tag').map((l) =>
      `<button type="button" data-laenge="${l}" aria-pressed="${l === chartLaenge.tag}">${LAENGE_NAME[l]}</button>`).join('');
    setzePille(el('c-laenge'), true);
  }
  merkeChartWahl();
  VORBOERSE_PFADE.forEach((pfad) => { delete antworten[pfad]; delete antworten[`${pfad}?vorboerse=false`]; delete antworten[`${pfad}?tr=true`]; delete antworten[`${pfad}?ny=true`]; });
  el('c-details').textContent = 'Wird neu berechnet …';
  ladePerioden();
  ladeVerlauf();
  ladeStunden();
  ladeTagesverlauf();
  ladeLava();
});
el('c-laenge').addEventListener('click', (e) => {
  const knopf = e.target.closest('button[data-laenge]');
  if (!knopf) return;
  const roh = knopf.dataset.laenge;
  chartLaenge[chartZeitraum] = /^\d+$/.test(roh) ? Number(roh) : roh;
  el('c-laenge').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b === knopf)));
  merkeChartWahl();
  chartZoom.loesen();
  zeigeChart();
});

// Überschrift, große Zahl und Hinweiszeile passend zum Zeitraum, dann zeichnen.
function zeigeChart() {
  chartAnsicht = baueAnsicht();
  const tag = chartZeitraum === 'tag';
  // Die Auswahl betrifft nur den Tageschart. Sie gleitet aus und ein, ihr Platz bleibt aber reserviert,
  // damit der Chart darunter beim Wechsel nicht springt.
  el('c-vorboerse').classList.toggle('zu', !tag);
  el('c-vorboerse').querySelectorAll('button').forEach((b) => { b.tabIndex = tag ? 0 : -1; });
  if (!chartAnsicht?.kerzen.length) {
    el('c-wert').textContent = '–';
    el('c-details').textContent = tag
      ? (tagesDaten?.fehler ?? (tagesDaten ? 'Für diesen Tag gibt es noch keine Minutenkurse.' : 'Wird geladen …'))
      : (() => { const q = typeof chartLaenge[chartZeitraum] === 'number' ? stundenDaten : verlaufDaten; return q?.fehler ?? (q ? 'Für diesen Zeitraum gibt es noch keine Kurse.' : 'Wird geladen …'); })();
    el('c-svg').innerHTML = '';
    return;
  }
  const letzter = chartAnsicht.kerzen.at(-1).c;
  el('c-titel').textContent = tag
    ? (tagesDaten.modus === 'ny' ? `Depot seit New York Open (${tagesDaten.oeffnung} Uhr)`
      : `${tagesDaten.datum === isoLokal(new Date()) ? 'Depot heute' : `Depot am ${lokal(tagesDaten.datum).toLocaleDateString('de-DE')}`}${tagesDaten.modus === 'tr' ? ' · Trade Republic' : ''}`)
    : { woche: 'Depot in den letzten 7 Tagen', monat: 'Depot seit Monatsbeginn', ytd: 'Depot seit Jahresbeginn', jahr: 'Depot in den letzten 12 Monaten', gesamt: 'Depot seit dem ersten Kauf' }[chartZeitraum];
  const faktor = chartEuroFaktor();
  // Prozent auf das im Schnitt investierte Geld (wie in der Liste darunter); der Chart selbst rechnet zeitgewichtet.
  const geldProzent = tag ? null : periodenDaten?.zeitraeume?.[chartZeitraum]?.gv_prozent ?? null;
  setzeWert('c-wert', chartZahl(letzter, faktor), letzter);
  el('c-details').textContent = [
    chartAnsicht.euro ? `${geldProzent === null ? '' : `${prozent.format(geldProzent)} % auf das im Schnitt investierte Geld · `}${prozent.format(chartAnsicht.prozent)} % zeitgewichtet`
      : faktor === null ? (!tag && geldProzent !== null ? `zeitgewichtet wie ein Fonds · auf das im Schnitt investierte Geld ${prozent.format(geldProzent)} %` : '') : `${prozent.format(letzter)} %, in Euro umgerechnet`,
    `Kerzen à ${LAENGE_NAME[chartLaenge[chartZeitraum]]}`,
    'gefüllt gestiegen, hohl gefallen',
    tag ? `Stand ${zeitText(tagesDaten.aktualisiert)} Uhr`
      : typeof chartLaenge[chartZeitraum] === 'number' ? `aus Stundenkursen · Stand ${zeitText(stundenDaten.aktualisiert)} Uhr`
      : `aus Tagesschlusskursen bis ${datumKurz(verlaufDaten.stand)}`,
    tag && tagesDaten.ohne_daten ? `${tagesDaten.ohne_daten} Position(en) ohne Minutenkurse fehlen` : '',
  ].filter(Boolean).join(' · ');
  el('c-svg').setAttribute('aria-label', `${el('c-titel').textContent}: ${chartAnsicht.euro ? plusEuro.format(letzter) : `${prozent.format(letzter)} Prozent`}`);
  zeichneTageschart();
}

function zeichneTageschart() {
  const flaeche = el('c-flaeche');
  const breite = flaeche.clientWidth;
  if (!chartAnsicht?.kerzen.length || !breite) return; // nichts da oder die Seite ist gerade nicht sichtbar
  const { kerzen } = chartAnsicht;
  const hoehe = breite < 560 ? 220 : 280;
  // Sichtbarer Ausschnitt in Kerzen-Plätzen; ohne Zoom der ganze Zeitraum.
  const { von, bis } = chartZoom.ausschnitt();
  const sichtbar = kerzen.filter((c) => c.slot + 1 > von && c.slot < bis);
  // Die Höhe richtet sich nach den sichtbaren Kerzen, so wird beim Reinzoomen auch die Bewegung größer.
  const basis = sichtbar.length ? sichtbar : kerzen;
  const { werte, schritt } = achsenWerte(Math.min(...basis.map((c) => c.l)), Math.max(...basis.map((c) => c.h)));
  const oben = werte.at(-1);
  const unten = werte[0];
  const format = achsenProzent(schritt);
  const faktor = chartEuroFaktor();
  const euroAchse = (e) => `${Math.abs(e) < 0.5 ? '0' : `${e > 0 ? '+' : '−'}${Math.round(Math.abs(e)).toLocaleString('de-DE')}`} €`;
  // Linker Rand so breit wie die längste Beschriftung (z. B. "−1.000 €"), damit nichts abgeschnitten wird.
  const laengste = Math.max(...werte.map((w) => (faktor === null ? `${format.format(w)} %` : euroAchse(w * faktor)).length));
  const rand = { links: Math.max(46, laengste * 6.5 + 12), rechts: 6, oben: 8, unten: 22 };
  const innen = breite - rand.links - rand.rechts;
  const slot = innen / (bis - von);
  const xVon = (s) => rand.links + (s - von) * slot;
  const y = (w) => rand.oben + (oben - w) / (oben - unten) * (hoehe - rand.oben - rand.unten);

  const gitter = werte.map((w) => `<line x1="${rand.links}" x2="${breite - rand.rechts}" y1="${y(w)}" y2="${y(w)}" stroke="${w === 0 ? 'var(--grau)' : 'var(--linie)'}" stroke-opacity="${w === 0 ? 0.55 : 1}"/>
    <text class="c-achse" x="${rand.links - 8}" y="${y(w) + 4}" text-anchor="end">${faktor === null ? `${format.format(w)} %` : euroAchse(w * faktor)}</text>`).join('');
  let zuletzt = -Infinity;
  const achseX = chartAnsicht.achseFuer(von, bis).map((a) => {
    const x = xVon(a.slot);
    if (!imBild(x, rand.links - 10, breite) || x - zuletzt < 44) return ''; // nicht am Rand, nicht übereinander
    zuletzt = x;
    return `<text class="c-achse" x="${x}" y="${hoehe - 6}" text-anchor="middle">${a.text}</text>`;
  }).join('');

  const koerper = Math.min(18, Math.max(2, slot * 0.68));
  const marken = sichtbar.map((c) => {
    const steigt = c.c >= c.o;
    const farbe = steigt ? 'var(--gewinn)' : 'var(--verlust)';
    const mitte = xVon(c.slot) + slot / 2;
    const kopf = y(Math.max(c.o, c.c));
    const hoeheKoerper = Math.max(1, y(Math.min(c.o, c.c)) - kopf);
    // Rot und Grün sind bei Farbsehschwäche schwer zu trennen: fallende Kerzen sind deshalb hohl.
    const fuellung = steigt ? `fill="${farbe}"` : `fill="${farbe}" fill-opacity=".18" stroke="${farbe}"`;
    return `<line x1="${mitte}" x2="${mitte}" y1="${y(c.h)}" y2="${y(c.l)}" stroke="${farbe}"/>
      <rect x="${mitte - koerper / 2}" y="${kopf}" width="${koerper}" height="${hoeheKoerper}" rx="1" ${fuellung}/>`;
  }).join('');

  const svg = el('c-svg');
  svg.setAttribute('width', breite);
  svg.setAttribute('height', hoehe);
  svg.setAttribute('viewBox', `0 0 ${breite} ${hoehe}`);
  // Angeschnittene Kerzen am Rand werden an der Zeichenfläche abgeschnitten.
  svg.innerHTML = `<defs><clipPath id="c-clip"><rect x="${rand.links}" y="0" width="${innen}" height="${hoehe}"/></clipPath></defs>
    ${gitter}${achseX}<g clip-path="url(#c-clip)">${marken}</g><line id="c-linie" y1="${rand.oben}" y2="${hoehe - rand.unten}" stroke="var(--grau)" visibility="hidden"/>`;
  chartLage = { rand, slot, breite, innen, von, bis };
  // Steht der Zeiger noch über dem Chart (z. B. beim Zoomen mit dem Mausrad), bleibt der Tooltip da.
  if (chartZeigerX !== null && !chartZoom.zieht) tipAmZeiger({ clientX: chartZeigerX });
  else versteckeTip();
}

function zeigeTip(index) {
  const c = chartAnsicht?.kerzen[index];
  if (!c || !chartLage) return;
  chartLage.index = index;
  const { rand, slot, breite, von } = chartLage;
  const mitte = rand.links + (c.slot - von) * slot + slot / 2;
  const linie = el('c-linie');
  linie.setAttribute('x1', mitte);
  linie.setAttribute('x2', mitte);
  linie.setAttribute('visibility', 'visible');

  const faktor = chartEuroFaktor();
  const zahl = (w) => chartZahl(w, faktor);
  const tip = el('c-tip');
  tip.innerHTML = `<b>${zahl(c.c)}</b><small>${c.titel}</small>
    <div><span>Eröffnung</span><span>${zahl(c.o)}</span></div>
    <div><span>Hoch</span><span>${zahl(c.h)}</span></div>
    <div><span>Tief</span><span>${zahl(c.l)}</span></div>`;
  tip.hidden = false;
  // Steht neben der Linie und klappt am rechten Rand auf die andere Seite.
  const platz = tip.offsetWidth + 12;
  tip.style.left = `${mitte + platz < breite ? mitte + 12 : Math.max(0, mitte - platz)}px`;
}

function versteckeTip() {
  el('c-tip').hidden = true;
  el('c-linie')?.setAttribute('visibility', 'hidden');
  if (chartLage) chartLage.index = null;
}

// Findet die Kerze unter dem Zeiger, die ganze Spalte zählt als Trefferfläche.
let chartZeigerX = null; // letzte Zeigerposition über dem Chart, null = Zeiger ist weg
function tipAmZeiger(e) {
  if (!chartLage || !chartAnsicht) return;
  if (chartZoom.zieht) { versteckeTip(); return; } // beim Verschieben stört der Tooltip
  const { rand, slot, von, innen } = chartLage;
  const px = e.clientX - el('c-svg').getBoundingClientRect().left - rand.links;
  const spalte = Math.floor(von + px / slot);
  const index = px < 0 || px > innen ? -1 : chartAnsicht.kerzen.findIndex((c) => Math.round(c.slot) === spalte);
  if (index < 0) versteckeTip(); else zeigeTip(index);
}
const chartZoom = zeitZoom(el('c-svg'), {
  ganz: () => ({ von: 0, bis: chartAnsicht?.slots ?? 1 }),
  lage: () => ({ links: chartLage?.rand.links ?? 46, breite: chartLage?.innen ?? 1 }),
  minBreite: () => 6,
  zeichnen: zeichneTageschart,
  leiste: el('c-zoom'),
});
el('c-svg').addEventListener('pointermove', (e) => { chartZeigerX = e.clientX; tipAmZeiger(e); });
el('c-svg').addEventListener('pointerdown', tipAmZeiger);
el('c-svg').addEventListener('pointerleave', () => { chartZeigerX = null; versteckeTip(); });
el('c-svg').addEventListener('pointercancel', () => { chartZeigerX = null; versteckeTip(); });
el('c-svg').addEventListener('focus', () => { if (chartAnsicht?.kerzen.length) zeigeTip(chartAnsicht.kerzen.length - 1); });
el('c-svg').addEventListener('blur', versteckeTip);
el('c-svg').addEventListener('keydown', (e) => {
  const schritt = { ArrowLeft: -1, ArrowRight: 1 }[e.key];
  if (!schritt || !chartAnsicht?.kerzen.length) return;
  e.preventDefault();
  const letzte = chartAnsicht.kerzen.length - 1;
  const index = Math.min(letzte, Math.max(0, (chartLage.index ?? letzte) + schritt));
  // Läuft die Auswahl aus dem Ausschnitt, wandert der Ausschnitt mit.
  const s = chartAnsicht.kerzen[index].slot;
  const { von, bis } = chartZoom.ausschnitt();
  if (s < von || s + 1 > bis) {
    const neuVon = s < von ? s : s + 1 - (bis - von);
    chartZoom.setze(neuVon, neuVon + (bis - von));
    requestAnimationFrame(() => requestAnimationFrame(() => zeigeTip(index)));
  } else zeigeTip(index);
});
window.addEventListener('resize', zeichneTageschart);

async function ladeTagesverlauf() {
  let d;
  try {
    d = await api(mitVorboerse('/api/tagesverlauf'));
  } catch {
    d = { fehler: 'Der Tagesverlauf konnte nicht geladen werden. Läuft der Server noch?' };
  }
  // Bei einem Fehler bleibt der letzte Stand stehen, aber nur, wenn er zur gewählten Ansicht gehört.
  // Sonst stünde z. B. vor 15:30 bei "New York Open" noch der Chart "Mit Vorbörse" da.
  const erwartet = { tr: 'tr', ny: 'ny' }[vorboerse];
  const andereAnsicht = (tagesDaten?.modus ?? undefined) !== erwartet;
  if (d.fehler || !d.minuten?.length) { if (!tagesDaten || andereAnsicht) tagesDaten = { fehler: d.fehler ?? 'Für heute gibt es noch keine Minutenkurse.', modus: erwartet }; }
  else {
    // Andere Ansicht oder neue Achse: den Zoom lösen, sonst bleibt der alte Ausschnitt stehen.
    if (andereAnsicht || tagesDaten?.achse?.von !== d.achse?.von) chartZoom.loesen();
    tagesDaten = d;
  }
  zeichneLedTafel();
  if (chartZeitraum === 'tag') zeigeChart();
}

zeichneChartWahl();

// ---- Watchlist ----
const vielfachFormat = new Intl.NumberFormat('de-DE', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const watchGesehen = new Set(); // welche Ausreißer schon einmal in die Leiste gesprungen sind

function watchZeile(w) {
  const hatKurs = w.kurs_eur !== null;
  const unter = [
    w.ticker,
    hatKurs ? euro.format(w.kurs_eur) : 'kein Kurs',
    w.vielfaches === null ? '' : `${vielfachFormat.format(w.vielfaches)}× die übliche Bewegung`,
  ].filter(Boolean).join(' · ');
  const marke = w.aussergewoehnlich ? `<span class="w-marke ${klasse(w.tag)}">Außergewöhnlich</span>` : '';
  const stand = w.kurs_status === 'veraltet' ? `<span class="klein alt">${esc(mitZeit('veraltet', w))}</span>` : aktualitaetHtml(w);
  const wert = w.tag === null
    ? '<span class="klein alt">keine Daten</span>'
    : `<span class="${klasse(w.tag)}">${marke}${prozent.format(w.tag)} %${stand}</span>`;
  return `<div class="w-zeile">
    ${wertZeile('reihe', w.ticker, `<span><span class="reihe-name">${esc(w.name)}</span><span class="klein">${esc(unter)}</span></span>${wert}`, 'Chart öffnen (Strg+Klick: Yahoo Finance)')}
    <button class="w-alarm${alAlle.some((a) => a.ticker === w.ticker) ? ' aktiv' : ''}" type="button" data-al-neu="${esc(w.ticker)}" data-al-name="${esc(w.name)}" aria-label="Preisalarm für ${esc(w.name)}" title="Preisalarm">${AL_GLOCKE}</button>
    <button class="w-weg" type="button" data-ticker="${esc(w.ticker)}" aria-label="${esc(w.name)} von der Watchlist entfernen">×</button>
  </div>`;
}

// Außergewöhnliche Werte kommen in die Leiste oben. Ein neuer springt sofort ins Bild.
function kopfWatchlist(werte) {
  const auffaellig = werte.filter((w) => w.aussergewoehnlich).sort((a, b) => b.vielfaches - a.vielfaches);
  kopf.watchlist = auffaellig.slice(0, 3).map((w) => `<a class="kopf-item" href="${esc(yahooLink(w.ticker))}" target="_blank" rel="noopener" title="${esc(`${w.name}: ${vielfachFormat.format(w.vielfaches)}-mal so stark wie an einem üblichen Tag. Chart bei Yahoo Finance öffnen`)}"><em>Watchlist ${esc(kurzName(w.name))}</em><b class="${klasse(w.tag)}">${prozent.format(w.tag)} %</b> <em>${AKTUALITAET[w.kurs_aktualitaet] ?? ''}</em></a>`).join('');
  const neu = auffaellig.filter((w) => !watchGesehen.has(`${w.ticker}|${w.kurs_stand}`));
  neu.forEach((w) => watchGesehen.add(`${w.ticker}|${w.kurs_stand}`));
  if (neu.length && !kopfPause) kopfIndex = Object.keys(kopf).filter((k) => kopf[k]).indexOf('watchlist');
  zeichneKopf();
}

async function ladeWatchlist() {
  let d;
  try {
    d = await api('/api/watchlist');
  } catch {
    d = { fehler: 'Die Watchlist konnte nicht geladen werden. Läuft der Server noch?' };
  }
  if (d.fehler) {
    el('w-status').textContent = d.fehler;
    return;
  }
  const sortiert = [...d.werte].sort((a, b) => Number(b.aussergewoehnlich) - Number(a.aussergewoehnlich) || (b.tag ?? -Infinity) - (a.tag ?? -Infinity));
  const liste = el('w-liste');
  liste.hidden = false;
  liste.innerHTML = sortiert.length ? sortiert.map(watchZeile).join('') : '<p class="w-leer">Noch keine Werte. Suche oben nach einer Aktie, um sie zu beobachten.</p>';
  el('w-status').textContent = [`${d.werte.length} ${d.werte.length === 1 ? 'Wert' : 'Werte'}`, d.aktualisiert ? `Kurse aktualisiert ${zeitText(d.aktualisiert)} Uhr` : ''].filter(Boolean).join(' · ');
  kopfWatchlist(d.werte);
}

function watchMeldung(text) {
  el('w-meldung').hidden = !text;
  el('w-meldung').textContent = text;
}

async function watchSenden(methode, pfad, daten) {
  let d;
  try {
    const antwort = await fetch(pfad, {
      method: methode,
      headers: { 'X-Vinter': 'watchlist', 'Content-Type': 'application/json' },
      body: daten ? JSON.stringify(daten) : undefined,
    });
    d = await antwort.json();
  } catch {
    d = { fehler: 'Das hat nicht geklappt. Läuft der Server noch?' };
  }
  watchMeldung(d.fehler ?? '');
  if (!d.fehler) {
    delete antworten['/api/watchlist'];
    ladeWatchlist();
  }
  return d;
}

// Suche: fragt erst, wenn kurz nicht mehr getippt wird, und ignoriert veraltete Antworten.
let watchWarten;
let watchLetzte = '';
function schliesseTreffer() { el('w-treffer').hidden = true; }
el('w-eingabe').addEventListener('input', (e) => {
  clearTimeout(watchWarten);
  const q = e.target.value.trim();
  watchLetzte = q;
  if (q.length < 2) { schliesseTreffer(); return; }
  watchWarten = setTimeout(async () => {
    let d = { treffer: [] };
    try { d = await api(`/api/watchlist/suche?q=${encodeURIComponent(q)}`); } catch {}
    if (q !== watchLetzte) return;
    el('w-treffer').innerHTML = d.treffer.length
      ? d.treffer.map((t) => `<button type="button" data-ticker="${esc(t.ticker)}" data-name="${esc(t.name)}"><span>${esc(t.name)}</span><small>${esc(t.ticker)}${t.boerse ? ` · ${esc(t.boerse)}` : ''}</small></button>`).join('')
      : '<p>Nichts gefunden.</p>';
    el('w-treffer').hidden = false;
  }, 250);
});
el('w-treffer').addEventListener('click', async (e) => {
  const knopf = e.target.closest('button');
  if (!knopf) return;
  schliesseTreffer();
  el('w-eingabe').value = '';
  watchLetzte = '';
  await watchSenden('POST', '/api/watchlist', { ticker: knopf.dataset.ticker, name: knopf.dataset.name });
});
el('w-form').addEventListener('submit', (e) => {
  e.preventDefault(); // Enter übernimmt den ersten Treffer
  el('w-treffer').querySelector('button')?.click();
});
el('w-eingabe').addEventListener('keydown', (e) => { if (e.key === 'Escape') schliesseTreffer(); });
document.addEventListener('click', (e) => { if (!el('w-form').contains(e.target)) schliesseTreffer(); });
el('w-liste').addEventListener('click', (e) => {
  const knopf = e.target.closest('.w-weg');
  if (knopf) watchSenden('DELETE', `/api/watchlist/${encodeURIComponent(knopf.dataset.ticker)}`);
});

// ---- Live-Newsfeed ----
// Merkt sich, was schon zu sehen war. Alles andere bekommt beim nächsten Abruf eine grüne Uhrzeit.
let newsBekannt = null;
const newsNeu = new Set();
let feedDaten = null;
let feedFilter = 'Alle';
try { feedFilter = localStorage.getItem('newsFilter') || 'Alle'; } catch {}
const NEWS_TAKT = 90 * 1000;
const tagName = new Intl.DateTimeFormat('de-DE', { weekday: 'short', day: '2-digit', month: '2-digit' });

const passtFilter = (m) => feedFilter === 'Alle' || (feedFilter === 'Wichtig' ? m.wichtig : m.tags.includes(feedFilter));

function feedTag(iso) {
  const d = new Date(iso);
  const gestern = new Date();
  gestern.setDate(gestern.getDate() - 1);
  if (isoLokal(d) === isoLokal(new Date())) return 'Heute';
  if (isoLokal(d) === isoLokal(gestern)) return 'Gestern';
  return tagName.format(d);
}

function feedZeile(m) {
  const klassen = ['n-zeile', m.wichtig && 'wichtig', m.positionen && 'eigen', m.thesen && 'these', newsNeu.has(m.titel) && 'neu'].filter(Boolean).join(' ');
  const bezug = [...(m.positionen ?? []), ...(m.thesen ?? []).map((t) => `These: ${t}`)];
  const tags = m.tags.filter((t) => t !== 'Meine Positionen');
  const unter = [m.quellen.join(', '), ...tags].map(esc).join(' · ');
  const inhalt = `<span class="n-zeit">${uhrzeit.format(new Date(m.zeit))}</span>
    <span><span class="n-titel">${m.wichtig ? '<span class="n-wichtig">Wichtig</span>' : ''}${esc(m.titel)}</span>
    <span class="n-unter">${bezug.length ? `<b>${esc(bezug.join(', '))}</b> · ` : ''}${unter}</span></span>`;
  return sichererLink(m.link)
    ? `<a class="${klassen}" href="${esc(m.link)}" target="_blank" rel="noopener">${inhalt}</a>`
    : `<div class="${klassen}">${inhalt}</div>`;
}

function zeichneFeed() {
  if (!feedDaten) return;
  const alle = feedDaten.meldungen;
  const anzahl = (tag) => alle.filter((m) => (tag === 'Wichtig' ? m.wichtig : m.tags.includes(tag))).length;
  if (feedFilter !== 'Alle' && !feedDaten.tags.includes(feedFilter)) feedFilter = 'Alle';
  // Die Knöpfe nur einmal bauen: Neu geschriebenes HTML würde die gleitende Pille darunter entfernen.
  const box = el('n-tags');
  const namen = ['Alle', ...feedDaten.tags];
  if (box.dataset.tags !== namen.join('|')) {
    box.querySelectorAll('button').forEach((b) => b.remove());
    box.insertAdjacentHTML('beforeend', namen.map((t) => `<button type="button" data-tag="${esc(t)}" aria-pressed="false">${esc(t)}<span></span></button>`).join(''));
    box.dataset.tags = namen.join('|');
  }
  box.querySelectorAll('button').forEach((b) => {
    b.querySelector('span').textContent = b.dataset.tag === 'Alle' ? alle.length : anzahl(b.dataset.tag);
    b.setAttribute('aria-pressed', String(b.dataset.tag === feedFilter)); // verschiebt die Pille
  });
  setzePille(box);

  const liste = alle.filter(passtFilter);
  let tag = null;
  const zeilen = liste.map((m) => {
    const t = feedTag(m.zeit);
    const kopfzeile = t !== tag ? `<h2 class="n-tag">${esc(t)}</h2>` : '';
    tag = t;
    return kopfzeile + feedZeile(m);
  });
  el('n-liste').hidden = false;
  el('n-liste').innerHTML = zeilen.join('') || '<p class="n-leer">Zu diesem Filter gibt es gerade keine Meldungen.</p>';
}
el('n-tags').addEventListener('click', (e) => {
  const knopf = e.target.closest('button');
  if (!knopf) return;
  feedFilter = knopf.dataset.tag;
  try { localStorage.setItem('newsFilter', feedFilter); } catch {}
  zeichneFeed();
});

async function ladeNews() {
  delete antworten['/api/newsfeed'];
  let d;
  try {
    d = await api('/api/newsfeed');
  } catch {
    d = { fehler: 'Die News konnten nicht geladen werden. Läuft der Server noch?' };
  }
  if (d.fehler) {
    if (!newsBekannt) el('n-status').textContent = d.fehler; // sonst bleibt der letzte Stand stehen
    return;
  }
  if (newsBekannt) d.meldungen.filter((m) => !newsBekannt.has(m.titel)).forEach((m) => newsNeu.add(m.titel));
  newsBekannt = new Set([...(newsBekannt ?? []), ...d.meldungen.map((m) => m.titel)]);

  const anzahlNeu = d.meldungen.filter((m) => newsNeu.has(m.titel)).length;
  el('n-status').textContent = [`${d.meldungen.length} Meldungen`, `aktualisiert ${zeitText(d.aktualisiert)} Uhr`, anzahlNeu ? `${anzahlNeu} neu` : ''].filter(Boolean).join(' · ');
  const ausfaelle = d.quellen.filter((q) => q.fehler);
  el('n-quellen').hidden = !ausfaelle.length;
  // Quellen mit demselben Grund in einen Hinweis, z. B. alle, denen dieselbe Angabe in .env fehlt.
  const gruende = new Map();
  ausfaelle.forEach((q) => gruende.set(q.fehler, [...(gruende.get(q.fehler) ?? []), q]));
  el('n-quellen').innerHTML = [...gruende].map(([grund, qs]) => `<span>${esc(qs.map((q) => q.name).join(', '))}: ${esc(grund)}</span>`).join('');
  feedDaten = d;
  zeichneFeed();
  kachelWert('news', String(d.meldungen.filter((m) => m.wichtig || m.positionen).length));
}
// Der Server fragt jede Quelle nur so oft ab, wie in news_quellen.yaml steht.
setInterval(() => { if (!document.hidden) ladeNews(); }, NEWS_TAKT);

// ---- Reden & Zitate: Auftritte von Trump, Notenbankern, Ministern und Chefs ----
let redenDaten = null;
let redenKategorie = 'Alle';
let newsAnsicht = 'ticker';
try {
  if (localStorage.getItem('newsAnsicht') === 'reden') newsAnsicht = 'reden';
  redenKategorie = localStorage.getItem('redenKategorie') || 'Alle';
} catch {}
const TENDENZ_TEXT = { straff: 'eher straff: spricht gegen Zinssenkungen', locker: 'eher locker: spricht für Zinssenkungen' };

function zeigeNewsAnsicht() {
  el('n-ansicht').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.ansicht === newsAnsicht)));
  el('n-teil-ticker').hidden = newsAnsicht !== 'ticker';
  el('n-teil-reden').hidden = newsAnsicht !== 'reden';
  if (newsAnsicht === 'reden') ladeReden();
}

// Wo man eine Rede selbst verfolgen kann: Livestream-Suche bei YouTube (nur laufende Übertragungen),
// die offizielle Seite je Gruppe und die jüngste Meldung im Squawk-Feed (dort kommen neue Aussagen zuerst).
// Es werden nur Links gebaut, nichts wird abgerufen.
const REDE_SEITEN = {
  Fed: [['Fed-Reden', 'https://www.federalreserve.gov/newsevents/speeches.htm'], ['Fed-Kalender', 'https://www.federalreserve.gov/newsevents/calendar.htm']],
  EZB: [['EZB-Reden', 'https://www.ecb.europa.eu/press/key/html/index.en.html'], ['EZB-Pressekonferenzen', 'https://www.ecb.europa.eu/press/press_conference/html/index.en.html']],
  'Trump & US-Regierung': [['Transkripte (Factbase)', 'https://rollcall.com/factbase/trump/search/'], ['Weißes Haus live', 'https://www.whitehouse.gov/live/']],
};
function redeQuellen(a) {
  const name = a.wer.replace(/'s\b/g, '').trim();
  const links = [[a.live ? 'Livestream suchen' : 'Video suchen',
    `https://www.youtube.com/results?search_query=${encodeURIComponent(name)}${a.live ? '&sp=EgJAAQ%3D%3D' : ''}`]];
  links.push(...(REDE_SEITEN[a.kategorie] ?? []));
  const neueste = a.zitate.at(-1)?.link;
  if (neueste && sichererLink(neueste)) links.push(['Neueste Meldung', neueste]);
  return links.map(([t, u]) => `<a href="${esc(u)}" target="_blank" rel="noopener">${esc(t)} ↗</a>`).join(' · ');
}

function zeichneReden() {
  const d = redenDaten;
  if (!d) return;
  const kategorien = ['Alle', ...d.kategorien.filter((k) => d.auftritte.some((a) => a.kategorie === k))];
  if (!kategorien.includes(redenKategorie)) redenKategorie = 'Alle';
  const box = el('r-kategorien');
  if (box.dataset.k !== kategorien.join('|')) {
    box.querySelectorAll('button').forEach((b) => b.remove());
    box.insertAdjacentHTML('beforeend', kategorien.map((k) => `<button type="button" data-kategorie="${esc(k)}" aria-pressed="false">${esc(k)}</button>`).join(''));
    box.dataset.k = kategorien.join('|');
  }
  box.querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.kategorie === redenKategorie)));
  setzePille(box);

  const liste = d.auftritte.filter((a) => redenKategorie === 'Alle' || a.kategorie === redenKategorie);
  el('r-auftritte').innerHTML = liste.map((a) => {
    const zeit = (iso) => uhrzeit.format(new Date(iso));
    const tag = feedTag(a.start);
    const kern = a.kern.map((i) => `<li>${esc(a.zitate[i].text)}</li>`).join('');
    const weitere = a.zitate.length > a.kern.length
      ? `<details class="r-alle"><summary>Alle ${a.zitate.length} Aussagen</summary><ol>${a.zitate.map((z) => `<li><span class="n-zeit">${zeit(z.zeit)}</span> ${z.thema ? `<em>${esc(z.thema)}:</em> ` : ''}${esc(z.text)}</li>`).join('')}</ol></details>` : '';
    return `<article class="karte r-auftritt ${a.live ? 'live' : ''}">
      <p class="r-kopf">${a.live ? '<span class="r-live">LIVE</span>' : ''}<b>${esc(a.wer)}</b><span>${esc(a.kategorie)} · ${esc(tag)} ${zeit(a.start)}${a.ende !== a.start ? `–${zeit(a.ende)}` : ''} Uhr · ${a.zitate.length} ${a.zitate.length === 1 ? 'Aussage' : 'Aussagen'}</span></p>
      ${a.themen.length ? `<p class="klein">Themen: ${esc(a.themen.join(', '))}</p>` : ''}
      <ul class="r-kern">${kern}</ul>
      ${a.tendenz ? `<p class="r-tendenz ${a.tendenz.richtung}">Tendenz ${TENDENZ_TEXT[a.tendenz.richtung]} (${a.tendenz.straff} straffe, ${a.tendenz.locker} lockere Signalwörter)</p>` : ''}
      ${a.wortlaut && sichererLink(a.wortlaut) ? `<p class="klein"><a href="${esc(a.wortlaut)}" target="_blank" rel="noopener">Offizieller Wortlaut ↗</a></p>` : ''}
      <p class="klein r-quellen">${a.live ? 'Live verfolgen' : 'Selbst nachsehen'}: ${redeQuellen(a)}</p>
      ${weitere}
    </article>`;
  }).join('') || '<p class="sekundaer">In den letzten Tagen keine Aussagen in dieser Gruppe.</p>';
  const live = d.auftritte.filter((a) => a.live).map((a) => a.wer);
  el('r-status').textContent = [`${d.auftritte.length} Auftritte in den letzten Tagen`, live.length ? `gerade live: ${live.join(', ')}` : '', `aktualisiert ${zeitText(d.aktualisiert)} Uhr`].filter(Boolean).join(' · ');
}

async function ladeReden() {
  delete antworten['/api/zitate'];
  let d;
  try {
    d = await api('/api/zitate');
  } catch {
    d = { fehler: 'Die Reden konnten nicht geladen werden. Läuft der Server noch?' };
  }
  if (d.fehler) { if (!redenDaten) el('r-status').textContent = d.fehler; return; }
  redenDaten = d;
  zeichneReden();
}
el('n-ansicht').addEventListener('click', (e) => {
  const knopf = e.target.closest('button[data-ansicht]');
  if (!knopf || knopf.dataset.ansicht === newsAnsicht) return;
  newsAnsicht = knopf.dataset.ansicht;
  try { localStorage.setItem('newsAnsicht', newsAnsicht); } catch {}
  zeigeNewsAnsicht();
});
el('r-kategorien').addEventListener('click', (e) => {
  const knopf = e.target.closest('button[data-kategorie]');
  if (!knopf) return;
  redenKategorie = knopf.dataset.kategorie;
  try { localStorage.setItem('redenKategorie', redenKategorie); } catch {}
  zeichneReden();
});
zeigeNewsAnsicht();
setInterval(() => { if (!document.hidden && newsAnsicht === 'reden' && !el('seite-news').hidden) ladeReden(); }, NEWS_TAKT);

// ---- Wortmarke: Jeder Buchstabe wächst beim Öffnen aus einem seiner Enden heraus ----
// Über jedem echten Buchstaben liegt eine Maske aus dicken Linien entlang seiner Form. Laufen die
// Linien los, wird der Buchstabe dort sichtbar, wo sie schon sind. Danach fällt die Maske weg.
// Pfade: x von 0 bis 1 über die Breite des Buchstabens, y in Schrifthöhen über der Grundlinie.
const WM_PFADE = {
  // Die Pfade enden ein Stück außerhalb der Form. So läuft die langsamste Phase dort aus, wo man sie nicht sieht.
  V: [{ d: 'M .04 .9 L .5 -.12 L 1.03 1.02', breite: 44 }],
  i: [{ d: 'M .5 -.14 L .5 .68', breite: 40 }, { d: 'M .5 .64 L .5 1', breite: 40, ab: .62, dauer: .42 }],
  n: [{ d: 'M .2 -.16 L .2 .84', breite: 40 }, { d: 'M .2 .4 C .32 .56 .78 .62 .79 .32 L .79 -.32', breite: 42, ab: .3, dauer: .82 }],
  t: [{ d: 'M .42 .9 L .42 .14 C .42 .02 .6 .0 1.3 .03', breite: 42 }, { d: 'M -.28 .46 L 1.28 .46', breite: 26, ab: .46, dauer: .56 }],
  e: [{ d: 'M -.12 .28 L .9 .28 C .95 .48 .72 .5 .5 .5 C .24 .5 .13 .4 .13 .26 C .13 .1 .28 .03 .5 .03 C .68 .03 .86 .08 1.12 .36', breite: 37 }],
  r: [{ d: 'M .28 -.16 L .28 .84', breite: 42 }, { d: 'M .28 .36 C .42 .54 .66 .56 1.34 .48', breite: 38, ab: .46, dauer: .6 }],
};
const WM_DAUER = 1.05; // Sekunden pro Buchstabe
const WM_VERSATZ = 0.12; // Abstand zwischen zwei Buchstaben
const SVG_NS = 'http://www.w3.org/2000/svg';
let wmEnde = null;

function svgElement(name, attribute = {}) {
  const e = document.createElementNS(SVG_NS, name);
  for (const [k, w] of Object.entries(attribute)) e.setAttribute(k, w);
  return e;
}

// Ersetzt den Text durch ein SVG. Alle Abstände werden vorher am echten Text gemessen,
// damit die fertige Wortmarke genauso aussieht wie vorher.
function baueWortmarke() {
  const marke = document.querySelector('.wortmarke');
  if (document.documentElement.dataset.stil === 'vinter') {
    // Jeder Buchstabe bekommt eine leicht andere Strichstärke (die Schrift ist stufenlos einstellbar).
    // Feste Werte statt Zufall: Die Wortmarke sieht bei jedem Öffnen gleich aus.
    if (!marke.dataset.buchstaben) {
      // Breite (scaleX), Stärke und Höhe je Buchstabe: an Unbounded angelehnt, aber bewusst ungleich.
      const form = [
        { w: 700, x: 1.16, y: 0 },      // V breit und kräftig
        { w: 540, x: 0.93, y: -0.02 },  // i etwas schmaler
        { w: 640, x: 1.06, y: 0 },      // n
        { w: 560, x: 0.86, y: 0.015 },  // t schmal, leicht tiefer
        { w: 680, x: 1.12, y: 0 },      // e breit
        { w: 590, x: 0.9, y: -0.01 },   // r
      ];
      marke.innerHTML = [...marke.textContent.trim()].map((b, i) => {
        const f = form[i % form.length];
        // Die Breite wird über margin ausgeglichen, damit die Abstände zwischen den Buchstaben stimmen.
        return `<span style="font-weight:${f.w};transform:translateY(${f.y}em) scaleX(${f.x});margin:0 ${((f.x - 1) * 0.3).toFixed(3)}em">${esc(b)}</span>`;
      }).join('');
      marke.setAttribute('aria-label', marke.textContent);
      marke.dataset.buchstaben = '1';
    }
    return marke;
  }
  if (marke.dataset.gebaut || !marke.getBoundingClientRect().width) return marke;
  const knoten = marke.firstChild;
  const text = knoten.textContent;
  const kasten = marke.getBoundingClientRect();
  // Das SVG nutzt die echte Pixelgröße: Manche Schriften ändern ihre Form mit der Schriftgröße.
  const groesse = parseFloat(getComputedStyle(marke).fontSize);
  const s = groesse / 100;
  const bereich = document.createRange();
  const links = [...text].map((_, i) => {
    bereich.setStart(knoten, i);
    bereich.setEnd(knoten, i + 1);
    return bereich.getBoundingClientRect().left - kasten.left;
  });
  const probe = document.createElement('span');
  probe.style.cssText = 'display:inline-block;width:0;height:0;vertical-align:baseline';
  marke.append(probe);
  const grundlinie = probe.getBoundingClientRect().bottom - kasten.top;
  probe.remove();
  const breite = kasten.width;
  const hoehe = kasten.height;

  // Derselbe Verlauf wie zuvor (160 Grad über das ganze Wort), für SVG umgerechnet.
  const winkel = 160 * Math.PI / 180;
  const laenge = Math.abs(breite * Math.sin(winkel)) + Math.abs(hoehe * Math.cos(winkel));
  const dx = Math.sin(winkel) * laenge / 2;
  const dy = -Math.cos(winkel) * laenge / 2;
  const svg = svgElement('svg', { viewBox: `0 0 ${breite} ${hoehe}`, 'aria-hidden': 'true' });
  svg.style.width = `${breite / groesse}em`;
  svg.style.height = `${hoehe / groesse}em`;
  const defs = svgElement('defs');
  const verlauf = svgElement('linearGradient', { id: 'wm-verlauf', gradientUnits: 'userSpaceOnUse', x1: breite / 2 - dx, y1: hoehe / 2 - dy, x2: breite / 2 + dx, y2: hoehe / 2 + dy });
  [[0.06, 'wm-v1'], [0.5, 'wm-v2'], [0.98, 'wm-v3']].forEach(([offset, klasse_]) => verlauf.append(svgElement('stop', { offset, class: klasse_ })));
  defs.append(verlauf);
  // Macht die Vorderkante der wachsenden Linien leicht weich statt scharf abgeschnitten.
  const weich = svgElement('filter', { id: 'wm-weich', filterUnits: 'userSpaceOnUse', x: -30 * s, y: -40 * s, width: breite + 60 * s, height: hoehe + 80 * s });
  weich.append(svgElement('feGaussianBlur', { stdDeviation: 1.5 * s }));
  defs.append(weich);

  [...text].forEach((zeichen, i) => {
    const x0 = links[i];
    const vorschub = (links[i + 1] ?? breite) - x0;
    const rand = { x: -30 * s, y: -40 * s, width: breite + 60 * s, height: hoehe + 80 * s };
    const maske = svgElement('mask', { id: `wm-m${i}`, maskUnits: 'userSpaceOnUse', ...rand });
    const umrechnen = (d) => d.replace(/(-?[\d.]+) (-?[\d.]+)/g, (_, x, y) => `${(x0 + Number(x) * vorschub).toFixed(2)} ${(grundlinie - Number(y) * groesse).toFixed(2)}`);
    const beginn = i * WM_VERSATZ;
    let ende = beginn;
    const linien = svgElement('g', { filter: 'url(#wm-weich)' });
    maske.append(linien);
    for (const { d, breite: dicke, ab = 0, dauer = 1 } of WM_PFADE[zeichen]) {
      const strich = svgElement('path', { d: umrechnen(d), pathLength: 1, class: 'wm-strich', 'stroke-width': dicke * s });
      strich.style.setProperty('--start', `${beginn + ab * WM_DAUER}s`);
      strich.style.setProperty('--dauer', `${dauer * WM_DAUER}s`);
      linien.append(strich);
      ende = Math.max(ende, beginn + (ab + dauer) * WM_DAUER);
    }
    // Die Linien treffen nicht jede Ecke jeder Schrift. Der Rest blendet am Schluss weich ein.
    const voll = svgElement('rect', { ...rand, fill: '#fff', class: 'wm-voll' });
    voll.style.setProperty('--start', `${ende - 0.28}s`);
    voll.style.setProperty('--dauer', '0.28s');
    maske.append(voll);
    defs.append(maske);
  });
  svg.append(defs);
  [...text].forEach((zeichen, i) => {
    const t = svgElement('text', { x: links[i], y: grundlinie, fill: 'url(#wm-verlauf)', 'font-size': groesse });
    t.style.letterSpacing = '0';
    t.textContent = zeichen;
    svg.append(t);
  });
  // Zwei Kopien des fertigen Worts mit Leuchten, die unter den gezeichneten Buchstaben liegen.
  const ebene = (klasse_) => {
    const kopie = svgElement('svg', { viewBox: `0 0 ${breite} ${hoehe}`, 'aria-hidden': 'true', class: klasse_ });
    kopie.style.width = svg.style.width;
    kopie.style.height = svg.style.height;
    svg.querySelectorAll('text').forEach((t) => kopie.append(t.cloneNode(true)));
    return kopie;
  };
  marke.setAttribute('aria-label', text);
  marke.textContent = '';
  marke.append(ebene('wm-schein'), ebene('wm-blitz'), svg);
  marke.classList.add('geteilt');
  marke.dataset.gebaut = '1';
  return marke;
}

function spieleWortmarke() {
  if (schriftWarten) { schriftWarten.then(spieleWortmarke); schriftWarten = null; return; }
  const marke = baueWortmarke();
  if (!marke.dataset.gebaut || matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const buchstaben = [...marke.querySelectorAll('svg:not(.wm-schein):not(.wm-blitz) text')];
  clearTimeout(wmEnde);
  marke.classList.remove('spielt');
  void marke.getBoundingClientRect(); // startet die Animation neu, auch wenn sie gerade läuft
  buchstaben.forEach((t, i) => t.setAttribute('mask', `url(#wm-m${i})`));
  const gesamt = Math.max(...[...marke.querySelectorAll('.wm-strich, .wm-voll')].map((s) => parseFloat(s.style.getPropertyValue('--start')) + parseFloat(s.style.getPropertyValue('--dauer'))));
  // Das Leuchten setzt ein, wenn der letzte Buchstabe gerade fertig wird.
  const leuchten = gesamt - 0.1;
  marke.style.setProperty('--wm-zeichnen', `${leuchten}s`);
  marke.classList.add('spielt');
  wmEnde = setTimeout(() => {
    buchstaben.forEach((t) => t.removeAttribute('mask'));
    marke.classList.remove('spielt');
  }, (leuchten + 1.3) * 1000 + 60);
}

// ---- Themen-Ranking: pro Thema ein Balkendiagramm um eine Nulllinie ----
let themenDaten = null;
let themenEigene = new Set(); // Ticker der eigenen Positionen
let themenZeit = 'tag';
let themenIndex = 0;
const ZEIT_NAMEN = { tag: 'heute', woche: 'seit einer Woche', monat: 'seit einem Monat', ytd: 'seit Jahresbeginn' };
try {
  const gemerkt = JSON.parse(localStorage.getItem('themenWahl') ?? 'null');
  if (gemerkt?.zeit in ZEIT_NAMEN) themenZeit = gemerkt.zeit;
  if (Number.isInteger(gemerkt?.index)) themenIndex = gemerkt.index;
} catch {}
const merkeThemen = () => { try { localStorage.setItem('themenWahl', JSON.stringify({ zeit: themenZeit, index: themenIndex })); } catch {} };
const prozentText = (w) => (w === null || w === undefined ? '–' : `${prozent.format(w)} %`);

// Zeichnet ein Diagramm. zeilen: { label, wert, titel, eigen, alarm, thema | sprung | link, logo, spanne: [von, bis], text };
// spanne zeichnet eine feine Linie für den Unsicherheitsbereich, text ersetzt die Prozentzahl am Balken.
// linien: { name, wert, art }. thema: öffnet ein Thema, sprung: scrollt zu einem Element, sonst Yahoo-Chart.
function balkenDiagramm(zeilen, linien) {
  const mitDaten = zeilen.filter((z) => z.wert !== null && z.wert !== undefined).sort((a, b) => b.wert - a.wert);
  const ohne = zeilen.filter((z) => z.wert === null || z.wert === undefined);
  const gueltigeLinien = linien.filter((l) => l.wert !== null && l.wert !== undefined);
  const groesste = Math.max(0.5, ...mitDaten.map((z) => Math.abs(z.wert)), ...gueltigeLinien.map((l) => Math.abs(l.wert)));
  // Die Nulllinie liegt in der Mitte, der größte Ausschlag nutzt gut zwei Drittel einer Hälfte:
  // daneben bleibt Platz für die Zahl am Balkenende.
  const lage = (w) => 50 + (w / groesste) * 34;

  // Beschriftungen der Vergleichslinien rutschen eine Zeile tiefer, wenn sie sich sonst überlappen.
  let vorige = null;
  const reihen = [...gueltigeLinien].sort((a, b) => a.wert - b.wert).map((l) => {
    const x = lage(l.wert);
    const reihe = vorige && x - vorige.x < 13 ? vorige.reihe + 1 : 0;
    vorige = { x, reihe };
    return { ...l, x, reihe };
  });
  const kopfhoehe = (Math.max(-1, ...reihen.map((r) => r.reihe)) + 1) * 1.05;
  const linienHtml = reihen.map((l) => `<span class="th-linie ${l.art ?? ''}" style="left:${l.x}%"><em style="top:${l.reihe * 1.05}rem">${esc(l.name)} ${prozentText(l.wert)}</em></span>`).join('');

  const zeile = (z) => {
    const x = lage(z.wert);
    const zahl = z.text ?? prozentText(z.wert);
    // Die Spanne darf breiter sein als das Diagramm: Sie wird am Rand abgeschnitten, die Balken bleiben lesbar.
    const imFeld = (v) => Math.max(0, Math.min(100, v));
    const spanne = z.spanne
      ? `<i class="th-spanne" style="left:${imFeld(lage(z.spanne[0]))}%;width:${imFeld(lage(z.spanne[1])) - imFeld(lage(z.spanne[0]))}%"></i>`
      : '';
    // Mit Spanne steht die Zahl hinter deren Ende, sonst würden Zahl und Linie sich überlagern.
    // Höchstens bis 88 % (bzw. ab 12 %), damit die Zahl nicht aus der Karte ragt.
    const rand = z.spanne
      ? (z.wert >= 0 ? Math.min(88, Math.max(x, lage(z.spanne[1]))) : Math.max(12, Math.min(x, lage(z.spanne[0]))))
      : x;
    const balken = (z.wert >= 0
      ? `<i class="th-balken plus" style="left:50%;width:${x - 50}%"></i><b class="th-wert plus" style="left:calc(${rand}% + 6px)">${zahl}</b>`
      : `<i class="th-balken minus" style="left:${x}%;width:${50 - x}%"></i><b class="th-wert minus" style="right:calc(${100 - rand}% + 6px)">${zahl}</b>`) + spanne;
    const logo = z.logo ? `<img src="/api/logo/${encodeURIComponent(z.label)}" alt="" width="16" height="16" loading="lazy">` : '';
    const name = `<span class="th-name">${logo}${esc(z.label)}${z.eigen ? '<span class="th-eigen" title="Deine Position">●</span>' : ''}</span>`;
    const inhalt = `${name}<span class="th-spur">${balken}</span>`;
    const klassen = `th-zeile${z.eigen ? ' eigen' : ''}${z.alarm ? ` alarm-${z.alarm}` : ''}`;
    if (z.statisch) return `<div class="${klassen}" title="${esc(z.titel)}">${inhalt}</div>`;
    if (z.thema !== undefined) return `<button type="button" class="${klassen}" data-thema="${z.thema}" title="${esc(z.titel)}">${inhalt}</button>`;
    if (z.sprung) return `<button type="button" class="${klassen}" data-sprung="${esc(z.sprung)}" title="${esc(z.titel)}">${inhalt}</button>`;
    return `<a class="${klassen}" href="${esc(yahooLink(z.link ?? z.label))}" target="_blank" rel="noopener" title="${esc(z.titel)}">${inhalt}</a>`;
  };
  const fehlend = ohne.length ? `<p class="klein th-fehlt">Ohne Kurs: ${ohne.map((z) => esc(z.label)).join(', ')}</p>` : '';
  return `<div class="th-diagramm" style="--kopf:${kopfhoehe}rem">
      <div class="th-linien" aria-hidden="true"><span class="th-null"></span>${linienHtml}</div>
      ${mitDaten.map(zeile).join('')}
    </div>${fehlend}`;
}

// Zahlen am Balkenende dürfen nicht aus der Karte ragen: Nach dem Zeichnen wird gemessen. Steht eine
// Zahl über den Rand, rückt sie in den Balken hinein (ans andere Ende der Zahl). Gilt für alle Balkendiagramme.
function balkenEinpassen(diagramm) {
  const rahmen = diagramm.getBoundingClientRect();
  if (!rahmen.width) return;
  diagramm.querySelectorAll('.th-spur').forEach((spur) => {
    const wert = spur.querySelector('.th-wert'), balken = spur.querySelector('.th-balken');
    if (!wert || !balken) return;
    if (wert.dataset.innen) { wert.style.left = wert.dataset.left; wert.style.right = wert.dataset.right; delete wert.dataset.innen; wert.classList.remove('innen'); }
    const r = wert.getBoundingClientRect();
    const links = parseFloat(balken.style.left), breite = parseFloat(balken.style.width);
    if (wert.classList.contains('plus') && r.right > rahmen.right + 1) {
      Object.assign(wert.dataset, { innen: '1', left: wert.style.left, right: wert.style.right });
      wert.style.left = 'auto';
      wert.style.right = `calc(${100 - links - breite}% + 4px)`;
      wert.classList.add('innen');
    } else if (wert.classList.contains('minus') && r.left < rahmen.left - 1) {
      Object.assign(wert.dataset, { innen: '1', left: wert.style.left, right: wert.style.right });
      wert.style.right = 'auto';
      wert.style.left = `calc(${links}% + 4px)`;
      wert.classList.add('innen');
    }
  });
}
let einpassenTakt = 0;
const allesEinpassen = () => { cancelAnimationFrame(einpassenTakt); einpassenTakt = requestAnimationFrame(() => document.querySelectorAll('.th-diagramm').forEach(balkenEinpassen)); };
new MutationObserver((m) => { if (m.some((x) => [...x.addedNodes].some((n) => n.nodeType === 1 && (n.matches?.('.th-diagramm') || n.querySelector?.('.th-diagramm'))))) allesEinpassen(); })
  .observe(document.body, { childList: true, subtree: true });
addEventListener('resize', allesEinpassen);
addEventListener('hashchange', () => setTimeout(allesEinpassen, 50)); // verdeckte Seiten haben erst sichtbar eine Breite

function vergleichsLinien() {
  return (themenDaten?.vergleich ?? []).map((v) => ({ name: v.name, wert: v[themenZeit] }));
}

function zeichneThemen() {
  if (!themenDaten) return;
  const themen = themenDaten.themen;
  themenIndex = Math.min(Math.max(0, themenIndex), themen.length - 1);
  const eigene = themenEigene;
  const logos = new Set(themenDaten.logos);

  // "Alle Themen": jedes Thema ein Balken mit seiner Durchschnittsperformance. Antippen öffnet es.
  el('th-alle').innerHTML = balkenDiagramm(
    themen.map((th, i) => ({
      label: th.name, wert: th.schnitt[themenZeit], thema: i,
      eigen: th.werte.some((w) => eigene.has(w.ticker)),
      titel: `${th.name}: Durchschnitt ${prozentText(th.schnitt[themenZeit])}. Antippen zeigt die einzelnen Werte.`,
    })),
    vergleichsLinien(),
  );
  el('th-alle-unter').textContent = `Gleichgewichteter Durchschnitt je Thema, ${ZEIT_NAMEN[themenZeit]}`;

  const th = themen[themenIndex];
  const schnitt = th.schnitt[themenZeit];
  el('th-titel').innerHTML = `${esc(th.name)} <span class="${klasse(schnitt)}">Ø ${prozentText(schnitt)}</span>`;
  const eigeneHier = th.werte.filter((w) => eigene.has(w.ticker)).length;
  el('th-unter').textContent = [`${th.werte.length} Werte`, ZEIT_NAMEN[themenZeit], eigeneHier ? `${eigeneHier} davon in deinem Depot` : ''].filter(Boolean).join(' · ');
  el('th-thema').innerHTML = balkenDiagramm(
    th.werte.map((w) => ({
      label: w.ticker, wert: w[themenZeit], eigen: eigene.has(w.ticker), logo: logos.has(w.ticker),
      titel: `${w.name}: ${prozentText(w[themenZeit])}. Chart bei Yahoo Finance öffnen`,
    })),
    [...vergleichsLinien(), { name: 'Ø Thema', wert: schnitt, art: 'schnitt' }],
  );
  el('th-auswahl').innerHTML = themen.map((t, i) => `<option value="${i}"${i === themenIndex ? ' selected' : ''}>${esc(t.name)}</option>`).join('');
}

async function ladeThemen() {
  let d;
  try {
    d = await api('/api/themen');
  } catch {
    d = { fehler: 'Die Themen konnten nicht geladen werden. Läuft der Server noch?' };
  }
  if (d.fehler) {
    if (!themenDaten) el('th-status').textContent = d.fehler; // sonst bleibt der letzte Stand stehen
    return;
  }
  themenDaten = d;
  // Die eigenen Positionen kommen vom Depot, damit sie im Diagramm markiert werden können.
  try { themenEigene = new Set(((await api('/api/portfolio')).positionen ?? []).map((p) => p.ticker).filter(Boolean)); } catch {}
  el('th-status').textContent = [
    `${d.themen.length} Themen`,
    d.stand ? `Stand ${lokal(d.stand).toLocaleDateString('de-DE')}` : '',
    d.aktualisiert ? `aktualisiert ${zeitText(d.aktualisiert)} Uhr` : '',
    d.veraltet ? 'Yahoo antwortet gerade nicht, letzter bekannter Stand' : '',
  ].filter(Boolean).join(' · ');
  zeichneThemen();
  fuelleKacheln();
}

function zeigeThema(index) {
  if (!themenDaten) return;
  const anzahl = themenDaten.themen.length;
  themenIndex = (index + anzahl) % anzahl;
  merkeThemen();
  zeichneThemen();
}
el('th-zeit').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.zeit === themenZeit)));
el('th-zeit').addEventListener('click', (e) => {
  const knopf = e.target.closest('button[data-zeit]');
  if (!knopf) return;
  themenZeit = knopf.dataset.zeit;
  el('th-zeit').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b === knopf)));
  merkeThemen();
  zeichneThemen();
});
el('th-auswahl').addEventListener('change', (e) => zeigeThema(Number(e.target.value)));
el('th-zurueck').addEventListener('click', () => zeigeThema(themenIndex - 1));
el('th-weiter').addEventListener('click', () => zeigeThema(themenIndex + 1));
el('th-alle').addEventListener('click', (e) => {
  const knopf = e.target.closest('button[data-thema]');
  if (!knopf) return;
  zeigeThema(Number(knopf.dataset.thema));
  el('th-karte').scrollIntoView({ behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'start' });
});
// Auf dem Handy: seitlich wischen wechselt das Thema. Senkrechtes Scrollen bleibt unberührt.
let wischStart = null;
el('th-karte').addEventListener('touchstart', (e) => { const t = e.touches[0]; wischStart = { x: t.clientX, y: t.clientY }; }, { passive: true });
el('th-karte').addEventListener('touchend', (e) => {
  if (!wischStart) return;
  const t = e.changedTouches[0];
  const dx = t.clientX - wischStart.x, dy = t.clientY - wischStart.y;
  wischStart = null;
  if (Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy) * 1.5) zeigeThema(themenIndex + (dx < 0 ? 1 : -1));
}, { passive: true });

// ---- Exit-Alarme: Abstand zu den Exit-Leveln der Thesen, als Grafiken ----
let exitDaten = null;
let exitSchwelle = 5;
try {
  const gemerkt = Number(localStorage.getItem('exitSchwelle'));
  if (gemerkt >= 1 && gemerkt <= 30) exitSchwelle = gemerkt;
} catch {}
el('x-schwelle').value = String(exitSchwelle);
const exitGesehen = new Set();
const kurzLevel = { teilverkauf: 'Teilverkauf', komplett: 'Komplett', nachkauf: 'Nachkauf', stop: 'Stop' };
const euroKurs = (w) => (w === null || w === undefined ? '–' : euro.format(w));

// Zustand eines Levels: erreicht, nah (innerhalb der Schwelle) oder noch weit weg.
const levelZustand = (l) => (l.erreicht ? 'erreicht' : Math.abs(l.abstand) <= exitSchwelle ? 'nah' : '');

// Für den Tooltip im Exit-Chart: je Ticker die Kurse und die Höhenumrechnung.
const exitVerlauf = new Map();
// Überfahren zeigt Datum, Kurs und den Abstand zu Einstand und Levels an dieser Stelle.
function exitTip(e) {
  const flaeche = e.target.closest?.('.x-flaeche');
  const daten = flaeche && exitVerlauf.get(flaeche.dataset.ticker);
  if (!daten) return;
  const { w, y } = daten;
  const punkte = w.verlauf;
  const kasten = flaeche.getBoundingClientRect();
  const anteil = Math.min(1, Math.max(0, (e.clientX - kasten.left) / kasten.width));
  const i = Math.round(anteil * (punkte.length - 1));
  const p = punkte[i];
  const links = (i / (punkte.length - 1)) * kasten.width;
  const [zeiger, punkt, tip] = ['.x-zeiger', '.x-zeiger-punkt', '.x-tip'].map((s) => flaeche.querySelector(s));
  zeiger.style.left = `${links}px`;
  punkt.style.left = `${links}px`;
  punkt.style.top = `${y(p.c)}%`;
  const zeile = (name, wert) => `<div><span>${name}</span><span>${wert}</span></div>`;
  const naechstes = [...w.level].sort((a, b) => Math.abs(a.kurs / p.c - 1) - Math.abs(b.kurs / p.c - 1))[0];
  tip.innerHTML = `<b>${euroKurs(p.c)}</b><small>${datumLang(p.d)}</small>
    ${w.einstand ? zeile('zum Einstand', prozentText((p.c / w.einstand - 1) * 100)) : ''}
    ${zeile('bis heute', prozentText((w.kurs / p.c - 1) * 100))}
    ${naechstes ? zeile(`bis ${esc(kurzLevel[naechstes.art])}`, prozentText((naechstes.kurs / p.c - 1) * 100)) : ''}`;
  zeiger.hidden = punkt.hidden = tip.hidden = false;
  const platz = tip.offsetWidth + 12;
  tip.style.left = `${links + platz < kasten.width ? links + 12 : Math.max(0, links - platz)}px`;
}
function exitTipWeg(e) {
  const flaeche = e.target.closest?.('.x-flaeche');
  if (!flaeche || e.relatedTarget?.closest?.('.x-flaeche') === flaeche) return;
  flaeche.querySelectorAll('.x-zeiger, .x-zeiger-punkt, .x-tip').forEach((t) => { t.hidden = true; });
}
document.addEventListener('pointermove', exitTip);
document.addEventListener('pointerdown', exitTip);
document.addEventListener('pointerout', exitTipWeg);

// Kurschart der letzten 6 Monate mit den Levels als waagrechte Linien. Das SVG wird auf jede Breite
// gezogen; Beschriftungen und Kurspunkt liegen als HTML darüber, damit Schrift und Kreis nicht verzerren.
function exitChart(w) {
  const punkte = w.verlauf;
  if (punkte.length < 2) return '<p class="sekundaer">Kein Kursverlauf verfügbar.</p>';
  const linien = [
    ...w.level.map((l) => ({ wert: l.kurs, text: `${kurzLevel[l.art]} ${euroKurs(l.kurs)}`, klasse: `x-${l.art} ${levelZustand(l)}` })),
    ...(w.einstand ? [{ wert: w.einstand, text: `Einstand ${euroKurs(w.einstand)}`, klasse: 'x-einstand' }] : []),
    ...(w.trailing ? [{ wert: w.trailing, text: `ATR-Stop ${euroKurs(w.trailing)}`, klasse: 'x-trailing' }] : []),
  ];
  const alle = [...punkte.map((p) => p.c), ...linien.map((l) => l.wert), w.kurs];
  const tief = Math.min(...alle), hoch = Math.max(...alle);
  const rand = (hoch - tief) * 0.08 || 1;
  const y = (v) => ((hoch + rand - v) / (hoch - tief + 2 * rand)) * 100; // in Prozent der Höhe
  const x = (i) => (i / (punkte.length - 1)) * 1000;
  const pfad = punkte.map((p, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)} ${(y(p.c) * 2.6).toFixed(2)}`).join('');
  const linienSvg = linien.map((l) => `<line class="${l.klasse}" x1="0" x2="1000" y1="${(y(l.wert) * 2.6).toFixed(2)}" y2="${(y(l.wert) * 2.6).toFixed(2)}" vector-effect="non-scaling-stroke"/>`).join('');

  // Beschriftungen rechts: sortiert und auseinandergeschoben, damit sie sich nicht überdecken.
  const marken = linien.map((l) => ({ ...l, oben: y(l.wert) })).sort((a, b) => a.oben - b.oben);
  for (let i = 1; i < marken.length; i++) marken[i].oben = Math.max(marken[i].oben, marken[i - 1].oben + 9);
  const verschub = Math.max(0, (marken.at(-1)?.oben ?? 0) - 97);
  marken.forEach((m) => { m.oben = Math.max(2, m.oben - verschub); });

  const erster = lokal(punkte[0].d).toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit' });
  exitVerlauf.set(w.ticker, { w, y });
  return `<div class="x-chart">
      <div class="x-flaeche" data-ticker="${esc(w.ticker)}">
        <svg viewBox="0 0 1000 260" preserveAspectRatio="none" aria-hidden="true">
          <defs><linearGradient id="x-verlauf-${esc(w.ticker)}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="currentColor" stop-opacity=".22"/><stop offset="1" stop-color="currentColor" stop-opacity="0"/></linearGradient></defs>
          <path d="${pfad}L1000 260L0 260Z" fill="url(#x-verlauf-${esc(w.ticker)})" stroke="none"/>
          ${linienSvg}
          <path class="x-kurslinie" d="${pfad}" fill="none" vector-effect="non-scaling-stroke"/>
        </svg>
        <span class="x-punkt" style="top:${y(w.kurs)}%" title="Aktueller Kurs ${euroKurs(w.kurs)}"></span>
        <span class="x-zeiger" hidden></span><span class="x-zeiger-punkt" hidden></span><div class="c-tip x-tip" hidden></div>
        <span class="x-datum links">${erster}</span><span class="x-datum rechts">heute</span>
      </div>
      <div class="x-marken" aria-hidden="true">${marken.map((m) => `<span class="${m.klasse}" style="top:${m.oben}%">${esc(m.text)}</span>`).join('')}</div>
    </div>`;
}

function exitBalken(w) {
  return w.level.map((l) => {
    const zustand = levelZustand(l);
    const status = l.erreicht ? 'erreicht' : `noch ${prozentText(l.abstand)}`;
    const fuellung = l.fortschritt === null ? '' : `<span class="x-fuellung ${l.richtung}" style="width:${(l.fortschritt * 100).toFixed(1)}%"></span>`;
    // Was das Level für deinen Einstieg bedeutet: Gewinn oder Verlust, wenn es ausgelöst wird.
    const ergebnis = w.einstand ? ` · ${prozentText((l.kurs / w.einstand - 1) * 100)} zum Einstand` : '';
    return `<div class="x-zeile ${zustand}">
        <span class="x-name">${esc(l.name)}<span class="klein">${euroKurs(l.kurs)}${ergebnis}</span></span>
        <span class="x-spur" title="${l.fortschritt === null ? 'Nicht im Depot: kein Einstandskurs als Startpunkt' : `${Math.round(l.fortschritt * 100)} % des Wegs vom Einstand zum Level`}">${fuellung}</span>
        <span class="x-status">${zustand === 'nah' ? '<b>nah</b> · ' : ''}${status}</span>
      </div>`;
  }).join('');
}

// Alles relativ zum eigenen Einstand: 0 = Einstandskurs. Balken = wo der Kurs heute steht,
// rote Marke = wo der Stop-Vorschlag liegt. Sortiert nach dem, was der Stop sichern würde.
function einstiegDiagramm(liste) {
  const relativ = (wert, basis) => (wert / basis - 1) * 100;
  const zeilen = liste.map((o) => {
    if (!o.einstand || !o.kurs) return { ...o, ohne: true };
    return { ...o, gv: relativ(o.kurs, o.einstand), stop: o.trailing ? relativ(o.trailing, o.einstand) : null };
  });
  const mit = zeilen.filter((z) => !z.ohne).sort((a, b) => (b.stop ?? -1e9) - (a.stop ?? -1e9));
  const groesste = Math.max(1, ...mit.flatMap((z) => [Math.abs(z.gv), Math.abs(z.stop ?? 0)]));
  const lage = (w) => 50 + (w / groesste) * 46;
  const zeile = (z) => {
    const x = lage(z.gv);
    const balken = `<i class="th-balken ${z.gv >= 0 ? 'plus' : 'minus'}" style="left:${Math.min(50, x)}%;width:${Math.abs(x - 50)}%"></i>`;
    const marke = z.stop === null ? '' : `<i class="ex-stop" style="left:${lage(z.stop)}%"></i>`;
    // Nach starkem Rückgang ist der Stop vom Hoch schon unterschritten: Dann gilt ein neuer ab heute.
    const neu = z.hoch_stop_unterschritten ? ' <span class="ex-neu" title="Der Kurs ist unter den Stop vom Hoch der letzten Wochen gefallen. Dieser Vorschlag ist neu vom heutigen Kurs aus gerechnet.">neu ab heute</span>' : '';
    const text = z.stop === null ? 'kein Stop-Vorschlag'
      : z.stop >= 0 ? `Stop sichert <b class="plus">${prozentText(z.stop)}</b>${neu}`
      : `Stop hieße <b class="minus">${prozentText(z.stop)}</b> Verlust${neu}`;
    const titel = `${z.name}: Kurs ${euroKurs(z.kurs)} (${prozentText(z.gv)} zum Einstand ${euroKurs(z.einstand)})${z.stop === null ? '' : `, Stop-Vorschlag ${euroKurs(z.trailing)} (${prozentText(z.trailing_abstand)} unter dem Kurs), ATR ${komma2.format(z.atr_prozent)} % am Tag`}`;
    return `<a class="th-zeile ex-zeile" href="${esc(yahooLink(z.ticker))}" target="_blank" rel="noopener" title="${esc(titel)}">
        <span class="th-name">${esc(z.ticker)}</span>
        <span class="th-spur">${balken}${marke}</span>
        <span class="ex-text">${text}</span>
      </a>`;
  };
  const fehlend = zeilen.filter((z) => z.ohne);
  return `<div class="th-diagramm ex-diagramm" style="--kopf:1.05rem">
      <div class="th-linien" aria-hidden="true"><span class="th-null"></span><span class="th-linie einstand" style="left:50%"><em>Einstand</em></span></div>
      ${mit.map(zeile).join('')}
    </div>
    <p class="klein ex-legende"><span class="ex-legende-balken"></span> Kurs heute · <span class="ex-legende-stop"></span> Stop-Vorschlag · beides im Vergleich zu deinem Einstand</p>
    ${fehlend.length ? `<p class="klein th-fehlt">Ohne Einstand oder Kurs: ${fehlend.map((z) => esc(z.ticker)).join(', ')}</p>` : ''}`;
}

// Reihenfolge: zuerst Werte mit Handlungsbedarf (erreicht oder nah), darin das nächste Level zuerst.
let exitAuswahl = null; // Ticker, dessen Details unten stehen
try { exitAuswahl = localStorage.getItem('exitAuswahl'); } catch {}
const naechstesLevel = (w) => [...w.level].sort((a, b) => (b.erreicht - a.erreicht) || Math.abs(a.abstand) - Math.abs(b.abstand))[0];
function exitReihenfolge() {
  const werte = exitDaten.werte.filter((w) => !w.fehler && w.level.length);
  const dringend = (w) => w.level.some((l) => levelZustand(l));
  return werte.sort((a, b) => (dringend(b) - dringend(a)) || Math.abs(naechstesLevel(a).abstand) - Math.abs(naechstesLevel(b).abstand));
}

// Kursleiter: eine Spur vom tiefsten bis zum höchsten Level, darauf alle Level als Marken,
// der Einstand als feiner Strich und der heutige Kurs als Punkt. Ein Blick zeigt, wo es eng wird.
function kursleiter(w) {
  const werte = [w.kurs, ...w.level.map((l) => l.kurs), ...(w.einstand ? [w.einstand] : [])];
  const tief = Math.min(...werte), hoch = Math.max(...werte);
  const rand = (hoch - tief) * 0.04 || 1;
  const lage = (v) => ((v - tief + rand) / (hoch - tief + 2 * rand)) * 100;
  const marken = w.level.map((l) => `<i class="xl-marke x-${l.art} ${levelZustand(l)}" style="left:${lage(l.kurs)}%" title="${esc(`${l.name} ${euroKurs(l.kurs)}: ${l.erreicht ? 'erreicht' : `noch ${prozentText(l.abstand)}`}`)}"></i>`).join('');
  const einstand = w.einstand ? `<i class="xl-einstand" style="left:${lage(w.einstand)}%" title="Einstand ${euroKurs(w.einstand)}"></i>` : '';
  return `<span class="xl-spur">${einstand}${marken}<i class="xl-kurs" style="left:${lage(w.kurs)}%" title="Kurs ${euroKurs(w.kurs)}"></i></span>`;
}

function exitUebersichtZeile(w) {
  const l = naechstesLevel(w);
  const zustand = levelZustand(l);
  const status = l.erreicht ? `<b>${esc(kurzLevel[l.art])} erreicht</b>` : `${esc(kurzLevel[l.art])} <b>${prozentText(l.abstand)}</b>`;
  return `<button type="button" class="xl-zeile ${zustand}${w.ticker === exitAuswahl ? ' gewaehlt' : ''}" data-ticker="${esc(w.ticker)}" aria-pressed="${w.ticker === exitAuswahl}">
      <span class="xl-name"><b>${esc(w.ticker)}</b><span class="klein">${esc(w.name)}</span></span>
      ${kursleiter(w)}
      <span class="xl-status">${status}</span>
    </button>`;
}

function zeichneExits() {
  if (!exitDaten) return;
  const liste = exitReihenfolge();
  if (!liste.some((w) => w.ticker === exitAuswahl)) exitAuswahl = liste[0]?.ticker ?? null;

  // Übersicht: eine Zeile pro Aktie, gruppiert nach Dringlichkeit.
  const dringend = liste.filter((w) => w.level.some((l) => levelZustand(l)));
  const ruhig = liste.filter((w) => !dringend.includes(w));
  const gruppe = (titel, werte) => (werte.length ? `<h3 class="xl-gruppe">${titel} <span>${werte.length}</span></h3>${werte.map(exitUebersichtZeile).join('')}` : '');
  el('x-uebersicht').innerHTML = liste.length
    ? `${gruppe('Handlungsbedarf', dringend)}${gruppe('Im Plan', ruhig)}
       <p class="klein ex-legende"><i class="xl-legende x-teilverkauf"></i> Verkaufs-Level · <i class="xl-legende x-nachkauf"></i> Nachkauf · <i class="xl-legende x-stop"></i> Stop · <i class="xl-legende einstand"></i> Einstand · <i class="xl-legende kurs"></i> Kurs heute</p>`
    : '<p class="sekundaer">Noch keine Exit-Level eingetragen. Trag sie bei deinen Thesen ein (Thesen → These bearbeiten → Exit-Plan).</p>';

  // Auswahl für die Details: Pfeile und Liste, wie beim Themen-Ranking.
  el('x-wahl').hidden = liste.length < 2;
  el('x-auswahl').innerHTML = liste.map((w) => `<option value="${esc(w.ticker)}"${w.ticker === exitAuswahl ? ' selected' : ''}>${esc(w.name)} (${esc(w.ticker)})</option>`).join('');

  const fehler = exitDaten.werte.filter((w) => w.fehler).map((w) => `<p class="meldung">${esc(w.ticker)}: ${esc(w.fehler)}</p>`).join('');
  el('x-werte').innerHTML = fehler + liste.filter((w) => w.ticker === exitAuswahl).map((w) => {
    const zumEinstand = (v) => (w.einstand ? prozentText((v / w.einstand - 1) * 100) : null);
    const fakten = [
      `Kurs ${euroKurs(w.kurs)}${AKTUALITAET[w.aktualitaet] ? ` (${AKTUALITAET[w.aktualitaet]})` : ''}`,
      w.einstand ? `Einstand ${euroKurs(w.einstand)}, Kurs ${zumEinstand(w.kurs)} dazu` : 'nicht im Depot',
      w.atr_prozent !== undefined ? `ATR ${komma2.format(w.atr_prozent)} % am Tag` : '',
      w.trailing ? `ATR-Stop-Vorschlag ${euroKurs(w.trailing)} (${prozentText(w.trailing_abstand)} vom Kurs${w.einstand ? `, ${zumEinstand(w.trailing)} vom Einstand` : ''}${w.hoch_stop_unterschritten ? ', neu ab heute' : ''})` : '',
    ].filter(Boolean).join(' · ');
    const alarme = w.level.filter((l) => levelZustand(l)).length;
    return `<section class="karte th-karte x-karte${alarme ? ' mit-alarm' : ''}" id="x-${esc(w.ticker)}">
        <div class="th-kopf"><h2>${esc(w.name)} <span class="sekundaer">${esc(w.ticker)} · These ${esc(w.these)}</span></h2><p class="sekundaer">${esc(fakten)}</p></div>
        ${exitChart(w)}
        <div class="x-balken">${exitBalken(w)}</div>
      </section>`;
  }).join('');

  // Ohne Exit-Plan: wie viel Luft bis zum ATR-Stop-Vorschlag bleibt. Negativ heißt: Der Kurs liegt
  // schon darunter, nach dieser Regel wäre die Position ausgestoppt.
  const ohne = exitDaten.ohne_plan;
  el('x-ohne-unter').textContent = ohne.length
    ? `${ohne.length} Positionen haben noch keine Exit-Level. Nulllinie ist dein Einstand: Der Balken zeigt, wo der Kurs heute steht, die rote Marke, wo der Trailing-Stop-Vorschlag aus der ATR liegt (${exitDaten.trailing_regel}). Rechts steht, ob ein Stop dort Gewinn sichern oder Verlust festmachen würde.`
    : 'Alle Positionen haben einen Exit-Plan.';
  el('x-ohne').innerHTML = ohne.length ? einstiegDiagramm(ohne) : '';
}

async function ladeExits() {
  let d;
  try {
    d = await api('/api/exits');
  } catch {
    d = { fehler: 'Die Exit-Alarme konnten nicht geladen werden. Läuft der Server noch?' };
  }
  if (d.fehler) {
    if (!exitDaten) el('x-status').textContent = d.fehler;
    return;
  }
  exitDaten = d;
  const levels = d.werte.flatMap((w) => (w.level ?? []).map((l) => ({ ...l, w })));
  const alarme = levels.filter((l) => levelZustand(l));
  el('x-status').textContent = [
    `${d.werte.length} ${d.werte.length === 1 ? 'Wert' : 'Werte'} mit Exit-Plan, ${levels.length} Level`,
    alarme.length ? `${alarme.length} ${alarme.length === 1 ? 'Level ist' : 'Level sind'} erreicht oder nah` : 'kein Level in der Nähe',
  ].join(' · ');
  zeichneExits();

  // Alarm auch in der Leiste oben, neue Alarme springen sofort ins Bild.
  kopf.exits = alarme.slice(0, 3).map((l) => `<span class="kopf-item"><em>Exit ${esc(l.w.ticker)}</em><b class="${l.erreicht ? 'minus' : 'alt'}">${esc(kurzLevel[l.art])} ${l.erreicht ? 'erreicht' : prozentText(l.abstand)}</b></span>`).join('');
  const neu = alarme.filter((l) => !exitGesehen.has(`${l.w.ticker}|${l.art}|${l.erreicht}`));
  neu.forEach((l) => exitGesehen.add(`${l.w.ticker}|${l.art}|${l.erreicht}`));
  if (neu.length && !kopfPause) kopfIndex = Object.keys(kopf).filter((k) => kopf[k]).indexOf('exits');
  zeichneKopf();
}

el('x-schwelle').addEventListener('change', (e) => {
  const wert = Number(String(e.target.value).replace(',', '.'));
  if (!(wert >= 1 && wert <= 30)) { e.target.value = String(exitSchwelle); return; }
  exitSchwelle = wert;
  try { localStorage.setItem('exitSchwelle', String(exitSchwelle)); } catch {}
  zeichneExits();
  ladeExits();
});
function waehleExit(ticker, scrollen = false) {
  exitAuswahl = ticker;
  try { localStorage.setItem('exitAuswahl', ticker); } catch {}
  zeichneExits();
  if (scrollen) el('x-werte').scrollIntoView({ behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'start' });
}
function blaettereExit(schritt) {
  const liste = exitReihenfolge();
  if (!liste.length) return;
  const i = liste.findIndex((w) => w.ticker === exitAuswahl);
  waehleExit(liste[(i + schritt + liste.length) % liste.length].ticker);
}
el('x-uebersicht').addEventListener('click', (e) => {
  const knopf = e.target.closest('button[data-ticker]');
  if (knopf) waehleExit(knopf.dataset.ticker, true);
});
el('x-auswahl').addEventListener('change', (e) => waehleExit(e.target.value));
el('x-zurueck').addEventListener('click', () => blaettereExit(-1));
el('x-weiter').addEventListener('click', () => blaettereExit(1));
// Auf dem Handy: seitlich über die Details wischen wechselt die Aktie.
let exitWisch = null;
el('x-werte').addEventListener('touchstart', (e) => { const t = e.touches[0]; exitWisch = { x: t.clientX, y: t.clientY }; }, { passive: true });
el('x-werte').addEventListener('touchend', (e) => {
  if (!exitWisch) return;
  const t = e.changedTouches[0];
  const dx = t.clientX - exitWisch.x, dy = t.clientY - exitWisch.y;
  exitWisch = null;
  if (Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy) * 1.5) blaettereExit(dx < 0 ? 1 : -1);
}, { passive: true });

// ---- Gemeinsame Diagramm-Bausteine für Risiko und Benchmark ----
const prozent1 = new Intl.NumberFormat('de-DE', { minimumFractionDigits: 1, maximumFractionDigits: 1, signDisplay: 'exceptZero' });
const zahl2 = new Intl.NumberFormat('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const datumKurzJahr = (iso) => lokal(iso).toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: '2-digit' });

// Linien- oder Flächenchart, das sich der Breite seines Platzes anpasst.
// serien: [{ name, klasse, werte: [Zahl|null] }], daten: ISO-Tage, format: Zahl -> Text.
// flaeche: "null" füllt die erste Serie bis zur Nulllinie (grün darüber, rot darunter).
// Jedes Linien-Chart lässt sich zoomen und verschieben (siehe zeitZoom). Der Ausschnitt bleibt
// beim Neuzeichnen erhalten, solange dieselben Tage gezeigt werden.
// Zusätzlich: serien mit rechts: true bekommen eine eigene Skala rechts (z. B. ein Kurs neben einem Indikator),
// nullpunkt: false lässt die linke Achse nicht bei 0 beginnen, linien: [{ wert, text }] zeichnet Referenzlinien.
function linienChart(feld, { daten, serien, format = (v) => `${prozent1.format(v)} %`, hoehe = 260, flaeche = null, nullpunkt = true, linien = [], formatRechts = null }) {
  if (!feld.clientWidth || !daten.length) return;
  const kennung = `${daten.length}|${daten[0]}|${daten.at(-1)}`;
  const lc = feld._lc ?? (feld._lc = linienChartEinrichten(feld));
  if (lc.kennung !== kennung) lc.zoom.loesen();
  Object.assign(lc, { kennung, daten, serien, format, hoehe, flaeche, nullpunkt, linien, formatRechts });
  feld.innerHTML = `<div class="lc"><svg></svg><div class="c-tip lc-tip" hidden></div></div>
    ${serien.length > 1 ? `<p class="lc-legende">${serien.map((s) => `<span class="${s.klasse}"><i></i>${esc(s.name)}${s.rechts && serien.some((x) => !x.rechts) ? ' <small>(rechte Achse)</small>' : ''}</span>`).join('')}</p>` : ''}`;
  feld.append(lc.leiste);
  linienChartMalen(feld);
}

// Einmal pro Feld: Zoom und Tooltip. Die Ereignisse hängen am Feld, das bleibt beim Neuzeichnen stehen.
function linienChartEinrichten(feld) {
  const lc = { leiste: Object.assign(document.createElement('p'), { className: 'zoom-leiste' }), zeigerX: null };
  lc.zoom = zeitZoom(feld, {
    ganz: () => ({ von: 0, bis: Math.max(1, lc.daten.length - 1) }),
    lage: () => ({ links: lc.rand?.links ?? 52, breite: lc.innen ?? 1 }),
    minBreite: () => Math.min(5, lc.daten.length - 1),
    zeichnen: () => linienChartMalen(feld),
    leiste: lc.leiste,
  });
  // Werte an der Mausposition: senkrechte Linie und kleine Tabelle.
  lc.zeigen = (clientX) => {
    const svg = feld.querySelector('.lc svg'), tip = feld.querySelector('.lc-tip'), zeiger = feld.querySelector('.lc-zeiger');
    if (!svg || !lc.x) return;
    if (lc.zoom.zieht) { lc.weg(); return; }
    const { von, bis } = lc.ausschnitt;
    const px = clientX - svg.getBoundingClientRect().left;
    const i = Math.max(Math.ceil(von), Math.min(Math.floor(bis), Math.round(von + ((px - lc.rand.links) / lc.innen) * (bis - von))));
    const x = lc.x(i);
    zeiger.setAttribute('x1', x); zeiger.setAttribute('x2', x); zeiger.setAttribute('visibility', 'visible');
    tip.innerHTML = `<small>${lokal(lc.daten[i]).toLocaleDateString('de-DE')}</small>${lc.serien.map((s) => `<div class="${s.klasse}"><span><i></i>${esc(s.name)}</span><span>${s.werte[i] === null || s.werte[i] === undefined ? '–' : (s.rechts && lc.formatRechts ? lc.formatRechts : lc.format)(s.werte[i])}</span></div>`).join('')}`;
    tip.hidden = false;
    const platz = tip.offsetWidth + 12;
    tip.style.left = `${x + platz < lc.breite ? x + 12 : Math.max(0, x - platz)}px`;
  };
  lc.weg = () => {
    const tip = feld.querySelector('.lc-tip'), zeiger = feld.querySelector('.lc-zeiger');
    if (tip) tip.hidden = true;
    zeiger?.setAttribute('visibility', 'hidden');
  };
  const imChart = (e) => e.target.closest?.('.lc svg');
  feld.addEventListener('pointermove', (e) => { if (!imChart(e)) return; lc.zeigerX = e.clientX; lc.zeigen(e.clientX); });
  feld.addEventListener('pointerdown', (e) => { if (imChart(e)) lc.zeigen(e.clientX); });
  feld.addEventListener('pointerout', (e) => { if (imChart(e) && !e.relatedTarget?.closest?.('.lc svg')) { lc.zeigerX = null; lc.weg(); } });
  return lc;
}

function linienChartMalen(feld) {
  const lc = feld._lc;
  const svg = feld.querySelector('.lc svg');
  const breite = feld.clientWidth;
  if (!lc || !svg || !breite) return;
  const { daten, serien, format, hoehe, flaeche, nullpunkt = true, linien = [] } = lc;
  const rechtsSerien = serien.filter((s) => s.rechts);
  const rand = { links: 52, rechts: rechtsSerien.length ? 56 : 10, oben: 10, unten: 24 };
  const innen = breite - rand.links - rand.rechts;
  const ausschnitt = lc.zoom.ausschnitt();
  const { von, bis } = ausschnitt;
  const erstes = Math.max(0, Math.floor(von)), letztes = Math.min(daten.length - 1, Math.ceil(bis));
  // Die Höhe richtet sich nach dem sichtbaren Teil.
  const sichtbar = (liste) => liste.flatMap((s) => s.werte.slice(erstes, letztes + 1)).filter((v) => v !== null && v !== undefined && Number.isFinite(v));
  const alle = sichtbar(serien.filter((s) => !s.rechts));
  if (!alle.length) alle.push(0);
  for (const l of linien) alle.push(l.wert);
  const { werte: ticks, schritt } = nullpunkt ? achsenWerte(Math.min(...alle), Math.max(...alle)) : achsenFrei(Math.min(...alle), Math.max(...alle));
  const oben = ticks.at(-1), unten = ticks[0];
  const x = (i) => rand.links + (daten.length === 1 ? innen / 2 : ((i - von) / (bis - von || 1)) * innen);
  const y = (v) => rand.oben + ((oben - v) / (oben - unten || 1)) * (hoehe - rand.oben - rand.unten);
  Object.assign(lc, { rand, innen, breite, x, ausschnitt });
  const achse = nullpunkt ? achsenProzent(schritt) : achsenZahl(schritt);
  // Rechte Achse: eigene Skala, nur Beschriftung (die Gitterlinien gehören zur linken)
  let yRechts = null, rechteAchse = '';
  if (rechtsSerien.length) {
    const r = sichtbar(rechtsSerien);
    if (r.length) {
      const fr = achsenFrei(Math.min(...r), Math.max(...r));
      const ro = fr.werte.at(-1), ru = fr.werte[0];
      yRechts = (v) => rand.oben + ((ro - v) / (ro - ru || 1)) * (hoehe - rand.oben - rand.unten);
      const fz = achsenZahl(fr.schritt);
      rechteAchse = fr.werte.map((t) => `<text class="c-achse" x="${breite - rand.rechts + 6}" y="${yRechts(t) + 4}" text-anchor="start">${fz.format(t)}</text>`).join('');
    }
  }
  const referenz = linien.map((l) => `<line class="lc-ref" x1="${rand.links}" x2="${breite - rand.rechts}" y1="${y(l.wert)}" y2="${y(l.wert)}"/>${l.text ? `<text class="c-achse lc-ref-text" x="${rand.links + 4}" y="${y(l.wert) - 4}">${esc(l.text)}</text>` : ''}`).join('');
  const gitter = ticks.map((t) => `<line x1="${rand.links}" x2="${breite - rand.rechts}" y1="${y(t)}" y2="${y(t)}" class="${t === 0 ? 'lc-null' : 'lc-gitter'}"/>
    <text class="c-achse" x="${rand.links - 8}" y="${y(t) + 4}" text-anchor="end">${achse.format(t)}${format(1).includes('%') ? ' %' : ''}</text>`).join('');
  const anzahl = Math.min(6, letztes - erstes + 1);
  const datumsachse = Array.from({ length: anzahl }, (_, k) => Math.round(von + (k / Math.max(1, anzahl - 1)) * (bis - von)))
    .map((i, k) => `<text class="c-achse" x="${x(i)}" y="${hoehe - 6}" text-anchor="${k === 0 ? 'start' : k === anzahl - 1 ? 'end' : 'middle'}">${datumKurzJahr(daten[Math.min(daten.length - 1, Math.max(0, i))])}</text>`).join('');
  // Nur der sichtbare Teil (plus je ein Punkt links und rechts, damit die Linie bis an den Rand reicht).
  const pfad = (werte, abbilden = (v) => v, yf = y) => {
    let d = '', offen = false;
    for (let i = erstes; i <= letztes; i++) {
      const v = werte[i];
      if (v === null || v === undefined || !Number.isFinite(v)) { offen = false; continue; }
      d += `${offen ? 'L' : 'M'}${x(i).toFixed(1)} ${yf(abbilden(v)).toFixed(1)}`;
      offen = true;
    }
    return d;
  };
  let flaechen = '';
  if (flaeche === 'null') {
    const w = serien[0].werte;
    let erster = -1, letzter = -1;
    for (let i = erstes; i <= letztes; i++) if (w[i] !== null) { if (erster < 0) erster = i; letzter = i; }
    if (erster >= 0) {
      const zu = `L${x(letzter).toFixed(1)} ${y(0).toFixed(1)}L${x(erster).toFixed(1)} ${y(0).toFixed(1)}Z`;
      flaechen = `<path class="lc-plus" d="${pfad(w, (v) => Math.max(0, v))}${zu}"/><path class="lc-minus" d="${pfad(w, (v) => Math.min(0, v))}${zu}"/>`;
    }
  }
  const pfade = serien.map((s) => (s.rechts && !yRechts ? '' : `<path class="lc-linie ${s.klasse}${s.rechts ? ' lc-rechts' : ''}" d="${pfad(s.werte, undefined, s.rechts ? yRechts : y)}"/>`)).join('');
  lc.nummer ??= Math.random().toString(36).slice(2, 8);
  const clip = `lc-clip-${lc.nummer}`;
  svg.setAttribute('width', breite);
  svg.setAttribute('height', hoehe);
  svg.setAttribute('viewBox', `0 0 ${breite} ${hoehe}`);
  svg.innerHTML = `<defs><clipPath id="${clip}"><rect x="${rand.links}" y="0" width="${innen}" height="${hoehe}"/></clipPath></defs>
    ${gitter}${rechteAchse}${datumsachse}<g clip-path="url(#${clip})">${referenz}${flaechen}${pfade}</g><line class="lc-zeiger" y1="${rand.oben}" y2="${hoehe - rand.unten}" visibility="hidden"/>`;
  if (lc.zeigerX !== null && !lc.zoom.zieht) lc.zeigen(lc.zeigerX); else lc.weg();
}

// ---- Schwebendes Info-Fenster: Elemente mit data-tip zeigen beim Überfahren Details ----
// data-tip enthält Zeilen, getrennt durch "\n"; die erste Zeile ist die Überschrift.
const tipAttr = (...zeilen) => `data-tip="${esc(zeilen.filter(Boolean).join('\n'))}"`;
const schwebe = el('schwebe');
function zeigeSchwebe(e) {
  const ziel = e.target.closest?.('[data-tip]');
  if (!ziel) { schwebe.hidden = true; return; }
  const [kopf, ...rest] = ziel.dataset.tip.split('\n');
  schwebe.innerHTML = `<b>${esc(kopf)}</b>${rest.map((z) => `<span>${esc(z)}</span>`).join('')}`;
  schwebe.hidden = false;
  // Neben den Zeiger, am Rand auf die andere Seite.
  const abstand = 14, b = schwebe.offsetWidth, h = schwebe.offsetHeight;
  const links = e.clientX + abstand + b > innerWidth ? e.clientX - abstand - b : e.clientX + abstand;
  const oben = e.clientY + abstand + h > innerHeight ? e.clientY - abstand - h : e.clientY + abstand;
  schwebe.style.left = `${Math.max(4, links)}px`;
  schwebe.style.top = `${Math.max(4, oben)}px`;
}
document.addEventListener('pointermove', zeigeSchwebe);
document.addEventListener('pointerdown', (e) => { if (e.pointerType !== 'mouse') zeigeSchwebe(e); });
document.addEventListener('scroll', () => { schwebe.hidden = true; }, { passive: true });

// ---- 13 Risiko ----
let risikoDaten = null;
let risikoZeit = '1j';
try {
  const gemerkt = localStorage.getItem('risikoZeit');
  if (['3m', '6m', '1j', '2j'].includes(gemerkt)) risikoZeit = gemerkt;
} catch {}
const RISIKO_ZEIT_NAME = { '3m': '3 Monate', '6m': '6 Monate', '1j': '1 Jahr', '2j': '2 Jahre' };
const posTip = (p) => tipAttr(
  `${p.name} (${p.ticker})`,
  `Gewicht ${zahl2.format(p.gewicht)} % · Risikobeitrag ${zahl2.format(p.beitrag)} %`,
  `Volatilität ${zahl2.format(p.vol)} % p. a. · Beta ${zahl2.format(p.beta)}`,
  `Rendite im Zeitraum ${prozent1.format(p.rendite)} % · größter Rückgang ${prozent1.format(p.max_dd)} %`,
  'Klick für Details',
);

function risikoKennzahlen(d) {
  const k = d.depot;
  const karte = (titel, wert, text, klasse = '') => `<article class="karte r-kz"><h2>${titel}</h2><p class="kennzahl ${klasse}">${wert}</p><p class="sekundaer">${text}</p></article>`;
  el('r-kennzahlen').innerHTML = [
    karte('Schwankung pro Jahr', `${zahl2.format(k.vol)} %`, 'Typische Spanne, um die dein Depot in einem Jahr schwankt. Der MSCI World liegt meist bei 12 bis 18 %.'),
    karte('Value at Risk, 1 Tag', euro.format(k.var_eur), `${zahl2.format(k.var_prozent)} % · an 19 von 20 Tagen war der Verlust kleiner.`, 'minus'),
    karte('Expected Shortfall', euro.format(k.es_eur), `${zahl2.format(k.es_prozent)} % · so viel im Schnitt an den übrigen, schlechtesten Tagen.`, 'minus'),
    karte('Beta zum Weltmarkt', zahl2.format(k.beta), `Fällt der MSCI World um 1 %, fällt dein Depot im Schnitt um ${zahl2.format(k.beta)} %.`),
    karte('Größter Absturz', `${prozent1.format(k.max_dd)} %`, `Tiefster Rückgang vom Hoch in ${RISIKO_ZEIT_NAME[d.zeitraum.schluessel] === '1 Jahr' ? 'einem Jahr' : `${RISIKO_ZEIT_NAME[d.zeitraum.schluessel]}`}. Heute: ${prozent1.format(k.dd_jetzt)} % unter dem Hoch.`, 'minus'),
    karte('Streuung', `${zahl2.format(k.diversifikation)}×`, `Durchschnittliche Korrelation ${zahl2.format(k.korrelation_schnitt)}. Je höher die Zahl, desto mehr Schwankung hebt die Mischung auf.`),
  ].join('');
}

// Gewicht gegen Risikobeitrag, je Position zwei Balken übereinander.
function risikoBeitrag(d) {
  const liste = [...d.positionen].sort((a, b) => b.beitrag - a.beitrag);
  const groesste = Math.max(...liste.map((p) => Math.max(p.gewicht, p.beitrag)));
  el('r-beitrag').innerHTML = `<div class="rb">${liste.map((p) => {
    const faktor = p.gewicht ? p.beitrag / p.gewicht : 0;
    const art = faktor >= 1.3 ? 'mehr' : faktor <= 0.7 ? 'weniger' : 'gleich';
    return `<button type="button" class="rb-zeile r-klick" data-pos="${esc(p.ticker)}" ${posTip(p)}>
        <span class="th-name">${esc(p.ticker)}</span>
        <span class="rb-spur"><i class="rb-gewicht" style="width:${(p.gewicht / groesste) * 100}%"></i><i class="rb-risiko ${art}" style="width:${(Math.max(0, p.beitrag) / groesste) * 100}%"></i></span>
        <span class="rb-text"><b>${zahl2.format(p.beitrag)} %</b> Risiko · ${zahl2.format(p.gewicht)} % Gewicht <em class="${art}">${faktor >= 0 ? `${zahl2.format(faktor)}×` : ''}</em></span>
      </button>`;
  }).join('')}</div>
  <p class="klein ex-legende"><span class="rb-l-gewicht"></span> Anteil am Depotwert · <span class="rb-l-risiko mehr"></span> trägt deutlich mehr Risiko als Gewicht · <span class="rb-l-risiko gleich"></span> etwa gleich · <span class="rb-l-risiko weniger"></span> beruhigt das Depot</p>`;
}

// Streudiagramm: Volatilität (x) gegen Beta (y), Kreisgröße nach Gewicht. Dazu das Depot als Raute.
// Der ganze Wertebereich des Streudiagramms, mit etwas Luft an den Rändern.
function streuBereich(d) {
  const p = d.positionen;
  const ywerte = [...p.map((q) => q.beta), d.depot.beta, 0, 1];
  return { x0: 0, x1: Math.max(...p.map((q) => q.vol), d.depot.vol) * 1.1, y0: Math.min(...ywerte) - 0.2, y1: Math.max(...ywerte) + 0.2 };
}

// Streudiagramm Volatilität (x) gegen Beta (y). bereich = sichtbarer Ausschnitt, für das Zoomen.
function risikoStreuung(d, feld = el('r-streu'), { hoehe = 300, bereich = streuBereich(d), abstand = 40 } = {}) {
  const breite = feld.clientWidth;
  if (!breite) return;
  const rand = { links: 44, rechts: 16, oben: 14, unten: 30 };
  const p = d.positionen;
  const { x0, x1, y0, y1 } = bereich;
  const x = (v) => rand.links + ((v - x0) / (x1 - x0)) * (breite - rand.links - rand.rechts);
  const y = (v) => rand.oben + ((y1 - v) / (y1 - y0)) * (hoehe - rand.oben - rand.unten);
  const xticks = achsenWerte(x0, x1).werte.filter((t) => t >= x0 && t <= x1);
  const yticks = achsenWerte(y0, y1).werte.filter((t) => t >= y0 && t <= y1);
  const maxGew = Math.max(...p.map((q) => q.gewicht));
  const dx = x(d.depot.vol), dy = y(d.depot.beta);
  // Beschriftet werden nur Punkte mit genug Platz, sonst überdecken sich die Namen.
  // Beim Reinzoomen rücken die Punkte auseinander, dann bekommen alle ihren Namen.
  const beschriftet = [];
  const punkte = [...p].sort((a, b) => b.gewicht - a.gewicht).map((q) => {
    const r = 4 + Math.sqrt(q.gewicht / maxGew) * 16;
    const px = x(q.vol), py = y(q.beta);
    const frei = beschriftet.every(([bx, by]) => Math.hypot(bx - px, by - py) > abstand) && Math.hypot(dx - px, dy - py) > 30;
    if (frei) beschriftet.push([px, py]);
    return `<g class="rs-punkt r-klick" data-pos="${esc(q.ticker)}" ${posTip(q)}>
      <circle cx="${px}" cy="${py}" r="${r}"/>${frei ? `<text x="${px}" y="${py - r - 4}" text-anchor="middle">${esc(q.ticker)}</text>` : ''}</g>`;
  }).join('');
  const clip = `rs-clip-${feld.id}`;
  feld.innerHTML = `<svg width="${breite}" height="${hoehe}" viewBox="0 0 ${breite} ${hoehe}" role="img" aria-label="Streudiagramm Volatilität gegen Beta">
    <defs><clipPath id="${clip}"><rect x="${rand.links}" y="${rand.oben}" width="${breite - rand.links - rand.rechts}" height="${hoehe - rand.oben - rand.unten}"/></clipPath></defs>
    ${xticks.map((t) => `<line class="lc-gitter" x1="${x(t)}" x2="${x(t)}" y1="${rand.oben}" y2="${hoehe - rand.unten}"/><text class="c-achse" x="${x(t)}" y="${hoehe - 10}" text-anchor="middle">${achsenProzent(xticks[1] - xticks[0] || 1).format(t).replace('+', '')} %</text>`).join('')}
    ${yticks.map((t) => `<line class="${t === 1 ? 'rs-eins' : 'lc-gitter'}" x1="${rand.links}" x2="${breite - rand.rechts}" y1="${y(t)}" y2="${y(t)}"/><text class="c-achse" x="${rand.links - 8}" y="${y(t) + 4}" text-anchor="end">${zahl2.format(t)}</text>`).join('')}
    <text class="c-achse rs-achsname" x="${breite - rand.rechts}" y="${hoehe - 22}" text-anchor="end">Volatilität pro Jahr →</text>
    <text class="c-achse rs-achsname" x="${rand.links + 4}" y="${rand.oben + 10}">↑ Beta</text>
    <g clip-path="url(#${clip})">
      ${punkte}
      <g class="rs-depot" ${tipAttr('Dein Depot', `Volatilität ${zahl2.format(d.depot.vol)} % p. a. · Beta ${zahl2.format(d.depot.beta)}`)}><rect x="${dx - 7}" y="${dy - 7}" width="14" height="14" transform="rotate(45 ${dx} ${dy})"/><text x="${dx + 12}" y="${dy + 4}">Depot</text></g>
    </g>
  </svg>`;
  return { rand, breite, hoehe };
}

// Großansicht des Streudiagramms: Mausrad zoomt an der Zeigerstelle, Ziehen verschiebt den Ausschnitt.
let streuZoom = null;
function oeffneStreuGross() {
  const d = risikoDaten;
  if (!d) return;
  el('r-d-titel').innerHTML = `Schwankung gegen Marktnähe <span class="sekundaer">${RISIKO_ZEIT_NAME[d.zeitraum.schluessel]}</span>`;
  el('r-d-inhalt').innerHTML = `
    <div class="rz-leiste">
      <button type="button" class="knopf th-pfeil" id="rz-rein" aria-label="Hineinzoomen">+</button>
      <button type="button" class="knopf th-pfeil" id="rz-raus" aria-label="Herauszoomen">−</button>
      <button type="button" class="knopf" id="rz-zurueck">Alles zeigen</button>
      <span class="sekundaer">Mausrad: zoomen · Ziehen: verschieben · Kreis anklicken: Details</span>
    </div>
    <div class="rz-flaeche" id="r-streu-gross"></div>`;
  const dialog = el('r-dialog');
  dialog.classList.add('breit');
  if (!dialog.open) dialog.showModal();
  const feld = el('r-streu-gross');
  const ganz = streuBereich(d);
  streuZoom = { bereich: { ...ganz }, lage: null };
  const zeichne = () => { streuZoom.lage = risikoStreuung(d, feld, { hoehe: Math.max(360, Math.min(innerHeight * 0.65, 640)), bereich: streuZoom.bereich, abstand: 26 }); };
  zeichne();

  // Zoomen um einen Punkt (in Datenwerten): der Punkt bleibt unter dem Zeiger stehen.
  const zoom = (faktor, fx = 0.5, fy = 0.5) => {
    const b = streuZoom.bereich;
    const mx = b.x0 + (b.x1 - b.x0) * fx, my = b.y1 - (b.y1 - b.y0) * fy;
    const neueBreite = Math.min((ganz.x1 - ganz.x0) * 1.5, Math.max(2, (b.x1 - b.x0) * faktor));
    const neueHoehe = Math.min((ganz.y1 - ganz.y0) * 1.5, Math.max(0.1, (b.y1 - b.y0) * faktor));
    streuZoom.bereich = { x0: mx - neueBreite * fx, x1: mx + neueBreite * (1 - fx), y0: my - neueHoehe * (1 - fy), y1: my + neueHoehe * fy };
    zeichne();
  };
  const anteil = (e) => {
    const { rand, breite, hoehe } = streuZoom.lage;
    const kasten = feld.getBoundingClientRect();
    return [
      Math.min(1, Math.max(0, (e.clientX - kasten.left - rand.links) / (breite - rand.links - rand.rechts))),
      Math.min(1, Math.max(0, (e.clientY - kasten.top - rand.oben) / (hoehe - rand.oben - rand.unten))),
    ];
  };
  feld.addEventListener('wheel', (e) => {
    e.preventDefault();
    zoom(e.deltaY < 0 ? 0.8 : 1.25, ...anteil(e));
  }, { passive: false });
  let zug = null;
  feld.addEventListener('pointerdown', (e) => {
    if (e.target.closest('[data-pos]')) return; // Klick auf einen Kreis öffnet die Details
    zug = { x: e.clientX, y: e.clientY, bereich: { ...streuZoom.bereich } };
    feld.setPointerCapture(e.pointerId);
    feld.classList.add('zieht');
  });
  feld.addEventListener('pointermove', (e) => {
    if (!zug) return;
    const { rand, breite, hoehe } = streuZoom.lage;
    const b = zug.bereich;
    const vx = ((e.clientX - zug.x) / (breite - rand.links - rand.rechts)) * (b.x1 - b.x0);
    const vy = ((e.clientY - zug.y) / (hoehe - rand.oben - rand.unten)) * (b.y1 - b.y0);
    streuZoom.bereich = { x0: b.x0 - vx, x1: b.x1 - vx, y0: b.y0 + vy, y1: b.y1 + vy };
    zeichne();
  });
  const loslassen = () => { zug = null; feld.classList.remove('zieht'); };
  feld.addEventListener('pointerup', loslassen);
  feld.addEventListener('pointercancel', loslassen);
  el('rz-rein').addEventListener('click', () => zoom(0.7));
  el('rz-raus').addEventListener('click', () => zoom(1.4));
  el('rz-zurueck').addEventListener('click', () => { streuZoom.bereich = { ...ganz }; zeichne(); });
}

// Histogramm der Tagesrenditen, mit Value at Risk und Expected Shortfall als Linien.
function risikoHistogramm(d) {
  const feld = el('r-hist');
  const breite = feld.clientWidth;
  if (!breite) return;
  const { kanten, anzahl } = d.histogramm;
  const hoehe = 300, rand = { links: 30, rechts: 10, oben: 30, unten: 30 };
  const x = (v) => rand.links + ((v - kanten[0]) / (kanten.at(-1) - kanten[0])) * (breite - rand.links - rand.rechts);
  const maxN = Math.max(...anzahl);
  const y = (n) => hoehe - rand.unten - (n / maxN) * (hoehe - rand.oben - rand.unten);
  const varGrenze = -d.depot.var_prozent, esGrenze = -d.depot.es_prozent;
  const balken = anzahl.map((n, i) => {
    const mitte = (kanten[i] + kanten[i + 1]) / 2;
    const art = mitte <= varGrenze ? 'rh-schlimm' : mitte < 0 ? 'rh-minus' : 'rh-plus';
    // Volle Höhe als Trefferfläche, damit auch niedrige Balken leicht zu treffen sind.
    return `<g ${tipAttr(`${n} ${n === 1 ? 'Tag' : 'Tage'}`, `Depot zwischen ${zahl2.format(kanten[i])} und ${zahl2.format(kanten[i + 1])} %`, `${zahl2.format((n / anzahl.reduce((a, b) => a + b, 0)) * 100)} % aller Handelstage`, mitte <= varGrenze ? 'gehört zu den schlimmsten 5 %' : '')}>
      <rect class="rh-treffer" x="${x(kanten[i])}" y="${rand.oben}" width="${x(kanten[i + 1]) - x(kanten[i])}" height="${hoehe - rand.unten - rand.oben}"/>
      <rect class="${art}" x="${x(kanten[i]) + 0.5}" y="${y(n)}" width="${Math.max(1, x(kanten[i + 1]) - x(kanten[i]) - 1)}" height="${hoehe - rand.unten - y(n)}"/></g>`;
  }).join('');
  const ticks = achsenWerte(kanten[0], kanten.at(-1)).werte.filter((t) => t >= kanten[0] && t <= kanten.at(-1));
  feld.innerHTML = `<svg width="${breite}" height="${hoehe}" viewBox="0 0 ${breite} ${hoehe}" role="img" aria-label="Verteilung der Tagesrenditen">
    ${ticks.map((t) => `<text class="c-achse" x="${x(t)}" y="${hoehe - 10}" text-anchor="middle">${achsenProzent(1).format(t)} %</text>`).join('')}
    ${balken}
    <line class="rh-linie" x1="${x(varGrenze)}" x2="${x(varGrenze)}" y1="${rand.oben - 18}" y2="${hoehe - rand.unten}"/><text class="rh-text" x="${x(varGrenze) + 4}" y="${rand.oben - 8}">VaR ${zahl2.format(varGrenze)} %</text>
    <line class="rh-linie es" x1="${x(esGrenze)}" x2="${x(esGrenze)}" y1="${rand.oben}" y2="${hoehe - rand.unten}"/><text class="rh-text es" x="${x(esGrenze) - 4}" y="${rand.oben + 10}" text-anchor="end">ES ${zahl2.format(esGrenze)} %</text>
  </svg>`;
  const tage = anzahl.reduce((a, b) => a + b, 0);
  el('r-hist-unter').textContent = `${tage} Handelstage. Schlechtester Tag ${prozent1.format(d.depot.schlechtester_tag)} %, bester ${prozent1.format(d.depot.bester_tag)} %. Rot: die schlimmsten 5 % der Tage.`;
}

// Korrelations-Heatmap als Raster. Farbe nach Stärke: rot = gleichlaufend, mint = gegenläufig.
function risikoKorrelation(d) {
  const { ticker, werte } = d.korrelation;
  const zelle = (v, a, b) => {
    if (a === b) return '<span class="rk-zelle rk-diag"></span>';
    const farbe = v >= 0 ? `color-mix(in srgb, var(--verlust) ${Math.round(v * 100)}%, transparent)` : `color-mix(in srgb, var(--gewinn) ${Math.round(-v * 100)}%, transparent)`;
    const text = v >= 0.6 ? 'bewegen sich sehr ähnlich' : v >= 0.3 ? 'bewegen sich eher gleich' : v > -0.3 ? 'weitgehend unabhängig' : 'eher gegenläufig';
    return `<button type="button" class="rk-zelle r-klick${Math.abs(v) >= 0.6 ? ' stark' : ''}" style="background:${farbe}" data-paar="${esc(ticker[a])}|${esc(ticker[b])}" ${tipAttr(`${ticker[a]} und ${ticker[b]}`, `Korrelation ${zahl2.format(v)}: ${text}`, 'Klick: beide Kursverläufe vergleichen')}>${Math.abs(v) >= 0.6 ? zahl2.format(v).replace(/^0/, '') : ''}</button>`;
  };
  const pos = Object.fromEntries(d.positionen.map((p) => [p.ticker, p]));
  const extra = new Set((d.extra ?? []).map((x) => x.ticker));
  el('r-korr').innerHTML = `<div class="rk" style="--n:${ticker.length}">
      <span></span>${ticker.map((t) => `<button type="button" class="rk-kopf r-klick${extra.has(t) ? ' extra' : ''}" data-pos="${esc(t)}" ${pos[t] ? posTip(pos[t]) : ''}><span>${esc(t)}</span></button>`).join('')}
      ${werte.map((zeile, a) => `<button type="button" class="rk-name r-klick${extra.has(ticker[a]) ? ' extra' : ''}" data-pos="${esc(ticker[a])}" ${pos[ticker[a]] ? posTip(pos[ticker[a]]) : ''}>${esc(ticker[a])}</button>${zeile.map((v, b) => zelle(v, a, b)).join('')}`).join('')}
    </div>
    <p class="klein ex-legende"><span class="rk-skala"></span> −1 gegenläufig · 0 unabhängig · +1 gleichlaufend. Zahlen ab 0,6.${extra.size ? ' Gold: nicht im Depot (aus „Mehr vom Markt“).' : ''}</p>`;
}

// Drawdown je Position: größter Rückgang (Balken) und heutiger Abstand zum Hoch (Punkt).
function risikoDrawdowns(d) {
  const liste = [...d.positionen].sort((a, b) => a.max_dd - b.max_dd);
  const tiefste = Math.min(...liste.map((p) => p.max_dd));
  el('r-dd').innerHTML = `<div class="rd">${liste.map((p) => `<button type="button" class="rd-zeile r-klick" data-pos="${esc(p.ticker)}" ${tipAttr(`${p.name} (${p.ticker})`, `Tiefster Rückgang vom Hoch: ${prozent1.format(p.max_dd)} %`, `Heute ${prozent1.format(p.dd_jetzt)} % unter dem Hoch`, `Schlechtester Tag ${prozent1.format(p.schlechtester_tag)} %`, 'Klick für Details')}>
      <span class="th-name">${esc(p.ticker)}</span>
      <span class="rd-spur"><i class="rd-max" style="width:${(p.max_dd / tiefste) * 100}%"></i><i class="rd-jetzt" style="right:${(p.dd_jetzt / tiefste) * 100}%"></i></span>
      <span class="rd-text">${prozent1.format(p.max_dd)} %</span>
    </button>`).join('')}</div>`;
}

function zeichneRisiko() {
  const d = risikoDaten;
  if (!d || el('seite-risiko').hidden) return;
  risikoKennzahlen(d);
  risikoBeitrag(d);
  risikoStreuung(d);
  risikoHistogramm(d);
  risikoKorrelation(d);
  risikoDrawdowns(d);
  linienChart(el('r-wasser'), { daten: d.unter_wasser.map((p) => p.d), serien: [{ name: 'Depot', klasse: 'lc-depot', werte: d.unter_wasser.map((p) => p.w) }], flaeche: 'null', hoehe: 300 });
  linienChart(el('r-rollend'), {
    daten: d.rollend.daten,
    serien: [{ name: 'Dein Depot', klasse: 'lc-depot', werte: d.rollend.depot }, { name: 'MSCI World', klasse: 'lc-welt', werte: d.rollend.markt }],
    format: (v) => `${zahl2.format(v)} % p. a.`, hoehe: 240,
  });
  risikoKorrRollend(d.korr_rollend);
}

// Rollierende Korrelation: Bewegt sich gerade alles gleich? Mit Warnung bei deutlichem Anstieg.
function risikoKorrRollend(k) {
  el('r-kr-karte').hidden = !k;
  if (!k) return;
  const z = (v) => zahl2.format(v);
  const richtung = k.jetzt - k.vor20 >= 0.05 ? `gestiegen (vor 20 Handelstagen ${z(k.vor20)})` : k.jetzt - k.vor20 <= -0.05 ? `gesunken (vor 20 Handelstagen ${z(k.vor20)})` : 'etwa gleich geblieben';
  const satz = el('r-kr-satz');
  satz.classList.toggle('warnung', k.warnung);
  satz.textContent = (k.warnung
    ? (k.jetzt >= k.schwelle_hoch ? `Achtung: Deine Positionen bewegen sich gerade fast wie eine einzige (${z(k.jetzt)}). ` : `Achtung: Deine Positionen rücken deutlich zusammen. `)
    : '')
    + `Heute ${z(k.jetzt)}, in den letzten 20 Handelstagen ${richtung}. Höher als an ${Math.round(k.perzentil)} % der Tage seit ${datumDe(k.daten[0])}; üblich ist ${z(k.median)}, am höchsten war es am ${datumDe(k.hoechst_am)} mit ${z(k.hoechst)}.`;
  linienChart(el('r-kr-linie'), {
    daten: k.daten,
    serien: [{ name: `${k.fenster[0]} Tage`, klasse: 'lc-depot', werte: k.lang }, { name: `${k.fenster[1]} Tage`, klasse: 'lc-welt', werte: k.kurz }],
    format: (v) => zahl2.format(v), hoehe: 220,
  });
  el('r-kr-paare').innerHTML = k.paare.length
    ? `<div class="r-kr-paare"><h3>Diese Paare rücken gerade zusammen (letzte 60 Handelstage gegen die 60 davor)</h3>${k.paare.map((p) => `<div class="r-kr-paar"><span>${esc(p.a)} und ${esc(p.b)}</span><span>${z(p.vorher)} → ${z(p.jetzt)}</span></div>`).join('')}</div>`
    : '';
}

// Detail-Fenster einer Position: Kurs gegen den Weltmarkt, Rückgänge, Kennzahlen, ähnlichste Werte.
function oeffneRisikoDetail(ticker) {
  const d = risikoDaten;
  const extra = d?.extra?.find((q) => q.ticker === ticker);
  const p = d?.positionen.find((q) => q.ticker === ticker) ?? (extra ? { ...extra, extra: true } : null);
  if (!p) return;
  const { ticker: namen, werte } = d.korrelation;
  const i = namen.indexOf(ticker);
  if (p.extra) {
    const nameVon = (t) => d.positionen.find((q) => q.ticker === t)?.name ?? d.extra?.find((q) => q.ticker === t)?.name ?? t;
    const liste = namen.map((t, j) => ({ t, v: werte[i][j] })).filter((x) => x.t !== ticker).sort((a, b) => b.v - a.v);
    el('r-d-titel').innerHTML = `${esc(p.name)} <span class="sekundaer">${esc(p.ticker)} · nicht im Depot · ${RISIKO_ZEIT_NAME[d.zeitraum.schluessel]}</span>`;
    el('r-d-inhalt').innerHTML = `<p class="r-d-satz">Wie ähnlich sich ${esc(p.name)} zu deinen Werten bewegt (Korrelation der Tagesrenditen in Euro). Klick öffnet den Vergleich.</p>
      ${liste.map((x) => `<button type="button" class="r-partner r-klick" data-paar="${esc(ticker)}|${esc(x.t)}"><span>${esc(nameVon(x.t))}</span><b>${zahl2.format(x.v)}</b></button>`).join('')}`;
    const dialog = el('r-dialog');
    dialog.classList.remove('breit');
    if (!dialog.open) dialog.showModal();
    return;
  }
  const partner = namen.map((t, j) => ({ t, v: werte[i][j] })).filter((x) => x.t !== ticker).sort((a, b) => b.v - a.v);
  const name = (t) => d.positionen.find((q) => q.ticker === t)?.name ?? t;
  const chip = (titel, wert, kl = '') => `<div class="r-chip"><span>${titel}</span><b class="${kl}">${wert}</b></div>`;
  const partnerZeile = (x) => `<button type="button" class="r-partner r-klick" data-paar="${esc(ticker)}|${esc(x.t)}" ${tipAttr(`${ticker} und ${x.t}`, `Korrelation ${zahl2.format(x.v)}`, 'Klick: Kursverläufe vergleichen')}><span>${esc(name(x.t))}</span><b>${zahl2.format(x.v)}</b></button>`;
  el('r-d-titel').innerHTML = `${esc(p.name)} <span class="sekundaer">${esc(p.ticker)} · ${RISIKO_ZEIT_NAME[d.zeitraum.schluessel]}</span>`;
  el('r-d-inhalt').innerHTML = `
    <div class="r-chips">
      ${chip('Rendite im Zeitraum', `${prozent1.format(p.rendite)} %`, klasse(p.rendite))}
      ${chip('Gewicht', `${zahl2.format(p.gewicht)} %`)}
      ${chip('Risikobeitrag', `${zahl2.format(p.beitrag)} %`, p.beitrag > p.gewicht * 1.3 ? 'minus' : '')}
      ${chip('Volatilität p. a.', `${zahl2.format(p.vol)} %`)}
      ${chip('Beta', zahl2.format(p.beta))}
      ${chip('Größter Rückgang', `${prozent1.format(p.max_dd)} %`, 'minus')}
      ${chip('Unter dem Hoch', `${prozent1.format(p.dd_jetzt)} %`, p.dd_jetzt < -10 ? 'minus' : '')}
      ${chip('Bester / schlechtester Tag', `${prozent1.format(p.bester_tag)} / ${prozent1.format(p.schlechtester_tag)} %`)}
    </div>
    <h3>Kurs gegen den MSCI World</h3><div class="r-grafik" id="r-d-kurs"></div>
    <h3>Abstand zum Hoch</h3><div class="r-grafik" id="r-d-dd"></div>
    <div class="r-zwei r-partnerliste">
      <div><h3>Läuft am stärksten mit</h3>${partner.slice(0, 4).map(partnerZeile).join('')}</div>
      <div><h3>Streut am besten mit</h3>${partner.slice(-4).reverse().map(partnerZeile).join('')}</div>
    </div>
    <p class="r-d-fuss"><a class="mehr" href="${esc(yahooLink(ticker))}" target="_blank" rel="noopener">Chart bei Yahoo Finance ↗</a></p>`;
  const dialog = el('r-dialog');
  dialog.classList.remove('breit');
  if (!dialog.open) dialog.showModal();
  // Erst nach dem Öffnen hat das Fenster eine Breite, dann können die Charts zeichnen.
  const zuProzent = (reihe) => reihe.map((v) => (v === null ? null : v - 100));
  const kurs = d.verlaeufe[ticker];
  linienChart(el('r-d-kurs'), { daten: d.daten, serien: [{ name: p.name, klasse: 'lc-depot', werte: zuProzent(kurs) }, { name: 'MSCI World', klasse: 'lc-welt', werte: zuProzent(d.verlaeufe[d.markt_ticker]) }], hoehe: 220 });
  let hoch = null;
  linienChart(el('r-d-dd'), { daten: d.daten, serien: [{ name: 'Abstand zum Hoch', klasse: 'lc-depot', werte: kurs.map((v) => { if (v === null) return null; hoch = Math.max(hoch ?? v, v); return (v / hoch - 1) * 100; }) }], flaeche: 'null', hoehe: 160 });
}

// Zwei Positionen nebeneinander: Warum laufen sie (nicht) zusammen?
function oeffneRisikoPaar(a, b) {
  const d = risikoDaten;
  if (!d || a === b) return;
  const name = (t) => d.positionen.find((q) => q.ticker === t)?.name ?? d.extra?.find((q) => q.ticker === t)?.name ?? t;
  const { ticker: namen, werte } = d.korrelation;
  const v = werte[namen.indexOf(a)][namen.indexOf(b)];
  const imDepot = (t) => d.positionen.some((q) => q.ticker === t);
  const text = v >= 0.6 ? 'Die beiden bewegen sich sehr ähnlich. Als Streuung zählen sie kaum doppelt.' : v >= 0.3 ? 'Die beiden bewegen sich eher gleich.' : v > -0.3 ? 'Die beiden bewegen sich weitgehend unabhängig: gut für die Streuung.' : 'Die beiden laufen eher gegeneinander: Das beruhigt das Depot.';
  el('r-d-titel').innerHTML = `${esc(name(a))} und ${esc(name(b))} <span class="sekundaer">${RISIKO_ZEIT_NAME[d.zeitraum.schluessel]}</span>`;
  el('r-d-inhalt').innerHTML = `
    <div class="r-chips"><div class="r-chip"><span>Korrelation</span><b>${zahl2.format(v)}</b></div></div>
    <p class="r-d-satz">${text}</p>
    <h3>Kursverläufe, beide ab 0 %</h3><div class="r-grafik" id="r-d-kurs"></div>
    <p class="r-d-fuss">${[a, b].map((t) => `<button type="button" class="knopf r-klick" data-pos="${esc(t)}">${imDepot(t) ? 'Details' : 'Ähnlichste Werte'} zu ${esc(t)}</button>`).join(' ')}</p>`;
  const dialog = el('r-dialog');
  dialog.classList.remove('breit');
  if (!dialog.open) dialog.showModal();
  const zuProzent = (reihe) => reihe.map((x) => (x === null ? null : x - 100));
  linienChart(el('r-d-kurs'), { daten: d.daten, serien: [{ name: name(a), klasse: 'lc-depot', werte: zuProzent(d.verlaeufe[a]) }, { name: name(b), klasse: 'lc-sp', werte: zuProzent(d.verlaeufe[b]) }, { name: 'MSCI World', klasse: 'lc-welt', werte: zuProzent(d.verlaeufe[d.markt_ticker]) }], hoehe: 260 });
}

// Klicks auf der Risiko-Seite (das Fenster liegt darin): Position öffnen oder zwei vergleichen.
el('seite-risiko').addEventListener('click', (e) => {
  const ziel = e.target.closest('[data-pos], [data-paar]');
  if (!ziel) return;
  schwebe.hidden = true;
  if (ziel.dataset.pos) oeffneRisikoDetail(ziel.dataset.pos);
  else oeffneRisikoPaar(...ziel.dataset.paar.split('|'));
});
el('r-d-zu').addEventListener('click', () => el('r-dialog').close());
el('r-dialog').addEventListener('close', () => el('r-dialog').classList.remove('breit'));
el('r-streu-gross-knopf').addEventListener('click', oeffneStreuGross);
el('r-dialog').addEventListener('click', (e) => { if (e.target === el('r-dialog')) el('r-dialog').close(); }); // Klick neben das Fenster schließt

el('r-zeitraum').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.zeit === risikoZeit)));
el('r-zeitraum').addEventListener('click', (e) => {
  const knopf = e.target.closest('button[data-zeit]');
  if (!knopf || knopf.dataset.zeit === risikoZeit) return;
  risikoZeit = knopf.dataset.zeit;
  try { localStorage.setItem('risikoZeit', risikoZeit); } catch {}
  el('r-zeitraum').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b === knopf)));
  el('r-status').textContent = `Wird für ${RISIKO_ZEIT_NAME[risikoZeit]} berechnet …`;
  ladeRisiko();
});

async function ladeRisiko() {
  let d;
  const zeit = risikoZeit;
  try {
    d = await api(mwPfad('risiko', `/api/risiko?zeitraum=${zeit}`));
  } catch {
    d = { fehler: 'Das Risiko konnte nicht geladen werden. Läuft der Server noch?' };
  }
  if (zeit !== risikoZeit) return; // inzwischen anderer Zeitraum gewählt
  if (d.fehler) {
    if (!risikoDaten) el('r-status').textContent = d.fehler;
    return;
  }
  risikoDaten = d;
  const groesster = [...d.positionen].sort((a, b) => b.beitrag - a.beitrag)[0];
  el('r-status').textContent = [
    `${RISIKO_ZEIT_NAME[d.zeitraum.schluessel]}: ${d.positionen.length} Positionen, ${d.zeitraum.tage} Handelstage (${lokal(d.zeitraum.von).toLocaleDateString('de-DE')} bis ${lokal(d.zeitraum.bis).toLocaleDateString('de-DE')})`,
    groesster ? `${groesster.name} trägt ${zahl2.format(groesster.beitrag)} % des Risikos bei ${zahl2.format(groesster.gewicht)} % Gewicht` : '',
    // Reicht der Zeitraum vor den ersten Kauf zurück, ist das eine Rückrechnung mit den heutigen Positionen.
    d.zeitraum.von < d.depot_seit ? `Dein Depot gibt es seit ${lokal(d.depot_seit).toLocaleDateString('de-DE')}: Die Kennzahlen rechnen mit deinen heutigen Positionen auch davor, die Zeitverläufe beginnen erst mit deinem ersten Kauf` : '',
    d.ohne_daten.length ? `ohne genug Kursdaten: ${d.ohne_daten.join(', ')}` : '',
  ].filter(Boolean).join(' · ');
  zeichneRisiko();
}

// ---- 14 Benchmark ----
let benchDaten = null;
let benchZeit = 'start';
let benchVon = null, benchBis = null; // eigene Daten statt fester Zeitraum
try {
  const gemerkt = localStorage.getItem('benchZeit');
  if (['1m', '3m', 'ytd', '1j', 'start'].includes(gemerkt)) benchZeit = gemerkt;
} catch {}

function benchAusschnitt() {
  const p = benchDaten.punkte;
  let von, bis = p.at(-1).d;
  if (benchVon || benchBis) {
    von = benchVon ?? p[0].d;
    bis = benchBis ?? bis;
  } else {
    const ende = lokal(bis);
    const z = new Date(ende);
    if (benchZeit === '1m') z.setMonth(z.getMonth() - 1);
    if (benchZeit === '3m') z.setMonth(z.getMonth() - 3);
    if (benchZeit === '1j') z.setFullYear(z.getFullYear() - 1);
    von = benchZeit === 'ytd' ? `${bis.slice(0, 4)}-01-01` : benchZeit === 'start' ? p[0].d : isoLokal(z);
  }
  // Der Startpunkt ist der letzte Tag vor dem Zeitraum, damit der erste Tag schon zählt.
  const i0 = Math.max(0, p.findIndex((q) => q.d >= von) - 1);
  const i1 = p.findLastIndex((q) => q.d <= bis);
  return p.slice(i0, i1 + 1);
}

function kennzahlenVon(werte) {
  const r = [];
  for (let i = 1; i < werte.length; i++) if (werte[i] !== null && werte[i - 1] !== null) r.push(werte[i] / werte[i - 1] - 1);
  if (r.length < 2) return null;
  const gesamt = werte.at(-1) / werte[0] - 1;
  const jahre = r.length / 252;
  const pa = (1 + gesamt) ** (1 / jahre) - 1;
  const mittel = r.reduce((a, b) => a + b, 0) / r.length;
  const vol = Math.sqrt(r.reduce((a, b) => a + (b - mittel) ** 2, 0) / (r.length - 1)) * Math.sqrt(252);
  let hoch = werte[0], maxDd = 0;
  for (const v of werte) { if (v === null) continue; hoch = Math.max(hoch, v); maxDd = Math.min(maxDd, v / hoch - 1); }
  return { gesamt: gesamt * 100, pa: pa * 100, vol: vol * 100, sharpe: vol ? pa / vol : 0, maxDd: maxDd * 100, bester: Math.max(...r) * 100, schlechtester: Math.min(...r) * 100 };
}

function zeichneBenchmark() {
  if (!benchDaten || el('seite-benchmark').hidden) return;
  const teil = benchAusschnitt();
  if (teil.length < 3) { el('b-urteil').textContent = 'Der gewählte Zeitraum ist zu kurz.'; return; }
  // Feste Vergleiche plus selbst gewählte (x_<Ticker>, höchstens 4, je eine eigene Farbe)
  const zusatz = Object.keys(benchDaten.namen).filter((k) => k.startsWith('x_'));
  const schluessel = ['depot', 'welt', 'sp500', ...zusatz].filter((k) => k === 'depot' || benchDaten.namen[k]);
  const klassen = { depot: 'lc-depot', welt: 'lc-welt', sp500: 'lc-sp', ...Object.fromEntries(zusatz.map((k, i) => [k, `lc-x${i + 1}`])) };
  const roh = Object.fromEntries(schluessel.map((k) => [k, teil.map((q) => q[k] ?? null)]));
  // Jede Linie startet bei 0 %.
  const rebasiert = Object.fromEntries(schluessel.map((k) => {
    const basis = roh[k].find((v) => v !== null);
    return [k, roh[k].map((v) => (v === null || !basis ? null : (v / basis - 1) * 100))];
  }));
  const tage = teil.map((q) => q.d);
  el('b-von').value = tage[0]; el('b-bis').value = tage.at(-1);
  linienChart(el('b-linie'), { daten: tage, serien: schluessel.map((k) => ({ name: benchDaten.namen[k], klasse: klassen[k], werte: rebasiert[k] })), hoehe: 320 });

  // Vorsprung als Verhältnis der beiden Indexstände: über 0 vorn, darunter hinten.
  const vorsprung = roh.depot.map((v, i) => (v === null || roh.welt[i] === null ? null : ((v / roh.depot[0]) / (roh.welt[i] / roh.welt[0]) - 1) * 100));
  linienChart(el('b-vorsprung'), { daten: tage, serien: [{ name: 'Vorsprung', klasse: 'lc-depot', werte: vorsprung }], flaeche: 'null', hoehe: 220, format: (v) => `${prozent1.format(v)} %-Pkt.` });

  // Urteil in einem Satz, ehrlich auch wenn das Depot hinten liegt.
  const k = Object.fromEntries(schluessel.map((s) => [s, kennzahlenVon(roh[s])]));
  if (k.depot && k.welt) {
    const abstand = k.depot.gesamt - k.welt.gesamt;
    el('b-urteil').innerHTML = `${lokal(tage[0]).toLocaleDateString('de-DE')} bis ${lokal(tage.at(-1)).toLocaleDateString('de-DE')}: Dein Depot <b class="${klasse(k.depot.gesamt)}">${prozent1.format(k.depot.gesamt)} %</b>, MSCI World <b class="${klasse(k.welt.gesamt)}">${prozent1.format(k.welt.gesamt)} %</b>${k.sp500 ? `, S&amp;P 500 <b class="${klasse(k.sp500.gesamt)}">${prozent1.format(k.sp500.gesamt)} %</b>` : ''}. `
      + (Math.abs(abstand) < 0.5 ? 'Du liegst etwa gleichauf mit dem Weltmarkt.' : `Du liegst <b class="${klasse(abstand)}">${zahl2.format(Math.abs(abstand))} Prozentpunkte ${abstand > 0 ? 'vor' : 'hinter'}</b> dem MSCI World.`)
      + (k.depot.vol > k.welt.vol * 1.2 ? ` Dabei schwankt dein Depot ${zahl2.format(k.depot.vol / k.welt.vol)}-mal so stark.` : '');
  }

  // Kennzahlen: je Kennzahl drei Balken um eine Nulllinie, der beste ist hervorgehoben.
  const metriken = [
    ['gesamt', 'Rendite im Zeitraum', (v) => `${prozent1.format(v)} %`, 'hoch'],
    ['pa', 'Rendite pro Jahr', (v) => `${prozent1.format(v)} %`, 'hoch'],
    ['vol', 'Schwankung pro Jahr', (v) => `${zahl2.format(v)} %`, 'tief'],
    ['sharpe', 'Sharpe Ratio', (v) => zahl2.format(v), 'hoch'],
    ['maxDd', 'Größter Rückgang', (v) => `${prozent1.format(v)} %`, 'hoch'],
    ['schlechtester', 'Schlechtester Tag', (v) => `${prozent1.format(v)} %`, 'hoch'],
  ];
  el('b-kennzahlen').innerHTML = `<div class="bk">${metriken.map(([feld, titel, fmt, besser]) => {
    const werte = schluessel.filter((s) => k[s]).map((s) => ({ s, v: k[s][feld] }));
    if (!werte.length) return '';
    const bester = werte.reduce((a, b) => ((besser === 'hoch' ? b.v > a.v : b.v < a.v) ? b : a));
    const groesste = Math.max(...werte.map((w) => Math.abs(w.v))) || 1;
    return `<div class="bk-gruppe"><h3>${titel}</h3>${werte.map(({ s, v }) => {
      const breite = (Math.abs(v) / groesste) * 50;
      return `<div class="bk-zeile ${s === bester.s ? 'bester' : ''}"><span class="bk-name ${klassen[s]}"><i></i>${esc(benchDaten.namen[s])}</span>
        <span class="bk-spur"><i class="bk-balken ${klassen[s]}" style="${v >= 0 ? `left:50%;width:${breite}%` : `left:${50 - breite}%;width:${breite}%`}"></i></span>
        <span class="bk-wert">${fmt(v)}</span></div>`;
    }).join('')}</div>`;
  }).join('')}</div>`;

  // Monat für Monat: Depot gegen MSCI World.
  const monate = [];
  teil.forEach((q, i) => {
    const m = q.d.slice(0, 7);
    if (!monate.length || monate.at(-1).m !== m) monate.push({ m, start: i > 0 ? i - 1 : 0, ende: i });
    else monate.at(-1).ende = i;
  });
  const zeilen = monate.map(({ m, start, ende }) => {
    const r = (s) => (roh[s][start] && roh[s][ende] ? (roh[s][ende] / roh[s][start] - 1) * 100 : null);
    return { m, depot: r('depot'), welt: r('welt') };
  }).filter((z) => z.depot !== null && z.welt !== null);
  const geschlagen = zeilen.filter((z) => z.depot > z.welt).length;
  el('b-monate-unter').textContent = `Du hast ${geschlagen} von ${zeilen.length} Monaten besser abgeschnitten als der MSCI World.`;
  const groesste = Math.max(1, ...zeilen.flatMap((z) => [Math.abs(z.depot), Math.abs(z.welt)]));
  const balken = (v, kl) => { const b = (Math.abs(v) / groesste) * 50; return `<i class="bm-balken ${kl}" style="${v >= 0 ? `left:50%;width:${b}%` : `left:${50 - b}%;width:${b}%`}"></i>`; };
  el('b-monate').innerHTML = `<div class="bm">${zeilen.map((z) => `<div class="bm-zeile ${z.depot > z.welt ? 'vorn' : 'hinten'}" ${tipAttr(lokal(`${z.m}-01`).toLocaleDateString('de-DE', { month: 'long', year: 'numeric' }), `Dein Depot ${prozent1.format(z.depot)} %`, `MSCI World ${prozent1.format(z.welt)} %`, `${z.depot > z.welt ? 'Vorsprung' : 'Rückstand'} ${prozent1.format(z.depot - z.welt)} Prozentpunkte`)}>
      <span class="bm-monat">${lokal(`${z.m}-01`).toLocaleDateString('de-DE', { month: 'short', year: '2-digit' })}</span>
      <span class="bm-spur">${balken(z.depot, 'lc-depot')}${balken(z.welt, 'lc-welt')}</span>
      <span class="bm-diff">${prozent1.format(z.depot - z.welt)}</span>
    </div>`).join('')}</div>
    <p class="lc-legende"><span class="lc-depot"><i></i>Dein Depot</span><span class="lc-welt"><i></i>MSCI World</span><span>rechts: Differenz in Prozentpunkten</span></p>`;

  // Rückschläge: Abstand zum letzten Hoch für alle drei.
  const unterWasser = (werte) => { let hoch = null; return werte.map((v) => { if (v === null) return null; hoch = hoch === null ? v : Math.max(hoch, v); return (v / hoch - 1) * 100; }); };
  linienChart(el('b-dd'), { daten: tage, serien: schluessel.map((s) => ({ name: benchDaten.namen[s], klasse: klassen[s], werte: unterWasser(roh[s]) })), hoehe: 260 });
}

async function ladeBenchmark() {
  let d;
  try {
    d = await api(mwPfad('benchmark', '/api/benchmark'));
  } catch {
    d = { fehler: 'Der Benchmark-Vergleich konnte nicht geladen werden. Läuft der Server noch?' };
  }
  if (d.fehler) {
    if (!benchDaten) el('b-status').textContent = d.fehler;
    return;
  }
  benchDaten = d;
  el('b-status').textContent = `Daten seit ${lokal(d.punkte[0].d).toLocaleDateString('de-DE')} (dein erster Kauf), letzter Stand ${lokal(d.punkte.at(-1).d).toLocaleDateString('de-DE')}`;
  zeichneBenchmark();
}

el('b-zeitraum').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.zeit === benchZeit)));
el('b-zeitraum').addEventListener('click', (e) => {
  const knopf = e.target.closest('button[data-zeit]');
  if (!knopf) return;
  benchZeit = knopf.dataset.zeit;
  benchVon = benchBis = null;
  try { localStorage.setItem('benchZeit', benchZeit); } catch {}
  el('b-zeitraum').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b === knopf)));
  zeichneBenchmark();
});
for (const [feld, setzen] of [['b-von', (v) => { benchVon = v; }], ['b-bis', (v) => { benchBis = v; }]]) {
  el(feld).addEventListener('change', (e) => {
    if (!e.target.value) return;
    setzen(e.target.value);
    benchVon ??= el('b-von').value; benchBis ??= el('b-bis').value;
    el('b-zeitraum').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', 'false'));
    zeichneBenchmark();
  });
}
// Bei geänderter Fenstergröße neu zeichnen, damit die Charts die Breite nutzen.
let neuZeichnen = null;
window.addEventListener('resize', () => { clearTimeout(neuZeichnen); neuZeichnen = setTimeout(() => { zeichneRisiko(); zeichneBenchmark(); zeichneStresstest(); zeichneMakroSens(); zeichnePrognosen(); }, 150); });

// ---- Stresstest: das heutige Depot in früheren Krisen ----
let stressDaten = null;
let stressWahl = 0;
let stressEigen = null; // { von, bis } für den eigenen Zeitraum
// Was-wäre-wenn: Faktor je Ticker (1 = wie heute) und wohin das umgeschichtete Geld geht.
const wwFaktor = {};
let wwZiel = 'bar';
const euro0 = new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR', maximumFractionDigits: 0, signDisplay: 'exceptZero' });
const datumDe = (iso) => lokal(iso).toLocaleDateString('de-DE');
const kzKarte = (titel, wert, text, klasse_ = '') => `<article class="karte r-kz"><h2>${titel}</h2><p class="kennzahl ${klasse_}">${wert}</p><p class="sekundaer">${text}</p></article>`;

function zeichneStresstest() {
  const d = stressDaten;
  if (!d || el('seite-stresstest').hidden) return;
  const liste = d.szenarien;
  stressWahl = Math.min(stressWahl, liste.length - 1);

  el('st-alle').innerHTML = balkenDiagramm(
    liste.map((s, i) => ({
      label: s.name, wert: s.depot_prozent, thema: i,
      titel: `${s.name} (${datumDe(s.von)} bis ${datumDe(s.bis)}): Depot ${prozentText(s.depot_prozent)} (${euro0.format(s.depot_eur)}), MSCI World ${prozentText(s.markt_prozent)}`,
    })),
    [],
  );
  el('st-wahl').innerHTML = liste.map((s, i) => `<button type="button" data-i="${i}" aria-pressed="${i === stressWahl}">${esc(s.name)}</button>`).join('');
  setzePille(el('st-wahl'), true);

  const s = liste[stressWahl];
  if (!s) return;
  const abstand = Math.abs(s.depot_prozent - s.markt_prozent);
  const vergleich = abstand < 1 ? 'etwa so viel wie' : `${zahl2.format(abstand)} Prozentpunkte ${s.depot_prozent < s.markt_prozent ? 'schlechter' : 'besser'} als`;
  el('st-text').textContent = `${s.name}, ${datumDe(s.von)} bis ${datumDe(s.bis)}: ${s.beschreibung} Dein heutiges Depot hätte ${prozentText(s.depot_prozent)} gemacht, ${vergleich} der MSCI World.`;
  const schlimmste = s.positionen[0];
  el('st-kennzahlen').innerHTML = [
    kzKarte('Verlust am Ende', euro0.format(s.depot_eur), `${prozentText(s.depot_prozent)} von heute ${euro.format(d.depotwert)}`, klasse(s.depot_eur)),
    kzKarte('Tiefster Punkt', euro0.format(s.depot_tief_eur), `${prozentText(s.depot_tief_prozent)}, schlechtester Stand während der Phase`, klasse(s.depot_tief_eur)),
    kzKarte('MSCI World', prozentText(s.markt_prozent), 'Der Weltmarkt im selben Zeitraum, zum Vergleich', klasse(s.markt_prozent)),
    schlimmste ? kzKarte('Härtester Treffer', esc(schlimmste.name), `${euro0.format(schlimmste.eur)} (${prozentText(schlimmste.prozent)})${schlimmste.geschaetzt ? ', geschätzt' : ''}`) : '',
  ].join('');
  const ww = wasWaereWenn(s);
  linienChart(el('st-linie'), {
    daten: s.tage,
    serien: [
      { name: 'Dein Depot', klasse: 'lc-depot', werte: s.depot_verlauf },
      ...(ww ? [{ name: 'Was-wäre-wenn', klasse: 'lc-gold', werte: ww.verlauf }] : []),
      { name: 'MSCI World', klasse: 'lc-welt', werte: s.markt_verlauf },
    ],
    hoehe: 260,
  });
  zeichneWasWaereWenn(d);
  const abstand_ = s.depot_prozent - s.markt_prozent;
  const pp = new Intl.NumberFormat('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2, signDisplay: 'exceptZero' });
  const treiber = s.positionen.filter((p) => Math.sign(p.abstand_pp) === Math.sign(abstand_)).sort((a, b) => Math.abs(b.abstand_pp) - Math.abs(a.abstand_pp));
  const top = treiber.slice(0, 2).map((p) => `${p.name} ${pp.format(p.abstand_pp)}`).join(', ');
  el('st-abstand-unter').textContent = `${abstand_ < 0 ? 'Mehrverlust' : 'Vorsprung'} gegenüber dem MSCI World: ${pp.format(abstand_)} Prozentpunkte.${top ? ` Am meisten trägt bei: ${top}.` : ''} Links macht eine Position dein Depot schlechter als den Markt, rechts besser. Gerechnet als Gewicht mal (eigene Bewegung minus Markt); alle Balken zusammen ergeben den Abstand.`;
  el('st-abstand').innerHTML = balkenDiagramm(
    s.positionen.map((p) => ({
      label: `${p.ticker}${p.geschaetzt ? ' ≈' : ''}`, wert: p.abstand_pp, link: p.ticker, text: `${pp.format(p.abstand_pp)} Pkt.`,
      titel: `${p.name}: ${pp.format(p.abstand_pp)} Prozentpunkte. Eigene Bewegung ${prozentText(p.prozent)} gegen MSCI World ${prozentText(s.markt_prozent)}, bei ${zahl2.format(p.gewicht)} % Gewicht.`,
    })),
    [],
  );
  el('st-pos-unter').textContent = `Veränderung je Position bis zum Ende der Phase.${s.geschaetzt.length ? ` Mit ≈ geschätzt über das Beta, weil es damals noch keine Kurse gab: ${s.geschaetzt.join(', ')}.` : ''}`;
  el('st-positionen').innerHTML = balkenDiagramm(
    s.positionen.map((p) => ({
      label: `${p.ticker}${p.geschaetzt ? ' ≈' : ''}`, wert: p.prozent, link: p.ticker,
      titel: `${p.name}: ${prozentText(p.prozent)} = ${euro0.format(p.eur)} bei heute ${zahl2.format(p.gewicht)} % Gewicht. Tiefster Stand ${prozentText(p.tief_prozent)}.${p.geschaetzt ? ` Geschätzt: Marktbewegung mal Beta ${p.beta === null ? '1 (unbekannt)' : zahl2.format(p.beta)}.` : ''}`,
    })),
    [{ name: 'Depot', wert: s.depot_prozent, art: 'schnitt' }, { name: 'MSCI World', wert: s.markt_prozent }],
  );
}

// Rechnet eine Krise mit geänderten Gewichten durch. Verkaufte Teile gehen ins Ziel (Bargeld,
// MSCI World oder eine andere Position), Aufstockungen werden von dort genommen. Ohne Änderung: null.
function wasWaereWenn(s) {
  if (s.positionen.some((p) => !Array.isArray(p.verlauf))) return null; // älterer Server, siehe zeichneWasWaereWenn
  const geaendert = s.positionen.some((p) => (wwFaktor[p.ticker] ?? 1) !== 1);
  if (!geaendert) return null;
  const werte = Object.fromEntries(s.positionen.map((p) => [p.ticker, p.wert * (wwFaktor[p.ticker] ?? 1)]));
  const vorher = s.positionen.reduce((n, p) => n + p.wert, 0);
  const umschichtung = vorher - Object.values(werte).reduce((n, w) => n + w, 0);
  let bar = 0, welt = 0;
  if (wwZiel === 'bar') bar = umschichtung;
  else if (wwZiel === 'welt') welt = umschichtung;
  else werte[wwZiel] = (werte[wwZiel] ?? 0) + umschichtung;
  const negativ = Object.values(werte).some((w) => w < -0.5) || welt < -0.5;
  const summe = vorher; // gleich viel Geld wie heute, nur anders verteilt
  const verlauf = s.tage.map((_, t) => {
    let wert = bar + welt * (1 + s.markt_verlauf[t] / 100);
    for (const p of s.positionen) wert += werte[p.ticker] * (1 + p.verlauf[t] / 100);
    return (wert / summe - 1) * 100;
  });
  return { verlauf, ende: verlauf.at(-1), tief: Math.min(...verlauf), summe, negativ, umschichtung };
}

function zeichneWasWaereWenn(d) {
  const s = d.szenarien[stressWahl];
  // Ein Server mit älterem Programmstand liefert die Tagesverläufe je Position noch nicht.
  if (s.positionen.some((p) => !Array.isArray(p.verlauf) || typeof p.wert !== 'number')) {
    el('st-ww-hinweis').textContent = 'Für Was-wäre-wenn bitte Vinter neu starten (start.bat): Der laufende Server hat noch einen älteren Programmstand.';
    el('st-ww-regler').innerHTML = '';
    el('st-ww-regler').dataset.kennung = '';
    el('st-ww-tabelle').innerHTML = '';
    return;
  }
  const feld = el('st-ww-regler');
  // Regler nur neu bauen, wenn sich die Positionen ändern: sonst springt der Fokus beim Ziehen weg.
  const kennung = s.positionen.map((p) => p.ticker).sort().join('|');
  if (feld.dataset.kennung !== kennung) {
    const sortiert = [...s.positionen].sort((a, b) => b.wert - a.wert);
    feld.innerHTML = sortiert.map((p) => `<label class="ww-zeile">
        <span class="ww-name" title="${esc(p.name)}">${esc(p.ticker)}</span>
        <input type="range" min="0" max="200" step="10" value="${Math.round((wwFaktor[p.ticker] ?? 1) * 100)}" data-ticker="${esc(p.ticker)}" aria-label="${esc(p.name)}: Größe in Prozent von heute">
        <span class="ww-wert" data-wert="${esc(p.ticker)}"></span>
      </label>`).join('');
    el('st-ww-ziel').innerHTML = `<option value="bar">Bargeld (0 %)</option><option value="welt">MSCI World</option>${sortiert.map((p) => `<option value="${esc(p.ticker)}">${esc(p.name)}</option>`).join('')}`;
    el('st-ww-ziel').value = wwZiel;
    feld.dataset.kennung = kennung;
  }
  for (const p of s.positionen) {
    const f = wwFaktor[p.ticker] ?? 1;
    const ausgabe = feld.querySelector(`[data-wert="${CSS.escape(p.ticker)}"]`);
    if (ausgabe) ausgabe.textContent = `${Math.round(f * 100)} % · ${euro.format(p.wert * f)}`;
  }
  const ergebnisse = d.szenarien.map((x) => ({ x, ww: wasWaereWenn(x) }));
  const erstes = ergebnisse.find((e) => e.ww)?.ww;
  el('st-ww-hinweis').textContent = !erstes ? 'Zieh an einem Regler: 0 % = ganz verkauft, 200 % = verdoppelt. Alle Krisen rechnen sofort neu.'
    : `${erstes.umschichtung >= 0 ? `${euro.format(erstes.umschichtung)} gehen` : `${euro.format(-erstes.umschichtung)} kommen`} ${erstes.umschichtung >= 0 ? 'nach' : 'aus'} „${el('st-ww-ziel').selectedOptions[0]?.textContent ?? ''}“. Der Depotwert bleibt gleich, nur die Verteilung ändert sich.${erstes.negativ ? ' Achtung: Das Ziel reicht nicht für die Aufstockung, dort entstünde ein Minus.' : ''}`;
  el('st-ww-tabelle').innerHTML = `<div class="ww-reihe ww-kopf"><span>Krise</span><span>Heute</span><span>Was-wäre-wenn</span><span>Unterschied</span></div>${ergebnisse.map(({ x, ww }) => {
    const neu = ww ? ww.ende : x.depot_prozent;
    const diff = neu - x.depot_prozent;
    return `<div class="ww-reihe"><span>${esc(x.name)}</span><span class="${klasse(x.depot_prozent)}">${prozentText(x.depot_prozent)}</span><span class="${klasse(neu)}">${prozentText(neu)}</span><span class="${klasse(diff)}">${ww ? `${prozent1.format(diff)} Pkt. · ${euro0.format(diff / 100 * x.positionen.reduce((n, p) => n + p.wert, 0))}` : '–'}</span></div>`;
  }).join('')}`;
}
el('st-ww-regler').addEventListener('input', (e) => {
  const regler = e.target.closest('input[data-ticker]');
  if (!regler) return;
  wwFaktor[regler.dataset.ticker] = Number(regler.value) / 100;
  zeichneStresstest();
});
el('st-ww-ziel').addEventListener('change', (e) => { wwZiel = e.target.value; zeichneStresstest(); });
el('st-ww-zurueck').addEventListener('click', () => {
  Object.keys(wwFaktor).forEach((k) => delete wwFaktor[k]);
  el('st-ww-regler').querySelectorAll('input').forEach((r) => { r.value = 100; });
  zeichneStresstest();
});

async function ladeStresstest() {
  const pfad = stressEigen ? `/api/stresstest?von=${stressEigen.von}&bis=${stressEigen.bis}` : '/api/stresstest';
  let d;
  try {
    d = await api(pfad);
  } catch {
    d = { fehler: 'Der Stresstest konnte nicht geladen werden. Läuft der Server noch?' };
  }
  if (d.fehler) {
    el('st-status').textContent = d.fehler;
    return;
  }
  const neu = stressDaten?.szenarien.length !== d.szenarien.length;
  stressDaten = d;
  if (stressEigen && neu) stressWahl = d.szenarien.length - 1;
  el('st-status').textContent = [`${d.szenarien.length} Krisen, gerechnet mit deinem heutigen Depot (${euro.format(d.depotwert)})`, ...d.hinweise].join(' · ');
  zeichneStresstest();
}
el('st-alle').addEventListener('click', (e) => {
  const knopf = e.target.closest('[data-thema]');
  if (!knopf) return;
  stressWahl = Number(knopf.dataset.thema);
  zeichneStresstest();
  el('st-wahl').scrollIntoView({ behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'start' });
});
el('st-wahl').addEventListener('click', (e) => {
  const knopf = e.target.closest('button[data-i]');
  if (!knopf) return;
  stressWahl = Number(knopf.dataset.i);
  zeichneStresstest();
});
for (const feld of ['st-von', 'st-bis']) {
  el(feld).max = isoLokal(new Date());
  el(feld).addEventListener('change', () => {
    const von = el('st-von').value, bis = el('st-bis').value;
    if (!von || !bis) return;
    if (von >= bis) { el('st-status').textContent = 'Bitte ein „von“-Datum vor dem „bis“-Datum wählen.'; return; }
    stressEigen = { von, bis };
    stressWahl = Number.MAX_SAFE_INTEGER; // der eigene Zeitraum steht immer am Ende
    el('st-status').textContent = 'Eigener Zeitraum wird berechnet …';
    ladeStresstest();
  });
}

// ---- Makro-Sensitivität: Zins, Öl, Dollar ----
let makroSensDaten = null;
let makroSensJahre = 3;
let makroOhneMarkt = true; // Gesamtmarkt herausrechnen: weniger Rauschen, belastbarere Zahlen
try {
  if (localStorage.getItem('makroSensJahre') === '5') makroSensJahre = 5;
  if (localStorage.getItem('makroOhneMarkt') === 'nein') makroOhneMarkt = false;
} catch {}
const bereichText = (w) => `wahrscheinlich zwischen ${prozentText(w.von)} und ${prozentText(w.bis)}`;
let makroAnsicht = 'themen'; // Themen bündeln mehrere Aktien: weniger Rauschen
try { if (localStorage.getItem('makroAnsicht') === 'werte') makroAnsicht = 'werte'; } catch {}

function zeichneMakroSens() {
  const d = makroSensDaten;
  if (!d || el('seite-makro').hidden) return;
  el('ms-kennzahlen').innerHTML = d.faktoren.map((f) => {
    const w = d.depot[f.schluessel];
    const sicherheit = w.sicher ? 'Statistisch sicher' : 'Statistisch unsicher, kein klarer Zusammenhang';
    const zusatz = d.ohne_markt ? ', zusätzlich zur normalen Marktbewegung' : '';
    return kzKarte(esc(f.frage), euro0.format(w.eur), `${prozentText(w.prozent)} fürs Depot in einer Woche, in der ${esc(f.satz)}${zusatz}; ${bereichText(w)}. ${sicherheit}.`, w.sicher ? klasse(w.eur) : '');
  }).join('');
  const themen = makroAnsicht === 'themen' && d.themen?.length;
  const zeilen = themen ? d.themen : d.positionen;
  el('ms-faktoren').innerHTML = d.faktoren.map((f) => `
    <section class="karte th-karte st-teil" aria-labelledby="ms-${f.schluessel}-titel">
      <div class="th-kopf"><h2 id="ms-${f.schluessel}-titel">${esc(f.frage)}: ${esc(f.name)} ${esc(f.schock_text)}</h2>
        <p class="sekundaer">So hat sich ${themen ? 'jedes deiner Themen' : 'jede Position'} in einer solchen Woche im Schnitt bewegt${d.ohne_markt ? ', über die normale Marktbewegung hinaus' : ''}. Rechts profitiert ${themen ? 'es' : 'sie'}, links leidet ${themen ? 'es' : 'sie'}. Die feine Linie zeigt den wahrscheinlichen Bereich, blass = statistisch unsicher.</p></div>
      <div class="r-grafik">${balkenDiagramm(
        zeilen.map((p) => {
          const w = p.wirkung[f.schluessel];
          const wer = themen ? `${p.name} (${zahl2.format(p.gewicht)} % deines Depots: ${p.mitglieder.join(', ')})` : p.name;
          return {
            label: themen ? p.name : p.ticker, wert: w.prozent, link: p.ticker, statisch: themen, alarm: w.sicher ? undefined : 'unsicher', spanne: [w.von, w.bis],
            titel: `${wer}: ${prozentText(w.prozent)} (${euro0.format(w.eur)}) bei ${f.name} ${f.schock_text}, ${bereichText(w)}. t-Wert ${zahl2.format(w.t)}${w.sicher ? '' : ', also unsicher'}.${p.beta !== null ? ` Markt-Beta ${zahl2.format(p.beta)}.` : ''} Die Rechnung erklärt ${Math.round(p.r2 * 100)} % der Wochenschwankung.`,
          };
        }),
        [{ name: 'Depot', wert: d.depot[f.schluessel].prozent, art: 'schnitt' }],
      )}</div>
    </section>`).join('');
}

async function ladeMakroSens() {
  const jahre = makroSensJahre;
  let d;
  try {
    d = await api(mwPfad('makro', `/api/makro-sensitivitaet?jahre=${jahre}&ohne_markt=${makroOhneMarkt}`));
  } catch {
    d = { fehler: 'Die Makro-Sensitivität konnte nicht geladen werden. Läuft der Server noch?' };
  }
  if (jahre !== makroSensJahre || (!d.fehler && d.ohne_markt !== makroOhneMarkt)) return;
  if (d.fehler) {
    el('ms-status').textContent = d.fehler;
    return;
  }
  makroSensDaten = d;
  const sicher = d.positionen.reduce((n, p) => n + Object.values(p.wirkung).filter((w) => w.sicher).length, 0);
  el('ms-status').textContent = [
    `${d.zeitraum.wochen} Wochen (${datumDe(d.zeitraum.von)} bis ${datumDe(d.zeitraum.bis)}), ${d.positionen.length} Positionen`,
    `${sicher} von ${d.positionen.length * d.faktoren.length} Zusammenhängen statistisch sicher`,
    d.ohne_daten.length ? `zu kurze Kurshistorie: ${d.ohne_daten.join(', ')}` : '',
  ].filter(Boolean).join(' · ');
  zeichneMakroSens();
}
el('ms-jahre').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(Number(b.dataset.jahre) === makroSensJahre)));
el('ms-markt').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String((b.dataset.markt === 'ohne') === makroOhneMarkt)));
el('ms-ansicht').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.ansicht === makroAnsicht)));
el('ms-ansicht').addEventListener('click', (e) => {
  const knopf = e.target.closest('button[data-ansicht]');
  if (!knopf || knopf.dataset.ansicht === makroAnsicht) return;
  makroAnsicht = knopf.dataset.ansicht;
  try { localStorage.setItem('makroAnsicht', makroAnsicht); } catch {}
  el('ms-ansicht').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b === knopf)));
  zeichneMakroSens();
});
el('ms-markt').addEventListener('click', (e) => {
  const knopf = e.target.closest('button[data-markt]');
  if (!knopf || (knopf.dataset.markt === 'ohne') === makroOhneMarkt) return;
  makroOhneMarkt = knopf.dataset.markt === 'ohne';
  try { localStorage.setItem('makroOhneMarkt', makroOhneMarkt ? 'ja' : 'nein'); } catch {}
  el('ms-markt').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b === knopf)));
  el('ms-status').textContent = 'Wird berechnet …';
  ladeMakroSens();
});
el('ms-jahre').addEventListener('click', (e) => {
  const knopf = e.target.closest('button[data-jahre]');
  if (!knopf || Number(knopf.dataset.jahre) === makroSensJahre) return;
  makroSensJahre = Number(knopf.dataset.jahre);
  try { localStorage.setItem('makroSensJahre', String(makroSensJahre)); } catch {}
  el('ms-jahre').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b === knopf)));
  el('ms-status').textContent = 'Wird berechnet …';
  ladeMakroSens();
});

// ---- Earnings-Moves: Kursreaktionen an den letzten Zahlen ----
let emDaten = null;
const tagMonatJahr = (iso) => lokal(iso).toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: '2-digit' });
const bisDahin = (iso) => {
  const tage = Math.round((lokal(iso) - lokal(isoLokal(new Date()))) / 864e5);
  return tage === 0 ? 'heute' : tage === 1 ? 'morgen' : `in ${tage} Tagen`;
};

function zeichneEarningsMoves() {
  const d = emDaten;
  if (!d || el('seite-earnings-moves').hidden) return;
  const bald = d.werte.filter((z) => z.naechster && (lokal(z.naechster.datum) - new Date()) / 864e5 <= 30);
  el('em-kennzahlen').innerHTML = bald.slice(0, 4).map((z) => {
    const e = z.erwartet?.prozent;
    const vergleich = e == null ? '' : e > z.schnitt_betrag * 1.15 ? ' Optionen erwarten mehr als üblich.' : e < z.schnitt_betrag * 0.85 ? ' Optionen erwarten weniger als üblich.' : ' Etwa so viel wie üblich.';
    return kzKarte(`${esc(z.name)} · ${bisDahin(z.naechster.datum)}`, e == null ? `±${zahl2.format(z.schnitt_betrag)} %` : `±${zahl2.format(e)} %`,
      e == null ? `Zahlen am ${datumDe(z.naechster.datum)}. Im Schnitt der letzten ${z.reaktionen.length} Termine bewegte sich die Aktie so stark.`
        : `Zahlen am ${datumDe(z.naechster.datum)}. So viel Bewegung preist der Optionsmarkt ein; historisch im Schnitt ±${zahl2.format(z.schnitt_betrag)} %.${vergleich}`);
  }).join('') || '<p class="sekundaer">In den nächsten 30 Tagen hat keine deiner Aktien Quartalszahlen.</p>';

  // Ab 20 % ist der Balken voll: Einzelne Ausreißer sollen die übrigen nicht platt drücken.
  const groesste = Math.min(20, Math.max(5, ...d.werte.flatMap((z) => z.reaktionen.map((r) => Math.abs(r.prozent)))));
  const balken = (r) => {
    const h = Math.min(1, Math.abs(r.prozent) / groesste) * 50;
    const ueber = r.eps_ueberraschung == null ? '' : `, Gewinn je Aktie ${prozentText(r.eps_ueberraschung)} gegenüber der Erwartung`;
    return `<span class="em-platz" title="${esc(`${datumDe(r.datum)} (${r.zeitpunkt === 'fenster' ? 'Uhrzeit unbekannt, Zwei-Tage-Fenster' : r.zeitpunkt}): ${prozentText(r.prozent)}${ueber}`)}"><i class="em-b ${r.prozent >= 0 ? 'plus' : 'minus'}" style="height:${Math.max(h, 1.5)}%;${r.prozent >= 0 ? 'bottom' : 'top'}:50%"></i></span>`;
  };
  el('em-liste').innerHTML = `<div class="em-zeile em-kopf"><span>Aktie</span><span>Letzte Zahlen (alt → neu)</span><span>Ø Ausschlag</span><span>Größter</span><span>Hoch / runter</span><span>Nächste Zahlen</span></div>${d.werte.map((z) => {
    const n = z.naechster;
    const e = z.erwartet?.prozent;
    const naechste = !n ? '–' : `${tagMonatJahr(n.datum)}<small>${e != null ? `Optionen ±${zahl2.format(e)} %` : (lokal(n.datum) - new Date()) / 864e5 <= d.optionen_ab_tage && !z.ticker.includes('.') ? 'Optionen: keine Daten' : bisDahin(n.datum)}</small>`;
    return `<a class="em-zeile" href="${esc(yahooLink(z.ticker))}" target="_blank" rel="noopener" title="${esc(`${z.name}: Kursreaktion an den letzten ${z.reaktionen.length} Quartalszahlen. Chart bei Yahoo öffnen.`)}">
      <span class="em-name"><b>${esc(z.ticker)}</b><small>${esc(z.name)}</small></span>
      <span class="em-balken">${z.reaktionen.map(balken).join('')}</span>
      <span>±${zahl2.format(z.schnitt_betrag)} %</span>
      <span class="${klasse(z.max)}">${prozentText(z.max)}</span>
      <span>${z.hoch} / ${z.runter}</span>
      <span class="em-naechste">${naechste}</span>
    </a>`;
  }).join('')}`;
}

// Punkt 35: Earnings-Barometer der laufenden Saison, über den eigenen Earnings-Moves
async function ladeBarometer() {
  const box = el('em-barometer');
  if (box.dataset.fertig) return;
  box.innerHTML = '<p class="sekundaer">Barometer wird berechnet … Beim ersten Mal lädt Vinter den Earnings-Kalender der letzten 15 Monate.</p>';
  let d;
  try { d = await api('/api/earnings-barometer'); } catch { d = { fehler: 'Der Server antwortet gerade nicht.' }; }
  if (d.fehler) { box.innerHTML = ggFehler(d); delete antworten['/api/earnings-barometer']; return; }
  box.dataset.fertig = '1';
  const s = d.saisons, jetzt = s[0], frueher = s.slice(1).filter((x) => x.vollstaendig);
  const mittel = (k, f) => { const w = frueher.map((x) => x[k]?.schnitt ?? (typeof x[k] === 'number' ? x[k] : null)).filter((v) => v !== null && v !== undefined); return w.length ? w.reduce((a, b) => a + b, 0) / w.length : null; };
  const fs = mittel('schlagen'), fv = mittel('verfehlen');
  const satz = `In der laufenden Saison (${jetzt.name}, ${jetzt.n} Meldungen im S&P 500) übertreffen <b>${jetzt.anteil_schlagen} %</b> die Erwartungen. Danach liegen sie im Schnitt <b class="${klasse(jetzt.schlagen.schnitt)}">${ggPz(jetzt.schlagen.schnitt, gz1)}</b> vor dem Markt${fs !== null ? ` (frühere Saisons ${ggPz(fs, gz1)})` : ''}, wer verfehlt, <b class="${klasse(jetzt.verfehlen.schnitt)}">${ggPz(jetzt.verfehlen.schnitt, gz1)}</b>${fv !== null ? ` (früher ${ggPz(fv, gz1)})` : ''}. ${fs !== null && jetzt.schlagen.schnitt < fs - 0.5 ? 'Gute Zahlen werden diese Saison weniger belohnt als sonst: Die Erwartungen sind hoch.' : fs !== null && jetzt.schlagen.schnitt > fs + 0.5 ? 'Gute Zahlen werden diese Saison stärker belohnt als sonst.' : ''}`;
  const zeile = (x) => `<tr class="${x === jetzt ? 'gg-aktiv' : ''}"><td>${esc(x.name)}${x === jetzt ? ' <small>läuft</small>' : x.vollstaendig ? '' : ' <small>unvollständig</small>'}</td><td>${x.n}</td><td>${x.anteil_schlagen} %</td>
    <td class="${klasse(x.schlagen.schnitt)}">${ggPz(x.schlagen.schnitt, gz1)} <small>${x.schlagen.steigt ?? '–'} % steigen</small></td>
    <td class="${klasse(x.verfehlen.schnitt)}">${ggPz(x.verfehlen.schnitt, gz1)} <small>${x.verfehlen.steigt ?? '–'} % steigen</small></td><td>±${gz1.format(x.ausschlag)} %</td></tr>`;
  const liste = (l) => (l.length ? `<ul class="em-b-liste">${l.map((x) => `<li><span>${esc(x.name)} <small>${esc(x.ticker)} · ${ggDatum(x.tag)}</small></span><span>Überraschung ${ggPz(x.ueberraschung, gz0)}</span><b class="${klasse(x.reaktion)}">${ggPz(x.reaktion, gz1)}</b></li>`).join('')}</ul>` : '<p class="klein">Keine.</p>');
  box.innerHTML = ggKarte('em-baro', 'Earnings-Barometer der Saison', [
    ['Was es zeigt', 'Wie Aktien des S&P 500 auf ihre Quartalszahlen reagieren, getrennt nach übertroffenen (Überraschung beim Gewinn je Aktie ab +1 %) und verfehlten Erwartungen (ab −1 %), je Berichtssaison.'],
    ['Rechnung', 'Kurs am Handelstag nach dem Termin gegen den Tag davor (so zählen Meldungen vor und nach Börsenschluss gleich), abzüglich der Bewegung aller S&P-500-Werte im selben Fenster. Überraschung und Termine vom Earnings-Kalender von nasdaq.com.'],
    ['Lesart', 'Werden gute Zahlen kaum noch belohnt, ist viel Optimismus schon im Kurs. Werden schlechte Zahlen kaum bestraft, war die Stimmung schon schlecht. Ausschlag: durchschnittliche Bewegung egal in welche Richtung.'],
  ], `${ggLage(satz)}${ggTabelle(['Saison', 'Meldungen', 'Übertroffen', 'Reaktion übertroffen', 'Reaktion verfehlt', 'Ø Ausschlag'], s.map(zeile), 'gg-uebersicht')}
    <div class="em-b-zwei"><div><h3 class="gg-h3">Übertroffen und trotzdem gefallen</h3>${liste(d.geschlagen_gefallen)}</div><div><h3 class="gg-h3">Verfehlt und trotzdem gestiegen</h3>${liste(d.verfehlt_gestiegen)}</div></div>`, `Stand ${ggDatum(d.stand)}`);
}

async function ladeEarningsMoves() {
  let d;
  try {
    d = await api(mwPfad('earnings-moves', '/api/earnings-moves'));
  } catch {
    d = { fehler: 'Die Earnings-Moves konnten nicht geladen werden. Läuft der Server noch?' };
  }
  if (d.fehler) {
    el('em-status').textContent = d.fehler;
    return;
  }
  emDaten = d;
  el('em-status').textContent = [`${d.werte.length} Aktien, je bis zu 8 Quartalszahlen`, d.ohne_daten.length ? `ohne Termine bei Yahoo: ${d.ohne_daten.join(', ')}` : ''].filter(Boolean).join(' · ');
  zeichneEarningsMoves();
}

// ---- Prognosen: Fed-Wahrscheinlichkeiten aus Futures und ausgewählte Prognosemärkte ----
let prognosenDaten = null;
let prognosenThemen = null;
let prognosenSuche = null; // { begriff, treffer } solange gesucht wird
const pgOffen = new Set();  // Themen-Blöcke, in denen "Mehr" geklickt wurde
const pkt = new Intl.NumberFormat('de-DE', { maximumFractionDigits: 1, signDisplay: 'exceptZero' });
// Die FedWatch-Methode kennt nur zwei benachbarte Schritte. Ganz oben und unten wird es deshalb zu glatt.
const pz = (p) => (p == null ? '–' : p >= 0.985 ? '≈ 100 %' : p <= 0.015 ? '≈ 0 %' : `${Math.round(p * 100)} %`);
const pzMarkt = (p) => (p == null ? '–' : `${Math.round(p * 100)} %`);
// Vergleich mit den großen Echtgeld-Märkten: nur als Link, Vinter liest dort nichts aus (deren Bedingungen).
const vergleichLink = (frage) => `https://www.google.com/search?q=${encodeURIComponent(`${frage} site:polymarket.com OR site:kalshi.com`)}`;

function veraenderung(v, name) {
  return v?.[name] == null ? '<span class="pg-leer">–</span>' : `<span class="${klasse(v[name])}">${pkt.format(v[name])}</span>`;
}

let pgVerlaufSitzung = null;
// Verlauf der Fed-Wahrscheinlichkeiten je Sitzung (M4): täglich gespeichert, seit der letzten Sitzung nachgerechnet
function zeichneFedVerlauf(fed) {
  const box = el('pg-fed-verlauf');
  if (!box) return;
  const mit = fed.sitzungen.filter((s) => s.verlauf?.tage?.length > 1);
  if (!mit.length) { box.innerHTML = '<p class="sekundaer">Der Verlauf entsteht ab heute: Vinter speichert die Wahrscheinlichkeiten jeden Tag.</p>'; return; }
  if (!mit.some((s) => s.datum === pgVerlaufSitzung)) pgVerlaufSitzung = mit[0].datum;
  const s = mit.find((x) => x.datum === pgVerlaufSitzung), v = s.verlauf;
  const halten = v.tage.map((_, i) => (v.erhoehung[i] === null || v.senkung[i] === null ? null : Math.max(0, 1 - v.erhoehung[i] - v.senkung[i]) * 100));
  const vorher = v.erhoehung.find((x) => x !== null), jetzt = [...v.erhoehung].reverse().find((x) => x !== null);
  box.innerHTML = `${ggKnoepfe('pg-verlauf', mit.map((x) => [x.datum, `Sitzung ${datumDe(x.datum)}`]), pgVerlaufSitzung)}
    <p class="sekundaer klein">Erhöhung am ${datumDe(v.tage[0])}: ${pz(vorher)}, heute ${pz(jetzt)} (${pkt.format((jetzt - vorher) * 100)} Pkt.). Tage vor dem ersten eigenen Speichern sind aus den Schlusskursen der noch laufenden Futures nachgerechnet (Yahoo hat abgelaufene Kontrakte nicht mehr).</p>
    <div class="r-grafik" id="pg-verlauf-chart"></div>`;
  linienChart(el('pg-verlauf-chart'), { daten: v.tage, hoehe: 200, nullpunkt: true, format: (x) => `${gz0.format(x)} %`, serien: [
    { name: 'Erhöhung', klasse: 'lc-x2', werte: v.erhoehung.map((x) => (x === null ? null : x * 100)) },
    { name: 'Unverändert', klasse: 'lc-grau', werte: halten },
    { name: 'Senkung', klasse: 'lc-depot', werte: v.senkung.map((x) => (x === null ? null : x * 100)) }] });
  ggFilterKlick(box, 'pg-verlauf', (w) => { pgVerlaufSitzung = w; zeichneFedVerlauf(fed); });
}
function zeichneFed(fed) {
  if (fed?.fehler) { el('pg-fed').innerHTML = `<p class="sekundaer">${esc(fed.fehler)}</p>`; return; }
  el('pg-fed-unter').textContent = `Heute: Tagesgeld ${zahl2.format(fed.tagesgeld.satz)} %, Zielspanne ${zahl2.format(fed.tagesgeld.von)} bis ${zahl2.format(fed.tagesgeld.bis)} % (New York Fed, ${datumDe(fed.tagesgeld.stand)}). Selbst gerechnet aus Fed-Funds-Futures der CME, einem der größten Zinsmärkte der Welt.`;
  el('pg-fed').innerHTML = fed.sitzungen.map((s) => {
    const teile = [['senkung', s.senkung, 'Senkung'], ['halten', s.halten, 'Unverändert'], ['erhoehung', s.erhoehung, 'Erhöhung']];
    const balken = teile.map(([k, p, n]) => (p > 0.005 ? `<i class="pg-teil ${k}" style="width:${p * 100}%" title="${n}: ${pz(p)}"></i>` : '')).join('');
    const groesster = [...teile].sort((a, b) => b[1] - a[1])[0];
    const schritte = s.diese_sitzung.filter((x) => x.p > 0.005).map((x) => `${x.aenderung_bp === 0 ? 'unverändert' : `${x.aenderung_bp > 0 ? '+' : '−'}${(Math.abs(x.aenderung_bp) / 100).toLocaleString('de-DE', { minimumFractionDigits: 2 })}`} ${pz(x.p)}`).join(' · ');
    const glatt = Math.max(s.erhoehung, s.senkung, s.halten) >= 0.985
      ? '<p class="pg-fussnote">„≈ 100 %“: Die Rechnung verteilt die Wahrscheinlichkeit nur auf zwei benachbarte Schritte. Echtgeld-Märkte sehen meist noch ein paar Prozent für die übrigen Ausgänge.</p>' : '';
    return `<article class="pg-sitzung">
      <p class="pg-kopf">${datumDe(s.datum)} · ${bisDahin(s.datum)}</p>
      <p class="pg-haupt">${groesster[2]} <b>${pz(groesster[1])}</b></p>
      <div class="pg-leiste" aria-hidden="true">${balken}</div>
      <p class="pg-schritte">${esc(schritte)}</p>
      <p class="pg-schritte">Zielspanne danach: ${s.zielspanne.map((z) => `${zahl2.format(z.von)}–${zahl2.format(z.bis)} % (${pz(z.p)})`).join(', ')}</p>
      <p class="pg-schritte">Erhöhung seit gestern ${veraenderung(s.veraenderung_erhoehung, 'tag')} Pkt., 7 Tage ${veraenderung(s.veraenderung_erhoehung, 'woche')} Pkt.</p>
      ${glatt}
    </article>`;
  }).join('') || '<p class="sekundaer">Keine kommenden Fed-Termine in daten/markt/makro_termine.yaml. Trag dort die nächsten Sitzungen ein (Name „Fed-Zinsentscheid“).</p>';
  zeichneFedVerlauf(fed);
  linienChart(el('pg-kurve'), {
    daten: fed.kurve.map((k) => `${k.monat}-01`),
    // Als Veränderung gegenüber heute: So sieht man die Richtung, statt einer flachen Linie bei 4 %.
    serien: [{ name: 'Erwartete Veränderung des Leitzinses gegenüber heute', klasse: 'lc-depot', werte: fed.kurve.map((k) => k.satz - fed.tagesgeld.satz) }],
    format: (v) => `${pkt.format(v)} Pkt. (Zins ${zahl2.format(v + fed.tagesgeld.satz)} %)`, hoehe: 200,
  });
}


// ---- Dein Depot an Fed-Tagen (Prognosen-Seite): Rechnung in app/nutzer/fed_tage.py ----
let ftDaten = null, ftAlle = false;
const FT_NAME = { gesenkt: 'Senkung', gehalten: 'Unverändert', erhöht: 'Erhöhung' };
const ftPz = (v) => (v === null || v === undefined ? '–' : `<span class="${klasse(v)}">${ggPz(v * 100, zahl2)}</span>`);
const ftSchritt = (z) => (z.schritt_bp ? `${z.schritt_bp > 0 ? '+' : '−'}${zahl2.format(Math.abs(z.schritt_bp) / 100)}` : '±0');

async function ladeFedTage() {
  el('pg-fedtage').innerHTML = '<section class="karte th-karte"><p class="sekundaer">Dein Depot an Fed-Tagen wird gerechnet …</p></section>';
  try { ftDaten = await api('/api/prognosen/fed-tage'); } catch { ftDaten = { fehler: 'Die Fed-Tage konnten nicht geladen werden.' }; }
  zeichneFedTage();
}

function zeichneFedTage() {
  const d = ftDaten;
  if (!d || d.fehler) { el('pg-fedtage').innerHTML = `<section class="karte th-karte">${ggFehler(d)}</section>`; return; }
  const a = d.depot.alle, sp = d.sp500.alle;
  // Nächste Sitzung: wahrscheinlichster Ausgang laut Futures
  const naechste = prognosenDaten?.fed?.sitzungen?.[0];
  let ausblick = '';
  if (naechste) {
    const [art, p] = [['gesenkt', naechste.senkung], ['gehalten', naechste.halten], ['erhöht', naechste.erhoehung]].sort((x, y) => y[1] - x[1])[0];
    const g = d.depot[art];
    if (g) ausblick = ` Nächste Entscheidung am ${datumDe(naechste.datum)}, am wahrscheinlichsten „${FT_NAME[art]}“ (${pz(p)}). Bei ${art === 'gehalten' ? 'unverändertem Zins' : FT_NAME[art] === 'Senkung' ? 'Senkungen' : 'Erhöhungen'} bewegte sich dein Depot bis zum Folgetag im Schnitt um ${ggPz(g.schnitt * 100, zahl2)}, typisch ±${zahl2.format(g.betrag * 100)} % (${g.anzahl} Mal).`;
  }
  const staerker = a.faktor >= 1.15 ? 'stärker als' : a.faktor <= 0.87 ? 'eher ruhiger als' : 'etwa so stark wie';
  const lage = `Dein heutiges Depot bewegte sich an Fed-Tagen bis zum Folgetag typisch um ±${zahl2.format(a.betrag * 100)} %, ${staerker} an normalen zwei Tagen (±${zahl2.format(d.ueblich.depot.folge * 100)} %). Der S&P 500 reagiert deutlicher: ${gz1.format(sp.faktor)}-fach.${ausblick}`;

  const chip = (titel, g, unter) => `<div class="st-chip"><span>${titel}</span><b>${g ? ftPz(g.schnitt) : '–'}</b><small>${g ? `${g.anzahl} Mal · im Plus ${gz0.format(g.plus * 100)} % · ${gz1.format(g.faktor)}-fach bewegt` : ''}${unter ? ` · ${unter}` : ''}</small></div>`;
  const chips = `<div class="st-chips">
    ${chip('Alle Entscheidungen', a)}
    ${chip('Nach Senkungen', d.depot.gesenkt, d.sp500.gesenkt ? `S&P 500 ${ggPz(d.sp500.gesenkt.schnitt * 100, zahl2)}` : '')}
    ${chip('Zins unverändert', d.depot.gehalten, d.sp500.gehalten ? `S&P 500 ${ggPz(d.sp500.gehalten.schnitt * 100, zahl2)}` : '')}
    ${chip('Nach Erhöhungen', d.depot.erhöht, d.sp500.erhöht ? `S&P 500 ${ggPz(d.sp500.erhöht.schnitt * 100, zahl2)}` : '')}
  </div>`;

  const liste = ftAlle ? d.termine : d.termine.slice(0, 12);
  const termine = ggTabelle(['Entscheidung', 'Zins', 'Depot am Tag', 'Depot bis Folgetag', 'S&P 500 am Tag', 'S&P 500 bis Folgetag', 'MSCI World (€)'], liste.map((z) => `<tr>
      <td>${datumDe(z.datum)}${z.notsitzung ? ' <small class="sekundaer">Notsitzung</small>' : ''}</td>
      <td>${FT_NAME[z.entscheidung]} <small class="sekundaer">${ftSchritt(z)}</small></td>
      <td>${ftPz(z.depot_tag)}</td><td><b>${ftPz(z.depot_folge)}</b>${z.abdeckung < 0.9 || z.ohne_zahlen?.length ? `<br><small class="sekundaer">${z.abdeckung < 0.9 ? `${gz0.format(z.abdeckung * 100)} % des Depots` : ''}${z.ohne_zahlen?.length ? `${z.abdeckung < 0.9 ? ' · ' : ''}ohne ${esc(z.ohne_zahlen.join(', '))} (Zahlen)` : ''}</small>` : ''}</td>
      <td>${ftPz(z.sp500_tag)}</td><td>${ftPz(z.sp500_folge)}</td><td>${ftPz(z.welt_folge)}</td></tr>`), 'ft-tabelle')
    + (d.termine.length > 12 ? `<button type="button" class="knopf klein-knopf" id="ft-alle">${ftAlle ? 'Nur die letzten 12' : `Alle ${d.termine.length} Entscheidungen seit ${new Date(d.ab).getFullYear()}`}</button>` : '');

  const werte = ggTabelle(['Position', 'Anteil', 'Ø bis Folgetag', 'Senkung', 'Unverändert', 'Erhöhung', 'Bewegung ggü. normal', 'Größte Reaktion'], d.positionen.map((p) => `<tr>
      <td><b>${esc(p.name)}</b><br><small class="sekundaer">${p.anzahl} Termine${p.ohne_zahlen ? `, ${p.ohne_zahlen} mit Zahlen ausgelassen` : ''}</small></td>
      <td>${gz1.format(p.gewicht)} %</td><td>${ftPz(p.schnitt)}</td><td>${ftPz(p.gesenkt)}</td><td>${ftPz(p.gehalten)}</td><td>${ftPz(p.erhöht)}</td>
      <td class="${p.faktor >= 1.3 ? 'gold' : ''}">${p.faktor ? `${gz1.format(p.faktor)}-fach` : '–'}</td>
      <td>${ftPz(p.groesste.wert)} <small class="sekundaer">${datumDe(p.groesste.datum)}, ${FT_NAME[p.groesste.entscheidung]}</small></td></tr>`), 'ft-tabelle');

  el('pg-fedtage').innerHTML = ggKarte('ft-karte', 'Dein Depot an Fed-Tagen', [
    ['Was hier steht', 'Wie sich dein heutiges Depot (heutige Positionen und Gewichte, in Euro) an allen Zinsentscheidungen der Fed seit 2015 bewegt hätte, auch an den Notsitzungen im März 2020. Termine aus dem offiziellen Kalender der Fed, Entscheidung aus der Zielspanne (FRED).'],
    ['Zwei Fenster', 'Die Fed entscheidet um 20 Uhr deutscher Zeit, Xetra hat dann schon zu. „Am Tag“ = Schluss am Handelstag davor bis Schluss am Entscheidungstag (US-Werte reagieren hier schon), „bis Folgetag“ = bis zum Schluss am Tag danach (da reagieren auch deutsche Werte). Die Hauptzahl ist deshalb „bis Folgetag“.'],
    ['Bewegung ggü. normal', 'Durchschnittlicher Betrag der Bewegung an Fed-Tagen geteilt durch den an gewöhnlichen zwei Handelstagen. 1-fach heißt: Fed-Tage sind für diesen Wert nichts Besonderes; ab 1,3-fach gold.'],
    ['Quartalszahlen', 'Meldet eine Firma im selben Fenster Zahlen, würde das die Fed-Reaktion überdecken. Sie zählt an diesem Termin nicht mit (Termine von Yahoo, etwa 7 Jahre zurück; davor nicht erkennbar).'],
    ['Vorsicht', 'Vergangenheit, keine Vorhersage. Wichtiger als die Entscheidung selbst ist meist, ob sie überrascht hat und was der Fed-Chef danach sagt; das steckt hier mit drin, wird aber nicht getrennt. Bei Senkungen sind es nur 11 Termine, darunter die Corona-Notsenkungen.'],
  ], `${ggLage(lage)}${chips}<h3 class="pg-unter">Je Entscheidung</h3>${termine}<h3 class="pg-unter">Je Position</h3>${werte}`, `seit ${datumDe(d.ab)} · ${d.termine.length} Entscheidungen`);
}
document.addEventListener('click', (e) => {
  if (e.target.id !== 'ft-alle') return;
  ftAlle = !ftAlle;
  zeichneFedTage();
});

function zeichnePrognosen() {
  const d = prognosenDaten;
  if (!d || el('seite-prognosen').hidden) return;
  if (d.fed) zeichneFed(d.fed);
  const z = d.zins_wirkung;
  el('pg-depot').textContent = z
    ? `Zum Einordnen, aus „Zins, Öl, Dollar“: In Wochen, in denen die 10-jährige US-Rendite um 0,25 Prozentpunkte stieg, bewegte sich dein heutiges Depot im Schnitt um ${prozentText(z.prozent)} (${euro0.format(z.eur)}), wahrscheinlich zwischen ${prozentText(z.von)} und ${prozentText(z.bis)}${z.sicher ? '' : ', statistisch unsicher'}. Ein Fed-Schritt bewegt die 10-jährige Rendite meist deutlich weniger; entscheidend ist die Überraschung gegenüber dem, was oben schon eingepreist ist.`
    : '';

  // Deine Prognosen: eine kompakte Liste, eine Zeile je Frage.
  el('pg-eigene').innerHTML = d.eigene.length ? `<div class="pg-zeile pg-tabkopf"><span>Frage</span><span>Wahrscheinlichkeit</span><span>1 Tag</span><span>7 Tage</span><span>Mitwetter</span><span></span></div>${d.eigene.map((m) => {
    const oben = m.art === 'ja_nein' ? { text: 'Ja', p: m.p } : { text: m.antworten?.[0]?.text ?? '', p: m.antworten?.[0]?.p };
    return `<div class="pg-zeile">
      <span class="pg-frage"><a href="${esc(sichererLink(m.link))}" target="_blank" rel="noopener">${esc(m.frage)}</a>
        <small>${m.art === 'ja_nein' ? '' : `Vorn: ${esc(oben.text)} · `}<a href="${esc(vergleichLink(m.frage))}" target="_blank" rel="noopener">Mit Polymarket/Kalshi vergleichen ↗</a>${m.veraltet ? ' · letzter Stand' : ''}</small></span>
      <span class="pg-wkeit"><i style="width:${(oben.p ?? 0) * 100}%"></i><b>${pzMarkt(oben.p)}</b></span>
      <span>${veraenderung(m.veraenderung, 'tag')}</span>
      <span>${veraenderung(m.veraenderung, 'woche')}</span>
      <span class="pg-wetter ${m.wetter < 50 ? 'wenig' : ''}" title="${m.wetter < 50 ? 'Wenige Mitwetter: Zahl eher wackelig' : 'Viele Mitwetter'}">${m.wetter}</span>
      <button type="button" class="w-weg pg-weg" data-id="${esc(m.id)}" aria-label="Nicht mehr verfolgen" title="Nicht mehr verfolgen">×</button>
    </div>`;
  }).join('')}` : '<p class="sekundaer">Du verfolgst noch keine Prognosen. Unten in den Themen auf + klicken.</p>';
  el('pg-meldungen').textContent = d.meldungen.join(' ');
  zeichneEntdecken();
}

// Entdecken: alle Themen als offene Blöcke mit den wichtigsten Fragen, oder die Treffer einer Suche.
function trefferZeile(t, verfolgt) {
  const dabei = verfolgt.has(t.id);
  return `<div class="pg-t">
    <a href="${esc(sichererLink(t.link))}" target="_blank" rel="noopener" title="${esc(t.frage)}">${esc(t.frage)}</a>
    <span class="pg-t-wert">${t.art === 'ja_nein' ? pzMarkt(t.p) : 'Auswahl'}<small>${t.wetter} Wetter</small></span>
    <button type="button" class="pg-plus ${dabei ? 'dabei' : ''}" data-id="${esc(t.id)}" ${dabei ? 'disabled aria-label="Wird schon verfolgt"' : 'aria-label="Verfolgen"'} title="${dabei ? 'Wird schon verfolgt' : 'Verfolgen'}">${dabei ? '✓' : '+'}</button>
  </div>`;
}

function zeichneEntdecken() {
  const verfolgt = new Set((prognosenDaten?.eigene ?? []).map((m) => m.id));
  if (prognosenSuche) {
    el('pg-bloecke').innerHTML = `<section class="pg-block pg-suchblock"><h3>Treffer für „${esc(prognosenSuche.begriff)}“</h3>${
      prognosenSuche.treffer ? (prognosenSuche.treffer.map((t) => trefferZeile(t, verfolgt)).join('') || '<p class="sekundaer">Keine offenen Fragen mit genug Mitwettern gefunden.</p>') : '<p class="sekundaer">Sucht …</p>'}</section>`;
    return;
  }
  if (!prognosenThemen) { el('pg-bloecke').innerHTML = '<p class="sekundaer">Themen werden geladen …</p>'; return; }
  el('pg-bloecke').innerHTML = prognosenThemen.themen.map((th) => {
    const alle = th.treffer;
    const sichtbar = pgOffen.has(th.name) ? alle : alle.slice(0, 4);
    return `<section class="pg-block"><h3>${esc(th.name)}</h3>
      ${sichtbar.map((t) => trefferZeile(t, verfolgt)).join('') || `<p class="sekundaer">${esc(th.fehler ?? 'Gerade nichts Passendes.')}</p>`}
      ${alle.length > 4 ? `<button type="button" class="pg-mehr" data-thema="${esc(th.name)}">${pgOffen.has(th.name) ? 'Weniger' : `${alle.length - 4} weitere`}</button>` : ''}
    </section>`;
  }).join('');
}

async function suchePrognosen(begriff) {
  prognosenSuche = { begriff, treffer: null };
  zeichneEntdecken();
  let d;
  try {
    d = await api(`/api/prognosen/suche?q=${encodeURIComponent(begriff)}`);
  } catch {
    d = { fehler: 'Die Suche hat nicht geklappt. Läuft der Server noch?' };
  }
  if (prognosenSuche?.begriff !== begriff) return; // inzwischen etwas anderes gesucht
  prognosenSuche.treffer = d.treffer ?? [];
  if (d.fehler) el('pg-meldungen').textContent = d.fehler;
  zeichneEntdecken();
}

async function prognoseSenden(methode, pfad, daten) {
  let d;
  try {
    const antwort = await fetch(pfad, { method: methode, headers: { 'X-Vinter': 'prognosen', 'Content-Type': 'application/json' }, body: daten ? JSON.stringify(daten) : undefined });
    d = await antwort.json();
  } catch {
    d = { fehler: 'Das hat nicht geklappt. Läuft der Server noch?' };
  }
  el('pg-meldungen').textContent = d.fehler ?? '';
  if (!d.fehler) { delete antworten['/api/prognosen']; ladePrognosen(); }
}

async function ladePrognosen() {
  let d;
  try {
    d = await api('/api/prognosen');
  } catch {
    d = { fehler: 'Die Prognosen konnten nicht geladen werden. Läuft der Server noch?' };
  }
  if (d.fehler) { el('pg-status').textContent = d.fehler; return; }
  prognosenDaten = d;
  ladeFedTage();
  ladeEzb();
  el('pg-status').textContent = `${d.eigene.length} verfolgte Prognosen · Fed ${d.fed?.fehler ? 'gerade nicht verfügbar' : `${d.fed.sitzungen.length} Sitzungen`}`;
  zeichnePrognosen();
  if (!prognosenThemen) {
    try {
      const t = await api('/api/prognosen/themen');
      if (!t.fehler) { prognosenThemen = t; zeichneEntdecken(); }
    } catch {}
  }
}
let pgWarten;
el('pg-suche').addEventListener('input', (e) => {
  clearTimeout(pgWarten);
  const begriff = e.target.value.trim();
  if (begriff.length < 2) { prognosenSuche = null; zeichneEntdecken(); return; }
  pgWarten = setTimeout(() => suchePrognosen(begriff), 400);
});
el('pg-bloecke').addEventListener('click', (e) => {
  const plus = e.target.closest('.pg-plus');
  if (plus && !plus.disabled) { plus.disabled = true; prognoseSenden('POST', '/api/prognosen', { id: plus.dataset.id }); return; }
  const mehr = e.target.closest('.pg-mehr');
  if (mehr) {
    const name = mehr.dataset.thema;
    if (pgOffen.has(name)) pgOffen.delete(name); else pgOffen.add(name);
    zeichneEntdecken();
  }
});
el('pg-eigene').addEventListener('click', (e) => {
  const knopf = e.target.closest('.pg-weg');
  if (knopf) prognoseSenden('DELETE', `/api/prognosen/${encodeURIComponent(knopf.dataset.id)}`);
});

// ---- Startseite: in jede Kachel eine echte Zahl ----
// Nutzt die Antworten, die die Seite ohnehin lädt; doppelt gefragt wird dadurch nichts.
function kachelWert(id, text, wert = null, name = null) {
  const feld = el(`kw-${id}`);
  if (!feld) return;
  feld.textContent = text;
  feld.className = `k-wert ${wert === null ? '' : klasse(wert)}`;
  if (name !== null && el(`kw-${id}-name`)) el(`kw-${id}-name`).textContent = name;
}
async function fuelleKacheln() {
  const hole = async (pfad) => { try { const d = await api(pfad); return d?.fehler ? null : d; } catch { return null; } };
  const [depot, perioden, verteilungD, frei, maerkte, sektorD, earnings, thesenD] = await Promise.all([
    hole('/api/portfolio'), hole(mitVorboerse('/api/perioden')), hole('/api/verteilung'), hole('/api/freibetrag'), hole('/api/maerkte'),
    hole('/api/sektoren'), hole('/api/earnings'), hole('/api/thesen'),
  ]);
  if (depot?.summen) kachelWert('uebersicht', new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 }).format(depot.summen.wert));
  setzeDepotSatz(perioden?.zeitraeume?.tag);
  const heute = perioden?.zeitraeume?.tag?.gv_prozent;
  if (heute !== null && heute !== undefined) kachelWert('performance', `${prozent.format(heute)} %`, heute);
  const usd = verteilungD?.dimensionen?.find((x) => x.titel === 'Währung')?.teile.find((t) => t.name === 'USD');
  if (usd) kachelWert('verteilung', `${Math.round(usd.anteil)} %`);
  if (frei && frei.anteil !== undefined) kachelWert('freibetrag', `${Math.round(frei.anteil)} %`);
  const sp = maerkte?.gruppen?.flatMap((g) => g.kacheln).find((k) => k.ticker === '^GSPC');
  if (sp?.tag !== null && sp?.tag !== undefined) kachelWert('maerkte', `${prozent.format(sp.tag)} %`, sp.tag);
  const besterSektor = [...(sektorD?.sektoren ?? [])].filter((s) => s.tag !== null && s.tag !== undefined).sort((a, b) => b.tag - a.tag)[0];
  if (besterSektor) kachelWert('sektoren', `${prozent.format(besterSektor.tag)} %`, besterSektor.tag, besterSektor.name);
  const bestesThema = [...(themenDaten?.themen ?? [])].filter((t) => t.schnitt.tag !== null).sort((a, b) => b.schnitt.tag - a.schnitt.tag)[0];
  if (bestesThema) kachelWert('themen', `${prozent.format(bestesThema.schnitt.tag)} %`, bestesThema.schnitt.tag, bestesThema.name);
  const iso = isoLokal(new Date());
  const naechster = (earnings?.termine ?? []).filter((t) => t.eigen && t.datum >= iso).sort((a, b) => a.datum.localeCompare(b.datum))[0];
  if (naechster) kachelWert('kalender', lokal(naechster.datum).toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit' }), null, naechster.name);
  if (thesenD?.thesen) kachelWert('thesen', String(thesenD.thesen.length));
}

// ---- Volatilitätsoberfläche: 3D-Fläche auf einem Canvas, gezeichnet ohne Bibliothek ----
// Jeder Punkt ist eine implizite Volatilität (IV). Der Server liefert ein festes Raster:
// Zeilen = Restlaufzeit in Tagen, Spalten = Strike in % vom Kurs.
const VOLA_TICKER = ['SPY', 'QQQ']; // immer da; dazu deine US-Aktien und jeder US-Wert mit Optionen
const VOLA_ANSICHTEN = ['heute', 'gestern', 'woche', 'monat', 'earnings', 'frei'];
// Name eines gespeicherten Stands: Datum und Uhrzeit (Live) bzw. "Schluss"
const volaStandName = (f) => `${lokal(f.datum).toLocaleDateString('de-DE', { weekday: 'short', day: '2-digit', month: '2-digit' })} ${f.art === 'live' ? `${new Date(f.zeit).toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' })} Uhr` : 'Schluss'}`;
const volaGueltig = (t) => /^[A-Z][A-Z0-9-]{0,9}$/.test(t ?? '');
const VOLA_AUSSCHNITT = { eng: [90, 110], weit: [80, 120] }; // Strike-Bereich der 3D-Fläche
const volaDaten = {};
const volaWahl = { ticker: 'SPY', ansicht: 'heute', form: grobZeiger ? 'karte' : '3d', ausschnitt: 'eng', farbe: 'handel', handel: 'oi' };
try {
  const g = JSON.parse(localStorage.getItem('volaWahl') ?? 'null');
  if (volaGueltig(g?.ticker)) volaWahl.ticker = g.ticker;
  if (VOLA_ANSICHTEN.includes(g?.ansicht)) volaWahl.ansicht = g.ansicht;
  if (typeof g?.frei === 'string') volaWahl.frei = g.frei;
  if (['3d', 'karte'].includes(g?.form)) volaWahl.form = g.form;
  if (g?.ausschnitt in VOLA_AUSSCHNITT) volaWahl.ausschnitt = g.ausschnitt;
  if (['handel', 'iv'].includes(g?.farbe)) volaWahl.farbe = g.farbe;
  if (['oi', 'volumen'].includes(g?.handel)) volaWahl.handel = g.handel;
} catch {}
const merkeVola = () => { try { localStorage.setItem('volaWahl', JSON.stringify(volaWahl)); } catch {} };
// Kamera schräg von oben: 45 Grad seitlich, 40 Grad Höhe.
const VOLA_KAMERA_START = { dreh: Math.PI / 4, neig: (40 * Math.PI) / 180, zoom: 1, ziel: 1 };
const VOLA_ZOOM = [0.85, 1.6];
const volaKamera = { ...VOLA_KAMERA_START };
let volaLage = null;    // Vierecke auf dem Bildschirm, für den Tooltip
let volaMarke = null;   // [Zeile, Spalte im Ausschnitt] unter dem Zeiger
let volaZelle = null;       // angetippte Zelle der Heatmap ("Zeile,Spalte"), falls dort keine Zahl Platz hat
let volaTerminFokus = null; // Datum des Makro-Termins, der gerade in der Legende gewählt ist
const vol1 = new Intl.NumberFormat('de-DE', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const volPkt = new Intl.NumberFormat('de-DE', { minimumFractionDigits: 1, maximumFractionDigits: 1, signDisplay: 'exceptZero' });
const dollar = new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'USD' });
const kurzDatum = (iso) => lokal(iso).toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit' });
const begrenzt = (v, a, b) => Math.min(b, Math.max(a, v));
const volAchse = new Intl.NumberFormat('de-DE', { maximumFractionDigits: 1 });

// CSS-Farben (auch oklch) in RGB umrechnen: einmal auf ein 1×1-Canvas malen und auslesen.
const farbProbe = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
const farbSpeicher = new Map();
function rgbVon(css) {
  if (farbSpeicher.has(css)) return farbSpeicher.get(css);
  farbProbe.clearRect(0, 0, 1, 1);
  farbProbe.fillStyle = '#000';
  farbProbe.fillStyle = css;
  farbProbe.fillRect(0, 0, 1, 1);
  const [r, g, b] = farbProbe.getImageData(0, 0, 1, 1).data;
  farbSpeicher.set(css, [r, g, b]);
  return [r, g, b];
}
const rgbText = (c, alpha = 1) => `rgba(${c[0]}, ${c[1]}, ${c[2]}, ${alpha})`;

// Farbskalen in OKLCH (Helligkeit %, Buntheit, Farbton): gleich große Schritte sehen gleich groß aus.
// Höhe der IV: ein Farbton (Gold), von dunkel/blass nach hell/kräftig. Veränderung: Blau – Grau – Rot.
// Höhe der IV: dunkel → Mint → Gold → Rot. Vier feste Stufen in OKLCH, kein Regenbogen:
// niedrige IV ruhig und dunkel, sehr hohe IV rot. Veränderung: Blau – Grau – Rot.
const VOLA_SKALA = {
  dark: { stufen: [[0, [27, 0.02, 165]], [0.4, [72, 0.12, 168]], [0.7, [86, 0.15, 88]], [1, [66, 0.19, 27]]], mitte: [42, 0.008, 80], rot: [70, 0.16, 27], blau: [70, 0.13, 248] },
  light: { stufen: [[0, [95, 0.02, 165]], [0.4, [72, 0.11, 168]], [0.7, [76, 0.15, 80]], [1, [52, 0.19, 27]]], mitte: [91, 0.005, 80], rot: [56, 0.17, 27], blau: [55, 0.15, 252] },
};
const HANDEL_SKALA = { dark: [[24, 0.02, 165], [88, 0.13, 165]], light: [[94, 0.012, 165], [55, 0.12, 165]] };
const HANDEL_NAME = { oi: 'Open Interest', volumen: 'Volumen' };
const ganzeZahl = new Intl.NumberFormat('de-DE', { maximumFractionDigits: 0 });
// t = 0 bis 1 auf der logarithmischen Skala. 32 Stufen reichen, mehr sieht man nicht.
const handelFarbe = (t) => oklch(zwischen(...HANDEL_SKALA[volaThema()], Math.round(begrenzt(t, 0, 1) * 32) / 32));
function skalaFarbe(stufen, t) {
  const k = stufen.findIndex(([ab], n) => n === stufen.length - 1 || t <= stufen[n + 1][0]);
  const [a, fa] = stufen[k], [b, fb] = stufen[Math.min(k + 1, stufen.length - 1)];
  return zwischen(fa, fb, b === a ? 0 : (t - a) / (b - a));
}
const volaThema = () => (document.documentElement.dataset.theme === 'light' ? 'light' : 'dark');
const oklch = ([l, c, h]) => rgbVon(`oklch(${l.toFixed(1)}% ${c.toFixed(3)} ${h.toFixed(0)})`);
const zwischen = (a, b, t) => a.map((v, i) => v + (b[i] - v) * t);
function volaFarben() {
  const stil = getComputedStyle(document.body);
  const wert = (n) => rgbVon(stil.getPropertyValue(n).trim());
  return {
    flaeche: wert('--karte-fest'), grau: wert('--grau'), text: wert('--text'), gold: wert('--gold'), skala: VOLA_SKALA[volaThema()],
    lila: oklch(volaThema() === 'light' ? [50, 0.14, 295] : [78, 0.1, 295]),
  };
}
// Farbe für einen Wert, in wenigen Stufen gerundet (so bleiben es wenige verschiedene Farben).
function volaFarbe(f, r, v) {
  const s = f.skala;
  if (r.art === 'stand') return oklch(skalaFarbe(s.stufen, Math.round(begrenzt((v - r.tief) / (r.hoch - r.tief), 0, 1) * 48) / 48));
  const t = Math.round(begrenzt(Math.abs(v) / r.hoch, 0, 1) * 24) / 24;
  const seite = v >= 0 ? s.rot : s.blau;
  return oklch([s.mitte[0] + (seite[0] - s.mitte[0]) * t, s.mitte[1] + (seite[1] - s.mitte[1]) * t, seite[2]]);
}

function perzentil(werte, p) {
  const s = [...werte].sort((a, b) => a - b);
  return s[begrenzt(Math.round((p / 100) * (s.length - 1)), 0, s.length - 1)];
}

// Was gezeigt wird: die IV selbst oder ihre Veränderung gegen einen früheren Tag.
// Höhe und Farbe reichen vom 5. bis zum 95. Perzentil der echten Werte im gezeigten Strike-Bereich.
// Einzelne Spitzen werden dadurch abgeschnitten, dafür ist der Rest gut zu unterscheiden.
const VOLA_SKALA_FEST = [10, 40];
const VOLA_DIFF_FEST = 3;
function volaRaster(d) {
  // Ob Werte "extrem" sind, entscheidet der Bereich nahe am Kurs (90 bis 110 %). Weit aus dem
  // Geld liegen kurze Laufzeiten auch an normalen Tagen über 40 %, das soll die Skala nicht verschieben.
  const spalten = d.moneyness.map((_, j) => j).filter((j) => d.moneyness[j] >= 90 && d.moneyness[j] <= 110);
  const echt = (raster) => raster.flatMap((z, i) => spalten.filter((j) => !d.geschaetzt[i][j]).map((j) => z[j]));
  if (volaWahl.ansicht === 'heute') {
    // Feste Skala von 10 bis 40 %: So sieht man von Tag zu Tag, ob die Fläche steigt oder fällt.
    // Nur wenn die Werte extrem sind (95. Perzentil außerhalb), wird sie in 10er-Schritten erweitert.
    const kern = echt(d.iv);
    const tief = Math.min(VOLA_SKALA_FEST[0], Math.floor(perzentil(kern, 5) / 10) * 10);
    const hoch = Math.max(VOLA_SKALA_FEST[1], Math.ceil(perzentil(kern, 95) / 10) * 10);
    return { werte: d.iv, art: 'stand', tief, hoch, erweitert: tief !== VOLA_SKALA_FEST[0] || hoch !== VOLA_SKALA_FEST[1] };
  }
  if (volaWahl.ansicht === 'frei') {
    const f = (d.archiv ?? []).find((x) => `${x.art}|${x.zeit ?? x.datum}` === volaWahl.frei);
    d.frei = f ? { datum: f.datum, name: volaStandName(f), iv: f.iv } : null;
  }
  const alt = d[volaWahl.ansicht];
  if (!alt) return null;
  const werte = d.iv.map((z, i) => z.map((v, j) => v - alt.iv[i][j]));
  // Auch die Veränderung hat eine feste Skala (±3 Punkte), erweitert nur bei sehr großen Sprüngen.
  const hoch = Math.max(VOLA_DIFF_FEST, Math.ceil(perzentil(echt(werte).map(Math.abs), 95)));
  return { werte, art: 'diff', tief: -hoch, hoch, seit: alt.datum, erweitert: hoch !== VOLA_DIFF_FEST };
}
const tageText = (t) => (t >= 60 && t % 30 === 0 ? `${t / 30} M` : `${t} T`);
const terminText = (t) => `${t.kurz} ${kurzDatum(t.datum)}`;

// ---- Fazit in einem Satz ----
// Die größte Erhebung: Aus zwei benachbarten Laufzeiten lässt sich die Vola nur für den Zeitraum
// dazwischen herausrechnen ("Terminvolatilität"). Liegt ein Makro-Termin darin und ist sie dort
// höher als sonst, preist der Markt für dieses Ereignis eine größere Bewegung ein.
function volaAbschnitte(d) {
  const m = d.moneyness.indexOf(100);
  const abschnitte = d.tage.map((b, k) => {
    const a = k ? d.tage[k - 1] : 0;
    const va = k ? d.iv[k - 1][m] ** 2 * a : 0;
    const varianz = (d.iv[k][m] ** 2 * b - va) / (b - a);
    return { a, b, vola: varianz > 0 ? Math.sqrt(varianz) : null, termine: d.termine.filter((t) => t.tage > a && t.tage <= b) };
  }).filter((x) => x.vola !== null);
  const normal = perzentil(abschnitte.map((x) => x.vola), 50);
  return abschnitte.map((x) => ({ ...x, ueber: x.vola - normal }));
}
const BEULE_AB = 0.3; // Vol-Punkte über dem üblichen Niveau, ab denen ein Termin als Beule gilt
function volaErhebung(d) {
  return volaAbschnitte(d).filter((x) => x.termine.length).sort((a, b) => b.ueber - a.ueber)[0] ?? null;
}

// ---- "Was heißt das für mich": feste Regeln, keine Kauf- oder Verkaufsempfehlung ----
const VOLA_NAME = { SPY: 'S&P 500 (SPY)', QQQ: 'Nasdaq 100 (QQQ)' };
function volaFuerMich(d) {
  const k = d.kennzahlen, e = d.einordnung;
  const stufen = ['atm30', 'skew25', 'steigung'].map((n) => e[n].stufe);
  const abschnitte = volaAbschnitte(d);
  const beulen = abschnitte.filter((x) => x.ueber >= BEULE_AB).flatMap((x) => x.termine.map((t) => ({ ...t, ueber: x.ueber })));
  const bald = beulen.filter((t) => t.tage <= 7);
  const punkte = [];

  // Hebel: meiden bei Stress, vorsichtig bei erhöhten Werten oder einer Beule in den nächsten 7 Tagen.
  const gruende = [];
  if (e.atm30.stufe && e.atm30.stufe !== 'normal') gruende.push(`ATM-IV ${e.atm30.stufe === 'Stress' ? 'im Stressbereich' : 'erhöht'}`);
  if (e.skew25.stufe && e.skew25.stufe !== 'normal') gruende.push(`Absturz-Schutz ${e.skew25.stufe === 'Stress' ? 'sehr teuer' : 'teurer als üblich'}`);
  if (e.steigung.stufe === 'Stress') gruende.push('kurze Laufzeiten teurer als lange');
  else if (e.steigung.stufe === 'erhöht') gruende.push('Laufzeitkurve fast flach');
  if (bald.length) gruende.push(`${bald.map(terminText).join(', ')} in den nächsten Tagen mit Beule`);
  const hebel = stufen.includes('Stress') ? 'meiden' : (stufen.includes('erhöht') || bald.length) ? 'vorsichtig' : 'normal';
  const hebelText = {
    normal: 'Der Optionsmarkt preist ruhige Märkte ein. Gehebelte Positionen schwanken im üblichen Rahmen.',
    vorsichtig: `${gruende.join(', ')}. Gehebelte Positionen können stärker ausschlagen als gewohnt.`,
    meiden: `${gruende.join(', ')}. In solchen Phasen werden gehebelte Positionen oft schon von normalen Schwankungen ausgestoppt.`,
  }[hebel];
  punkte.push({ titel: 'Hebel-Trades', stufe: hebel, text: hebelText });

  // Makro-Termine mit Beule in den nächsten 45 Tagen.
  const anstehend = beulen.filter((t) => t.tage <= 45);
  punkte.push({
    titel: 'Makro-Termine',
    text: anstehend.length
      ? anstehend.map((t) => `${t.name} am ${kurzDatum(t.datum)} (in ${t.tage} Tagen): Optionen preisen für diesen Zeitraum ${vol1.format(t.ueber)} Pkt. mehr Bewegung ein als üblich`).join('. ') + '.'
      : 'Keiner der nächsten Termine zeigt eine Beule: Der Markt erwartet dort keine Sonderbewegung.',
  });

  // Erwartete Tagesbewegung: Jahres-IV geteilt durch die Wurzel aus 252 Handelstagen.
  // An gut zwei von drei Tagen bleibt die Bewegung innerhalb dieser Spanne.
  if (k.atm30 !== null) {
    const tag = k.atm30 / Math.sqrt(252);
    const inDollar = (x) => dollar.format((d.kurs * x) / 100);
    punkte.push({
      titel: `Stop-Abstand ${VOLA_NAME[d.ticker] ?? d.ticker}`,
      text: `Erwartete Tagesbewegung etwa ±${komma2.format(tag)} % (≈ ${inDollar(tag)}). Ein Stop näher als das liegt im normalen Tagesrauschen. Als Mindestabstand gilt grob diese Spanne, mehr Luft geben 1,5 bis 2 Tagesbewegungen (${komma2.format(tag * 1.5)} bis ${komma2.format(tag * 2)} %).`,
    });
  }

  // Bei Stress: Wird die Angst größer oder kleiner? Vergleich mit dem letzten gespeicherten Tag.
  if (stufen.includes('Stress')) {
    const v = d.verlauf;
    let text;
    if (v.length < 2) text = 'Ob die Angst steigt oder fällt, lässt sich ab dem nächsten gespeicherten Handelstag sagen.';
    else {
      const [alt, neu] = v.slice(-2);
      const dAtm = neu.atm30 - alt.atm30, dSteig = neu.steigung - alt.steigung;
      const richtung = dAtm > 0.3 || dSteig < -0.3 ? 'steigt' : dAtm < -0.3 || dSteig > 0.3 ? 'fällt' : 'bleibt etwa gleich';
      text = `Gegenüber ${kurzDatum(alt.datum)}: ATM-IV ${volPkt.format(dAtm)} Pkt., Laufzeitstruktur ${volPkt.format(dSteig)} Pkt. Die Angst ${richtung}.`;
    }
    punkte.push({ titel: 'Angst', text });
  }
  return `<h2 id="v-fm-titel">Was heißt das für mich</h2>
    <ul>${punkte.map((x) => `<li><b>${esc(x.titel)}${x.stufe ? ` <span class="v-hebel ${x.stufe}">${x.stufe}</span>` : ''}</b><span>${esc(x.text)}</span></li>`).join('')}</ul>
    <p class="klein">Einordnung aus festen Regeln, keine Kauf- oder Verkaufsempfehlung.</p>`;
}
function volaFazit(d) {
  const stufen = ['atm30', 'skew25', 'steigung'].map((n) => d.einordnung[n].stufe);
  const zustand = stufen.includes('Stress') ? 'angespannt' : stufen.includes('erhöht') ? 'leicht erhöht' : 'ruhig';
  const k = d.kennzahlen;
  const zahl = (v, fmt) => (v === null ? '–' : fmt(v));
  const teile = [
    `ATM-IV ${zahl(k.atm30, (v) => `${vol1.format(v)} %`)} (${stufen[0] ?? '–'})`,
    `Skew ${zahl(k.skew25, (v) => `${vol1.format(v)} Pkt.`)} (${stufen[1] ?? '–'})`,
    `Laufzeitstruktur ${zahl(k.steigung, (v) => `${volPkt.format(v)} Pkt.`)} (${stufen[2] ?? '–'})`,
  ];
  const e = volaErhebung(d);
  const ereignis = e && e.ueber >= BEULE_AB
    ? `Größte IV-Erhebung rund um ${e.termine.map(terminText).join(', ')}: Für diesen Zeitraum liegt die Vola ${vol1.format(e.ueber)} Pkt. über dem üblichen Niveau.`
    : 'Bei den Makro-Terminen zeigt die Fläche keine deutliche Erhebung.';
  return `<b>${esc(d.ticker)}: insgesamt ${zustand}.</b> ${teile.join(' · ')}. ${ereignis}`;
}

// Projektion: erst um die senkrechte Achse drehen, dann kippen, dazu eine leichte Perspektive.
function volaProjektion(breite, hoehe) {
  const { dreh, neig, zoom } = volaKamera;
  const cd = Math.cos(dreh), sd = Math.sin(dreh), cn = Math.cos(neig), sn = Math.sin(neig);
  // Einpassen: Gedreht reicht der Boden höchstens √2 vom Mittelpunkt weg (bei 45 Grad genau so weit).
  // Daraus folgt eine Größe, die beim Drehen gleich bleibt und die Karte bei der Startansicht füllt.
  const rand = 24, weit = Math.SQRT2, zOben = 0.55 * 1.15, zUnten = -0.45 * 1.15;
  const oben = -weit * sn - zOben * cn, unten = weit * sn - zUnten * cn;
  const skala = (Math.min((breite - 2 * rand) / (2 * weit), (hoehe - 2 * rand) / (unten - oben)) / 1.02) * zoom;
  const mx = breite / 2, my = hoehe / 2 - ((oben + unten) / 2) * skala;
  return (x, y, z) => {
    const xr = x * cd - y * sd, yr = x * sd + y * cd;
    const zz = (z - 0.45) * 1.15;
    const tiefe = yr * cn + zz * sn; // größer = näher am Betrachter
    const p = 1 / (1 - tiefe * 0.12);
    return [mx + xr * skala * p, my + (yr * sn - zz * cn) * skala * p, tiefe];
  };
}

function zeichneVola() {
  const d = volaDaten[volaWahl.ticker];
  const leer = el('v-leer'), canvas = el('v-canvas'), karte = el('v-karte');
  el('v-tip').hidden = true;
  el('v-ausschnitt').hidden = volaWahl.form !== '3d';
  el('v-farbwahl').hidden = volaWahl.form !== '3d' || volaWahl.ansicht !== 'heute';
  const handelOffen = volaWahl.farbe === 'handel';
  el('v-handel-klapp').classList.toggle('offen', handelOffen);
  el('v-handel-klapp').inert = !handelOffen; // zugeklappt nicht per Tab erreichbar
  if (!d || d.fehler) { canvas.hidden = karte.hidden = true; el('v-legende').innerHTML = ''; el('v-schnitte').hidden = true; return; }
  el('v-schnitte').hidden = false;
  zeichneVolaSchnitte(d);
  if (!volaRaster(d)) {
    canvas.hidden = karte.hidden = true;
    const ab = lokal(d.erster_tag);
    ab.setDate(ab.getDate() + 7);
    const monat = lokal(d.erster_tag); monat.setDate(monat.getDate() + 30);
    const warum = {
      gestern: 'Der Vergleich mit dem Vortag klappt ab dem nächsten Handelstag',
      woche: `Der Wochenvergleich klappt ab etwa ${ab.toLocaleDateString('de-DE')}`,
      monat: `Der Monatsvergleich klappt ab etwa ${monat.toLocaleDateString('de-DE')}`,
      earnings: d.earnings_tag ? `Die letzten Zahlen kamen am ${lokal(d.earnings_tag).toLocaleDateString('de-DE')}, damals war noch keine Fläche gespeichert. Der Vergleich klappt nach den nächsten Zahlen` : 'Für diesen Wert sind keine Earnings-Termine bekannt. Der Vergleich klappt nach den nächsten Zahlen',
    }[volaWahl.ansicht] ?? 'Der Vergleich klappt später';
    leer.textContent = `Für diesen Vergleich ist noch keine ältere Fläche gespeichert. Die Sammlung für ${d.ticker} hat am ${lokal(d.erster_tag).toLocaleDateString('de-DE')} begonnen. ${warum}, wenn der Server dann nach US-Börsenschluss läuft.`;
    leer.hidden = false;
    el('v-legende').innerHTML = '';
    return;
  }
  leer.hidden = true;
  const f = volaFarben();
  let r;
  if (volaWahl.form === '3d') { karte.hidden = true; canvas.hidden = false; r = zeichneVola3d(d, f); }
  else { canvas.hidden = true; karte.hidden = false; r = volaRaster(d); zeichneVolaKarte(d, r, f); }
  if (r) volaLegende(d, r, f);
}

function zeichneVola3d(d, f) {
  const canvas = el('v-canvas');
  const breite = el('v-flaeche').clientWidth;
  if (!breite) return null;
  const [mVon, mBis] = VOLA_AUSSCHNITT[volaWahl.ausschnitt];
  const spalten = d.moneyness.map((_, j) => j).filter((j) => d.moneyness[j] >= mVon && d.moneyness[j] <= mBis);
  const r = volaRaster(d);
  if (!r) return null;
  const hoehe = Math.round(Math.min(600, Math.max(360, breite * 0.56)));
  const dpr = window.devicePixelRatio || 1;
  canvas.width = breite * dpr; canvas.height = hoehe * dpr;
  canvas.style.width = `${breite}px`; canvas.style.height = `${hoehe}px`;
  const ctx = canvas.getContext('2d');
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, breite, hoehe);
  const proj = volaProjektion(breite, hoehe);
  const mitteM = (mVon + mBis) / 2, halb = (mBis - mVon) / 2;
  const xVon = (m) => (m - mitteM) / halb;
  // Kurze Laufzeiten vorn (y = +1), lange hinten.
  const yVonTag = (t) => 1 - ((t - d.tage[0]) / (d.tage.at(-1) - d.tage[0])) * 2;
  const zVon = (v) => (r.art === 'stand' ? begrenzt((v - r.tief) / (r.hoch - r.tief), 0, 1) : 0.45 + begrenzt(v / r.hoch, -1, 1) * 0.45);
  const W = r.werte.map((zeile, i) => spalten.map((j) => [xVon(d.moneyness[j]), yVonTag(d.tage[i]), zVon(zeile[j])]));
  const P = W.map((zeile) => zeile.map(([x, y, z]) => proj(x, y, z)));
  const linie = (a, b, farbe, dicke = 1) => { ctx.beginPath(); ctx.moveTo(a[0], a[1]); ctx.lineTo(b[0], b[1]); ctx.strokeStyle = farbe; ctx.lineWidth = dicke; ctx.stroke(); };
  const pfad = (punkte, farbe, dicke, strich = []) => {
    ctx.beginPath();
    punkte.forEach((p, k) => (k ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1])));
    ctx.strokeStyle = farbe; ctx.lineWidth = dicke; ctx.setLineDash(strich); ctx.stroke(); ctx.setLineDash([]);
  };

  // Boden mit wenigen Gitterlinien. Bei der Veränderung liegt er auf der Nulllinie.
  const boden = r.art === 'stand' ? 0 : 0.45;
  const mTicks = volaWahl.ausschnitt === 'eng' ? [90, 95, 100, 105, 110] : [80, 90, 100, 110, 120];
  const tTicks = [30, 90].filter((t) => t > d.tage[0] && t < d.tage.at(-1));
  for (const m of mTicks) linie(proj(xVon(m), -1, boden), proj(xVon(m), 1, boden), rgbText(f.grau, m === 100 ? 0.4 : 0.16));
  for (const t of [d.tage[0], ...tTicks, d.tage.at(-1)]) linie(proj(-1, yVonTag(t), boden), proj(1, yVonTag(t), boden), rgbText(f.grau, 0.16));
  const vorneY = proj(0, 1, boden)[2] > proj(0, -1, boden)[2] ? 1 : -1;
  const vorneX = proj(1, 0, boden)[2] > proj(-1, 0, boden)[2] ? 1 : -1;
  // Senkrechte Achse an der Ecke, die im Bild ganz links liegt: Ihre Zahlen stehen dann neben der Fläche, nicht darauf.
  const ecke = [[-1, -1], [1, -1], [1, 1], [-1, 1]].map(([x, y]) => ({ x, y, sx: proj(x, y, boden)[0] })).sort((a, b) => a.sx - b.sx)[0];
  linie(proj(ecke.x, ecke.y, 0), proj(ecke.x, ecke.y, 1), rgbText(f.grau, 0.4));

  // Rückwände: die hintere Laufzeit-Wand (x fest) zeigt die Laufzeitstruktur bei 100 % und 90 %,
  // die hintere Strike-Wand (y fest) den Skew der gewählten Laufzeit. Wie ein Schattenwurf der Fläche.
  const wandX = -vorneX, wandY = -vorneY;
  const wand = (ecken) => {
    ctx.beginPath();
    ecken.forEach((p, k) => (k ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1])));
    ctx.closePath();
    ctx.fillStyle = rgbText(f.text, 0.035);
    ctx.fill();
    ctx.strokeStyle = rgbText(f.grau, 0.25);
    ctx.lineWidth = 1;
    ctx.stroke();
  };
  wand([proj(wandX, -1, 0), proj(wandX, 1, 0), proj(wandX, 1, 1), proj(wandX, -1, 1)]);
  wand([proj(-1, wandY, 0), proj(1, wandY, 0), proj(1, wandY, 1), proj(-1, wandY, 1)]);
  const wandSchilder = [];
  // Die Linien selbst kommen erst nach der Fläche dran (siehe unten): Bei niedriger IV lägen sie
  // sonst hinter der Fläche verborgen.
  const wandLinien = [];
  const wandLinie = (punkte, farbe, text) => {
    wandLinien.push({ punkte, farbe });
    const ende = punkte.reduce((a, b) => (b[1] < a[1] ? b : a)); // höchster Punkt für das Schild
    wandSchilder.push({ p: ende, text, farbe });
  };
  if (r.art === 'stand') {
    for (const [m, farbe, text] of [[100, f.text, 'Laufzeitstruktur 100 %'], [90, f.gold, '90 %']]) {
      const j = d.moneyness.indexOf(m);
      if (j >= 0) wandLinie(d.tage.map((t, i) => proj(wandX, yVonTag(t), zVon(d.iv[i][j]))), farbe, text);
    }
    const iW = d.tage.indexOf(volaSchnitt.tage);
    if (iW >= 0) wandLinie(spalten.map((j) => proj(xVon(d.moneyness[j]), wandY, zVon(d.iv[iW][j]))), f.lila, `Skew ${tageText(volaSchnitt.tage)}`);
  }

  // Die Fläche als Vierecke, die hinteren zuerst (Maler-Verfahren). Eine Lichtquelle schräg
  // von oben schattiert jedes Viereck nach seiner Neigung: So ist die Form gut zu erkennen.
  const licht = (() => { const v = [-0.35, 0.45, 0.82]; const l = Math.hypot(...v); return v.map((x) => x / l); })();
  // Farbe nach Handel: log10(1 + Kontrakte), geteilt durch den größten Wert im gezeigten Ausschnitt.
  // Logarithmisch, weil der Handel nahe am Kurs oft hundertmal so groß ist wie am Rand.
  const H = r.art === 'stand' && volaWahl.farbe === 'handel' ? d[volaWahl.handel] : null;
  const logH = H && H.map((z) => z.map((v) => Math.log10(1 + v)));
  // Die Skala reicht von der Zehnerstufe der kleinsten Werte (5. Perzentil) bis zum größten Wert:
  // Wird im Ausschnitt überall viel gehandelt, bleiben die Unterschiede trotzdem sichtbar.
  const logAlle = logH ? logH.flatMap((z) => spalten.map((j) => z[j])) : null;
  const logMax = logH ? Math.max(1, ...logAlle) : null;
  const logMin = logH ? Math.min(logMax - 1, Math.floor(perzentil(logAlle, 5))) : null;
  r.handel = H ? { art: volaWahl.handel, max: 10 ** logMax - 1, min: 10 ** logMin } : null;
  const vierecke = [];
  for (let i = 0; i < W.length - 1; i++) {
    for (let jj = 0; jj < spalten.length - 1; jj++) {
      const j = spalten[jj];
      const ecken = [P[i][jj], P[i][jj + 1], P[i + 1][jj + 1], P[i + 1][jj]];
      const wert = (r.werte[i][j] + r.werte[i][j + 1] + r.werte[i + 1][j + 1] + r.werte[i + 1][j]) / 4;
      const geschaetzt = d.geschaetzt[i][j] && d.geschaetzt[i][j + 1] && d.geschaetzt[i + 1][j + 1] && d.geschaetzt[i + 1][j];
      const a = W[i + 1][jj + 1].map((v, k) => v - W[i][jj][k]), b = W[i + 1][jj].map((v, k) => v - W[i][jj + 1][k]);
      const n = [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
      const hell = Math.abs(n[0] * licht[0] + n[1] * licht[1] + n[2] * licht[2]) / (Math.hypot(...n) || 1);
      const handel = logH ? ((logH[i][j] + logH[i][j + 1] + logH[i + 1][j + 1] + logH[i + 1][j]) / 4 - logMin) / (logMax - logMin) : null;
      vierecke.push({ i, j: jj, ecken, wert, handel, geschaetzt, schatten: 0.72 + 0.28 * hell, tiefe: ecken.reduce((s, p) => s + p[2], 0) / 4 });
    }
  }
  vierecke.sort((a, b) => a.tiefe - b.tiefe);
  const netzDunkel = volaThema() === 'light' ? 0.72 : 0.55; // Kante = Flächenfarbe, deutlich dunkler
  for (const q of vierecke) {
    ctx.beginPath();
    q.ecken.forEach((p, k) => (k ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1])));
    ctx.closePath();
    const grund = q.handel === null ? volaFarbe(f, r, q.wert) : handelFarbe(q.handel);
    ctx.fillStyle = rgbText(grund.map((c) => Math.round(c * q.schatten)), q.geschaetzt ? 0.4 : 1);
    ctx.fill();
    ctx.strokeStyle = rgbText(grund.map((c) => Math.round(c * q.schatten * netzDunkel)), q.geschaetzt ? 0.4 : 0.95);
    ctx.lineWidth = 0.9;
    ctx.stroke();
  }

  // Wandlinien mit dunklem Rand, damit sie sich von der Fläche abheben.
  for (const w of wandLinien) {
    pfad(w.punkte, rgbText(f.flaeche, 0.85), 4.5);
    pfad(w.punkte, rgbText(w.farbe), 2);
  }
  // Linien auf der Fläche: aktueller Kurs (100 %), gewählte Laufzeit des Smiles, Makro-Termine.
  const zeileBei = (t) => {
    const k = d.tage.findIndex((x) => x >= t);
    if (k <= 0) return r.werte[0];
    const a = (t - d.tage[k - 1]) / (d.tage[k] - d.tage[k - 1]);
    return r.werte[k].map((v, j) => r.werte[k - 1][j] + (v - r.werte[k - 1][j]) * a);
  };
  const quer = (t) => { const z = zeileBei(t); return spalten.map((j) => proj(xVon(d.moneyness[j]), yVonTag(t), zVon(z[j]) + 0.012)); };
  // Ist ein Termin in der Legende gewählt, ist seine Linie hell und durchgezogen, die anderen treten zurück.
  for (const termin of d.termine.filter((t) => t.tage >= d.tage[0])) {
    const aktiv = volaTerminFokus === termin.datum;
    pfad(quer(termin.tage), rgbText(f.text, volaTerminFokus ? (aktiv ? 1 : 0.12) : 0.45), aktiv ? 2.25 : 1, aktiv ? [] : [3, 3]);
  }
  const m100 = d.moneyness.indexOf(100);
  const kurslinie = d.tage.map((t, i) => proj(0, yVonTag(t), zVon(r.werte[i][m100]) + 0.01));
  pfad(kurslinie, rgbText(f.text, 0.6), 1.25);
  if (d.tage.includes(volaSchnitt.tage)) pfad(quer(volaSchnitt.tage), rgbText(f.text, 0.95), 2.25);

  // ---- Beschriftung: zuletzt, über allem, mit leichtem Hintergrund. Was sich mit einer schon
  // gesetzten Beschriftung überschneiden würde, entfällt. Alles bleibt innerhalb des Bildes.
  const belegt = [];
  const mitteBild = proj(0, 0, boden);
  const schrift = (gewicht) => { ctx.font = `${gewicht} 12px -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", sans-serif`; };
  function setze(text, x, y, { ausrichtung = 'left', gewicht = 400, farbe = f.grau, hinterlegt = true } = {}) {
    schrift(gewicht);
    const w = ctx.measureText(text).width, h = 15;
    const x0 = begrenzt(ausrichtung === 'center' ? x - w / 2 : ausrichtung === 'right' ? x - w : x, 4, breite - w - 4);
    const y0 = begrenzt(y - h / 2, 2, hoehe - h - 2);
    const kasten = [x0 - 4, y0, x0 + w + 4, y0 + h];
    if (belegt.some((b) => kasten[0] < b[2] && kasten[2] > b[0] && kasten[1] < b[3] && kasten[3] > b[1])) return false;
    belegt.push(kasten);
    if (hinterlegt) {
      ctx.fillStyle = rgbText(f.flaeche, 0.72);
      ctx.beginPath();
      ctx.roundRect(kasten[0], kasten[1], kasten[2] - kasten[0], h, 5);
      ctx.fill();
    }
    ctx.fillStyle = rgbText(farbe);
    ctx.textAlign = 'left';
    ctx.fillText(text, x0, y0 + 11.5);
    return true;
  }
  // Am Rand nach außen versetzt, vom Bildmittelpunkt weg.
  function aussen(p, text, weg, optionen = {}) {
    const dx = p[0] - mitteBild[0], dy = p[1] - mitteBild[1], l = Math.hypot(dx, dy) || 1;
    const ausrichtung = Math.abs(dx / l) < 0.35 ? 'center' : dx > 0 ? 'left' : 'right';
    return setze(text, p[0] + (dx / l) * weg, p[1] + (dy / l) * weg, { ausrichtung, ...optionen });
  }
  // Auf der Fläche: kleiner Punkt und darüber die Beschriftung.
  function aufFlaeche(p, text, seite = 'oben') {
    if (!setze(text, p[0], p[1] + (seite === 'oben' ? -16 : 16), { ausrichtung: 'center', gewicht: 600, farbe: f.text })) return false;
    ctx.beginPath(); ctx.arc(p[0], p[1], 3, 0, Math.PI * 2); ctx.fillStyle = rgbText(f.text); ctx.fill();
    return true;
  }
  // Senkrechte Achse: Titel oben am Ende, darunter höchstens vier Werte.
  const zOben = proj(ecke.x, ecke.y, 1);
  setze(r.art === 'stand' ? 'IV' : 'IV-Änderung', zOben[0], zOben[1] - 14, { ausrichtung: 'center', gewicht: 600, farbe: f.text });
  const schritt = [0.1, 0.2, 0.5, 1, 2, 2.5, 5, 10].find((s) => (r.hoch - r.tief) / s <= 4) ?? 20;
  for (let z = Math.ceil(r.tief / schritt) * schritt; z <= r.hoch + 1e-9; z += schritt) {
    const p = proj(ecke.x, ecke.y, zVon(z));
    linie([p[0] - 4, p[1]], [p[0], p[1]], rgbText(f.grau, 0.5));
    setze(r.art === 'stand' ? `${volAchse.format(z)} %` : `${volPkt.format(z)} Pkt.`, p[0] - 8, p[1], { ausrichtung: 'right' });
  }
  // Laufzeit-Achse: Enden mit "kurzfristig" und "langfristig", der Titel am hinteren Ende.
  const kurzEnde = proj(vorneX, 1, boden), langEnde = proj(vorneX, -1, boden);
  aussen(kurzEnde, `kurzfristig · ${tageText(d.tage[0])}`, 16, { gewicht: 600, farbe: f.text });
  aussen(langEnde, `langfristig · ${tageText(d.tage.at(-1))}`, 16, { gewicht: 600, farbe: f.text });
  aussen(proj(vorneX, -1.32, boden), 'Restlaufzeit →', 0, { gewicht: 600 });
  for (const t of tTicks) aussen(proj(vorneX, yVonTag(t), boden), tageText(t), 14);
  // Strike-Achse: Werte an der vorderen Kante, Titel am äußeren Ende.
  for (const m of mTicks) aussen(proj(xVon(m), vorneY, boden), `${m} %`, 14);
  // Titel am Ende der Achse; ist dort kein Platz, am anderen Ende, sonst unter der Mitte.
  const strikeTitel = (seite) => (seite > 0 ? 'Strike in % vom Kurs →' : '← Strike in % vom Kurs');
  if (!aussen(proj(-vorneX * 1.3, vorneY, boden), strikeTitel(-vorneX), 0, { gewicht: 600 })
    && !aussen(proj(vorneX * 1.3, vorneY, boden), strikeTitel(vorneX), 0, { gewicht: 600 })) {
    aussen(proj(0, vorneY, boden), 'Strike in % vom Kurs', 56, { gewicht: 600 });
  }
  // Erklärende Beschriftungen, die mit der Fläche mitwandern.
  aufFlaeche(kurslinie[Math.round(kurslinie.length * 0.75)], 'aktueller Kurs');
  // IV am Anfang und Ende der Kurslinie: kürzeste und längste Laufzeit am Geld.
  const ivText = (i) => (r.art === 'stand' ? `${vol1.format(d.iv[i][m100])} %` : `${volPkt.format(r.werte[i][m100])} Pkt.`);
  aufFlaeche(kurslinie[0], ivText(0), 'unten');
  aufFlaeche(kurslinie.at(-1), ivText(d.tage.length - 1));
  // Die gewählte Laufzeit (dicke Linie) bekommt ein eigenes, mitwanderndes Schild.
  const iSchnitt = d.tage.indexOf(volaSchnitt.tage);
  if (iSchnitt >= 0) aufFlaeche(P[iSchnitt][Math.round((spalten.length - 1) * 0.72)], `${volaSchnitt.tage}-Tage-Schnitt`);
  // Makro-Termine: Die Beschriftung liegt direkt auf der Linie, in ihrer Richtung gedreht, und
  // dreht sich mit der Fläche mit. Dicht beieinanderliegende Termine (z. B. Fed und CPI an zwei
  // Tagen hintereinander) bekommen verschiedene Stellen entlang ihrer Linie.
  function entlang(punkte, anteil, text, gewicht, seite = 1) {
    const lage = anteil * (punkte.length - 1), k = Math.min(punkte.length - 2, Math.floor(lage)), rest = lage - k;
    const a = punkte[k], b = punkte[k + 1];
    let winkel = Math.atan2(b[1] - a[1], b[0] - a[0]);
    if (winkel > Math.PI / 2) winkel -= Math.PI; else if (winkel < -Math.PI / 2) winkel += Math.PI; // Schrift nie kopfüber
    schrift(gewicht);
    const w = ctx.measureText(text).width + 8, h = 15;
    // Neben der Linie, damit sie sichtbar bleibt: senkrecht zur Schreibrichtung, erst darüber, sonst darunter.
    const cx = a[0] + (b[0] - a[0]) * rest + Math.sin(winkel) * 9 * seite, cy = a[1] + (b[1] - a[1]) * rest - Math.cos(winkel) * 9 * seite;
    const hw = Math.abs((w / 2) * Math.cos(winkel)) + Math.abs((h / 2) * Math.sin(winkel));
    const hh = Math.abs((w / 2) * Math.sin(winkel)) + Math.abs((h / 2) * Math.cos(winkel));
    const kasten = [cx - hw, cy - hh, cx + hw, cy + hh];
    if (kasten[0] < 2 || kasten[2] > breite - 2 || kasten[1] < 2 || kasten[3] > hoehe - 2) return false;
    if (belegt.some((q) => kasten[0] < q[2] && kasten[2] > q[0] && kasten[1] < q[3] && kasten[3] > q[1])) return false;
    belegt.push(kasten);
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(winkel);
    ctx.fillStyle = rgbText(f.flaeche, 0.72);
    ctx.beginPath();
    ctx.roundRect(-w / 2, -h / 2, w, h, 5);
    ctx.fill();
    ctx.fillStyle = rgbText(f.text);
    ctx.textAlign = 'center';
    ctx.fillText(text, 0, 4);
    ctx.restore();
    return true;
  }
  const stellen = [0.5, 0.25, 0.75, 0.38, 0.62, 0.15, 0.85, 0.06, 0.94];
  const sichtbar = d.termine.filter((t) => t.tage >= d.tage[0]);
  // Der gewählte Termin zuerst und mit vollem Namen, damit er sicher Platz bekommt.
  sichtbar.sort((x, y) => (y.datum === volaTerminFokus) - (x.datum === volaTerminFokus));
  sichtbar.forEach((termin, n) => {
    const punkte = quer(termin.tage);
    const fokus = termin.datum === volaTerminFokus;
    const text = fokus ? `${termin.name}, ${kurzDatum(termin.datum)}` : terminText(termin);
    // Jeder Termin beginnt an einer anderen Stelle, so liegen nahe Linien nicht Schild an Schild.
    const reihe = [...stellen.slice(n % stellen.length), ...stellen.slice(0, n % stellen.length)];
    reihe.some((anteil) => entlang(punkte, anteil, text, fokus ? 700 : 500)) || reihe.some((anteil) => entlang(punkte, anteil, text, fokus ? 700 : 500, -1));
  });
  for (const w of wandSchilder) setze(w.text, w.p[0], w.p[1] - 12, { ausrichtung: 'center', gewicht: 600, farbe: w.farbe });
  const schutzSpalte = spalten[Math.round((spalten.length - 1) * 0.15)];
  const schutzZeile = d.tage.findIndex((t) => t >= 60);
  aufFlaeche(P[schutzZeile][spalten.indexOf(schutzSpalte)], 'Absturz-Schutz');

  // Punkt unter dem Zeiger hervorheben.
  const p = volaMarke && P[volaMarke[0]]?.[volaMarke[1]];
  if (p) {
    ctx.beginPath();
    ctx.arc(p[0], p[1], 5, 0, Math.PI * 2);
    ctx.fillStyle = rgbText(f.text);
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = rgbText(f.flaeche);
    ctx.stroke();
  }
  volaLage = { vierecke, P, d, r, spalten };
  canvas.setAttribute('aria-label', `${d.ticker}: Volatilitätsoberfläche, ATM-IV 30 Tage ${vol1.format(d.kennzahlen.atm30)} %. Pfeiltasten drehen, Plus und Minus zoomen. Die Werte stehen auch in der Heatmap.`);
  return r;
}

// Heatmap: alle Strikes von 80 bis 120 %, mit Zahl in jedem Feld, wenn es breit genug ist.
function zeichneVolaKarte(d, r, f) {
  const feld = el('v-karte');
  const breite = el('v-flaeche').clientWidth;
  if (!breite) return;
  const schmal = breite < 560;
  const rand = { links: 40, rechts: d.termine.length ? (schmal ? 64 : 96) : 8, oben: 20, unten: 36 };
  const spalten = d.moneyness.length, zeilen = d.tage.length;
  const zelleB = (breite - rand.links - rand.rechts) / spalten;
  const zahlen = zelleB >= 34;
  feld.dataset.zahlen = String(zahlen);
  const zelleH = zahlen ? 28 : Math.max(18, Math.min(26, zelleB * 0.9));
  const hoehe = rand.oben + zelleH * zeilen + rand.unten;
  // Lange Laufzeiten oben, kurze unten.
  const y = (i) => rand.oben + (zeilen - 1 - i) * zelleH;
  const zellen = r.werte.map((zeile, i) => zeile.map((v, j) => {
    const geschaetzt = d.geschaetzt[i][j];
    const farbe = volaFarbe(f, r, v);
    // Schrift hell oder dunkel, je nachdem, was auf der Zellfarbe besser lesbar ist.
    const hell = (0.2126 * farbe[0] + 0.7152 * farbe[1] + 0.0722 * farbe[2]) / 255 > 0.55;
    const tip = tipAttr(`${d.moneyness[j]} % vom Kurs · ${d.tage[i]} Tage`,
      `Strike ≈ ${dollar.format((d.kurs * d.moneyness[j]) / 100)}`,
      `IV ${vol1.format(d.iv[i][j])} %`,
      r.art === 'diff' ? `${volPkt.format(v)} Pkt. seit ${lokal(r.seit).toLocaleDateString('de-DE')}` : '',
      geschaetzt ? 'kein Strike gehandelt: vom Rand fortgeschrieben' : '',
      'Klick: Smile dieser Laufzeit unten zeigen');
    const x0 = rand.links + j * zelleB;
    return `<g class="v-zelle${d.tage[i] === volaSchnitt.tage ? ' gewaehlt' : ''}" data-tage="${d.tage[i]}" data-zelle="${i},${j}" ${tip}>
      <rect x="${x0 + 1}" y="${y(i) + 1}" width="${Math.max(1, zelleB - 2)}" height="${zelleH - 2}" rx="3" fill="${rgbText(farbe)}" fill-opacity="${geschaetzt ? 0.4 : 1}"/>
      ${zahlen ? `<text x="${x0 + zelleB / 2}" y="${y(i) + zelleH / 2 + 4}" text-anchor="middle" class="v-zahl ${hell ? 'dunkel' : 'hell'}${geschaetzt ? ' blass' : ''}">${r.art === 'diff' ? volPkt.format(v) : vol1.format(v)}</text>` : ''}</g>`;
  }).join('')).join('');
  const xText = d.moneyness.map((m, j) => (m % 10 === 0 ? `<text class="c-achse" x="${rand.links + (j + 0.5) * zelleB}" y="${hoehe - rand.unten + 15}" text-anchor="middle">${m === 100 ? 'aktueller Kurs' : `${m} %`}</text>` : '')).join('');
  const yText = d.tage.map((t, i) => `<text class="c-achse${t === volaSchnitt.tage ? ' v-achse-wahl' : ''}" x="${rand.links - 6}" y="${y(i) + zelleH / 2 + 4}" text-anchor="end">${tageText(t)}</text>`).join('');
  // Makro-Termine: gestrichelte Linie bei der Laufzeit, der Name steht in der Legende und im Tooltip.
  const yVonTag = (t) => {
    const k = d.tage.findIndex((x) => x >= t);
    const lage = k <= 0 ? 0 : k - 1 + (t - d.tage[k - 1]) / (d.tage[k] - d.tage[k - 1]);
    return rand.oben + (zeilen - 1 - lage) * zelleH + zelleH / 2;
  };
  // Schilder rechts: in Reihenfolge der Laufzeit, bei Platzmangel nach unten versetzt.
  const schilder = d.termine.filter((t) => t.tage >= d.tage[0]).map((t) => ({ t, linie: yVonTag(t.tage) })).sort((a, b) => b.linie - a.linie);
  let vorher = Infinity;
  for (const s of schilder) { s.y = Math.min(s.linie, vorher - 13); vorher = s.y; }
  const termine = schilder.map(({ t, y: sy }) => {
    const ty = yVonTag(t.tage);
    const x = breite - rand.rechts;
    const schild = `<path class="v-termin-zu" d="M${x} ${ty}L${x + 6} ${sy}"/><text class="v-termin-text" x="${x + 9}" y="${sy + 4}">${esc(schmal ? t.kurz : terminText(t))}</text>`;
    return `<g ${tipAttr(t.name, `${lokal(t.datum).toLocaleDateString('de-DE')} · in ${t.tage} Tagen`)}><line class="v-termin${t.datum === volaTerminFokus ? ' aktiv' : ''}" data-datum="${t.datum}" x1="${rand.links}" x2="${breite - rand.rechts}" y1="${ty}" y2="${ty}"/><line class="v-termin-treffer" x1="${rand.links}" x2="${breite - rand.rechts}" y1="${ty}" y2="${ty}"/>${schild}</g>`;
  }).join('');
  feld.classList.toggle('fokus', Boolean(volaTerminFokus));
  feld.innerHTML = `<svg width="${breite}" height="${hoehe}" viewBox="0 0 ${breite} ${hoehe}" role="img" aria-label="Heatmap der impliziten Volatilität von ${esc(d.ticker)}">
    ${zellen}${xText}${yText}${termine}${(() => {
      // Angetippte Zelle: Wert als Blase darüber, wenn im Feld selbst kein Platz für die Zahl ist.
      if (zahlen || !volaZelle) return '';
      const [i, j] = volaZelle.split(',').map(Number);
      if (!r.werte[i] || r.werte[i][j] === undefined) return '';
      const text = r.art === 'diff' ? `${volPkt.format(r.werte[i][j])} Pkt.` : `${vol1.format(d.iv[i][j])} %`;
      const w = text.length * 7 + 12, cx = begrenzt(rand.links + (j + 0.5) * zelleB, w / 2 + 2, breite - w / 2 - 2), cy = Math.max(12, y(i) - 12);
      return `<g class="v-blase" pointer-events="none"><rect x="${cx - w / 2}" y="${cy - 10}" width="${w}" height="20" rx="10"/><text x="${cx}" y="${cy + 4}" text-anchor="middle">${text}</text></g>`;
    })()}
    <text class="c-achse v-achs-titel" x="${breite - rand.rechts}" y="${hoehe - 3}" text-anchor="end">Strike in % vom Kurs →</text>
    <text class="c-achse v-achs-titel" x="4" y="12">↑ Laufzeit</text>
  </svg>`;
}

function volaLegende(d, r, f) {
  if (r.handel) {
    const logMax = Math.log10(1 + r.handel.max), logMin = Math.log10(r.handel.min);
    const stufenH = Array.from({ length: 13 }, (_, k) => rgbText(handelFarbe(k / 12))).join(', ');
    const zehner = [];
    for (let e = Math.round(logMin); 10 ** e <= r.handel.max; e++) zehner.push(10 ** e);
    const marken = zehner.map((z) => `<b style="left:${(((Math.log10(z) - logMin) / (logMax - logMin)) * 100).toFixed(1)}%">${z === r.handel.min && z > 1 ? '≤ ' : ''}${ganzeZahl.format(z)}</b>`).join('');
    const termineH = d.termine.filter((t) => t.tage >= d.tage[0]);
    el('v-legende').innerHTML = `<span>kaum Handel</span><span class="v-log"><i style="background:linear-gradient(90deg, ${stufenH})"></i><span class="v-log-marken">${marken}</span></span><span>viel Handel</span>
      <span class="v-legende-extra">Höhe: IV · Farbe: ${HANDEL_NAME[r.handel.art]} je Feld (Calls und Puts, Kontrakte), logarithmisch: jede Stufe zehnmal so viel. Höchster Wert hier: ${ganzeZahl.format(r.handel.max)}.</span>
      <span class="v-legende-extra">${d.oi ? '' : 'Für diesen Tag sind keine Handelsdaten gespeichert. '}${volaThema() === 'light' ? 'Kräftiges Mint' : 'Helles Mint'}: Hier ist der Markt liquide, die IV dort ist verlässlich. ${volaThema() === 'light' ? 'Blass' : 'Dunkel'}: wenig Handel, die Werte sind eher grob.</span>
      ${termineH.length ? `<span class="v-legende-extra">Gestrichelt, Makro-Termine: ${termineH.map((t) => `<span class="v-termin-name${t.datum === volaTerminFokus ? ' aktiv' : ''}" data-datum="${t.datum}" tabindex="0" role="button" aria-pressed="${t.datum === volaTerminFokus}" ${tipAttr(t.name, `${lokal(t.datum).toLocaleDateString('de-DE')} · in ${t.tage} Tagen`, 'Linie auf der Fläche hervorheben')}>${esc(terminText(t))}</span>`).join(' · ')}</span>` : ''}`;
    return;
  }
  const stufen = Array.from({ length: 13 }, (_, k) => rgbText(volaFarbe(f, r, r.tief + ((r.hoch - r.tief) * k) / 12))).join(', ');
  const enden = r.art === 'stand'
    ? [`${vol1.format(r.tief)} % IV und weniger`, `${vol1.format(r.hoch)} % und mehr`]
    : [`−${vol1.format(r.hoch)} Pkt. gefallen`, `+${vol1.format(r.hoch)} Pkt. gestiegen`];
  const termine = d.termine.filter((t) => t.tage >= d.tage[0]);
  el('v-legende').innerHTML = `<span>${enden[0]}</span><i style="background:linear-gradient(90deg, ${stufen})"></i><span>${enden[1]}</span>
    <span class="v-legende-extra">${r.art === 'diff' ? `Vergleich mit ${volaWahl.ansicht === 'frei' && volaDaten[volaWahl.ticker]?.frei?.name ? volaDaten[volaWahl.ticker].frei.name : lokal(r.seit).toLocaleDateString('de-DE')} · ` : ''}${r.erweitert ? 'Skala wegen extremer Werte erweitert · ' : `feste Skala${r.art === 'stand' ? ', Spitzen darüber abgeschnitten' : ''} · `}blass: kein Strike gehandelt · dicke Linie: Laufzeit im Smile unten</span>
    ${termine.length ? `<span class="v-legende-extra">Gestrichelt, Makro-Termine: ${termine.map((t) => `<span class="v-termin-name${t.datum === volaTerminFokus ? ' aktiv' : ''}" data-datum="${t.datum}" tabindex="0" role="button" aria-pressed="${t.datum === volaTerminFokus}" ${tipAttr(t.name, `${lokal(t.datum).toLocaleDateString('de-DE')} · in ${t.tage} Tagen`, 'Linie auf der Fläche hervorheben')}>${esc(terminText(t))}</span>`).join(' · ')}</span>` : ''}`;
}

// ---- Zwei Schnitte durch die Fläche, zum genauen Ablesen ----
// Smile: IV über den Strike bei einer Laufzeit. Laufzeitstruktur: IV über die Laufzeit bei festem Strike.
const volaSchnitt = { tage: 30 };
try { const g = Number(localStorage.getItem('volaSmile')); if (g) volaSchnitt.tage = g; } catch {}
function waehleSmile(tage) {
  volaSchnitt.tage = tage;
  try { localStorage.setItem('volaSmile', String(tage)); } catch {}
  zeichneVola();
}

// Schlichtes Linien-Chart mit Zahlen auf der x-Achse und Tooltip an der Zeigerstelle.
// serien: [{ name, klasse, werte: [Zahl|null], strich }]
// senkrecht: [{ x, text, titel }] mit kurzer Beschriftung oben; bei Platzmangel in einer zweiten Reihe.
function kurvenChart(feld, { xs, xText, xName, serien, senkrecht = [], hoehe = 220, einheit = '%', titelX }) {
  feld.innerHTML = ''; // erst leeren: sonst misst das Feld die Breite des alten Charts mit
  const breite = feld.clientWidth;
  if (!breite) return;
  const alle = serien.flatMap((s) => s.werte).filter((v) => v !== null && Number.isFinite(v));
  if (!alle.length) { feld.innerHTML = '<p class="klein">Keine gehandelten Werte.</p>'; return; }
  const links = 44, rechts = 12, unten = 30;
  const x = (v) => links + ((v - xs[0]) / (xs.at(-1) - xs[0])) * (breite - links - rechts);
  // Termin-Beschriftungen in Reihen verteilen, damit nichts übereinanderliegt.
  const reihenEnde = [];
  const marken = senkrecht.filter((s) => s.x >= xs[0] && s.x <= xs.at(-1)).map((s) => {
    const breiteText = s.text.length * 6.6 + 6;
    const lage = begrenzt(x(s.x), links + breiteText / 2, breite - rechts - breiteText / 2);
    let reihe = reihenEnde.findIndex((ende) => ende < lage - breiteText / 2 - 4);
    if (reihe < 0) { reihe = reihenEnde.length; reihenEnde.push(0); }
    reihenEnde[reihe] = lage + breiteText / 2;
    return { ...s, lage, reihe };
  });
  const oben = 12 + reihenEnde.length * 14;
  let tief = Math.min(...alle), hoch = Math.max(...alle);
  const schritt = [0.5, 1, 2, 2.5, 5, 10, 20].find((s) => (hoch - tief) / s <= 4) ?? 25;
  tief = Math.floor(tief / schritt) * schritt; hoch = Math.ceil(hoch / schritt) * schritt;
  if (hoch === tief) hoch = tief + schritt;
  const y = (v) => oben + ((hoch - v) / (hoch - tief)) * (hoehe - oben - unten);
  const ticks = [];
  for (let t = tief; t <= hoch + 1e-9; t += schritt) ticks.push(t);
  const fmt = new Intl.NumberFormat('de-DE', { maximumFractionDigits: schritt < 1 ? 1 : 0 });
  const pfad = (werte) => {
    let d = '', offen = false;
    werte.forEach((v, i) => {
      if (v === null || !Number.isFinite(v)) { offen = false; return; }
      d += `${offen ? 'L' : 'M'}${x(xs[i]).toFixed(1)} ${y(v).toFixed(1)}`;
      offen = true;
    });
    return d;
  };
  feld.innerHTML = `<div class="lc"><svg width="${breite}" height="${hoehe}" viewBox="0 0 ${breite} ${hoehe}">
      ${ticks.map((t) => `<line class="lc-gitter" x1="${links}" x2="${breite - rechts}" y1="${y(t)}" y2="${y(t)}"/><text class="c-achse" x="${links - 8}" y="${y(t) + 4}" text-anchor="end">${fmt.format(t)} ${einheit}</text>`).join('')}
      ${marken.map((s) => `<g ${tipAttr(s.titel)}><line class="v-termin duenn" x1="${x(s.x)}" x2="${x(s.x)}" y1="${12 + s.reihe * 14 + 3}" y2="${hoehe - unten}"/>
        <text class="v-termin-text" x="${s.lage}" y="${10 + s.reihe * 14}" text-anchor="middle">${esc(s.text)}</text></g>`).join('')}
      ${xText.map(([v, t]) => `<text class="c-achse" x="${x(v)}" y="${hoehe - 12}" text-anchor="middle">${t}</text>`).join('')}
      ${titelX ? `<text class="c-achse v-achs-titel" x="${breite - rechts}" y="${hoehe}" text-anchor="end">${titelX}</text>` : ''}
      ${serien.map((s) => `<path class="lc-linie ${s.klasse}" d="${pfad(s.werte)}"${s.strich ? ' stroke-dasharray="5 4"' : ''}/>`).join('')}
      <line class="lc-zeiger" y1="${oben}" y2="${hoehe - unten}" visibility="hidden"/>
    </svg><div class="c-tip lc-tip" hidden></div></div>
    ${serien.length > 1 ? `<p class="lc-legende">${serien.map((s) => `<span class="${s.klasse}"><i${s.strich ? ' class="strich"' : ''}></i>${esc(s.name)}</span>`).join('')}</p>` : ''}`;
  const svg = feld.querySelector('svg'), tip = feld.querySelector('.lc-tip'), zeiger = feld.querySelector('.lc-zeiger');
  const zeigen = (e) => {
    const px = e.clientX - svg.getBoundingClientRect().left;
    const wert = xs[0] + ((px - links) / (breite - links - rechts)) * (xs.at(-1) - xs[0]);
    const i = xs.reduce((best, v, k) => (Math.abs(v - wert) < Math.abs(xs[best] - wert) ? k : best), 0);
    zeiger.setAttribute('x1', x(xs[i])); zeiger.setAttribute('x2', x(xs[i])); zeiger.setAttribute('visibility', 'visible');
    const vorher = i ? xs[i - 1] : -Infinity;
    const termin = marken.filter((s) => s.x > vorher && s.x <= xs[i]).map((s) => `<small>${esc(s.titel)}</small>`).join('');
    tip.innerHTML = `<small>${esc(xName(xs[i]))}</small>${serien.map((s) => `<div class="${s.klasse}"><span><i></i>${esc(s.name)}</span><span>${s.werte[i] === null ? '–' : `${vol1.format(s.werte[i])} ${einheit}`}</span></div>`).join('')}${termin}`;
    tip.hidden = false;
    const platz = tip.offsetWidth + 12;
    tip.style.left = `${x(xs[i]) + platz < breite ? x(xs[i]) + 12 : Math.max(0, x(xs[i]) - platz)}px`;
  };
  svg.addEventListener('pointermove', zeigen);
  svg.addEventListener('pointerdown', zeigen);
  svg.addEventListener('pointerleave', () => { tip.hidden = true; zeiger.setAttribute('visibility', 'hidden'); });
}

function zeichneVolaSchnitte(d) {
  if (!d.tage.includes(volaSchnitt.tage)) volaSchnitt.tage = 30;
  const i = d.tage.indexOf(volaSchnitt.tage);
  // Nur gehandelte Strikes zeigen; fortgeschriebene Randwerte bleiben in den Schnitten weg.
  const zeile = (raster, k) => raster[k].map((v, j) => (d.geschaetzt[k][j] ? null : v));
  const vergleiche = [['gestern', 'Vortag'], ['woche', 'vor 1 Woche']].filter(([s]) => d[s]);
  // Smile
  el('v-smile-tage').innerHTML = [7, 14, 30, 60, 90, 180].map((t) => `<button type="button" data-tage="${t}" aria-pressed="${t === volaSchnitt.tage}">${tageText(t)}</button>`).join('');
  setzePille(el('v-smile-tage'), true); // die Knöpfe sind neu, die Pille muss neu ausgerichtet werden
  el('v-smile-titel').textContent = `Smile bei ${volaSchnitt.tage} Tagen Restlaufzeit`;
  const xs = d.moneyness;
  kurvenChart(el('v-smile'), {
    xs, xText: xs.filter((m) => m % 10 === 0).map((m) => [m, m === 100 ? 'aktueller Kurs' : `${m} %`]),
    titelX: 'Strike in % vom Kurs →', xName: (m) => `Strike ${m} % vom Kurs ≈ ${dollar.format((d.kurs * m) / 100)}`,
    serien: [{ name: `Heute (${kurzDatum(d.datum)})`, klasse: 'lc-neutral', werte: zeile(d.iv, i) },
      ...vergleiche.map(([s, name], k) => ({ name: `${name} (${kurzDatum(d[s].datum)})`, klasse: k ? 'lc-gold' : 'lc-grau', werte: zeile(d[s].iv, i), strich: true }))],
  });
  // Laufzeitstruktur am Geld und bei 90 % (Absicherung nach unten).
  const spalte = (raster, m) => raster.map((z, k) => (d.geschaetzt[k][d.moneyness.indexOf(m)] ? null : z[d.moneyness.indexOf(m)]));
  kurvenChart(el('v-struktur'), {
    xs: d.tage, xText: [30, 60, 90, 120, 150, 180].map((t) => [t, tageText(t)]),
    titelX: 'Restlaufzeit →', xName: (t) => `${t} Tage Restlaufzeit`,
    senkrecht: d.termine.map((t) => ({ x: t.tage, text: t.kurz, titel: `${t.name}, ${lokal(t.datum).toLocaleDateString('de-DE')}` })),
    serien: [{ name: 'aktueller Kurs (100 %)', klasse: 'lc-neutral', werte: spalte(d.iv, 100) },
      { name: '90 % (Absturz-Schutz)', klasse: 'lc-gold', werte: spalte(d.iv, 90) },
      ...vergleiche.slice(0, 1).map(([s, name]) => ({ name: `100 %, ${name}`, klasse: 'lc-grau', werte: spalte(d[s].iv, 100), strich: true }))],
  });
}

// Tooltip im 3D-Bild: das vorderste Viereck unter dem Zeiger, darin die nächste Ecke.
let volaZug = null;
function volaTipAmZeiger(e) {
  if (!volaLage || volaZug?.bewegt) return;
  const kasten = el('v-canvas').getBoundingClientRect();
  const px = e.clientX - kasten.left, py = e.clientY - kasten.top;
  const innen = (ecken) => {
    let drin = false;
    for (let a = 0, b = ecken.length - 1; a < ecken.length; b = a++) {
      const [xa, ya] = ecken[a], [xb, yb] = ecken[b];
      if ((ya > py) !== (yb > py) && px < ((xb - xa) * (py - ya)) / (yb - ya) + xa) drin = !drin;
    }
    return drin;
  };
  const q = [...volaLage.vierecke].reverse().find((v) => innen(v.ecken));
  if (!q) { volaTipWeg(); return; }
  const { d, r, P, spalten } = volaLage;
  const abstand = ([a, b]) => Math.hypot(P[a][b][0] - px, P[a][b][1] - py);
  const [i, jj] = [[q.i, q.j], [q.i, q.j + 1], [q.i + 1, q.j + 1], [q.i + 1, q.j]].sort((a, b) => abstand(a) - abstand(b))[0];
  const j = spalten[jj];
  if (!volaMarke || volaMarke[0] !== i || volaMarke[1] !== jj) { volaMarke = [i, jj]; volaNeuZeichnen(); }
  const vorher = i ? d.tage[i - 1] : 0;
  const termine = d.termine.filter((t) => t.tage > vorher && t.tage <= d.tage[i]);
  const tip = el('v-tip');
  tip.innerHTML = `<b>${vol1.format(d.iv[i][j])} % IV</b><small>${d.moneyness[j]} % vom Kurs · ${d.tage[i]} Tage</small>
    <div><span>Strike</span><span>≈ ${dollar.format((d.kurs * d.moneyness[j]) / 100)}</span></div>
    ${r.art === 'diff' ? `<div><span>seit ${kurzDatum(r.seit)}</span><span>${volPkt.format(r.werte[i][j])} Pkt.</span></div>` : ''}
    ${d.oi ? `<div><span>Open Interest</span><span>${ganzeZahl.format(d.oi[i][j])}</span></div><div><span>Volumen</span><span>${ganzeZahl.format(d.volumen[i][j])}</span></div>` : ''}
    ${d.geschaetzt[i][j] ? '<div><span>kein Strike gehandelt</span><span>fortgeschrieben</span></div>' : ''}
    ${termine.map((t) => `<small>Termin davor: ${esc(t.name)}, ${kurzDatum(t.datum)}</small>`).join('')}`;
  tip.hidden = false;
  const p = P[i][jj];
  tip.style.left = `${p[0] + 14 + tip.offsetWidth < kasten.width ? p[0] + 14 : Math.max(0, p[0] - 14 - tip.offsetWidth)}px`;
  tip.style.top = `${Math.max(0, Math.min(kasten.height - tip.offsetHeight, p[1] - tip.offsetHeight / 2))}px`;
}
function volaTipWeg() {
  el('v-tip').hidden = true;
  if (volaMarke) { volaMarke = null; volaNeuZeichnen(); }
}
const volaJetztZeichnen = () => {
  const d = volaDaten[volaWahl.ticker];
  if (d && !d.fehler && volaWahl.form === '3d' && volaRaster(d)) zeichneVola3d(d, volaFarben());
};
let volaGeplant = false;
function volaNeuZeichnen() {
  if (volaGeplant) return;
  volaGeplant = true;
  requestAnimationFrame(() => { volaGeplant = false; volaJetztZeichnen(); });
}
// Zoomen gleitet weich zum Ziel, statt in großen Sprüngen zu springen.
let volaZoomLauf = null;
function volaZoomAuf(ziel) {
  volaKamera.ziel = begrenzt(ziel, ...VOLA_ZOOM);
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) { volaKamera.zoom = volaKamera.ziel; volaNeuZeichnen(); return; }
  if (volaZoomLauf) return;
  const schritt = () => {
    const rest = volaKamera.ziel - volaKamera.zoom;
    volaKamera.zoom = Math.abs(rest) < 0.002 ? volaKamera.ziel : volaKamera.zoom + rest * 0.2;
    volaJetztZeichnen();
    volaZoomLauf = volaKamera.zoom === volaKamera.ziel ? null : requestAnimationFrame(schritt);
  };
  volaZoomLauf = requestAnimationFrame(schritt);
}

// Drehen: ziehen (Maus oder ein Finger). Zoomen: Strg + Mausrad oder zwei Finger. Doppelklick: zurück.
const volaFinger = new Map();
const vc = el('v-canvas');
vc.addEventListener('pointerdown', (e) => {
  if (e.pointerType === 'mouse' && e.button !== 0) return;
  volaFinger.set(e.pointerId, [e.clientX, e.clientY]);
  if (volaFinger.size === 2) {
    const [a, b] = [...volaFinger.values()];
    volaZug = { art: 'zwei', abstand: Math.max(20, Math.hypot(a[0] - b[0], a[1] - b[1])), zoom: volaKamera.zoom, bewegt: true };
  } else {
    volaZug = { art: 'dreh', x: e.clientX, y: e.clientY, dreh: volaKamera.dreh, neig: volaKamera.neig, bewegt: false };
  }
  try { vc.setPointerCapture(e.pointerId); } catch {}
});
vc.addEventListener('pointermove', (e) => {
  if (!volaZug) { volaTipAmZeiger(e); return; }
  if (!volaFinger.has(e.pointerId)) return;
  volaFinger.set(e.pointerId, [e.clientX, e.clientY]);
  if (volaZug.art === 'zwei') {
    const [a, b] = [...volaFinger.values()];
    volaKamera.zoom = volaKamera.ziel = begrenzt((volaZug.zoom * Math.hypot(a[0] - b[0], a[1] - b[1])) / volaZug.abstand, ...VOLA_ZOOM);
  } else {
    const dx = e.clientX - volaZug.x, dy = e.clientY - volaZug.y;
    if (!volaZug.bewegt && Math.hypot(dx, dy) < 3) return;
    volaZug.bewegt = true;
    vc.classList.add('zieht');
    el('v-tip').hidden = true;
    volaMarke = null;
    volaKamera.dreh = volaZug.dreh + dx * 0.008;
    volaKamera.neig = begrenzt(volaZug.neig + dy * 0.006, 0.12, 1.45);
  }
  volaNeuZeichnen();
});
const volaLoslassen = (e) => {
  volaFinger.delete(e.pointerId);
  if (volaFinger.size) return;
  const war = volaZug;
  volaZug = null;
  vc.classList.remove('zieht');
  if (war && !war.bewegt) {
    // Tippen: Wert zeigen und die Laufzeit an dieser Stelle als Smile unten übernehmen.
    volaTipAmZeiger(e);
    const d = volaDaten[volaWahl.ticker];
    if (volaMarke && d) { volaSchnitt.tage = d.tage[volaMarke[0]]; try { localStorage.setItem('volaSmile', String(volaSchnitt.tage)); } catch {} zeichneVolaSchnitte(d); volaNeuZeichnen(); }
  }
};
vc.addEventListener('pointerup', volaLoslassen);
vc.addEventListener('pointercancel', volaLoslassen);
vc.addEventListener('pointerleave', () => { if (!volaZug) volaTipWeg(); });
vc.addEventListener('wheel', (e) => {
  if (!(e.ctrlKey || e.metaKey)) return; // normales Scrollen bewegt weiter die Seite
  e.preventDefault();
  const delta = begrenzt(e.deltaY * (e.deltaMode === 1 ? 16 : 1), -120, 120); // ein Raststufe = höchstens ca. 15 %
  volaZoomAuf(volaKamera.ziel * Math.exp(-delta * 0.0012));
}, { passive: false });
vc.addEventListener('dblclick', () => { Object.assign(volaKamera, VOLA_KAMERA_START); volaNeuZeichnen(); });
vc.addEventListener('keydown', (e) => {
  const schritt = { ArrowLeft: [-0.1, 0], ArrowRight: [0.1, 0], ArrowUp: [0, -0.08], ArrowDown: [0, 0.08] }[e.key];
  if (schritt) { volaKamera.dreh += schritt[0]; volaKamera.neig = begrenzt(volaKamera.neig + schritt[1], 0.12, 1.45); }
  else if (e.key === '+' || e.key === '=') { e.preventDefault(); volaZoomAuf(volaKamera.ziel * 1.12); return; }
  else if (e.key === '-') { e.preventDefault(); volaZoomAuf(volaKamera.ziel / 1.12); return; }
  else if (e.key === '0') Object.assign(volaKamera, VOLA_KAMERA_START);
  else return;
  e.preventDefault();
  volaNeuZeichnen();
});

// Drei Kennzahlen mit Einordnung und Verlauf.
const VOLA_KENNZAHLEN = [
  { name: 'atm30', titel: 'ATM-IV 30 Tage', wert: (v) => `${vol1.format(v)} %`, text: 'Erwartete Schwankung pro Jahr, Strike am Kurs, 30 Tage Laufzeit.' },
  { name: 'skew25', titel: 'Skew 25 Delta', wert: (v) => `${vol1.format(v)} Pkt.`, text: 'IV des 25-Delta-Puts minus 25-Delta-Call (30 Tage): Aufpreis für Schutz nach unten.' },
  { name: 'steigung', titel: 'Laufzeitstruktur', wert: (v) => `${volPkt.format(v)} Pkt.`, text: 'ATM-IV 90 Tage minus 30 Tage. Positiv ist normal, negativ heißt Stress.' },
];
const STUFE_KLASSE = { normal: 'normal', 'erhöht': 'erhoeht', Stress: 'stress' };
function volaTagesverlauf(d, name) {
  const reihe = (d.tagesverlauf ?? []).filter((p) => p[name] !== null && p[name] !== undefined);
  if (reihe.length < 2) return '';
  const w = reihe.map((p) => p[name]); const min = Math.min(...w), max = Math.max(...w);
  const linie = w.map((v, i) => `${(i / (w.length - 1) * 100).toFixed(1)},${(30 - (v - min) / ((max - min) || 1) * 26).toFixed(1)}`).join(' ');
  const zeit = (iso) => new Date(iso).toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' });
  const diff = w.at(-1) - w[0];
  return `<div class="v-tag"><p class="klein">Heute ${zeit(reihe[0].zeit)}–${zeit(reihe.at(-1).zeit)} Uhr: <b class="${diff > 0 ? 'minus' : diff < 0 ? 'plus' : ''}">${diff >= 0 ? '+' : '−'}${volPkt.format(Math.abs(diff))} Pkt.</b></p>
    <svg viewBox="0 0 100 32" preserveAspectRatio="none" class="v-tag-linie"><polyline points="${linie}" fill="none" stroke="currentColor" stroke-width="1.5" vector-effect="non-scaling-stroke"/></svg></div>`;
}
function zeichneVolaKennzahlen(d) {
  el('v-kennzahlen').innerHTML = VOLA_KENNZAHLEN.map((k) => {
    const v = d.kennzahlen[k.name], e = d.einordnung[k.name];
    return `<article class="karte v-kz">
      <h2>${k.titel}</h2>
      <p class="kennzahl">${v === null ? '–' : k.wert(v)}</p>
      ${e.stufe ? `<p class="v-stufe ${STUFE_KLASSE[e.stufe]}"><i aria-hidden="true"></i>${e.stufe}</p>` : ''}
      <p class="sekundaer">${esc(k.text)} ${esc(e.text)}.</p>
      ${volaTagesverlauf(d, k.name)}
      <div class="v-verlauf" id="v-verlauf-${k.name}"></div>
    </article>`;
  }).join('');
  for (const k of VOLA_KENNZAHLEN) {
    const ziel = el(`v-verlauf-${k.name}`);
    const reihe = d.verlauf.filter((p) => p[k.name] !== null && p[k.name] !== undefined);
    if (reihe.length < 2) {
      ziel.innerHTML = `<p class="klein">Verlauf entsteht: ${reihe.length} Handelstag${reihe.length === 1 ? '' : 'e'} gespeichert, jeden Abend kommt einer dazu.</p>`;
      continue;
    }
    linienChart(ziel, { daten: reihe.map((p) => p.datum), serien: [{ name: k.titel, klasse: 'lc-neutral', werte: reihe.map((p) => p[k.name]) }], hoehe: 120, format: (v) => (k.name === 'atm30' ? `${vol1.format(v)} %` : `${volPkt.format(v)} Pkt.`) });
  }
}

function zeigeVola() {
  const d = volaDaten[volaWahl.ticker];
  el('v-ticker').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.ticker === volaWahl.ticker)));
  el('v-ansicht').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.ansicht === volaWahl.ansicht)));
  el('v-form').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.form === volaWahl.form)));
  el('v-ausschnitt').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.ausschnitt === volaWahl.ausschnitt)));
  el('v-farbe').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.farbe === volaWahl.farbe)));
  el('v-handel').querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.handel === volaWahl.handel)));
  el('v-hilfe').innerHTML = volaWahl.form === '3d'
    ? `<span>${grobZeiger ? 'Ein Finger: drehen · zwei Finger: zoomen · tippen: Wert' : 'Ziehen: drehen · Strg + Mausrad: zoomen · Doppelklick: Ansicht zurücksetzen'}</span>`
    : '<span>Fahr über ein Feld für den Wert, Klick zeigt den Smile dieser Laufzeit</span>';
  if (!d) {
    el('v-fazit').innerHTML = '';
    el('v-fuermich').hidden = true;
    el('v-status').textContent = 'Wird geladen … Beim ersten Mal dauert es einige Sekunden, die Optionsketten kommen von Yahoo.';
    return;
  }
  if (d.fehler) { el('v-fazit').innerHTML = ''; el('v-fuermich').hidden = true; el('v-status').textContent = d.fehler; el('v-stand').textContent = ''; el('v-kennzahlen').innerHTML = ''; zeichneVola(); return; }
  el('v-fazit').innerHTML = volaFazit(d);
  el('v-fuermich').innerHTML = volaFuerMich(d);
  el('v-fuermich').hidden = false;
  el('v-status').textContent = !d.verlauf.length
    ? `Neu: ${d.ticker} wird ab heute jeden Abend nach US-Börsenschluss gespeichert (solange du es in den nächsten 30 Tagen wieder ansiehst). Vergleiche entstehen mit der Zeit.`
    : `Gespeichert seit ${lokal(d.erster_tag).toLocaleDateString('de-DE')}: ${d.verlauf.length} Handelstag${d.verlauf.length === 1 ? '' : 'e'}.`;
  el('v-stand').innerHTML = d.live
    ? `${esc(d.ticker)} ${dollar.format(d.kurs)} · <span class="v-live">Live</span> Stand ${new Date(d.abgerufen).toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' })} Uhr, etwa 15 Minuten verzögert, alle 30 Minuten neu · Vergleiche gegen Schlussflächen · ${d.verfaelle.length} Verfälle`
    : `${esc(d.ticker)} ${dollar.format(d.kurs)} · Schlusskurse vom ${datumLang(d.datum)} · einmal täglich nach US-Börsenschluss, während des Handels alle 30 Minuten · ${d.verfaelle.length} Verfälle ausgewertet`;
  el('v-ansicht').querySelector('[data-ansicht="earnings"]').hidden = Boolean(d.index);
  const staende = [...(d.archiv ?? [])].reverse();
  el('v-frei').innerHTML = `<option value="">Seit … (gespeicherter Stand)</option>${staende.map((f) => { const k = `${f.art}|${f.zeit ?? f.datum}`; return `<option value="${esc(k)}" ${volaWahl.ansicht === 'frei' && volaWahl.frei === k ? 'selected' : ''}>Seit ${esc(volaStandName(f))}</option>`; }).join('')}`;
  el('v-frei').disabled = !staende.length;
  el('v-abspielen').disabled = (d.archiv?.length ?? 0) < 3;
  el('v-abspielen').title = (d.archiv?.length ?? 0) < 3 ? 'Abspielen geht ab 3 gespeicherten Handelstagen' : `Die gespeicherten Flächen der letzten ${d.archiv.length} Handelstage nacheinander zeigen`;
  zeichneVola();
  zeichneVolaKennzahlen(d);
}



// ---- Volatilitäts-Risikoprämie je Wert (Roadmap Q5): app/nutzer/vrp.py ----
let vrpDaten = null;
async function vrpLaden() {
  if (!vrpDaten) {
    el('sw-vrp').innerHTML = '<section class="karte th-karte"><p class="sekundaer">Risikoprämie deiner Werte wird gerechnet …</p></section>';
    try { vrpDaten = await api('/api/vrp'); } catch { vrpDaten = { fehler: 'Die Risikoprämie konnte nicht geladen werden.' }; }
  }
  const d = vrpDaten;
  if (d.fehler) { el('sw-vrp').innerHTML = `<section class="karte th-karte">${ggFehler(d)}</section>`; return; }
  const teuer = d.werte.filter((w) => w.einordnung === 'Absicherung teuer').map((w) => w.ticker);
  const guenstig = d.werte.filter((w) => w.einordnung === 'Absicherung günstig').map((w) => w.ticker);
  const lage = `${teuer.length ? `Absicherung gerade teuer (IV mindestens 1,3-fach der realisierten Schwankung): ${teuer.map(esc).join(', ')}. ` : ''}${guenstig.length ? `Eher günstig (IV unter der realisierten): ${guenstig.map(esc).join(', ')}. ` : ''}Optionsscheine auf teure Werte kauft man mit viel bezahlter Schwankung ein; Faktor-Zertifikate leiden dagegen unter hoher realisierter Schwankung.`;
  const spur = (v) => {
    if (!v || v.praemie.length < 2) return '';
    const w = v.praemie, lo = Math.min(...w, 0), hi = Math.max(...w, 0), n = w.length - 1;
    const y = (x) => 29 - ((x - lo) / (hi - lo || 1)) * 28;
    return `<svg class="sw-spur" viewBox="0 0 100 30" preserveAspectRatio="none" aria-hidden="true"><line x1="0" x2="100" y1="${y(0)}" y2="${y(0)}" class="vrp-null"/><polyline points="${w.map((x, i) => `${(i / n) * 100},${y(x)}`).join(' ')}"/></svg>`;
  };
  el('sw-vrp').innerHTML = ggKarte('vrp-karte', 'Volatilitäts-Risikoprämie', [
    ['Was es zeigt', 'Implizite Volatilität (was Optionen für die nächsten rund 30 Tage einpreisen) minus realisierte Volatilität der letzten 20 Tage. Normal liegt die IV etwas darüber: Anleger zahlen eine Prämie für Schutz.'],
    ['Lesart', 'Ab 1,3-fach gilt Absicherung als teuer (Puts, Optionsscheine), unter 0,9-fach als günstig. Lagen Quartalszahlen in den letzten 20 Tagen, bläht der Sprung die realisierte Schwankung auf; dann steht „unklar“.'],
    ['Perzentil', 'Wo die Prämie heute im eigenen Verlauf liegt. SPY und QQQ über VIX und VXN mit einem Jahr; deine Aktien aus Vinters eigener Sammlung (abends eine Fläche), erst ab 20 Tagen.'],
    ['Hebelprodukte', 'Optionsscheine enthalten die IV im Preis: Bei hoher IV zahlst du viel Zeitwert, der bis zum Verfall abschmilzt. Faktor-Zertifikate haben keine IV im Preis, verlieren aber bei hoher tatsächlicher Schwankung durch die tägliche Anpassung (Volatility Decay).'],
  ], `${ggLage(lage)}${ggTabelle(['Wert', 'IV 30 T.', 'Realisiert 20 T.', 'Prämie', 'IV / RV', 'Perzentil', 'Verlauf', 'Einordnung'], d.werte.map((w) => `<tr>
      <td><b>${esc(w.name)}</b> <small class="sekundaer">${esc(w.ticker)}</small></td><td>${gz1.format(w.iv)} %<br><small class="sekundaer">${esc(w.quelle ?? '')}</small></td><td>${gz1.format(w.rv20)} %</td>
      <td class="${klasse(w.praemie)}">${ggVz(w.praemie, gz1)} Pkt.</td><td>${w.verhaeltnis ? `${gz2.format(w.verhaeltnis)}-fach` : '–'}</td>
      <td>${w.perzentil !== undefined ? `${gz0.format(w.perzentil)}.` : `<small class="sekundaer">${w.tage} von 20 Tagen</small>`}</td><td>${spur(w.verlauf)}</td>
      <td>${esc(w.einordnung)}${w.zahlen_im_fenster ? `<br><small class="sekundaer">Zahlen ${datumDe(w.zahlen_im_fenster)}</small>` : ''}</td></tr>`), 'vrp-tabelle')}`);
}

// ---- Schwankung des Werts und Depot-Rangliste (Volatilitäts-Seite): app/markt/schwankung.py, app/nutzer/schwankung.py ----
let swTicker = null, swDaten = {}, swDepot = null;
const swV = (v) => (v === null || v === undefined ? '–' : `${gz1.format(v)} %`);
const SW_STUFE = { unruhig: ['unruhig', 'minus'], ruhig: ['ruhig', 'plus'], normal: ['normal', ''] };

async function swLaden(ticker) {
  swTicker = ticker;
  if (!swDaten[ticker]) {
    el('sw-wert').innerHTML = `<section class="karte th-karte"><p class="sekundaer">Schwankung von ${esc(ticker)} wird gerechnet …</p></section>`;
    try { swDaten[ticker] = await api(`/api/schwankung?ticker=${encodeURIComponent(ticker)}`); } catch { swDaten[ticker] = { fehler: 'Die Schwankung konnte nicht geladen werden.' }; }
  }
  if (ticker === swTicker) swWertZeichnen();
}

function swKegel(kegel) {
  const hoch = Math.max(...kegel.map((k) => Math.max(k.max, k.jetzt))) * 1.05;
  const x = (v) => `${(v / hoch) * 100}%`;
  return `<div class="sw-kegel" role="img" aria-label="Vola-Kegel">${kegel.map((k) => `
    <div class="sw-k-zeile" title="${k.fenster} Tage: Spanne ${gz1.format(k.min)}–${gz1.format(k.max)} %, Median ${gz1.format(k.median)} %, heute ${gz1.format(k.jetzt)} % (höher als an ${gz0.format(k.perzentil)} % der Tage)">
      <span class="sw-k-name">${k.fenster} T.</span>
      <span class="sw-k-bahn">
        <i class="sw-k-spanne" style="left:${x(k.min)};width:calc(${x(k.max)} - ${x(k.min)})"></i>
        <i class="sw-k-kasten" style="left:${x(k.q25)};width:calc(${x(k.q75)} - ${x(k.q25)})"></i>
        <i class="sw-k-median" style="left:${x(k.median)}"></i>
        <i class="sw-k-jetzt ${k.perzentil >= 90 ? 'hoch' : k.perzentil <= 10 ? 'tief' : ''}" style="left:${x(k.jetzt)}"></i>
      </span>
      <span class="sw-k-wert">${gz1.format(k.jetzt)} % <small>${gz0.format(k.perzentil)}. Pz.</small></span>
    </div>`).join('')}
    <p class="sw-k-achse"><span>0 %</span><span>${gz0.format(hoch / 2)} %</span><span>${gz0.format(hoch)} %</span></p></div>`;
}

function swWertZeichnen() {
  const d = swDaten[swTicker];
  if (!d || d.fehler) { el('sw-wert').innerHTML = `<section class="karte th-karte">${ggFehler(d)}</section>`; return; }
  const k20 = d.kegel.find((k) => k.fenster === 20);
  const iv = d.iv;
  // Satz oben: Lage der 20-Tage-Vola und (bei US-Werten) ob Optionen teuer oder billig wirken
  let lage = k20 ? `${esc(d.ticker)} schwankt auf 20 Tage mit ${gz1.format(d.rv[20])} % aufs Jahr gerechnet, ${k20.perzentil >= 90 ? 'ungewöhnlich stark' : k20.perzentil >= 70 ? 'eher stark' : k20.perzentil <= 10 ? 'ungewöhnlich ruhig' : k20.perzentil <= 30 ? 'eher ruhig' : 'im üblichen Rahmen'}: höher als an ${gz0.format(k20.perzentil)} % der Tage der letzten 3 Jahre (Median ${gz1.format(k20.median)} %).` : '';
  if (iv?.verhaeltnis) {
    lage += ` Der Optionsmarkt erwartet ${gz1.format(iv.atm30)} % (${esc(iv.quelle === 'gespeicherte Flächen' ? 'ATM-IV 30 Tage' : iv.quelle)}), ${iv.verhaeltnis >= 1.2 ? 'deutlich mehr als zuletzt tatsächlich: Optionen wirken teuer' : iv.verhaeltnis <= 0.85 ? 'weniger als zuletzt tatsächlich: Optionen wirken günstig' : 'etwa so viel wie zuletzt tatsächlich'}.`;
  }
  const chip = (t, w, u = '') => `<div class="st-chip"><span>${t}</span><b>${w}</b>${u ? `<small>${u}</small>` : ''}</div>`;
  const ivRang = iv?.rang ? `${gz0.format(iv.rang.rang)}` : '–';
  const chips = `<div class="st-chips">
    ${chip('10 Tage', swV(d.rv[10]))}${chip('20 Tage', swV(d.rv[20]), 'Schluss zu Schluss')}${chip('60 Tage', swV(d.rv[60]))}${chip('1 Jahr', swV(d.rv[252]))}
    ${chip('Parkinson 20 T.', swV(d.parkinson20), d.hoch_tief ? 'aus Hoch und Tief' : 'keine echten Hoch/Tief-Daten')}
    ${chip('Yang-Zhang 20 T.', swV(d.yang_zhang20), d.hoch_tief ? 'mit Kurslücken über Nacht' : '')}
    ${chip('ATR 14', d.atr ? `${zahl2.format(d.atr)} ${esc(d.waehrung ?? '')}` : '–', d.atr_prozent ? `${gz1.format(d.atr_prozent)} % vom Kurs je Tag` : '')}
    ${iv ? chip('IV 30 Tage', swV(iv.atm30), `${esc(iv.quelle)}, Stand ${datumDe(iv.stand)}`) : ''}
    ${iv ? chip('IV − realisiert', iv.gegen_rv20 === null ? '–' : `${ggVz(iv.gegen_rv20, gz1)} Pkt.`, iv.verhaeltnis ? `${gz1.format(iv.verhaeltnis)}-fach der 20-Tage-Vola` : '') : ''}
    ${iv ? chip('IV-Rang / -Perzentil', iv.rang ? `${ivRang} / ${gz0.format(iv.rang.perzentil)}` : '–', iv.rang ? `1 Jahr: ${gz1.format(iv.rang.tief)}–${gz1.format(iv.rang.hoch)} %` : `ab ${iv.min_tage} gespeicherten Tagen (bisher ${iv.tage})`) : ''}
  </div>`;
  let crush = '';
  if (d.crush !== undefined) {
    crush = d.crush.length
      ? ggTabelle(['Earnings', 'IV 7 Tage davor', 'danach', 'Veränderung'], d.crush.map((c) => `<tr><td>${datumDe(c.termin)}</td><td>${swV(c.vor)}</td><td>${swV(c.nach)}</td><td class="${klasse(c.veraenderung)}">${ggPz(c.veraenderung)}</td></tr>`), 'sw-tabelle')
      : '<p class="sekundaer klein">Noch keine Earnings seit Beginn der eigenen IV-Aufzeichnung für diesen Wert. Die Tabelle füllt sich nach den nächsten Zahlen (gespeichert wird abends automatisch).</p>';
    crush = `<h3 class="pg-unter">IV-Crush nach Earnings</h3>${crush}`;
  }
  el('sw-wert').innerHTML = ggKarte('sw-karte', `Schwankung: ${d.ticker}`, [
    ['Realisierte Volatilität', 'Wie stark der Kurs tatsächlich geschwankt hat, aufs Jahr gerechnet (Standardabweichung der Tagesrenditen mal Wurzel aus 252). 30 % heißt grob: in einem Jahr sind ±30 % eine normale Spanne, an einem Tag etwa ±1,9 %.'],
    ['Parkinson und Yang-Zhang', 'Genauere Schätzer, die Hoch und Tief jedes Tages nutzen statt nur den Schlusskurs. Parkinson sieht Ausschläge innerhalb des Tages, übersieht aber Kurslücken über Nacht; Yang-Zhang nimmt die Lücken dazu. Liegen sie deutlich über der Schluss-zu-Schluss-Zahl, war der Tagesverlauf unruhiger, als die Schlusskurse zeigen.'],
    ['Vola-Kegel', 'Für jedes Zeitfenster die Spanne aller Werte der letzten 3 Jahre: dünner Strich = Minimum bis Maximum, Kasten = mittlere Hälfte, senkrechter Strich = Median, Punkt = heute. Kurze Fenster schwanken stärker, deshalb ist der Kegel links breiter.'],
    ['ATR', 'Average True Range über 14 Tage: wie weit sich der Kurs an einem Tag typisch bewegt, inklusive Lücken. Grundlage für Stop-Abstände (z. B. 2 ATR).'],
    ['IV gegen realisiert', 'Die implizite Volatilität (IV) ist die Schwankung, die der Optionsmarkt für die nächsten 30 Tage einpreist. Liegt sie deutlich über der zuletzt tatsächlichen, sind Optionen teuer (meist vor Ereignissen oder nach Schocks), darunter eher günstig. Für SPY, QQQ, IWM und DIA nimmt Vinter die offiziellen Indizes VIX, VXN, RVX und VXD.'],
    ['IV-Rang und IV-Perzentil', 'Rang: wo die IV heute zwischen ihrem Tief (0) und Hoch (100) des letzten Jahres liegt. Perzentil: an wie viel Prozent der Tage sie niedriger war. Bei Einzelaktien aus Vinters eigener Sammlung (abends eine Fläche), deshalb erst ab 20 Tagen.'],
    ['IV-Crush', 'Vor Quartalszahlen steigt die IV der kurzen Optionen, danach fällt sie meist schlagartig. Gemessen an der ATM-IV mit 7 Tagen Laufzeit, letzter gespeicherter Tag vor und erster nach dem Termin.'],
  ], `${ggLage(lage)}${chips}
    <h3 class="pg-unter">Vola-Kegel (letzte 3 Jahre)</h3>${swKegel(d.kegel)}
    <h3 class="pg-unter">Verlauf: realisierte Vola 20 Tage${iv ? ' und IV' : ''} (1 Jahr)</h3><div class="r-grafik" id="sw-verlauf"></div>
    ${crush}`, `Stand ${datumDe(d.stand)}`);
  const serien = [{ name: 'Realisiert 20 Tage', klasse: 'lc-depot', werte: d.verlauf.rv20 }];
  if (d.verlauf.iv?.some((v) => v !== null)) serien.push({ name: `IV 30 Tage (${iv.quelle})`, klasse: 'lc-gold', werte: d.verlauf.iv });
  linienChart(el('sw-verlauf'), { daten: d.verlauf.daten, serien, format: (v) => `${gz1.format(v)} %`, hoehe: 220, nullpunkt: false });
}

async function swDepotLaden() {
  if (!swDepot) {
    el('sw-depot').innerHTML = '<section class="karte th-karte"><p class="sekundaer">Rangliste deiner Positionen wird gerechnet …</p></section>';
    try { swDepot = await api('/api/schwankung/depot'); } catch { swDepot = { fehler: 'Die Rangliste konnte nicht geladen werden.' }; }
  }
  const d = swDepot;
  if (d.fehler) { el('sw-depot').innerHTML = `<section class="karte th-karte">${ggFehler(d)}</section>`; return; }
  const markt = d.positionen.find((p) => /S&P 500|MSCI World/.test(p.name));
  const unruhig = d.positionen.filter((p) => p.stufe === 'unruhig' && !p.extra && !/S&P 500|MSCI World|FTSE|All-World/.test(p.name));
  const lage = unruhig.length
    ? `${unruhig.length} von ${d.positionen.filter((p) => !/S&P 500|MSCI World|FTSE|All-World/.test(p.name)).length} Einzelwerten schwanken gerade ungewöhnlich stark gemessen an ihrem eigenen Normalwert: ${unruhig.slice(0, 4).map((p) => `${esc(p.name)} (${gz1.format(p.verhaeltnis)}-fach)`).join(', ')}${unruhig.length > 4 ? ' …' : ''}.${markt?.stufe === 'unruhig' ? ` Der Gesamtmarkt ist selbst unruhig (${esc(markt.name)} ${gz1.format(markt.verhaeltnis)}-fach), es liegt also nicht nur an einzelnen Werten.` : ''}`
    : 'Keine Position schwankt gerade ungewöhnlich stark gemessen an ihrem eigenen Normalwert.';
  const spur = (werte) => {
    const w = werte.filter((v) => v !== null);
    if (w.length < 2) return '';
    const lo = Math.min(...w), hi = Math.max(...w), n = werte.length - 1;
    const pkt = werte.map((v, i) => (v === null ? null : `${(i / n) * 100},${30 - ((v - lo) / (hi - lo || 1)) * 28 - 1}`)).filter(Boolean).join(' ');
    return `<svg class="sw-spur" viewBox="0 0 100 30" preserveAspectRatio="none" aria-hidden="true"><polyline points="${pkt}"/></svg>`;
  };
  el('sw-depot').innerHTML = ggKarte('sw-depot-karte', 'Welche Positionen sind gerade unruhig?', [
    ['Was hier steht', 'Je Position die realisierte Vola der letzten 20 Tage gegen ihren eigenen Normalwert (Median der 20-Tage-Vola im letzten Jahr) und das Perzentil in den letzten 3 Jahren. Jede Aktie wird an sich selbst gemessen: Bitcoin ist immer wilder als ein Versorger.'],
    ['Stufen', 'Unruhig ab 1,5-fach des Normalwerts oder über dem 90. Perzentil, ruhig unter 0,7-fach.'],
    ['Klick', 'Eine Zeile anklicken zeigt die Details des Werts in der Karte darunter (auch für deutsche Werte).'],
  ], `${ggLage(lage)}${ggTabelle(['Position', 'Vola 20 T.', 'Normal', 'Verhältnis', 'Perzentil 3 J.', 'ATR/Tag', 'Letzte 60 Tage', 'Stufe'], d.positionen.map((p) => `<tr class="sw-zeile" data-sw="${esc(p.ticker)}" tabindex="0">
      <td><b>${esc(p.name)}</b>${p.gewicht ? ` <small class="sekundaer">${gz1.format(p.gewicht)} %</small>` : ''}</td>
      <td>${swV(p.rv20)}</td><td>${swV(p.median_jahr)}</td><td><b>${p.verhaeltnis ? `${gz1.format(p.verhaeltnis)}-fach` : '–'}</b></td>
      <td>${gz0.format(p.perzentil)}</td><td>${swV(p.atr_prozent)}</td><td>${spur(p.verlauf)}</td>
      <td class="${SW_STUFE[p.stufe][1]}">${SW_STUFE[p.stufe][0]}</td></tr>`), 'sw-tabelle')}
    ${d.ohne.length ? `<p class="klein sekundaer">Ohne genug Kurse: ${esc(d.ohne.join(', '))}</p>` : ''}`);
}
document.addEventListener('click', (e) => {
  const z = e.target.closest('[data-sw]');
  if (!z) return;
  swLaden(z.dataset.sw);
  el('sw-wert').scrollIntoView({ behavior: 'smooth', block: 'start' });
});
document.addEventListener('keydown', (e) => { if (e.key === 'Enter' && e.target.matches?.('[data-sw]')) e.target.click(); });

async function ladeVola(ticker = volaWahl.ticker, neu = false) {
  if (swTicker !== ticker) swLaden(ticker);
  swDepotLaden();
  vrpLaden();
  if (neu) { delete volaDaten[ticker]; delete antworten[`/api/volaflaeche?ticker=${encodeURIComponent(ticker)}`]; }
  zeigeVola();
  if (volaDaten[ticker] && !volaDaten[ticker].fehler) return;
  const pfad = `/api/volaflaeche?ticker=${encodeURIComponent(ticker)}`;
  let d;
  try { d = await api(pfad); } catch (f) {
    // 404: Die Seite ist neuer als der laufende Server, er kennt diese Adresse noch nicht.
    d = { fehler: f.message === '404'
      ? 'Der Server läuft noch mit dem alten Stand und kennt die Volatilitätsoberfläche nicht. Bitte den Server einmal neu starten (Fenster schließen, start.bat erneut öffnen).'
      : 'Die Volatilitätsoberfläche konnte nicht geladen werden. Läuft der Server noch?' };
  }
  if (d.fehler) delete antworten[pfad]; // beim nächsten Öffnen neu versuchen
  volaDaten[ticker] = d;
  if (!d.fehler) volaTickerKnoepfe(d.ticker_liste);
  if (ticker === volaWahl.ticker && !el('seite-vola').hidden) zeigeVola();
}
// Live: solange die Seite offen ist, alle 5 Minuten nach einer neuen Fläche fragen (der Server rechnet alle 30 Minuten)
setInterval(() => { const d = volaDaten[volaWahl.ticker]; if (d?.live && !el('seite-vola').hidden && !document.hidden && !volaSpiel) ladeVola(volaWahl.ticker, true); }, 5 * 60 * 1000);

// Basiswerte: SPY, QQQ, deine US-Aktien, zuletzt angesehene und ein Suchfeld für jeden US-Wert
let volaDepot = [];
api('/api/chart/liste').then((l) => { volaDepot = (l.depot ?? []).map((w) => w.ticker).filter((t) => volaGueltig(t) && !/-(USD|EUR)$/.test(t)); volaTickerKnoepfe(); }).catch(() => {});
function volaTickerKnoepfe(gesehen = []) {
  const alle = [...new Set([...VOLA_TICKER, ...volaDepot, ...gesehen, volaWahl.ticker])];
  el('v-ticker').innerHTML = alle.map((t) => `<button type="button" data-ticker="${t}" aria-pressed="${t === volaWahl.ticker}" ${volaDepot.includes(t) ? 'title="In deinem Depot"' : ''}>${t}</button>`).join('');
  setzePille(el('v-ticker'), true);
}

el('v-ticker').innerHTML = VOLA_TICKER.map((t) => `<button type="button" data-ticker="${t}">${t}</button>`).join('');
el('v-suche').addEventListener('submit', (e) => {
  e.preventDefault();
  const t = el('v-suche-feld').value.trim().toUpperCase();
  if (!volaGueltig(t)) { el('v-status').textContent = 'Bitte einen US-Ticker eingeben, z. B. NVDA.'; return; }
  el('v-suche-feld').value = '';
  volaWahl.ticker = t; merkeVola(); volaTickerKnoepfe(); ladeVola();
});
// Abspielen: die gespeicherten Flächen der letzten Wochen nacheinander, als Stand (absolute IV)
let volaSpiel = null;
el('v-abspielen').addEventListener('click', () => {
  const d = volaDaten[volaWahl.ticker];
  if (volaSpiel) { volaSpielEnde(); return; }
  if (!d?.archiv || d.archiv.length < 3) return;
  volaSpiel = { d, orig: { iv: d.iv, datum: d.datum, kurs: d.kurs }, ansicht: volaWahl.ansicht, i: 0 };
  volaWahl.ansicht = 'heute';
  el('v-abspielen').textContent = '■ Stopp'; el('v-abspielen').setAttribute('aria-pressed', 'true');
  const schritt = () => {
    if (!volaSpiel) return;
    const f = volaSpiel.d.archiv[volaSpiel.i];
    Object.assign(volaSpiel.d, { iv: f.iv, datum: f.datum, kurs: f.kurs });
    el('v-stand').textContent = `Abspielen: ${volaSpiel.d.ticker} · ${volaStandName(f)}${f.art === 'live' ? ' (live)' : ' (Schlussfläche)'} · ${volaSpiel.i + 1} von ${volaSpiel.d.archiv.length} · ${dollar.format(f.kurs)}`;
    zeichneVola();
    volaSpiel.i++;
    if (volaSpiel.i >= volaSpiel.d.archiv.length) { volaSpiel.uhr = setTimeout(volaSpielEnde, 1400); return; }
    volaSpiel.uhr = setTimeout(schritt, matchMedia('(prefers-reduced-motion: reduce)').matches ? 1400 : 700);
  };
  schritt();
});
function volaSpielEnde() {
  if (!volaSpiel) return;
  clearTimeout(volaSpiel.uhr);
  Object.assign(volaSpiel.d, volaSpiel.orig);
  volaWahl.ansicht = volaSpiel.ansicht;
  volaSpiel = null;
  el('v-abspielen').textContent = '▶ Abspielen'; el('v-abspielen').setAttribute('aria-pressed', 'false');
  zeigeVola();
}
const volaKnopf = (id, feld, danach) => el(id).addEventListener('click', (e) => {
  const b = e.target.closest(`button[data-${feld}]`);
  if (!b) return;
  volaWahl[feld] = b.dataset[feld];
  merkeVola();
  danach();
});
volaKnopf('v-ticker', 'ticker', () => { volaSpielEnde(); volaTickerKnoepfe(); ladeVola(); });
volaKnopf('v-ansicht', 'ansicht', () => { volaSpielEnde(); zeigeVola(); });
el('v-frei').addEventListener('change', (e) => {
  volaSpielEnde();
  if (!e.target.value) { volaWahl.ansicht = 'heute'; } else { volaWahl.ansicht = 'frei'; volaWahl.frei = e.target.value; }
  merkeVola(); zeigeVola();
});
volaKnopf('v-form', 'form', zeigeVola);
volaKnopf('v-ausschnitt', 'ausschnitt', zeigeVola);
volaKnopf('v-farbe', 'farbe', zeigeVola);
volaKnopf('v-handel', 'handel', zeigeVola);
el('v-karte').addEventListener('click', (e) => {
  // Liegt über der Zelle die Trefferfläche einer Termin-Linie, zählt trotzdem die Zelle darunter.
  const zelle = e.target.closest('.v-zelle') ?? document.elementsFromPoint(e.clientX, e.clientY).map((x) => x.closest?.('.v-zelle')).find(Boolean);
  if (!zelle) return;
  if (el('v-karte').dataset.zahlen === 'false') volaZelle = zelle.dataset.zelle;
  waehleSmile(Number(zelle.dataset.tage));
});
el('v-smile-tage').addEventListener('click', (e) => {
  const b = e.target.closest('button[data-tage]');
  if (b) waehleSmile(Number(b.dataset.tage));
});
// Makro-Termin in der Legende: Überfahren, Fokus oder Antippen hebt seine Linie hervor.
function volaFokus(datum) {
  if (volaTerminFokus === datum) return;
  volaTerminFokus = datum;
  el('v-legende').querySelectorAll('.v-termin-name').forEach((t) => {
    const an = t.dataset.datum === datum;
    t.classList.toggle('aktiv', an);
    t.setAttribute('aria-pressed', String(an));
  });
  el('v-karte').classList.toggle('fokus', Boolean(datum));
  el('v-karte').querySelectorAll('.v-termin').forEach((l) => l.classList.toggle('aktiv', l.dataset.datum === datum));
  volaNeuZeichnen();
}
const terminUnter = (e) => e.target.closest?.('.v-termin-name');
el('v-legende').addEventListener('pointerover', (e) => { if (e.pointerType === 'mouse' && terminUnter(e)) volaFokus(terminUnter(e).dataset.datum); });
el('v-legende').addEventListener('pointerout', (e) => { if (e.pointerType === 'mouse' && terminUnter(e) && !terminUnter(e).contains(e.relatedTarget)) volaFokus(null); });
// Fokus nur per Tastatur; beim Antippen bekommt das Element auch den Fokus, das regelt pointerup.
el('v-legende').addEventListener('focusin', (e) => { const t = terminUnter(e); if (t?.matches(':focus-visible')) volaFokus(t.dataset.datum); });
el('v-legende').addEventListener('focusout', (e) => { if (terminUnter(e)?.matches(':focus-visible')) volaFokus(null); });
// Antippen (Finger) schaltet um; mit der Maus genügt das Überfahren.
el('v-legende').addEventListener('pointerup', (e) => {
  const t = terminUnter(e);
  if (t && e.pointerType !== 'mouse') volaFokus(volaTerminFokus === t.dataset.datum ? null : t.dataset.datum);
});
el('v-legende').addEventListener('keydown', (e) => {
  const t = terminUnter(e);
  if (t && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); volaFokus(volaTerminFokus === t.dataset.datum ? null : t.dataset.datum); }
});
el('v-info-knopf').addEventListener('click', () => {
  const offen = el('v-info').hidden;
  el('v-info').hidden = !offen;
  el('v-info-knopf').setAttribute('aria-expanded', String(offen));
});
// Bei anderer Fenstergröße, Hell/Dunkel oder Tagesfarbe (Plus/Minus) neu zeichnen.
let volaGroesse = null;
const volaAuffrischen = () => { if (!el('seite-vola').hidden) zeichneVola(); };
window.addEventListener('resize', () => { clearTimeout(volaGroesse); volaGroesse = setTimeout(volaAuffrischen, 150); });
new MutationObserver(volaAuffrischen).observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });
new MutationObserver(volaAuffrischen).observe(document.body, { attributes: true, attributeFilter: ['class'] });

// ---- Muster-Galerie: typische Formen der Volatilität, schematisch gezeichnet ----
// Die Zeichnungen sind feste Skizzen, keine echten Daten. Welche Muster gerade zutreffen,
// prüfen einfache Regeln auf den gespeicherten Flächen von SPY und QQQ.

// Kleine Skizze: eine Kurve (Werte 0 bis 1, 1 = oben), wahlweise mit alter Kurve gestrichelt
// und einer senkrechten Marke. Oder ein Raster aus Veränderungen (−1 blau bis +1 rot).
function musterBild({ kurve, alt, marke, raster, achse }) {
  const B = 160, H = 74, x0 = 14, x1 = 150, y0 = 58, y1 = 8;
  const x = (i, n) => x0 + (i / (n - 1)) * (x1 - x0);
  const y = (v) => y0 - v * (y0 - y1);
  const linie = (werte) => werte.map((v, i) => `${i ? 'L' : 'M'}${x(i, werte.length).toFixed(1)} ${y(v).toFixed(1)}`).join('');
  let inhalt = '';
  if (raster) {
    // Zeilen von oben (lange Laufzeit) nach unten (kurze), Spalten von niedrigem zu hohem Strike.
    const zeilen = raster.length, spalten = raster[0].length;
    const zb = (x1 - x0) / spalten, zh = (y0 - y1) / zeilen;
    inhalt = raster.map((z, i) => z.map((v, j) => {
      const farbe = v > 0 ? 'var(--vola-rot)' : v < 0 ? 'var(--vola-blau)' : 'var(--grau)';
      const deckung = v === 0 ? 0.18 : 0.25 + Math.abs(v) * 0.7;
      return `<rect class="mu-zelle" x="${x0 + j * zb}" y="${y1 + i * zh}" width="${zb}" height="${zh}" rx="3" fill="${farbe}" fill-opacity="${deckung.toFixed(2)}"/>`;
    }).join('')).join('');
  } else {
    if (marke !== undefined) inhalt += `<line class="mu-marke" x1="${x(marke, kurve.length)}" x2="${x(marke, kurve.length)}" y1="${y1}" y2="${y0}"/>`;
    if (alt) inhalt += `<path class="mu-alt" d="${linie(alt)}"/>`;
    inhalt += `<path class="mu-kurve" d="${linie(kurve)}"/>`;
  }
  return `<svg viewBox="0 0 ${B} ${H}" role="img" aria-hidden="true">
    <path class="mu-achse" d="M${x0} ${y1 - 2}V${y0}H${x1 + 2}"/>
    <text class="mu-text" x="${x1 + 2}" y="${H - 2}" text-anchor="end">${achse} →</text>
    <text class="mu-text" x="${x0 - 2}" y="${y1 + 6}" text-anchor="end">IV</text>
    ${inhalt}
  </svg>`;
}

