    zeiger.removeAttribute('hidden'); zeiger.setAttribute('x1', x(kt[i])); zeiger.setAttribute('x2', x(kt[i]));
    tip.hidden = false;
    tip.innerHTML = `<b>${kt[i].toLocaleDateString('de-DE', { month: 'long', year: 'numeric' })}</b><br>Kurs ${kurz(kv[i])}${j >= 0 ? `<br>${esc(d.kennzahl_name)} ${esc(fuKzWert(zv[j], d.einheit))} <small>(${zt[j].toLocaleDateString('de-DE', { month: '2-digit', year: 'numeric' })})</small>` : ''}${d.art !== 'monat' ? '<br><small class="sekundaer">Klick: alle Zahlen</small>' : ''}`;
    const links = x(kt[i]) + 12 + tip.offsetWidth > B ? x(kt[i]) - tip.offsetWidth - 12 : x(kt[i]) + 12;
