// Weltkarte: Jede Bedienung merkt sich die Zeit. Ist der Globus herausgezoomt (ganze Kugel zu sehen), kein
// Fenster offen und 8 Sekunden nichts passiert, dreht er sich wieder langsam weiter.
['pointerdown', 'wheel', 'touchstart', 'keydown'].forEach((t) => document.addEventListener(t, (e) => { if (e.target.closest?.('#wk-rahmen, #wk-panel')) wk.ruheAb = Date.now(); }, { passive: true, capture: true }));
setInterval(() => {
  if (!wk.globus || !wk.drehen || wkRuhig() || document.hidden || el('seite-weltkarte')?.hidden) return;
  const panel = el('wk-panel');
  if ((panel && !panel.hidden) || (wk.k ?? 1) > 1.2) { wk.ruheAb = Date.now(); return; }
  if (Date.now() - (wk.ruheAb ?? 0) < 8000) return;
  if (wk.dreht && wk.drehUhr) return;
  if (!wk.dreht) wk.anlauf = performance.now();
  wk.dreht = true;
  wk.drehUhr = requestAnimationFrame(wk.drehen);
}, 1000);

// ---- Mehr vom Markt: Funktionen, die fürs Depot gebaut sind, auch für beliebige Werte ----
// Jede dieser Seiten bekommt oben eine Leiste: weitere Werte (Ticker oder Firmenname suchen, Watchlist,
// S&P-Sektoren, Indizes) und wo es passt "nur Markt" ohne das Depot. Der Server markiert diese Werte mit
// extra=True: Sie bekommen eigene Zeilen, zählen aber nicht in Depot-Summen und -Gewichte.
// Die Wahl wird je Seite im Browser gemerkt.
function mwZeichnen(seite) {
  const box = document.querySelector(`.mw-leiste[data-mw="${seite}"]`);
  if (!box) return;
  const w = mwWahl[seite], cfg = MW_SEITEN[seite];
  const chips = w.extra.map((t) => `<span class="mw-chip">${esc(t)}<button type="button" data-mw-weg="${esc(t)}" aria-label="${esc(t)} entfernen">×</button></span>`).join('');
  box.innerHTML = `<details class="mw-details"${w.extra.length ? ' open' : ''}>
    <summary>Mehr vom Markt${w.extra.length ? ` <b>${w.extra.length}</b>` : ''}<span class="mw-hinweis">${w.extra.length ? (w.depot ? ' · Depot plus diese Werte' : ' · nur diese Werte') : ' · auch für Werte außerhalb deines Depots'}</span></summary>
    <div class="mw-innen">
      <form class="mw-form"><input type="text" class="mw-eingabe" list="mw-liste-${seite}" placeholder="Ticker oder Name, z. B. AAPL oder Siemens" aria-label="Wert hinzufügen" autocomplete="off" maxlength="40">
        <datalist id="mw-liste-${seite}"></datalist><button class="knopf" type="submit">Hinzufügen</button></form>
      <div class="mw-gruppen">${cfg.gruppen.map((g) => `<button type="button" class="knopf" data-mw-gruppe="${g}">+ ${MW_GRUPPEN[g]}</button>`).join('')}
        ${w.extra.length ? '<button type="button" class="knopf" data-mw-leeren>Alle entfernen</button>' : ''}
        ${cfg.nurMarkt && w.extra.length ? `<label class="mw-depot"><input type="checkbox" data-mw-depot${w.depot ? ' checked' : ''}> Depot mit anzeigen</label>` : ''}</div>
      ${chips ? `<div class="mw-chips">${chips}</div>` : ''}
      <p class="klein sekundaer">${esc(cfg.text ?? 'Höchstens 15 Werte. Sie erscheinen als eigene Zeilen und zählen nicht in die Summen und Gewichte deines Depots.')}</p>
    </div></details>`;
}

function mwSetzen(seite, aenderung) {
  const w = mwWahl[seite];
  aenderung(w);
  w.extra = [...new Set(w.extra.map((t) => t.toUpperCase().trim()).filter((t) => /^[A-Z0-9^][A-Z0-9.\-=^]{0,14}$/.test(t)))].slice(0, MW_SEITEN[seite].hoechstens ?? 15);
  if (!w.extra.length) w.depot = true;
  try { localStorage.setItem(`mw:${seite}`, JSON.stringify(w)); } catch {}
  mwZeichnen(seite);
  MW_SEITEN[seite].neu();
}

async function mwGruppe(seite, gruppe) {
  let neu = [];
  if (gruppe === 'sektoren') neu = MW_SEKTOREN;
  else if (gruppe === 'indizes') neu = seite === 'benchmark' ? MW_INDIZES_EURO : MW_INDIZES;
  else {
    mwWatchlist ??= await api('/api/chart/liste').then((l) => (l.watchlist ?? []).map((w) => w.ticker)).catch(() => []);
    neu = mwWatchlist;
    if (!neu.length) { alert('Die Watchlist ist leer.'); return; }
  }
  mwSetzen(seite, (w) => { w.extra = [...w.extra, ...neu]; });
}

// Seiten vorbereiten: Leiste unter die Überschrift bzw. den Umschalter der Gruppe
for (const seite in MW_SEITEN) {
  const s = el(`seite-${seite}`);
  if (!s) continue;
  const leiste = document.createElement('div');
  leiste.className = 'mw-leiste';
  leiste.dataset.mw = seite;
  const nach = s.querySelector(':scope > .teil-wahl') ?? s.querySelector(':scope > h1');
  nach.after(leiste);
  mwZeichnen(seite);
  leiste.addEventListener('submit', (e) => {
    e.preventDefault();
    const feld = leiste.querySelector('.mw-eingabe');
    const roh = feld.value.trim();
    // Aus der Vorschlagsliste: "AAPL · Apple Inc." → AAPL
    const t = roh.split(' · ')[0].toUpperCase();
    if (!t) return;
    mwSetzen(seite, (w) => { w.extra = [...w.extra, t]; });
  });
  leiste.addEventListener('click', (e) => {
    const weg = e.target.closest('[data-mw-weg]');
    if (weg) { mwSetzen(seite, (w) => { w.extra = w.extra.filter((t) => t !== weg.dataset.mwWeg); }); return; }
    const g = e.target.closest('[data-mw-gruppe]');
    if (g) { mwGruppe(seite, g.dataset.mwGruppe); return; }
    if (e.target.closest('[data-mw-leeren]')) mwSetzen(seite, (w) => { w.extra = []; });
  });
  leiste.addEventListener('change', (e) => {
    if (e.target.matches('[data-mw-depot]')) mwSetzen(seite, (w) => { w.depot = e.target.checked; });
  });
  // Vorschläge beim Tippen (Yahoo-Suche), ab 2 Zeichen
  let uhr = 0;
  leiste.addEventListener('input', (e) => {
    if (!e.target.matches('.mw-eingabe')) return;
    clearTimeout(uhr);
    const q = e.target.value.trim();
    if (q.length < 2 || q.includes(' · ')) return;
    uhr = setTimeout(async () => {
      const d = await api(`/api/watchlist/suche?q=${encodeURIComponent(q)}`).catch(() => ({ treffer: [] }));
      const liste = leiste.querySelector('datalist');
      if (liste) liste.innerHTML = (d.treffer ?? []).slice(0, 8).map((x) => `<option value="${esc(`${x.ticker} · ${x.name}`)}"></option>`).join('');
    }, 250);
  });
}

// ---- Dashboard auf dem Handy: eigene Reihenfolge und Höhe je Layout (layout.handy), bearbeitbar ----
// Eine Spalte. Ohne eigene Handy-Liste gilt die Reihenfolge des großen Bildschirms (oben links nach unten rechts).
// Änderungen am Handy verschieben nichts am großen Bildschirm und umgekehrt.
const tfHandy = () => matchMedia('(max-width: 760px)').matches;
const TF_HOEHEN = [['klein', 2], ['mittel', 3], ['groß', 5]];
// Breite, die ein Widget auf dem Handy "sieht" (für die Menge an Inhalt): etwa ein Drittel des großen Rasters
const TF_HANDY_BREITE = 4;

function tfHandyListe(lay) {
  if (Array.isArray(lay.handy)) return lay.handy.filter((k) => KACHELN[k.art]);
  return [...lay.kacheln].sort(nachLage).map((k) => ({ art: k.art, h: Math.max(mindest({ art: k.art, w: TF_HANDY_BREITE, h: 1 })[1], Math.min(5, k.h)) }));
}
// Vor der ersten Änderung am Handy die abgeleitete Liste festschreiben
function tfHandyEigene(lay) {
  if (!Array.isArray(lay.handy)) lay.handy = tfHandyListe(lay).map((k) => ({ ...k }));
  return lay.handy;
}

function tfHandyZeichnen() {
  const lay = tafelLayout();
  const raster = el('tafel');
  const liste = tfHandyListe(lay);
  raster.classList.toggle('handy-bearbeiten', tafelBearbeiten);
  raster.replaceChildren(...liste.map((k, i) => {
    const n = kachelKnoten({ art: k.art, x: 0, y: i, w: TF_HANDY_BREITE, h: k.h });
    n.dataset.handy = String(i);
    if (tafelBearbeiten) {
      const titel = KACHELN[k.art].titel;
      const stufe = TF_HOEHEN.findIndex(([, h]) => h >= k.h);
      n.querySelector('header').insertAdjacentHTML('beforeend', `<div class="tf-h-steuer">
        <button type="button" class="tf-h-knopf" data-h="hoch" aria-label="${esc(titel)} nach oben" ${i === 0 ? 'disabled' : ''}>↑</button>
        <button type="button" class="tf-h-knopf" data-h="runter" aria-label="${esc(titel)} nach unten" ${i === liste.length - 1 ? 'disabled' : ''}>↓</button>
        <button type="button" class="tf-h-knopf tf-h-groesse" data-h="groesse" aria-label="Höhe ändern">${TF_HOEHEN[Math.max(0, stufe)][0]}</button>
        <span class="tf-h-griff" data-h="ziehen" aria-hidden="true" title="Ziehen zum Verschieben"><i></i><i></i><i></i></span></div>`);
    }
    return n;
  }));
  tafelKnoten().forEach(kachelFuellen);
  // Vorrat: alle Widgets, die auf dem Handy (noch) fehlen
  const da = new Set(liste.map((k) => k.art));
  el('tf-vorrat').innerHTML = Object.entries(KACHELN).filter(([art]) => !da.has(art))
    .map(([art, k]) => `<button type="button" class="tf-vorrat-teil" data-art="${art}">${esc(k.titel)}</button>`).join('') || '<span class="sekundaer">Alle Widgets sind schon da.</span>';
  el('tf-leer').hidden = liste.length > 0;
  el('tf-hinweis').textContent = tafelBearbeiten
    ? `Handy-Ansicht${Array.isArray(lay.handy) ? ' (eigene Reihenfolge)' : ' (noch wie am Computer)'}: ↑ ↓ oder am Griff ziehen zum Verschieben, Höhe antippen zum Ändern, × blendet ein Widget nur hier aus. Unten antippen fügt hinzu. Am Computer bleibt alles, wie es ist.`
    : '';
  el('tf-wie-computer').hidden = !(tafelBearbeiten && Array.isArray(lay.handy));
}

function tfHandyAendern(aenderung) {
  const lay = tafelLayout();
  aenderung(tfHandyEigene(lay));
  tafelSpeichern();
  tfHandyZeichnen();
}

// Ziehen am Griff: das Widget folgt dem Finger, die anderen machen Platz; am Bildschirmrand scrollt die Seite mit
function tfHandyZiehen(knoten, e) {
  const raster = el('tafel');
  knoten.classList.add('zieht');
  const startY = e.clientY;
  let verschoben = 0, zeigerY = e.clientY, uhr = 0;
  const reihe = () => [...raster.querySelectorAll(':scope > .tf-kachel')];
  const lage = () => {
    knoten.style.transform = `translateY(${zeigerY - startY - verschoben}px)`;
    const andere = reihe().filter((n) => n !== knoten);
    let ziel = andere.filter((n) => { const r = n.getBoundingClientRect(); return zeigerY > r.top + r.height / 2; }).length;
    const jetzt = reihe().indexOf(knoten);
    if (ziel !== jetzt) {
      const vorher = knoten.getBoundingClientRect().top;
      tafelFlip(() => { raster.insertBefore(knoten, andere[ziel] ?? null); }, knoten);
      verschoben += knoten.getBoundingClientRect().top - vorher + (verschoben ? 0 : 0);
      knoten.style.transform = `translateY(${zeigerY - startY - verschoben}px)`;
    }
  };
  const bewegen = (ev) => { ev.preventDefault(); zeigerY = ev.clientY; lage(); };
  // Rand-Scrollen
  const rollen = () => {
    const rand = 70;
    const d = zeigerY < rand ? -(rand - zeigerY) / 4 : zeigerY > innerHeight - rand ? (zeigerY - (innerHeight - rand)) / 4 : 0;
    if (d) { scrollBy(0, d); verschoben -= d; lage(); }
    uhr = requestAnimationFrame(rollen);
  };
  uhr = requestAnimationFrame(rollen);
  const los = () => {
    cancelAnimationFrame(uhr);
    window.removeEventListener('pointermove', bewegen);
    window.removeEventListener('pointerup', los);
    window.removeEventListener('pointercancel', los);
    knoten.classList.remove('zieht');
    knoten.style.transform = '';
    const reihenfolge = reihe().map((n) => Number(n.dataset.handy));
    tfHandyAendern((liste) => {
      const alt = [...liste];
      liste.splice(0, liste.length, ...reihenfolge.map((i) => alt[i]).filter(Boolean));
    });
  };
  window.addEventListener('pointermove', bewegen, { passive: false });
  window.addEventListener('pointerup', los);
  window.addEventListener('pointercancel', los);
}

el('tafel').addEventListener('pointerdown', (e) => {
  if (!tfHandy() || !tafelBearbeiten) return;
  const griff = e.target.closest('[data-h="ziehen"]');
  if (!griff) return;
  e.preventDefault();
  tfHandyZiehen(griff.closest('.tf-kachel'), e);
}, true);

el('tafel').addEventListener('click', (e) => {
  if (!tfHandy() || !tafelBearbeiten) return;
  const knoten = e.target.closest('.tf-kachel');
  if (!knoten) return;
  e.preventDefault(); e.stopImmediatePropagation();
  const i = Number(knoten.dataset.handy);
  const k = e.target.closest('[data-h]')?.dataset.h;
  if (e.target.closest('.tf-weg')) { tfHandyAendern((liste) => liste.splice(i, 1)); return; }
  if (k === 'hoch' && i > 0) tfHandyAendern((liste) => liste.splice(i - 1, 0, ...liste.splice(i, 1)));
  else if (k === 'runter') tfHandyAendern((liste) => { if (i < liste.length - 1) liste.splice(i + 1, 0, ...liste.splice(i, 1)); });
  else if (k === 'groesse') {
    tfHandyAendern((liste) => {
      const stufe = TF_HOEHEN.findIndex(([, h]) => h >= liste[i].h);
      const minH = mindest({ art: liste[i].art, w: TF_HANDY_BREITE, h: 1 })[1];
      let neu = TF_HOEHEN[(Math.max(0, stufe) + 1) % TF_HOEHEN.length][1];
      if (neu < minH) neu = TF_HOEHEN.find(([, h]) => h >= minH)?.[1] ?? minH;
      liste[i].h = neu;
    });
  }
}, true);

el('tf-vorrat').addEventListener('click', (e) => {
  if (!tfHandy() || !tafelBearbeiten) return;
  const teil = e.target.closest('.tf-vorrat-teil');
  if (!teil) return;
  e.stopImmediatePropagation();
  tfHandyAendern((liste) => liste.push({ art: teil.dataset.art, h: Math.max(3, mindest({ art: teil.dataset.art, w: TF_HANDY_BREITE, h: 1 })[1]) }));
  el('tafel').lastElementChild?.scrollIntoView({ block: 'center', behavior: 'smooth' });
}, true);
// Am Handy kein Ziehen aus dem Vorrat (antippen genügt)
el('tf-vorrat').addEventListener('pointerdown', (e) => { if (tfHandy()) e.stopImmediatePropagation(); }, true);

el('tf-wie-computer').addEventListener('click', () => {
  const lay = tafelLayout();
  if (!confirm('Eigene Handy-Reihenfolge verwerfen? Das Handy zeigt dann wieder die Widgets wie am Computer.')) return;
  delete lay.handy;
  tafelSpeichern();
  tfHandyZeichnen();
});

// Wechsel zwischen Handy und großem Bildschirm (Fenster drehen oder verkleinern): neu zeichnen
matchMedia('(max-width: 760px)').addEventListener('change', () => { if (tafelDaten && !el('seite-tafel').hidden) zeichneTafel(); });
